"""Apply reviewed, context-aware corrections to the master translation sheet."""
import csv
import re
from pathlib import Path

MASTER = Path(__file__).resolve().parents[1] / "03_text" / "translated" / "translation-sheet.tsv"

OVERRIDES = {
    "Script/scenario05_13.binu8@75179": '@vMeguri_0899「不只是我。你们所有人应该都知道才对。啊，对了……该怎么说来着？那种荒唐的神话里不是写得清清楚楚吗？对了——巴德尔，是我杀的吧？是我把那家伙残忍地杀死了。是我！」',
    "Script/scenario05_14.binu8@73401": '@vKohaku_0651「不对！我害怕的不是那种东西！我真正应该害怕的，是神话的实现！数百年、数千年之后的未来。在一个发展到连我都无法理解的世界里，你们不曾产生一丝疑问，就这样享受着和平！而你们兴高采烈传颂的所谓北欧神话，不过是个任性至极的故事！」',
    "Script/scenario05_14.binu8@86263": '@vFutaba_0630「我绝不会让这样的故事流传下去！奥丁！我要把你究竟是多么残暴的暴君，原原本本地传述下去！还有！我要把父亲的清白与高洁，留在历史之中！历代最恶劣、最残虐的皇帝！这才是最适合你的称呼吧！」',
    "Script/scenario06_10.binu8@56906": '@vOboro_0305「好了，幸福的美梦也该醒了吧？你已经明白，自己不可能再获得真正的幸福。从这里开始、无止境延续的所谓幸福，对你而言只不过是地狱。」',
    "Script/scenario06_2.binu8@97635": '@vMeguri_1011「那个不负责任的团长把兰比里斯丢在一边，已经过去一周了。我想，大家也都对剧团今后的方向感到不安。说实话，我自己也有很多想法。」',
    "Script/scenario06_2.binu8@97929": '@vMeguri_1012「……不过，答案从一开始就已经很清楚了。我想做的，是今后也继续呈现最棒的戏剧。所以……在悠苑他们回来之前，我想让兰比里斯剧团变得更加强大。」',
    "Script/scenario06_4.binu8@77277": '@vMirai_0467「普通人和朋友玩得开心时，理世小姐却在排练室里含着泪，被人不断斥责。她还要忍受周围毫无根据的恶言，在脑中一遍又一遍刻下自己并不喜欢的故事。」',
    "Script/scenario06b_8.binu8@37729": '@vFutaba_0754「……不过，拍得好看的不是相机，而是天使酱的表情就是了。要是站在那里的是我，肯定能把她拍得更可爱。」',
    "Script/scenario05_5.binu8@76687": '@vMeguri_0588「……基本都是之前做好后剩下的。我嫌麻烦，总会多做一些。扔掉又觉得可惜，正好拿来招待你。」',
    "Script/scenario04_5.binu8@79103": '@vMirai_0272「人睡觉时，不是会随心所欲地做梦吗？不管梦到什么，都不会给任何人添麻烦。虚构世界也是一样的。」',
    "Script/scenario05_5.binu8@70112": '@vMeguri_0568「你那副一脸恍然大悟的表情是怎么回事？真是让人火大，特别火大。」',
    "Script/scenario05_10.binu8@92095": '@vRairai_0529「哈？你这臭小鬼以为自己是谁啊。像你这种毫无女人味的家伙，少对我指手画脚！」',
    "Script/scenario06_7.binu8@83460": '　和她两个人这样走在一起，感觉简直就像是在证明我们正在交往，让我不由得在意起来。',
    "Script/scenario05_9.binu8@99670": '@vOboro_0263「……怎么了，濑和君？从刚才开始就一副烦恼的样子。」',
    "Script/scenario05_2.binu8@87063": '　可即便如此，一旦迟迟拿不出成果，我就会闷闷不乐。@n　还会对这个不肯按自己心意运转的世界，发出各种牢骚和不满。',
    "Script/scenario05_12.binu8@82727": '@vRairai_0586「我很清楚该怎么发挥龙木悠苑的价值。所以，那家伙才是个好女人。」',
    "Script/scenario06_1.binu8@87235": '@vF_StudentA_0026「啊！果然！我就觉得可能是你！匂宫小姐可是相当有名的人呢。英姿飒爽、高贵冷峻，虽然让人难以接近……」',
    "Script/scenario05_3.binu8@75636": '@vRize_0598「不、不是那回事。虽然我确实演出了属于自己的风格……但总觉得，还是没能很好地适应那份剧本。」',
    "Script/scenario05_4.binu8@72359": '@vMeguri_0519「我倒要问座长，您怎么会在这种地方？该不会……是特意来找我的吧？」',
    "Script/scenario05_4.binu8@77065": '@vRairai_0447「你还有大把未来。那老头不想让你加入这里……想必就是因为这个吧。」',
    "Script/scenario05_7.binu8@87911": '@vNanana_0365「刚、刚才那句话，只是！没有什么特别的意思哦！？不，也不是说没有深意！」',
    "Script/scenario04_5.binu8@77472": '@vFutaba_0532「有必要。或者说……这是必然吧。你看起来不像无私的人。反正，你接近我也是为了你自己吧。」',
    "Script/scenario05_2.binu8@71744": '@vYuuen_0175「我们剧团里没有吝于合作的孩子。所以，你就尽管安排她们吧？毕竟，害羞、不被人开口请求就不会主动帮忙的孩子也很多。」',
    "Script/scenario05_5.binu8@80832": '@vMeguri_0602「——我不会离开这里。你要是非得这么做，就试着强行碰我啊？那不正是野兽诞生的瞬间吗？」',
    "Script/scenario05_6.binu8@99620": '@vHana_0182「……那个，接下来要有六个人去打扰濑和君家……真的没关系吗？如果会给你添麻烦，请千万别客气，直接告诉我哦。」',
    "Script/scenario06_5.binu8@77248": '@vMeguri_1035「……你下结论也太快了！再多和我们商量一下不行吗！兰比里斯剧团的未来才刚刚开始啊！从现在起，我们还可以变得更加强大——！」',
    "Script/scenario05_14.binu8@80372": '@vRairai_0598「该道谢的是我才对。我是个笨拙又愚蠢的男人，除了努力做个正确的人，什么也不会。」',
    "Script/scenario05_10.binu8@85928": '@vMeguri_0813「可是，我明白了！我明白天兄对我的演技抱有多么强烈的不满！也明白了，他是真的想让我变得不幸！」',
    "Script/scenario05_9.binu8@92064": '@vTeacherA_0009「我不是说你可以为所欲为。禁止在校内进行宣传活动，以及类似的行为。想做就到校外去。另外，不要让匂宫太引人注目。」',
    "Script/scenario06b_2.binu8@90270": '@vMika_0104「为什么？你明明已经察觉到奈奈菜的心意了。正是性欲旺盛的年纪……换作一般人，多少都会想趁机占点便宜吧。」',
    "Script/scenario05_3.binu8@73822": '@vMeguri_0464「所以呢？这种无聊的小事有什么意义吗？在我看来，这根本就是无关紧要的小事，不是吗？」',
    "Script/scenario04_1.binu8@92106": '　我本来应该早就察觉到这份疯狂。@n　从那天她夺走濑和君的角色开始，她的异常就已经显露无遗了。',
    "Script/scenario04_3.binu8@68884": '@vNanana_0274「怎么可能呢。因为我是天使奈奈菜啊？我是个演技糟糕透顶的天使奈奈菜。比起我，能把海尔演得更好的人应该多得是吧。」',
    "Script/scenario06b_2.binu8@67293": '@vNanana_0441「主角普洛斯彼罗明明被复仇的冲动驱使，却还是原谅了所有人。无论是已经改过自新的人、毫无悔意的人，甚至是曾想杀死他的人。他宽恕一切的结局，在莎士比亚最后一部作品中显得格外特别。」',
    "Script/scenario06_5.binu8@68313": '@vRize_0879「……冰狐也是这样。她的做法……我实在无法视若无睹。她不断消耗身体、磨损心灵，用一种注定无法长久的方法，让自己的演技更具冲击力。」',
    "Script/scenario06b_6.binu8@70518": '@vFutaba_0706「——现在就退出兰比里斯剧团吧。要实现天使酱的制作企划，同时兼顾两边是不可能的。」',
    "Script/scenario04_4.binu8@76257": '@vOboro_0187「既然已经喜欢上了，就没有办法。无论如何都只能痛苦，无论如何都只能悲伤。这大概也是荒谬故事的一种吧。」',
    "Script/scenario05_1.binu8@77108": '@vRairai_0365「当然。巡的指导讲究的是技术。想要月亮，就先学会飞上天空。这就是那家伙的做法。」',
    "Script/scenario06_5.binu8@69992": '@vRize_0884「我不这么认为。即使演出不够完美，我也由衷希望你们能笑着享受，把戏演到最后。我们应该都明白：和重要的伙伴一起创作的戏剧，哪怕并不完美，也会成为无可替代的回忆。」',
    "Script/scenario06_1.binu8@64834": '@vRize_0867「因为这是理所当然的，不是吗？我并不是出于自己的意愿来到这个世界。只是周围的人擅自对我抱有期待……又强行推着我，让我去演戏。」',
    "Script/scenario05_5.binu8@72554": '@vMeguri_0573「……那大概就是祖父在我身上发现的才能吧。匂宫巡很适合扮演强大的角色。我自己也曾这样认为。」',
    "Script/scenario06b_1.binu8@73466": '@vFutaba_0631「您在说什么理所当然的话？那可是天使酱啊！虽说是从网络走红的，她也是货真价实的偶像。杂志上也刊登过她，SNS账号更是拥有惊人的粉丝数。她可是个货真价实的大人物，明白了吗？」',
    "Script/scenario05_3.binu8@76554": '@vMeguri_0471「没有什么是我演不了的。不管琥珀准备了怎样的奥丁，我都会用与之相称的洛基来应战。」',
    "Script/scenario04_6.binu8@76501": '@vRize_0485「人的内心，不是那么容易就能说清楚的。别把它武断地归结为其中一边。我……曾经非常喜欢那个孩子，同时也非常讨厌她。仅此而已。」',
    "Script/scenario05_6.binu8@99620": '@vHana_0182「……那个，接下来要有六个人去打扰濑和君家……真的没关系吗？如果会给你添麻烦，请千万别客气，直接告诉我哦。」',
    "Script/scenario04_6.binu8@62239": '@vMirai_0310「……可是，箱鸟同学，你落选了。你觉得凭那样的心情，真的能演好凯瑞亚吗？想站在我的身边？不对……我是卡利古拉。既然是凯瑞亚，就必须抱着要杀死我的觉悟来面对我。」',
    "Script/scenario05_14.binu8@68404": '@vRize_0720「我不在意。我的正义感正在高声告诉我该怎么做。而且，洛基，即使发动叛乱，你也注定会死。既然如此，和你一同走向死亡，不正是朋友应该有的样子吗？」',
    "Script/scenario05_11.binu8@83188": '@vRairai_0568「匂宫巡这家伙，不就是你教育出来的成果吗。放心吧……那可是货真价实的天才。她还活得好好的，不就说明那老头的做法是正确的吗？」',
    "Script/scenario05_13.binu8@73636": '@vMeguri_0894「海姆达尔！我倒要问你怎么会在这种地方。你的工作不是无聊的看门吗？好了，赶紧出去吧。继续你的偷窥癖去！」',
    "Script/scenario06_3.binu8@57219": '「是折原京子。每当她说些什么，我的心就会躁动不安。明明知道她不是那个人，却还是会把未来的身影叠在她身上。她的演技明明很平庸，可我还是会从中感受到未来的痕迹。」',
    "Script/scenario05_2.binu8@84934": '@vRairai_0384「真厉害啊，从小就登上舞台的那些家伙。既然有那种实力，为什么还要退出呢？不过对我们来说，他们自我毁灭倒是件值得庆幸的事。」',
    "Script/scenario05_1.binu8@96927": '@vMeguri_0431「我总觉得，那孩子或许能帮我实现这个愿望。连我也不认为自己能独自超越祖父。但是，如果能为当时的兰比里斯添上它所欠缺的东西……我觉得，或许就有可能。」',
    "Script/scenario05_14.binu8@73821": '@vKohaku_0652「我从心底憎恨这一点！你们以‘不过是空想和妄想’为借口，肆意贬低那个名字！你们根本不知道背后的真相，却还把那些并列的词语当成可以随意附加价值的东西！我恨你们，恨得无以复加！！」',
    "Script/scenario06b_1.binu8@71583": '@vNanana_0410「座长先生和匂宫小姐，已经和好了吗……」',
    "Script/scenario05_7.binu8@74165": '@vOboro_0227「哦，居然放着伯爵茶。匂宫小姐还真是懂行啊。」',
    "Script/scenario05_7.binu8@73927": '@vOboro_0226「咦？我记得匂宫小姐在家里不是更喜欢红茶吗？」',
    "Script/scenario05_6.binu8@98962": '@vMeguri_0700「……又来？座长该不会只是想把琥珀一个人占为己有吧？」',
    "Script/scenario06_7.binu8@88392": '　课间休息时，我正前往理科教室换教室上课。',
    "Script/scenario06b_6.binu8@60759": '　剧团活动暂时休止，等养精蓄锐之后再重新开始。',
    "Script/scenario06_3.binu8@54401": '「未来的即兴剧……！住手！！我……！」',
    "Script/scenario06b_3.binu8@69494": '　那个和我同龄的剧团男孩，是我非常、非常不擅长应付的人。',
    "Script/scenario06_6.binu8@75704": '@vFutaba_0773「光天化日之下大声呼喊爱意，我觉得不太妥当。昨天佩特里科尔那件事，已经传成流言了吧？」',
    "Script/scenario05_10.binu8@70867": '　我之所以说出那样的权宜之计，只是因为想肯定那段甜得令人沉醉的时光。',
    "Script/scenario05_13.binu8@66608": '@vMeguri_0878「随着时间流逝，我体内的怪物开始露出面目。看不见的恶魔削磨着我的良心，又用爪子抓挠你的面具。啊，可即便如此！只要你在这里，我就还能忘记一切，还能继续当洛基。」',
    "Script/scenario05_9.binu8@91275": '@vTeacherA_0006「……幸运的是，替匂宫说话的人也很多，那篇报道的可信度因此动摇了。也有人指出那是恶意恶作剧，或是合成照片。再加上她平时品行良好，看来不会受到太重的处分……」',
    "Script/scenario04_7.binu8@40600": '@vRize_0515「不过，比起女主角，我觉得冰狐更适合反派。该说是黑暗英雄吗？」',
    "Script/scenario05_10.binu8@81960": '@vMeguri_0805「既然如此，直接告诉我不就好了吗？根本没必要用那种方式伤害我和濑和君……！！」',
    "Script/scenario05_10.binu8@87397": '@vMeguri_0817「是匂宫，对吧？请不要这样随意叫我的名字。」',
    "Script/scenario05_11.binu8@77246": '　一直真心支持悠苑未来的座长，对这桩婚事告吹一事怒不可遏。',
    "Script/scenario05_11.binu8@96260": '　只要面对面比较一下，就会明白了。@n　也就能明白，为什么天乐座长会把匂宫巡逼到绝境。',
    "Script/scenario05_11.binu8@100913": '　匂宫巡缺席一事，在彩排前不久才被发现。',
    "Script/scenario05_12.binu8@73290": '　匂宫巡没有迟到，在最后关头赶到了现场。',
    "Script/scenario05_12.binu8@76550": '　匂宫巡的怒火，变得越来越炽烈。',
    "Script/scenario05_12.binu8@91140": '@vRize_0692「架桥小姐的演技……简直像那个孩子的演技一样，危险得让人不安。」',
    "Script/scenario05_13.binu8@57621": '　我们必须对那个即将带来终焉的幕后黑手采取行动。',
    "Script/scenario05_13.binu8@77065": '　这个以怪物般的演员身份轰动世间的她，已经没有任何人能够真正理解。',
    "Script/scenario05_5.binu8@74327": '「便、便当！？匂宫，你还会做饭吗！？」',
    "Script/scenario05_5.binu8@82000": '　我什么也说不出来。@n　匂宫开心地笑了。',
    "Script/scenario05_5.binu8@91491": '　我们共同度过的大部分时间，确实都用在了戏剧上。',
    "Script/scenario04_6.binu8@72660": '@vOboro_0204「你落选了凯瑞亚一角；你和主演折原冰狐关系很好；你为了与她同台，才立志成为演员；还有……甚至连你落选的理由，我也知道。」',
    "Script/scenario05_10.binu8@81288": '@vRairai_0506「你、你们，正试图作出错误的解读！所以才有必要纠正你们的价值观。怎么样？感觉像被泼了一盆冷水吧？这下总该冷静一些了吧？」',
    "Script/scenario05_3.binu8@84666": '@vKohaku_0558「我想更多、更多地了解那种感情。我想知道爱一个人是什么感觉。即使牺牲其他一切，奥丁也有无论如何都想守护的东西。我想亲身体会那份心情。」',
    "Script/scenario05_2.binu8@68069": '@vRize_0545「不，我不知道。无论是您的想法，还是洛基的想法，我全都不明白。但是，有一个事实是明确的：我是侍奉这个国家的骑士；如果洛基要举起反旗，我就必须讨伐洛基。」',
    "Script/scenario04_5.binu8@87586": '@vFutaba_0563「我的故事，不能再这样开始下去！当个配角又算什么——但凡是让天使酱不幸的故事，我就绝对不会承认。休想让它开始！！」',
    "Script/scenario05_8.binu8@72719": '@vMeguri_0737「……留宿是上周末的事。不过，根本没有什么特别的气氛。只是请他陪我留在那里练习演技而已。牙刷……是那时候忘下的。」',
    "Script/scenario05_3.binu8@74230": '@vMeguri_0465「说实话，我也不知道。本来我还打算亲自教她很多东西……可座长把琥珀抢走了。还说什么‘交给我吧’。明明我更擅长教人。」',
    "Script/scenario05_7.binu8@91007": '@vOboro_0248「那个故事里的洛基，充满了爱与美德。她相信着自己的义兄弟奥丁，一次又一次地相信，直到彻底相信……最后沉溺于自己的爱。即使渴望复仇，即使身陷生命危险，她对奥丁的爱也始终优先。」',
    "Script/scenario06_1.binu8@94574": '@vMeguri_0996「谁知道呢。奈奈菜还有偶像这条路……理世也曾经放弃过演员之路。她不一定会永远陪着我。就连琥珀……也可能有一天被别的剧团挖走。」',
    "Script/scenario06_1.binu8@96163": '@vMeguri_1000「但你说得对。消沉可不像我……我不能永远迷惘下去。既然菲莉亚演出成功了，就必须开始筹划下一部戏。」',
    "Script/scenario06_4.binu8@78324": '@vMirai_0470「……如果真的热爱戏剧，就不会产生这种想法。爱是一种无偿的冲动。热爱戏剧、陷入疯狂的人，会理所当然地为了百分之一而舍弃百分之九十九，甚至会甘愿享受痛苦。」',
    "Script/scenario06_9.binu8@27905": '@vRize_1209「不过，像这样在回家路上分享观后感，正是戏剧的乐趣所在。走出剧场，漫步在无人的街道，聆听夜晚的声音。这样一来，各种情感就会涌上心头，对戏剧的感情也会满溢而出。」',
    "Script/scenario04_4.binu8@83013": '　如果白坂小姐愿意一起去，场面上也会更好看……吧？',
    "Script/scenario04_4.binu8@89145": '　王海先生保持着一贯的严峻表情，一动不动地看了我好一会儿。',
    "Script/scenario04_4.binu8@93267": '　我也不知道。@n　就连白坂小姐也不知道。',
    "Script/scenario04_5.binu8@68752": '@vFutaba_0506「我的眼中，从来就没有天使酱以外的人。」',
    "Script/scenario04_6.binu8@58922": '@n　——最终评审中要饰演的角色，是凯瑞亚。',
    "Script/scenario04_6.binu8@72660": '@vOboro_0204「你落选了凯瑞亚一角。你和主演折原冰狐关系很好。你为了和她同台，才立志成为演员。还有……甚至连你落选的理由。」',
    "Script/scenario04_6.binu8@73706": '@vOboro_0206「呐，你知道为什么箱鸟同学会被安排演凯瑞亚吗？如果是最爱折原冰狐的你，明明应该还有更合适的角色才对。」',
    "Script/scenario04_6.binu8@75161": '@vOboro_0211「她把亲哥哥当作垫脚石，华丽地完成了出道。她最初的牺牲者，就是濑和君。你对他多少抱有感情……所以无论如何都无法原谅这件事。」',
    "Script/scenario04_6.binu8@78048": '@vRize_0491「所以，把凯瑞亚一角交给我的，是那个孩子。从我们决裂的那天起……她就打算让我来演凯瑞亚。」',
    "Script/scenario04_6.binu8@78662": '@vOboro_0215「即便如此，凯瑞亚这个角色果然还是很适合你。正因为你固执又理性，才适合成为审判荒谬之物的人。」',
    "Script/scenario04_7.binu8@43579": '@vRize_0523「我想和濑和君、冰狐……和大家一起，创作出精彩的戏剧。」',
    "Script/scenario04_7.binu8@44087": '@vRize_0526「我确信，冰狐是真心渴求那一刻。她真心希望被我……以凯瑞亚的身份杀死。为了完成最棒的戏剧，为了展现逼真的演技，她简直把性命都献上了。」',
    "Script/scenario04_7.binu8@45315": '「兰比里斯剧团就是你的归宿吧。既然是以追求终极自我满足为目标的剧团，应该能创造出你想要的东西。」',
    "Script/scenario04_7.binu8@46619": '　我能说的，也就到这里了。@n　剩下的，只有接受理世做出的决定。',
    "Script/scenario05_10.binu8@91607": '　我的名字是天乐来来。@n　是兰比里斯剧团的演出家兼演员。',
    "Script/scenario05_10.binu8@93770": '@vRairai_0534「哈！我才不管什么匂宫王海不匂宫王海！那种事和我无关！要是以为一个名字就能吓住我，那可就大错特错了！」',
    "Script/scenario05_11.binu8@77371": '@vRairai_0554「……什么嘛，结果不就是你迷上了悠苑吗。」',
    "Script/scenario05_11.binu8@90411": '@vMeguri_0841「这是我在兰比里斯剧团的最后一场演出。」',
    "Script/scenario05_11.binu8@95312": '@n　——是匂宫，对吧？',
    "Script/scenario06_5.binu8@71906": '@vRize_0890「我不知道毁灭何时会降临。但我已经没有阻止它的办法了。无力的我，既无法引导她们，也无法拯救她们……」',
    "Script/scenario06b_2.binu8@87503": '@vMika_0092「有些孩子，消失之后反而会身价倍增。而在那场只演出一夜的《菲莉亚》中，有人注意到了以游击形式登场的天使奈奈菜。转型做演员？偶像活动呢？周围的人自顾自地议论起来，她的价值也越来越高。」',
    "Script/scenario04_1.binu8@106631": '@vRairai_0343「当然。否则，怎么可能把一个带着创伤、已经引退的演员，拖拖拉拉地留在身边当事务员？如果真想让她开始第二人生，就该干脆支持她走上另一条路才对。」',
    "Script/scenario04_6.binu8@63565": '@vDirectorC_0008「如果因为朋友情谊，就把不合适的人选为凯瑞亚，那就应该重新审视整个企划。还得向相关公司说明：折原冰狐无法胜任卡利古拉。」',
    "Script/scenario05_1.binu8@81148": '@vMeguri_0389「演出日程错开的剧团之间会互相协助宣传。现在我们帮他们宣传，等兰比里斯演出时，再请他们帮我们。」',
    "Script/scenario05_1.binu8@83028": '@vMeguri_0394「艺术之城尼克斯有许多出色的剧团，但其中最稳妥的还是剧团真空！感人的故事、卓越的演技和精彩的结构，一定会让她为之倾倒！」',
    "Script/scenario05_1.binu8@97556": '@vMeguri_0433「那个人总是让我演强大的角色。帅气的主角、锋利的反派。如果祖父还活着……他肯定会演奥丁吧。」',
    "Script/scenario05_11.binu8@90956": '@vcs_TeacherA_0002_b「做出会引起误会的行为，结果还被人抓了个现行……为什么就不能做得更好一点呢。要是只是想恶作剧，本来可以做得更巧妙……为什么偏偏在我当班主任的时候发生这种事……」',
    "Script/scenario06_1.binu8@103378": '@vRize_0744「其实，我原本只打算复出当这一次演员。舞台落幕的瞬间，我觉得已经没有遗憾了。所以以后做幕后工作也好。能够这样积极地想，我已经很满足了。」',
    "Script/scenario06_5.binu8@79175": '@vMeguri_1042「……还是说，你已经讨厌我了？如果你受够了我的任性和傲慢，就直说吧！我……我还想和理世、环一起，继续演更多更多的戏……」',
    "Script/scenario06b_1.binu8@76120": '@vF_StudentA_0009「没错！还有匂宫同学！我到现在还会梦见呢！架桥同学饰演的奥丁王，以及匂宫同学饰演的绝美洛基大人……啊啊，多么唯美的两个人啊！！」',
    "Script/scenario04_4.binu8@92260": '@vHana_0158「光是看着演员们穿上我做的服装时的表情，就会涌起令人愉快的成就感。正因为如此，我才想支持理世酱真正想做的事！」',
    "Script/scenario04_5.binu8@88593": '@vFutaba_0567「——正因为如此，我才被赋予了芬里尔这个角色。即使怀抱着这份憎恨，我也会把它完整地演出来。」',
    "Script/scenario05_12.binu8@89410": '@vOboro_0267「这是名誉的丧失。让这个国家的历史在后世流传时留下耻辱，正是我们贵族最应该恐惧的事。因此，奥丁王，我无法赞成给他人强加莫须有的罪名。」',
    "Script/scenario05_14.binu8@83530": '@vKohaku_0660「直到现在，我仍然从心底珍视着你。那颗纯洁的心，从那时起就没有改变。即使神话从未动摇——我爱过你的事实，也绝不允许任何人否定。」',
    "Script/scenario06_10.binu8@56906": '@vOboro_0305「好了，幸福的美梦也该醒了吧？你已经明白，自己不可能再获得真正的幸福。从这里开始永远延续的所谓幸福，对你而言只不过是地狱。」',
    "Script/scenario06_2.binu8@97635": '@vMeguri_1011「那个不负责任的团长把兰比里斯丢在一边，已经过去一周了。我想大家都对剧团今后的方向感到不安。说实话，我自己也有很多想法。」',
    "Script/scenario06_2.binu8@97929": '@vMeguri_1012「……但答案从一开始就已经明白了。我所希望的，是今后也继续呈现最棒的戏剧。所以……在悠小姐他们回来之前，我想让兰比里斯剧团变得更加强大。」',
    "Script/scenario06b_1.binu8@88612": '@vFutaba_0644「……看着就让人着急。环总是只和其他女孩子亲近……天使酱不但不去妨碍，还只是默默守望。这样下去，这段本来能实现的恋情也实现不了了。」',
    "Script/scenario06b_4.binu8@70893": '@vFutaba_0683「这不是理所当然的吗？这就是所谓的偶像宅。……不过，我自认为还是懂得分寸的。说到底，只要天使酱幸福，那就足够了。」',
    "Script/scenario04_1.binu8@103596": '@vHana_0089「我以为主角是巡酱，拼命做了服装！就连饰演托尔的理世酱也是！为什么完全没人告诉我啊——！？」',
    "Script/scenario04_2.binu8@88749": '@vKohaku_0480「是龙木前辈告诉我的。如果想演那样的女性……首先就应该谈一场恋爱。所以我决定试着恋爱。结果马上就演出来了。」',
    "Script/scenario04_2.binu8@96276": '@vHana_0120「理世酱不太会主动透露自己的事嘛。所以，剧团成员里去过理世酱家的人应该很少！也就只有巡酱吧？」',
    "Script/scenario05_10.binu8@81672": '@vRairai_0507「就只有这种程度！你看啊！我和你对这场演出的心意根本不同！我无论如何都要把它变成杰作！可你却抱着这种程度的觉悟在演！」',
    "Script/scenario05_14.binu8@71726": '@vKohaku_0645「吵死了！别再啰嗦，赶紧去把哪怕一个叛徒也给我砍了！在赢得这场战争之前，不准再出现在我眼前！！」',
    "Script/scenario06b_1.binu8@88217": '@vFutaba_0643「啊——真是急死人了！这种事怎样都好啦！这不就等于平时一直在告白吗！怎么看都肯定是喜欢啊。真叫人生气……真叫人生气！！！」',
    "Script/scenario06b_6.binu8@70739": '@vFutaba_0707「嗯——首先从脚踏实地的网络活动开始。勤快地发布可爱的照片，逐步积累关注度。当然要参加试镜，也必须积极参加角色扮演活动和同人展。」',
    "Script/scenario06b_2.binu8@87229": '@vMika_0091「……奈奈菜离家出走、偶像活动暂停之后……出乎意料的是，仍有许多粉丝在等她。在这个很容易被遗忘的世界里，这可是非常罕见的事。」',
    "Script/scenario04_2.binu8@82967": '@vHana_0115「先去买理世酱喜欢的点心吧！多买一些，然后直接上门发动惊喜攻击——！」',
    "Script/scenario04_2.binu8@85595": '@vMeguri_0357「他憎恨的，是北欧神话本身。那些与他们同名的神明愚蠢地走向毁灭的故事，他无法容忍。所以奥丁王才下定决心，要为毁灭神话而战。」',
    "Script/scenario04_5.binu8@89003": '@vFutaba_0568「正因为是我自己，才有意义。正因为我真心喜欢天使酱，才能把她演出来。既然如此，我就能战斗。让我用这副身体，讲述这个荒谬的故事吧。」',
    "Script/scenario05_13.binu8@66203": '@vMeguri_0877「……啊，是啊。这就是我所认识的奥丁王。所有人都说你已经彻底变了，可你果然还在这里。唯有这一点，是无可置疑的真相。」',
    "Script/scenario05_14.binu8@67931": '@vRize_0719「我的工作是监视你。不过，我的看守并不完美。而且，洛基……我不想亲手舍弃我珍爱的朋友。」',
    "Script/scenario05_14.binu8@85830": '@vFutaba_0629「这算什么北欧神话！竟敢侮辱我敬爱的父亲！把我深爱的家人还回来！都是因为你，大家才会变得不幸！！」',
    "Script/scenario05_4.binu8@63882": '@vYuuen_0182「果然是演员啊。太好了。那么，我有件事想拜托你……能不能请你来帮忙演出？我们正因为人手不足而发愁呢。」',
    "Script/scenario05_5.binu8@69712": '@vMeguri_0567「随着时间流逝，我体内的怪物开始露出面目。看不见的恶魔削磨着我的良心，又用爪子抓挠你的面具。啊，可即便如此！只要你在这里，我就还能忘记一切，还能继续当洛基。」',
    "Script/scenario06_10.binu8@56008": '@vOboro_0303「如果你真的已经满足，就不可能容许我的存在。你是空想剧场的指挥者，只要你挥动指挥棒，我的存在就会成为你不幸的证明。」',
    "Script/scenario06_10.binu8@56546": '@vOboro_0304「你一直都在迷惘。如此纯洁、热爱正义的你，不可能忘记罪恶感。正因为你是这样的人，我才一直支持着箱鸟同学。」',
    "Script/scenario06_5.binu8@82989": '「我说了，巡可以暂时保留意见！可要是我和理世都留在剧团，肯定会变成大麻烦！我们会在大家面前接吻，会卿卿我我、黏黏糊糊，碍眼得不得了！这肯定会妨碍剧团吧！？」',
    "Script/scenario06b_6.binu8@69587": '@vFutaba_0703「……嗯。确实，SNS上发布的照片和视频看起来像是专业人士拍的，服装也花了不少钱。那种水平，靠个人力量根本不可能做到。」',
    "Script/scenario04_5.binu8@85568": '@vMirai_0289「你的心意不是为了被人利用，也没有必要特意去品尝被夺走的痛苦。别人明明自私到这种程度，你为什么还能如此认真、如此纯洁呢？」',
    "Script/scenario05_10.binu8@81672": '@vRairai_0507「就只有这种程度！你看啊！我和你对这场演出的心意根本不同！我无论如何都要把它变成杰作！可你却抱着这种程度的觉悟在演！」',
    "Script/scenario05_13.binu8@74047": '@vMeguri_0895「被奥丁驯服的猪。你那双监视一切的眼睛，究竟从什么时候开始变得浑浊了？你所爱的一直都是疯子的妄想。」',
    "Script/scenario05_4.binu8@77506": '@vRairai_0449「啊，是啊。我就是这么随便的人。所以你也随便努力就行了，别去在意那个老头。那种事……已经和现在的你无关了。」',
    "Script/scenario05_4.binu8@86095": '@vMeguri_0560「洛基直到最后，都深爱着那个夺走家人、迫害自己的奥丁。她相信着义兄弟之间的羁绊。可奥丁却杀了洛基，舍弃了那份心意。既然知道这样的结局，她又怎么还能爱着奥丁呢？」',
    "Script/scenario05_7.binu8@76084": '@vFutaba_0584「差不多就好。老实说，一想到这是男人的房间我就想吐，但只要无视环的存在，这里其实还挺舒服的。自从红色房间的练习之后，我偶尔会过来一下。」',
    "Script/scenario05_8.binu8@72719": '@vMeguri_0737「……住在那里是上周末的事。不过，什么特别的事都没有。只是请他陪我住下来练习演技而已。牙刷……是那时候忘在那里的。」',
    "Script/scenario05_9.binu8@92064": '@vTeacherA_0009「我不是说你可以为所欲为。禁止在校内进行宣传活动以及类似行为。想做的话就到校外去。另外，不要让匂宫太引人注目。」',
    "Script/scenario06_1.binu8@79910": '@vMirai_0476「我想要你救救我。我想要一个能够分担同样痛苦的朋友。我想在这个疯狂的世界里，一边诅咒一切，一边和你待在一起。因为如果不是一个人，我也许就能撑下去！」',
    "Script/scenario06b_1.binu8@88217": '@vFutaba_0643「啊——真是急死人了！这种事怎样都好啦！这不就等于平时一直在告白吗！怎么看都肯定是喜欢啊。真叫人生气……真叫人生气！！！」',
    "Script/scenario06b_7.binu8@33612": '@vFutaba_0730「重要的是性癖。只要撒下不仅能挑起男性、连女孩子也会感兴趣的要素，自然就会扩散开来吧。……所以说。」',
    "Script/scenario04_1.binu8@81950": '@vMirai_0156「哥哥自从被安排去演那个不适合他的角色，就彻底不行了呢。只是碰巧成功了一次，就开始得意忘形。唉，他接下来究竟打算怎么办呢。」',
    "Script/scenario04_1.binu8@93615": '@vMirai_0184「啊，不过我好像稍微明白了。大家都和理世小姐一样，没有把百分之百的努力倾注在眼前的事情上。所以，才会演出那种无聊透顶的东西。」',
    "Script/scenario04_2.binu8@90009": '@vKohaku_0483「我把环君当成卡利古拉，试着演了一遍。所以，我觉得自己展现出了温柔的爱。之所以没能深入演出塞佐尼娅，是因为只有爱还不够，对吧？」',
    "Script/scenario04_4.binu8@72451": '@vOboro_0176「——想象一下自己被肌肉发达的男人抱住，你真的会毫无感觉吗？濑和君，我想说的就是这个。这才叫正常，是漂亮话背后的真心。」',
    "Script/scenario05_1.binu8@76313": '@vRairai_0363「你缺少的，是内心深处的孤独。因此你必须知道，必须理解——头顶闪耀的月白之光，以及得到那轮月亮的方法。」',
    "Script/scenario05_1.binu8@86152": '@vMeguri_0400「我也是演员嘛。演这种戏可是我的拿手好戏。如果你实在丢不下羞耻心，就试着把这当成自己的角色吧？」',
    "Script/scenario05_1.binu8@95043": '@vMeguri_0424「……可一旦不再需要我，他就把我丢在一边，只和自己喜欢的成员创办了兰比里斯。隐居？别开玩笑了。他根本就是个不把家人放在心上的人。」',
    "Script/scenario05_10.binu8@94173": '@vOmi_0038「来来！你就是想得太多了！用灵魂去触碰角色！把那些投机取巧的演技全丢掉！既然是学生，就演出学生特有的青涩！」',
    "Script/scenario05_13.binu8@78814": '@vMeguri_0901「……我闻到了死亡与傲慢的气息。辛酸灼烧着我的身体。啊啊，我快要疯了。真希望一切就这样结束。」',
    "Script/scenario06_3.binu8@62224": '@vRize_0805「别再为无法改变的事，以及多余的事情烦恼了。趁你睡着的时候，我会陪在你身边。」',
    "Script/scenario06_7.binu8@99513": '@vRize_1056「我、我也是啊！？我不想为这种事絮絮叨叨，也不想让你觉得我是个麻烦的女人！可即便如此，我还是希望你把它处理掉。」',
    "Script/scenario06b_1.binu8@80026": '@vNanana_0422「虽说是偶像，其实也只是曾在网上小小走红过而已。我既没有所属的事务所，也没有组建什么团体。」',
    "Script/scenario06b_4.binu8@80434": '「我本来想过总有一天要由我来说。但我又觉得，那是不是一句不该说出口的话。没想到……竟然是奈奈菜主动向我表明了跨过那条界线的觉悟。」',
    "Script/scenario04_4.binu8@89273": '　她会责骂那个没能跟上严苛训练的我吗？@n　还是会轻蔑地看着我，认为我是个因为这点程度就夹着尾巴逃跑的娇气女人？',
    "Script/scenario04_6.binu8@64226": '@vMirai_0313「——我想要真正的凯利亚。一个逻辑清晰、现实主义，能够亲手杀死暴走的卡利古拉、可以把落幕托付给她的人。」',
    "Script/scenario05_4.binu8@82655": '@vMeguri_0549「座长说，我的演技会被琥珀压过去。确实，那孩子的演技是一流的，这点我也承认。……但是！」',
    "Script/scenario05_5.binu8@69712": '@vMeguri_0567「随着时间流逝，我体内的怪物开始露出面目。看不见的恶魔不断削磨我的良心，又用爪子抓挠你的面具。啊，可即便如此！只要你在这里，我现在仍然能够忘记一切，仍然能够继续当洛基。」',
    "Script/scenario05_4.binu8@83541": '@vMeguri_0551「我也是这么想的。但是……我总觉得那孩子不会就这样结束。该说是暴风雨前的宁静吗……我不禁觉得，接下来或许会看到什么可怕的东西。」',
    "Script/scenario05_14.binu8@77372": '@vOmi_0042「无论是因为指导过度而把演员逼上死路，还是对巡施以残酷的教育，我都没有后悔。因为我认为自己应该那么做，所以才采取了行动。」',
    "Script/scenario06b_6.binu8@71083": '@vFutaba_0708「需要摄影师。要找就得找一个理解性癖、又有能力的摄影师……不过，我也不是不能亲自来。总不能让哪个不知名的男人来拍天使酱吧。我可是去过很多次偶像摄影会，对相机的操作很有自信，肯定比一般外行拍得好。」',
    "Script/scenario05_14.binu8@77817": '@vOmi_0044「我只是在拼命努力，想成为一个正确的人。我遵循这份信念，是因为我相信那样做是正确的。若要为自己的过错后悔，反而是对那份过错的亵渎。」',
    "Script/scenario05_7.binu8@91386": '@vOboro_0249「啊，喜欢到甚至想亲自演演看。再说，如果奥丁由架桥小姐出演，那么作为她的对手，确实只有匂宫小姐最合适。换作我，实力实在不够。」',
    "Script/scenario05_14.binu8@82793": '@vMeguri_0921「够了！你根本不知道我的感受，居然还说得出口！啊啊，我为什么会变成这样！面对杀害家人的仇人，我甚至连剑都拔不出来！我竟然把你那双野蛮的眼睛，和昔日的你重叠在了一起！啊啊，对不起，我亲爱的孩子们！我真是个不合格的父亲！」',
    "Script/scenario04_4.binu8@81689": '「不、不是……不能就这样把现在这种状态的理世带回去。」',
    "Script/scenario04_4.binu8@87447": '　这座由巨匠匂宫王海创立的剧团，起初还备受瞩目。然而，他们上演的戏剧评价普遍低迷，很快便开始承受越来越冷漠的目光。',
    "Script/scenario04_6.binu8@80143": '@n　——因为你用蛮不讲理的方式，排除了自己憧憬的濑和君。',
    "Script/scenario04_7.binu8@41026": '　平淡无奇的日常片段。@n　就连当事人自己，也不确定是否还记得。',
    "Script/scenario04_7.binu8@42830": '「……我已经不得不放弃了。因为我明白自己无法继续下去……也终于能够斩断留恋。」',
    "Script/scenario04_7.binu8@43846": '@vRize_0525「濑和君放弃了戏剧……冰狐拒绝了我，把自己的一切都献给了戏剧……我已经完全不明白了。为什么？为什么？我不明白这一切究竟有什么意义。」',
    "Script/scenario04_7.binu8@48262": '@vFutaba_0574「当、当然！我可不能拖天使酱的后腿！」',
    "Script/scenario05_1.binu8@78453": '　他以导演见习生的身份提出想法和意见，但演技指导及整体进度，则是座长和匂宫的工作。',
    "Script/scenario05_1.binu8@93836": '「……我记得他是以严格的指导出名的。甚至因为斯巴达式教育，一度闹出过问题。」',
    "Script/scenario05_10.binu8@72133": '　要把至今为止活过的岁月当成徒劳……我为此付出的实在太多了。',
    "Script/scenario05_10.binu8@73546": '@vMeguri_0799「……你还真是说得够狠的。喂，理世……我的演技真的有那么糟吗？」',
    "Script/scenario05_10.binu8@73794": '@vRize_0657「……确实不像平时的巡。不过……你才刚复出，还没有恢复到最佳状态而已……」',
    "Script/scenario05_9.binu8@90080": '@vTeacherA_0003「——所以，学校方面也对此非常为难。我们并不是说男女交往本身有错，但必须以有分寸的方式相处。」',
    "Script/scenario06_1.binu8@104750": '@vRize_0748「必须为有人愿意支持自己而感到幸福。也许，比起为自己演戏，我果然更适合为了某个人而演戏。」',
    "Script/scenario06_10.binu8@60238": '@vOboro_0314「箱鸟同学，我知道你是一个懂得爱的人。我想，我们爱着的，或许是同一种真相。」',
    "Script/scenario06_2.binu8@103149": '@vMeguri_1025「无论你说什么，这孩子入团的决定都不会改变。因为这里是兰比里斯剧团，是一个无论老手还是门外汉都欢迎、将终极自我满足化为现实的地方。」',
    "Script/scenario06_2.binu8@104037": '@vMirai_0417「不是‘呃’啦。我好像以前也说过……我是没有演技经验的门外汉，比那边的天使酱还要笨拙。」',
    "Script/scenario06_4.binu8@77277": '@vMirai_0467「普通人和朋友玩得很开心时，理世小姐却在排练室里含着泪，被人不断斥责。她还要忍受周围毫无根据的恶言，在脑中一遍又一遍刻下自己并不喜欢的故事。」',
    "Script/scenario06_5.binu8@74038": '「她能为了某个人哭泣，也愿意为了某个人留在身边。那家伙之所以把理世视为特别，或许就是看穿了她的这些特质。」',
    "Script/scenario06_6.binu8@78553": '@vFutaba_0783「环，你究竟喜欢上箱鸟同学哪一点？果然是胸部吗？还是胸部？男人真恶心，难道你只是看中了她的身体？」',
    "Script/scenario06b_2.binu8@73774": '@vFutaba_0666「……但我认为确实存在这种可能。天使酱以惊人的势头走红，还登上了杂志……当时势头真的很强。所以我才会拼命支持她。」',
    "Script/scenario06b_2.binu8@80042": '@vReiji_0072「别把我至今为止的恩情当成仇来报。你只要像以前一样听你母亲的话就行了。……不过，随你喜欢吧。该说的我确实已经说过了，对吧？」',
    "Script/scenario06b_3.binu8@82089": '@vNanana_0524「好可怕。好可怕，好可怕，好可怕。因为你很聪明，也很敏锐——我害怕你会看穿这样的我，和我的心情。」',
    "Script/scenario06b_6.binu8@62327": '@vNanana_0737「我、我想起来了……！小时候憧憬过的东西……我想再一次，再一次试试看……！」',
    "Script/scenario04_1.binu8@109873": '@vMeguri_0343「嗯，当然。我和其他人不同，对匂宫王海所追求的东西没有兴趣。我在意的，只有我们自己所追求的戏剧。」',
    "Script/scenario04_4.binu8@69539": '@vOboro_0166「天使小姐和仓科小姐在剧中饰演兄妹。为了自然地演出亲密的兄妹，两人尽可能多地共享时间。因为剧本希望她们这样做。」',
    "Script/scenario04_4.binu8@71211": '@vOboro_0171「如果是男女关系，事情大概不会变得这么复杂。想继续现在的关系，等演出结束后告白就好。但她们不一样，和普通情况有些不同。」',
    "Script/scenario04_5.binu8@76357": '@vMirai_0260「只要你许愿，这个世界就会被改造成能实现愿望的模样。创造这个世界的神，为人类准备了一条温柔的道路。」',
    "Script/scenario04_6.binu8@75569": '@vOboro_0212「曾经最喜欢轻松愉快戏剧的你……却把她的做法、戏剧，以及一切都恨之入骨。即便如此，你为什么还想和她同台？啊，我明白了……你是想亲手彻底击溃她吧。」',
    "Script/scenario05_12.binu8@87340": '@vKohaku_0614「忘却夏日的冬天，连续三次降临。突如其来的大饥荒令众人陷入恐慌。家人彼此相残，亲族之间犯下不伦。无血无泪之事接连成为现实，淫乱也堂而皇之地横行。」',
    "Script/scenario05_14.binu8@71726": '@vKohaku_0645「吵死了！别再啰嗦，赶紧去把哪怕一个叛徒也给我砍了！在赢得这场战争之前，不准再出现在我眼前！！」',
    "Script/scenario05_3.binu8@72524": '@vMeguri_0460「我被祖父折腾得够呛。他把家里的事丢在一边，以为只要给钱就够了。和孩子们之间，连一段回忆都没有。至于母亲……她到现在还恨着祖父。」',
    "Script/scenario06_1.binu8@104445": '「所以，别再说这种悲伤的话了。别说什么要退出演员之路。你有才华，也有吸引别人的魅力。所以……」',
    "Script/scenario06_2.binu8@87662": '「怎么可能做到啊。假的我，怎么可能变成真的我？可是妈妈说我做得到。她一边展示着未来的演技，一边对我说我一定做得到。」',
    "Script/scenario06_4.binu8@72550": '@vRize_0829「妈妈的熟人擅自替我报名参加了舞台童星的试镜……我没办法，只好去试了一下，结果竟然通过了……」',
    "Script/scenario06_4.binu8@74771": '@vMirai_0458「当然。别看她那样，冰狐可是非常勤奋好学的。对于同世代、比自己更早活跃起来的童星，她全都了如指掌。」',
    "Script/scenario06_4.binu8@77582": '@vMirai_0468「随着正式演出临近，我快被父母和周围人的期待压垮，连晚上都无法好好睡觉。没有任何能让灵魂休息的时间，只能一边消磨灵魂，一边埋头钻研角色。可同龄的女孩子却在平凡地恋爱，和男朋友享受青春。太不公平了！」',
    "Script/scenario06_5.binu8@63164": '@vRize_0860「……我觉得在这里，我可以坦率一些。所以，我想请濑和君听听我的心里话——那个忘记了漂亮话的、丑陋的真心。」',
    "Script/scenario06_5.binu8@67043": '@vRize_0876「……为了伟大的戏剧，有些心意注定会被践踏。热爱戏剧的人，会为了演技，牺牲自己珍视的东西。」',
    "Script/scenario06b_5.binu8@22510": '@vNanana_0709「要是我变成了假人，该怎么办？要是我不是妹妹……我总觉得，环君就会离我而去。」',
    "Script/scenario04_4.binu8@73943": '@vOboro_0181「我一直害怕着那个‘也许会发生’的未来。爱上同性，就是要与这样的矛盾不断抗争。」',
    "Script/scenario05_13.binu8@72226": '@vMeguri_0891「叫我安静？芙蕾雅，你怎么能说出这么愚蠢的话。希望一切平安无事地过去的，明明是我才对。扰乱这个国家的暴风雨不是我——是你们啊！」',
    "Script/scenario05_13.binu8@76648": '@vRize_0701「你应该明白。现在，我们彼此都还在这里。我对这一刻，丝毫没有后悔。」',
    "Script/scenario05_13.binu8@80077": '@vYuuen_0226「不是那样。因为现在……我已经能和这些为我们展现如此精彩演技的孩子们，共同完成一场演出了。」',
    "Script/scenario05_13.binu8@83183": '@vMeguri_0922「我现在仍然会忍不住许愿！希望你变回那个温柔的自己，重新抱住我！希望你变回我最喜欢的奥丁，再对我露出笑容！」',
    "Script/scenario06_4.binu8@75598": '@vMirai_0462「事到如今才说什么‘回想起来还挺开心’、‘很有成就感’，也只是马后炮罢了。被推入自己不想要的世界，所有空闲都被剥夺，整天沉浸在戏剧里……我真的能说那是幸福吗？」',
    "Script/scenario06_4.binu8@77044": '@vMirai_0466「想想看，你为了短暂的感动失去了什么？为了百分之一的幸福，承受了百分之九十九的痛苦。我不想把那种经历说成什么美谈。」',
    "Script/scenario06_5.binu8@71556": '@vRize_0889「……可是，只要追求至高，那些孩子就会不断受伤。我已经见识过把自己交给疯狂的戏剧，也已经知道该如何把人逼到极限之外。」',
    "Script/scenario06b_4.binu8@69771": '@vFutaba_0678「啊，真令人火大。我明明一直在驱赶那些想接近天使酱的害虫……没想到最棘手的害虫，竟然就在离她最近的地方……！」',
    "Script/scenario06b_4.binu8@73435": '@vFutaba_0692「……天使酱可是偶像啊。而且还是天生的天使。她拥有被所有人喜欢的才能，所以这并不奇怪。」',
    "Script/scenario06b_4.binu8@74182": '@vMeguri_0973「是吗。不过也别太拼命了。你眼睛下面都淡淡地出现黑眼圈了。之后记得好好遮住。」',
    "Script/scenario06b_6.binu8@70106": '「……老实说，我觉得这很难。在竞争激烈的世界里，奈奈菜究竟能走到什么程度……但这是她自己主动说想做的事。作为哥哥，我想尊重妹妹的意愿。」',
    "Script/scenario06b_7.binu8@35936": '「不，奈奈菜的魅力在于她的清纯吧！比起什么角度不角度的，首先应该改变营造出来的氛围！可爱的孩子，不如让她拿着花之类的？」',
    "Script/scenario06b_6.binu8@76422": '@vNanana_0753「那、那么！拜托你，只有今天，只有今天可以吗？从明天开始，我会努力当好偶像的……！」',
    "Script/scenario04_1.binu8@85310": '@vMirai_0167「不如让我把哥哥当成垫脚石吧。让失败的哥哥退场，由妹妹代替他挑战残酷的演艺圈……这种故事应该会很受欢迎。」',
    "Script/scenario04_5.binu8@66936": '　平时总是神情凛然的理世小姐，此刻却涨红了脸，气势汹汹地反驳着。@n　那个男人到底做了什么？',
    "Script/scenario04_5.binu8@86283": '@vMirai_0291「你也可以再多受到一点重视，再多被人关心一点啊。可即便如此，周围的人还是把你丢在一边。你辛苦坚持下来，等着你的却是配角的人生。差不多也该编织一部以你为主角的故事了吧。」',
    "Script/scenario05_1.binu8@89638": '@vNanana_0298「但、但是！今、今天是休息日……我还特意换上了便服……所以，也不能说我完全不在意……」',
    "Script/scenario05_11.binu8@104573": '@vHana_0235「……座长先生只能用这种方式来引导大家。那个人笨拙、不成熟又傲慢，还是个无可救药的阴沉家伙……他只知道用粗暴的方法。」',
    "Script/scenario05_12.binu8@90762": '@vaudienceA_0001「不可能。那个女孩究竟是什么人！没想到竟然有人能展现出比匂宫巡更有压迫感的演技——！！」',
    "Script/scenario05_13.binu8@73897": '@vRairai_0591「如果暴力对我完全不受限制，我现在就会把您的四肢撕成八段。」',
    "Script/scenario05_13.binu8@80809": '@vRize_0712「奥丁大人已经变了。染指贵族的妻女，沉溺于色欲之中。民众的不满接连不断，也是理所当然。正如您所说，叛乱恐怕真的会发生。」',
    "Script/scenario05_3.binu8@72230": '@vMeguri_0459「他沉迷于演戏，完全不顾家庭。一察觉孙女有才华，就半强迫地把超斯巴达式的英才教育强加给她。可一感到自己老了，又隐居起来，随心所欲地创办剧团。」',
    "Script/scenario04_4.binu8@82347": '「……我觉得事态变得更加棘手了。」',
    "Script/scenario04_4.binu8@87447": '　这座由巨匠匂宫王海创立的剧团，起初还备受瞩目。然而，他们上演的戏剧评价普遍低迷，很快便开始承受越来越冷漠的目光。',
    "Script/scenario04_5.binu8@85009": '@vMirai_0287「……那未免太过纯粹了。这样的想法……一定会让你变得不幸。」',
    "Script/scenario04_5.binu8@87586": '@vFutaba_0563「我的故事，绝不能再这样开始下去！当个配角又算什么——但凡是让天使酱不幸的故事，我就绝对不会承认。休想让它开始！！」',
    "Script/scenario04_7.binu8@43846": '@vRize_0525「濑和君放弃了戏剧……冰狐拒绝了我，把自己的一切都献给了戏剧……我已经完全不明白了。为什么？为什么？我不明白这一切究竟有什么意义。」',
    "Script/scenario05_1.binu8@78453": '　他以导演见习生的身份提出想法和意见，但演技指导及整体进度，则是座长和匂宫的工作。',
    "Script/scenario06_4.binu8@70426": '@vMirai_0446「对冰狐来说，理世小姐是让她得以证明自己正当性的象征。在那个世界里，只有理世小姐和冰狐怀着同样的想法。」',
    "Script/scenario06_2.binu8@88085": '「他看着那样的我，像是毫无兴趣似的说‘真可怜啊’。啊啊，光是回想起来就快让我发疯了。他那冷漠的表情，一点一点地磨损着我的心。」',
    "Script/scenario05_3.binu8@71602": '@vMeguri_0457「恰恰相反。是我说服了理世，设法让她加入剧团的。不管她本人拒绝得多么坚决，只要是理世或悠苑开口请求，我就无法拒绝。」',
    "Script/scenario05_3.binu8@80730": '@vKohaku_0541「他对我指手画脚，让我做这做那，却连示范都不肯给我看。还说什么‘你不可能做到’。这不残忍吗？明明是在逼我做根本做不到的事。」',
    "Script/scenario05_6.binu8@84796": '「我父母以前曾加入过一家知名歌剧团。所以他们对戏剧非常严格……我成功的时候，他们对我还很温柔；可随着我的前途开始显露，他们对我的态度也越来越糟糕。」',
    "Script/scenario05_6.binu8@96342": '@vMeguri_0693「花，你就是太过于讲究了。之前做的那些服装，不是全都废掉了吗？明明那样已经很棒了。」',
    "Script/scenario05_7.binu8@79681": '@vFutaba_0589「哈！？明明摆出一副无所不能的气势，结果竟然这么不像话！为什么会断货啊——！」',
    "Script/scenario05_8.binu8@71622": '@vMeguri_0733「那把牙刷是我的！正如你想的那样！所以，求你了，千万别告诉妈妈！」',
    "Script/scenario06_1.binu8@83834": '@vF_StudentA_0012「……嗯！演奥丁的孩子和演洛基的孩子！这两个人真的太厉害了！」',
    "Script/scenario06_3.binu8@52507": '@vMirai_0428「……所以我才说了嘛。我就是个普通人。别把我和什么天才相提并论。」',
    "Script/scenario06_6.binu8@76254": '@vFutaba_0775「也就是说，被人听见了。要告白的话，请考虑一下时间和地点。环丢脸倒是无所谓，可箱鸟同学太可怜了。她现在肯定正被班上的女生问各种问题吧。」',
    "Script/scenario06b_1.binu8@88891": '@vFutaba_0645「享受受欢迎的感觉或许很开心！但如果你真为对方着想，就赶紧拒绝这个注定没戏的女主角吧！否则天使酱永远都无法开始下一段恋情！」',
    "Script/scenario06b_2.binu8@70064": '@vNanana_0446「不、不算不行……！可是，就算是原创，要擅自修改戏剧之神的剧本，也实在太不敬了……！！」',
    "Script/scenario06b_2.binu8@82542": '@vFutaba_0673「能帮助天使酱的人，只有环。请你狠狠地多管一次闲事吧！」',
    "Script/scenario06b_2.binu8@84889": '@vMika_0085「对不起，我做了过分的事。我只是有些余裕不足，所以才说了违心的话。请你原谅我。」',
    "Script/scenario06b_5.binu8@19634": '　两人是可以靠近到互相触碰、也不会被责怪的关系。@n　然而，正是这份自由，反而激起了让人踌躇不前的奇妙情感。',
    "Script/scenario06b_7.binu8@76422": '@vNanana_0753「那、那么！就拜托你，只有今天，只有今天可以吗？从明天开始，我会努力当好偶像的……！」',
    "Script/scenario04_1.binu8@103923": '@vHana_0090「什么叫‘请多关照’！连我都气炸了！这事我可要当面问个清楚了哦！？」',
    "Script/scenario04_4.binu8@73213": '@vOboro_0178「是啊。旁观者总会说出自己觉得方便的妄想……但对当事人来说，并不是那么回事。」',
    "Script/scenario04_4.binu8@73395": '@vOboro_0179「那个孩子是个很棒的人。所以，她或许不会接受这份心意，但应该不会感到厌恶，也不会拒绝对方。」',
    "Script/scenario04_5.binu8@84660": '@vFutaba_0557「我想要的是天使酱本人！除此之外什么都不要！如果天使酱不是真心爱我——这种妄想我才不要！！」',
    "Script/scenario04_5.binu8@86723": '@vMirai_0292「是吗？我觉得不管是谁，包括你，都有成为主角的机会。这次的虚构也是一样。在编织出的世界里……毫无疑问，你就是故事的主人公。」',
    "Script/scenario04_6.binu8@74053": '@vOboro_0207「当然，这一点你现在也明白了吧。把当时的话和眼前的结局放在一起比较，就很明显了。」',
    "Script/scenario04_7.binu8@41295": '　所谓决定，会大幅左右人生。@n　正因如此，必须慎重选择，不能让自己留下悔恨。',
    "Script/scenario05_10.binu8@70992": '　和他相处的时光，只是单纯的奖励。@n　我只是想挺起胸膛说，正因为有他，我才能演得更好。',
    "Script/scenario05_10.binu8@87152": '@vMeguri_0816「如果你想要一个不幸的我，我就演给你看。谢谢你的演技指导。」',
    "Script/scenario05_11.binu8@103925": '@vHana_0232「我最喜欢这里了。我由衷觉得，能加入这个剧团真是太好了。因为这里有好多美好的回忆！」',
    "Script/scenario05_11.binu8@93046": '　头一阵阵地痛。@n　我好像做了一个非常讨厌的梦……可不知为什么，哪怕一点都想不起来。',
    "Script/scenario05_13.binu8@70898": '　你要伤害那些努力向前走的人吗？@n　就因为自己没能顺利走下去——别因为嫉妒和怨恨去妨碍别人！',
    "Script/scenario05_2.binu8@68069": '@vRize_0545「不，我不知道。无论是您的想法，还是洛基的想法，我全都不明白。但是，有一个明确的事实。那就是，我是侍奉这个国家的骑士；如果洛基举起反旗，我就必须讨伐洛基。」',
    "Script/scenario05_2.binu8@81290": '@vRize_0575「你刚才写在纸上的数字，可是女孩子的最高机密。现在马上忘掉。」',
    "Script/scenario05_2.binu8@88225": '@vOmi_0018「可是，你已经能够放弃了。我觉得那是一件幸福的事。相反，那些家伙是不幸的。他们无法放弃演员这条路……只能死死抓住、拼命挣扎，即使这样也还留在这里。」',
    "Script/scenario05_2.binu8@88531": '@vOmi_0019「已经不能用喜不喜欢这种尺度来衡量了。对他们来说，就只有这一条路。所谓演员，根本不是辞职还是不辞职这种层次的问题。」',
    "Script/scenario05_5.binu8@70861": '「因为爱而纯真，因为纯真而充满爱。我觉得那份甜蜜和温柔，构成了洛基的核心。她非但不会憎恨，反而会试着理解，会试着向对方靠近。」',
    "Script/scenario05_5.binu8@87385": '@vMeguri_0626「我想着说不定会遇到这种事，所以特意穿了安全裤。这样就算被看见也没关系了。」',
    "Script/scenario05_5.binu8@88242": '@vMeguri_0629「不，不是……不过，世上确实有那种被看见也没关系的短裤吧？看起来几乎不像内衣，也没什么色情意味……」',
    "Script/scenario05_7.binu8@78698": '@vRize_0614「……也不算意外吧。自从座长把架桥小姐拉进来以后，他们两个就一直待在一起……」',
    "Script/scenario05_7.binu8@84344": '@vNanana_0351「所以我才会想，这样真的好吗？这个故事在我看来并没有魅力。只有漆黑一片的故事，究竟有价值吗？」',
    "Script/scenario05_7.binu8@92424": '@vOboro_0253「我啊，濑和君。我觉得洛基是真心爱着义兄弟奥丁的。」',
    "Script/scenario05_7.binu8@93083": '@vOboro_0257「但我觉得，他之所以能那样信任奥丁，正是因为有那种特殊的感情。洛基把奥丁置于家人和恋人之上。这一点，是无可动摇的事实。」',
    "Script/scenario05_9.binu8@87980": '　刊登的照片，正是两人挽着手走进家中的瞬间。那种亲密到称不上朋友的距离，以及她进了他的家、直到第二天早上都没有出来的事实，已经说明了一切。',
    "Script/scenario06_1.binu8@84635": '@vF_StudentA_0016「咦、咦咦咦！？不、不会吧……咦？可、可是……在舞台上的时候，完全是另一副样子……」',
    "Script/scenario06_2.binu8@94826": '@vOboro_0287「往好的方面说，箱鸟同学是个杂种。也许正因为如此？她对戏剧的看法和其他人有些不同。正是这点微小的差异，至今以及今后都会产生深远影响。」',
    "Script/scenario06_4.binu8@88116": '@vKohaku_0724「菲莉亚的演出，真的很开心。演完的那一刻，那种无法用语言形容的兴奋感……我想把这份由环君教会我的感受，真心传达给他。」',
    "Script/scenario06_5.binu8@79633": '@vRize_0907「不，不是的。我现在也最喜欢巡了。真的……我一直把她当成家人。所以……这是我们自己的问题。」',
    "Script/scenario06_7.binu8@96290": '「总之只是暂时的。退出剧团后，我就失去了想做的事。所以哪怕只是暂时的，我也想要一个目标。」',
    "Script/scenario06_8.binu8@20670": '@vcs_Rize_0002「嗯……！因为我们好不容易才成为恋人……可你什么都不对我做。」',
    "Script/scenario06b_3.binu8@71546": '@vMika_0119「把他的照片挂在你的房间里吧。每天早上醒来，一边看着他的照片，一边把‘我喜欢你’说出来。每天都不能间断。」',
    "Script/scenario06b_3.binu8@71887": '@vMika_0121「除此之外，只要一有空闲，就无论何时何地都想起他，并试着说出‘我喜欢你’。」',
    "Script/scenario06b_5.binu8@21501": '@vNanana_0704「还有……世上最幸福的一对，是由‘兄妹’这两个字构成的，之类的……」',
    "Script/scenario06b_7.binu8@35936": '「不，奈奈菜的魅力在于她的清纯吧！比起什么角度不角度的，首先应该改变营造出来的氛围！可爱的孩子，不如让她拿着花之类的？」',
    "Script/scenario04_1.binu8@106386": '@vMeguri_0334「我可没听说过！在濑和君提议之前，我根本没考虑过这件事！」',
    "Script/scenario04_5.binu8@70115": '@vOboro_0168「对天使小姐来说，那应该是毫不痛苦的演技。她只会觉得自己多了一个女性朋友。」',
    "Script/scenario04_6.binu8@60804": '@vMirai_0307「没听见吗？还是没听懂？箱鸟同学落选了。所以，现在请你回去。」',
    "Script/scenario04_6.binu8@69781": '　我不知道其他人接受了怎样的评审，但大概和我的情况差不多吧。',
    "Script/scenario04_6.binu8@79191": '@vOboro_0217「折原冰狐……该怎么说呢，她就像我的老师一样吧。」',
    "Script/scenario05_10.binu8@76202": '@vRairai_0492「……真是的。明明这个剧团的事，我比谁都上心。」',
    "Script/scenario05_10.binu8@85165": '@vRairai_0517「那只是学生时代的事。我已经不是当时的我了。对吧？」',
    "Script/scenario05_11.binu8@86166": '@vDirectorA_0003「毕竟那里有个叫天乐来来的坏孩子。那里的演员真可怜啊，恐怕全都会被那个家伙毁掉吧。」',
    "Script/scenario05_14.binu8@73821": '@vKohaku_0652「我从心底憎恨这一点！你们一边以那只是空想和妄想为借口，一边贬低那个名字！你们连背后的真相都不知道，却还把并列的词语当成有附加价值的东西！我恨你们，恨得无法忍受！！」',
    "Script/scenario05_14.binu8@82433": '@vMeguri_0920「没错！你想笑就笑吧！说到底，我根本一点都不了解你！现在的我，已经不知道真正的你是什么样子了！我唯一知道的就是——希望你能陪我把这场闹剧演到最后！」',
    "Script/scenario05_14.binu8@84076": '　我会陪你走到地狱尽头。@n　让我相信，你认为的“为我好”，也就是我的“为我好”。',
    "Script/scenario05_9.binu8@92668": '@vTeacherA_0011「明白了就走吧。幸好……你家有权有势。要是你不是匂宫王海的孙女，可就不会只受到这种程度的处分了。」',
    "Script/scenario06_1.binu8@101254": '@vRize_0734「别把你和我混为一谈。我们获得这里的使用许可，只到今天为止。所以我是在为下一个使用的人收拾场地。」',
    "Script/scenario06_1.binu8@103194": '@vRize_0743「不是那样。正因为我不够认真，才可以毫不犹豫地转身离开。如果我当时能像个笨蛋一样直率……我……」',
    "Script/scenario06_10.binu8@59970": '@vOboro_0313「喜欢究竟是什么呢？爱又是什么？但我觉得……那就是希望对方幸福。」',
    "Script/scenario06_2.binu8@92957": '@vOboro_0280「箱鸟同学很会照顾人呢。她是我最想娶回家的女性第一名，因为她能为别人尽心尽力。」',
    "Script/scenario06_6.binu8@77641": '@vFutaba_0780「你在说什么呀？箱鸟同学从一开始就是一副‘喜欢环、喜欢环、超级喜欢环’的样子。只是不太坦率罢了。」',
    "Script/scenario06b_1.binu8@72582": '@vMeguri_0937「呵呵，是啊。我们还有未来。今后也一起挑战更多的戏剧吧！」',
    "Script/scenario06b_1.binu8@86568": '@vNanana_0435「小时候只交谈过几句而已。这样就足以让你一心一意地喜欢下去吗？」',
    "Script/scenario06b_2.binu8@85591": '@vMika_0087「没关系，已经不用再做那种事了。让我们用正规的方式，以成为偶像为目标吧。所以，回来好吗？」',
    "Script/scenario06b_4.binu8@66816": '@vNanana_0576「……架桥小姐的演技，太厉害了。真的，真的，仿佛要把我整个人吞没了。」',
    "Script/scenario06b_7.binu8@37492": '「说起来，你不考虑尝试动漫角色的Cosplay吗？最近好像也有偶像是靠这个走红的。」',
    "Script/scenario04_3.binu8@64629": '　实力不足、努力不足、觉悟不足。@n　这是一个什么都没能做到的废物，留下的可笑呓语。',
    "Script/scenario04_4.binu8@86837": '　我这个门外汉，就算通过选拔真的没问题吗？@n　入团几个月后，这种想法变得越来越强烈。',
    "Script/scenario04_4.binu8@92768": '　躺在沙发上的本人已经醉倒睡着了。@n　也不知道她到底有没有听见这些话。',
    "Script/scenario04_5.binu8@73669": '　我当时还在想，成为偶像的应该就是这种女孩子吧。@n　我到底得走什么运，才能遇到这么可爱的女孩呢。',
    "Script/scenario04_5.binu8@83359": '@vMirai_0285「嗯，当然。正因为如此，人类才会向虚构之物许愿啊。」',
    "Script/scenario04_7.binu8@46283": '@vRize_0533「这不是能轻易给出答案的事。我可是抱着坚定的觉悟，才决定引退的。」',
    "Script/scenario05_1.binu8@87121": '　即便起因如此随意，只要亲眼看过那场演出，原有的价值观也会被彻底颠覆。',
    "Script/scenario05_1.binu8@93722": '@vMeguri_0419「是祖父负责的。他那时既是座长，也是演出家。」',
    "Script/scenario05_1.binu8@97298": '@vMeguri_0432「琥珀、濑和君，还有双叶和奈奈菜。你们都是我选中的孩子。是连祖父都没能培育出来的全新嫩芽。」',
    "Script/scenario05_11.binu8@73732": '@vYuuen_0200「嗯，确实如此。我本来还拜托他不要让传闻扩散的……真是的，座长先生。」',
    "Script/scenario05_11.binu8@85276": '　我曾听人说过，那是由品行不端、扰乱风纪以及作为演员失败的人们聚集而成的末路。',
    "Script/scenario05_12.binu8@89706": '@vKohaku_0620「真正理解这一点的人啊，巴德尔。没错，历史中的荣誉正是我们迫切需要的东西。历史是映照活着的时间之镜。正因如此——我们必须编织出正确的历史。」',
    "Script/scenario05_12.binu8@92076": '　这不是两个人战斗的故事。@n　也不是点燃怨恨之火的故事。',
    "Script/scenario05_12.binu8@98172": '　只是我的任性恶作剧竟然成功了。@n　只是座长没有责怪我。',
    "Script/scenario05_13.binu8@57716": '@vKohaku_0624「回答我，洛基。我把你的孩子带走，可以吧？」',
    "Script/scenario05_13.binu8@58046": '@vKohaku_0626「……给我一点时间吧。喂，狗，把这个姑娘借我用一下。」',
    "Script/scenario05_13.binu8@58157": '　我茫然地眺望着戏剧的未来。@n　我没有逆着巨浪前进的力量。',
    "Script/scenario05_13.binu8@67188": '@vMeguri_0879「我所爱过的奥丁啊，能否允许我向你的诚实发问？你究竟希望我做什么？我究竟该做什么？」',
    "Script/scenario05_13.binu8@75074": '@vKohaku_0643「……哦？你知道巴德尔死亡的真相吗？」',
    "Script/scenario05_13.binu8@76706": '　看着她的演技，泪水涌上了眼眶。@n　啊，这究竟是隔了多少年才迎来的重逢啊。',
    "Script/scenario05_14.binu8@75296": '@vKohaku_0654「没错。但我和你不都还活着吗？只要众神还活着，神话就不会结束吧？」',
    "Script/scenario05_14.binu8@79963": '@vRairai_0596「……谁知道呢。说不定，保持原样反而更好。」',
    "Script/scenario05_14.binu8@89716": '@vMirai_0382「你不想和喜欢的人一起，永远留在这个地方吗？」',
    "Script/scenario05_3.binu8@73474": '@vMeguri_0463「那个人脑子里只有戏剧。就连理世加入剧团，也是从一开始就打算让她当演员。他根本没想过让她引退。一切，都是为了自己的戏剧。」',
    "Script/scenario05_3.binu8@77840": '@vMeguri_0475「花！关于这里的机关，能不能这样做？我觉得这样更能表现出奥丁的疯狂。」',
    "Script/scenario05_6.binu8@100333": '@vHana_0184「哇——！！不愧是濑和君！那么，接下来就是小型集训啦——！哎呀，真期待啊！」',
    "Script/scenario05_7.binu8@79923": '@vFutaba_0590「既然是这样，那就没办法了！如果是献给小天使的贡品，我反而很高兴！」',
    "Script/scenario05_7.binu8@88752": '@vOboro_0237「濑和君？刚才天使小姐一路小跑着躲进来了……你对她做了什么吗？」',
    "Script/scenario05_8.binu8@77105": '@vHana_0218「可是为什么偏偏只有濑和君呢？就算不算座长，椎名君也长得超级好看，不是吗？」',
    "Script/scenario06_10.binu8@61050": '@vOboro_0317「不是这样的。他至今传达给你的话语和心意，绝不是什么虚假的东西……只是还有比那更重要的事而已。」',
    "Script/scenario06_2.binu8@83757": '@vRize_0751「……果然，你不记得了。自从遇见那个孩子后，濑和君就因为头痛蜷缩在地上……之后可是发生了不得了的事啊。」',
    "Script/scenario06_2.binu8@85539": '「……我家是戏剧世家。虽然不出名……但父母都是真心喜欢戏剧。所以，他们也希望自己的孩子走上戏剧之路……从小就强迫我们接受严格的训练。」',
    "Script/scenario06_2.binu8@92341": '@vOboro_0277「我认为，像箱鸟同学这样包容力十足的女性，才适合满身伤痕的濑和君。」',
    "Script/scenario06_2.binu8@93356": '@vOboro_0282「我是在夸你。正因为如此，箱鸟同学才会被那个东西迷住。」',
    "Script/scenario06_4.binu8@86862": '@vKohaku_0718「……不过，能演出那样的效果，也是多亏了座长。我并不是凭自己的力量做到的，所以没什么好骄傲的。」',
    "Script/scenario06_5.binu8@64706": '　所以我一次又一次地告诫自己，希望在那之前就能喜欢上戏剧。',
    "Script/scenario06_6.binu8@86069": '@vRize_0983「！？不、不是的！我只是在向恋人要求普通的事而已！想、想接吻不是理所当然的吗？」',
    "Script/scenario06_7.binu8@95006": '@vRize_1038「……我在考虑要不要成为老师。虽然谈不上有什么强烈憧憬……但我觉得那是既有意义又有魅力的职业。」',
    "Script/scenario06_9.binu8@27187": '@vRize_1206「嗯，我好像明白。那是一个看完之后，会让人想温柔地对待某个人的故事。」',
    "Script/scenario06b_1.binu8@78826": '@vNanana_0416「才、才不是呢！当偶像的时候，我可是靠着活泼开朗的形象出道的。」',
    "Script/scenario06b_1.binu8@80468": '「这个世界看重的只有结果。所以现在，奈奈菜被某个人爱着这件事，应该值得她骄傲。」',
    "Script/scenario06b_2.binu8@67770": '@vNanana_0442「……嗯……是的，没错。虽然不是我特别喜欢的故事……但我觉得它确实是一个值得演绎的精彩故事。」',
    "Script/scenario06b_2.binu8@86442": '「……为什么偏偏是现在？如果你真的想把奈奈菜带回来，明明早就可以做到吧。」',
    "Script/scenario06b_3.binu8@77687": '@vMika_0109「……呐，奈奈菜。你已经不必再强迫自己相信喜欢濑和君了。那时的练习，也可以结束了吧？」',
    "Script/scenario06b_4.binu8@67732": '「……下一部戏是《暴风雨》吧。剧本你当然已经看过了？」',
    "Script/scenario06b_5.binu8@23604": '「这是匂宫拜托我拿来的《暴风雨》剧本。虽然被他说服，答应试试看了，但你真正的想法是什么？」',
    "Script/scenario06b_6.binu8@59345": '@vMeguri_0984「……但是，真的可以吗？如果你打算放弃剧本的话……」',
    "Script/scenario06b_6.binu8@64149": '@vNanana_0743「……不、不行吗？我、我不能成为偶像吗？」',
    "Script/scenario04_3.binu8@71055": '@vMirai_0246「你只是因为外表被看中，然后被利用而已。加入剧团之后，什么都没有改变。说到底，他们需要的只是你方便利用的价值。」',
    "Script/scenario04_5.binu8@71624": '　当时我直接装作没听见，置之不理，但那家伙为什么会说出那种话呢。',
    "Script/scenario04_5.binu8@83144": '@vMirai_0284「我、我完全听不懂你在说什么。正因为不可能实现，人们才会向虚构之物许愿啊？」',
    "Script/scenario04_5.binu8@83596": '　没错，这家伙把事情本末倒置了。@n　怎么可能允许为了满足自己，就把别人变成自己想要的样子！',
    "Script/scenario04_6.binu8@62707": '@vMirai_0311「你这个说谎的狸猫。明明是在试探我，看我能不能让理世落选——」',
    "Script/scenario04_6.binu8@71640": '　眼前是一片空白的账簿。@n　幸好不是什么急活，可这也太丢人了。',
    "Script/scenario05_1.binu8@79375": '@vMeguri_0385「才不是。那是被称为大师的匂宫王海创办的剧团。他是个对娱乐毫无兴趣、彻头彻尾的戏剧狂，所以资金还算充裕。从这个意义上说，我们剧团已经很幸运了。」',
    "Script/scenario05_1.binu8@95779": '@vMeguri_0426「……我并不恨他，也不认为他做错了什么。但是……我没法把那个人当成家人。更不用说为他感到骄傲了。」',
    "Script/scenario05_10.binu8@78925": '@vRairai_0501「都是因为你多管闲事，我们的演出差点就要砸了。你也该差不多意识到这一点了吧。」',
    "Script/scenario05_10.binu8@82158": '@vRairai_0508「啊，嗯，因为我就是为了伤害你才那么做的。那也是没办法的事吧。」',
    "Script/scenario05_10.binu8@82350": '@vRairai_0509「沉溺于爱情的你，需要一道会让你背负一生的伤口。那道伤口会让巡的演技升华为真实。人类就是如此消极的生物！艺术正是从负面情感中诞生的！」',
    "Script/scenario05_11.binu8@84980": '@vDirectorA_0001「你最好还是退出兰比里斯剧团吧。就算不是来我们剧团，也请设法加入其他剧团。」',
    "Script/scenario05_11.binu8@88500": '@vMeguri_0838「我所知道的，是那时候的天哥和悠小姐。我们一起度过的那些日子——至今仍未褪色，还在继续。」',
    "Script/scenario05_11.binu8@99117": '　本该在这里修正只有正式演出才会暴露、在练习阶段无法发现的问题和偏差，以提高完成度。',
    "Script/scenario05_12.binu8@80436": '@vRairai_0583「您说什么呢？那个粗暴的蛮族从一开始盯上的就是芙蕾雅大人。我们怎么能把那位比任何人都美丽的大人交给野蛮人。」',
    "Script/scenario05_13.binu8@72606": '@vcs_Meguri_0003_b「开什么玩笑！我可不想被你这种为了黄金就和男人上床的女人指手画脚。你自己也记不清了吧？你究竟和在场的这些男人中的多少人共度过夜晚！」',
    "Script/scenario05_13.binu8@77402": '　只是我没能察觉到，她其实一直都在渴求着什么。',
    "Script/scenario05_14.binu8@71379": '@vKohaku_0644「区区这种障碍，不可能阻挡我的霸道之路。叛徒，一个不留地杀掉。就让他们见识战神奥丁的威光！」',
    "Script/scenario05_14.binu8@72595": '@vKohaku_0648「但如果众神对邪恶无能为力，人类自然也不可能战胜邪恶。邪恶才是绝对之物。这就是神话根底的真相。」',
    "Script/scenario05_2.binu8@81488": '@vRize_0576「已经太迟了，真的！！啊——真是的！这也太丢人了……我怎么会把自己交出去呢。」',
    "Script/scenario05_4.binu8@77793": '　即使换成别人来说，我会气得斥责对方别装出一副什么都懂的样子；可如果是座长，我却能坦率地接受。',
    "Script/scenario05_4.binu8@81925": '　以洛基的身份活在故事中的匂宫。@n　那种场合下，根本没人有资格对她的演技说三道四。',
    "Script/scenario05_6.binu8@99211": '@vKohaku_0583「……对不起，巡酱。我还差得远呢。不过没关系，我想只差一点了。再一点点……我就能成为真正的我了。」',
    "Script/scenario05_7.binu8@80471": '@vFutaba_0591「请说这是毫不客气的关系。因为连一丁点敬意都没有，所以我只是在敷衍你而已。」',
    "Script/scenario05_8.binu8@65191": '@vHana_0204「看着一块布逐渐变成服装的过程，真的让人兴奋不已。光是想象穿上这套服装的演员会绽放出怎样的光彩，我就心跳加速。此刻的工作，究竟会为我们带来怎样的未来呢……我不禁浮想联翩。」',
    "Script/scenario05_8.binu8@76286": '@vHana_0217「濑和君还真受欢迎呢。除了天使小姐和巡酱以外，也有几个女孩子对濑和君很在意……」',
    "Script/scenario05_8.binu8@78648": '@vRize_0646「……咦？说起来，椎名君去哪儿了？去买东西的不是濑和君和奈奈吗？」',
    "Script/scenario05_8.binu8@78978": '@vMeguri_0757「我们之间的事……对他来说，应该一点都不好玩吧。」',
    "Script/scenario05_9.binu8@91624": '@vTeacherA_0007「停学三天。另外，暂时禁止你在校内进行剧团活动。只要低调一点，坏话总有一天会平息的。」',
    "Script/scenario05_9.binu8@91871": '@vTeacherA_0008「……幸好你所属的剧团是在校外，而不是学校里的社团。否则这次演出就不得不取消了。」',
    "Script/scenario05_9.binu8@96670": '@vKohaku_0589「这明显就是恶意吧。有人想妨碍巡酱。啊，真令人痛心。为什么会发生这种事呢——？」',
    "Script/scenario06_1.binu8@100314": '@vRize_0731「巡和架桥同学，比我陷得更深。她们是不是比我还抱有更加暧昧的感情呢。」',
    "Script/scenario06_1.binu8@82382": '@vYuuen_0231「我们只是想把戏剧演到最后、完成它而已。不需要更多的虚构。」',
    "Script/scenario06_10.binu8@61412": '@vRize_1371「不知不觉间，随着长大，世界反而越来越小了。很奇怪吧？按理说……世界本应该越来越广阔才对。」',
    "Script/scenario06_5.binu8@81203": '@vMeguri_1046「等、等一下，环！？你到底在这种地方说什么呢！」',
    "Script/scenario06_5.binu8@81941": '@vRize_0911「我、我不知道！我、我还是第一次听说！我、我确实憧憬着那样的未来……！！可是，因为……！！！」',
    "Script/scenario06_6.binu8@75465": '@vFutaba_0772「……既然这是环的愿望，我想我也没有资格多嘴。真要说点什么的话……嗯。」',
    "Script/scenario06_6.binu8@78155": '@vFutaba_0782「令人意外的是环。箱鸟同学，你表达心意的方式实在不太高明……所以他选择其他女孩子也不奇怪。比如天使酱、天使酱，还有天使酱……不过，天使酱大概会自己……」',
    "Script/scenario06b_1.binu8@91440": '@vFutaba_0653「我想问的是，你有没有把天使酱当作一个女孩子来爱。嘛，看你这个反应……似乎是没戏了呢。」',
    "Script/scenario06b_4.binu8@76447": '@vMeguri_0981「无论多么害羞，都要不躲开视线，把心意传达出去。对女孩子来说，告白可是……一生一次的大决战。」',
    "Script/scenario05_3.binu8@80301": '「……真是的。」',
    "Script/scenario06_2.binu8@79717": '@vMirai_0399「……戏剧，真的有那么了不起吗？」',
    "Script/scenario06_3.binu8@63853": '@vMirai_0436「……这张脸真可怕。看来你和我的原型之间，有着相当深的因缘啊。」',
    "Script/scenario06_5.binu8@65081": '　你是自由的，所以会说“那就辞职不干了”吧。',
    "Script/scenario06_5.binu8@83599": '@vRize_0913「才不好！！虽然确实不好……」',
    "Script/scenario06_5.binu8@83710": '@vRize_0914「……濑和君的心意，我真的很高兴。没想到你竟然为我考虑到这种地步……我都吓了一跳。」',
    "Script/scenario06b_1.binu8@90723": '「……说不定，我只是憧憬那种甜甜的妹妹吧。」',
    "Script/scenario06b_2.binu8@88517": '@vNanana_0476「我、我……在兰比里斯剧团……想和大家，一直在一起……」',
    "Script/scenario06b_8.binu8@39905": '　她理所当然般大方承认了热恋报道，甚至堂堂正正地豁出去了。',
    "Script/scenario04_1.binu8@92541": '@vMirai_0181「啊，嗯，只有这一点我也确实担心……不过，相应地也能展现出更加炉火纯青的演技。」',
    "Script/scenario04_1.binu8@95491": '@vMirai_0191「看到这样的我之后，你就别再事到如今才说这种话了。虽然只是表面上看不出来……其实每个演员，都在这样苦苦挣扎。」',
    "Script/scenario04_5.binu8@64323": '@vFutaba_0490「那个……关于我的角色，也就是芬里尔……该怎么说呢，我对它投入的感情实在太强了……没有信心能把它演好……」',
    "Script/scenario04_5.binu8@66169": '@vFutaba_0498「偏偏最近还总是在出风头……」',
    "Script/scenario04_6.binu8@77351": '@vRize_0489「作为朋友，我真的无法原谅。他用蛮不讲理的方式，把我憧憬的濑和君排除在外。」',
    "Script/scenario04_6.binu8@79970": '@vRize_0498「……濑、濑、濑……濑和君？」',
    "Script/scenario04_7.binu8@42323": '「不，没有。一开始确实烦恼了很多……但最后还是干脆地辞掉了。所以，我也做好重新走上导演之路的觉悟了。」',
    "Script/scenario04_7.binu8@44337": '@vRize_0527「不，不是那样！我想从事的戏剧……我所憧憬的戏剧，才不是那种东西。」',
    "Script/scenario04_7.binu8@49047": '@vRize_0539「那么……就拜托濑和君了。」',
    "Script/scenario05_11.binu8@79793": '@vMenberA_0005「那该怎么说呢？就像和有夫之妇偷情时的那种背德感？她身上散发出的薄幸气质，似乎会成为一种全新的味道……」',
    "Script/scenario05_11.binu8@88783": '　我所认识的天哥，是个别扭、刻薄，却又最喜欢戏剧……值得依靠的哥哥。',
    "Script/scenario05_13.binu8@63273": '「……这也是受那两个人影响吗。」',
    "Script/scenario06_3.binu8@58937": '「……没错。我绝对没有忘记。我做过的事，以及被别人做过的事……应该都记得清清楚楚。」',
    "Script/scenario06_3.binu8@60320": '「现在，我好像能够理解理世放弃戏剧时的心情了。即使原因和理由不同……其中的痛苦，应该是一样的吧。」',
    "Script/scenario06_3.binu8@63853": '@vMirai_0436「……这张脸真可怕。看来你和我的本体之间，有着相当深的因缘啊。」',
    "Script/scenario06_4.binu8@82685": '@vMirai_0485「明明知道丑陋，知道污秽，却还是喜欢上，那才奇怪。啊，对了……不是我奇怪。是周围的其他人奇怪。」',
    "Script/scenario06_6.binu8@81046": '「……我确实可能有点恶心。」',
    "Script/scenario06_6.binu8@87092": '「我们再偷偷接吻吧。只要别被发现……好吗？」',
    "Script/scenario06b_1.binu8@90014": '「她是我理想中的妹妹。甜美、温柔、坦率……那份可爱简直让我快要发疯。不是把她当成女人，而是当成妹妹而产生悸动，这也同样是正确的……」',
    "Script/scenario06b_2.binu8@88517": '@vNanana_0476「我、我……在兰比里斯剧团……想和大家，一直在一起……」',
    "Script/scenario06b_4.binu8@78961": '@vNanana_0597「……吸、呼……吸……呼……」',
    "Script/scenario05_13.binu8@58414": '赫尔',
    "Script/scenario05_13.binu8@67493": '　寂寞地。',
    "Script/scenario05_14.binu8@81021": '咚咚',
    "Script/scenario06b_4.binu8@81389": '咚咚',
    "Script/scenario06b_5.binu8@24047": '　就在这时。',
    "Script/scenario05_14.binu8@77615": '　不是对我。',
    "Script/scenario05_14.binu8@79075": '　而是真正的天乐来来。',
    "Script/scenario06_6.binu8@84948": '「～～～～～！！」',
    "Script/scenario06b_3.binu8@89125": '　必须拒绝。',
    "Script/scenario06b_4.binu8@76406": '　温柔地引导着我。',
    "Script/scenario06b_6.binu8@61817": '　说得结结巴巴。',
    "Script/scenario06b_7.binu8@38269": '　稍微收敛了一点。',
    "Script/scenario04_4.binu8@83390": '「啊啊，希望醉酒时的记忆全都消失……」',
    "Script/scenario04_5.binu8@65339": '　说起来，这个人本来就是天才型。@n　是个能够如字面意义般彻底融入角色的怪物。',
    "Script/scenario04_5.binu8@66495": '　视线一角，箱鸟同学和环正站着闲聊。@n　看起来像是进入了打情骂俏模式？',
    "Script/scenario04_5.binu8@71767": '@vFutaba_0514「明明有男有女，为什么偏偏会喜欢男人呢？」',
    "Script/scenario04_6.binu8@58023": '@n　——评审由包括舞台监督以及主演折原冰狐在内的工作人员负责。',
    "Script/scenario04_6.binu8@70709": '　那就是我与兰比里斯剧团的相遇。@n　也是我与匂宫王海先生的相遇。',
    "Script/scenario04_6.binu8@70830": '@vOmi_0012「没事可做就来我们剧团。现在正缺人手呢。你很闲吧？来帮忙。」',
    "Script/scenario04_7.binu8@48142": '@vNanana_0292「双叶酱的剧本已经破破烂烂了……她一定练习了很多次吧。」',
    "Script/scenario05_1.binu8@88913": '@vNanana_0295「抱、抱歉让您久等了。这是两杯综合咖啡。」',
    "Script/scenario05_10.binu8@71914": '　演戏需要爱，但不需要让自己得到满足。',
    "Script/scenario05_10.binu8@74530": '@vRairai_0488「就是字面意思啊。话说回来，你们把巡当成什么人了？她是那种会因为这点程度的诽谤中伤就状态崩溃的女人吗？」',
    "Script/scenario05_10.binu8@80806": '@vMeguri_0803「……你在说什么呢。我明明就是这样理解的。我可没打算把她塑造成一个只会撒娇卖萌的角色！」',
    "Script/scenario05_11.binu8@102530": '　现在还是专心于眼前的演出吧。@n　即使这只不过是逃避的一种形式。',
    "Script/scenario05_11.binu8@77482": '　就这样，这个世界总是由那些擅长周旋的人拿走美差。',
    "Script/scenario05_13.binu8@59452": '　在一个谁都能去的地方，演着谁都能演的戏，最后平平淡淡地被践踏殆尽。',
    "Script/scenario05_13.binu8@64416": '　被践踏的花朵无法忍受那份污秽，于是亲手离开了这个世界。',
    "Script/scenario05_13.binu8@79253": '@vMeguri_0902「我不需要什么通知。我的爱人们都被杀了，对吧？妻子、孩子，没有一个人逃过一劫，全都被惨杀了。我的家人，就是因为轻信了那个荒谬的故事才死去的。」',
    "Script/scenario05_14.binu8@72106": '@vKohaku_0646「……这样就好，这样就好。一切都在顺利进行。接下来只要战胜神话就行了。」',
    "Script/scenario05_14.binu8@72280": '@vKohaku_0647「北欧神话所描绘的世界，庄严得甚至让人觉得不该称之为神话。没有喜悦的光辉，也没有幸福的保障，无法逃避的毁灭威胁压在头顶。明知死亡终将到来，也明知自己会败北，却依然迎击敌人。」',
    "Script/scenario05_14.binu8@78718": '　为什么理世即使这样，还是愿意试着理解我？@n　面对沉溺于愤怒的我，她始终陪在我身边。',
    "Script/scenario05_2.binu8@83221": '　当时的兰比里斯剧团，虽然备受期待，却因迟迟拿不出成果而以自我满足的团体闻名。',
    "Script/scenario05_2.binu8@83680": '@vYuuen_0176「我们不是靠名字来演戏的。能做到什么，就去做什么吧。」',
    "Script/scenario05_2.binu8@94213": '@vOmi_0033「别自以为是了，小丫头。你以为我培养出来的演员有多少？比你强的人到处都是。差不多该停止把自己当成特别的人了。总有一天，你会认清现实。」',
    "Script/scenario05_3.binu8@83092": '　为此，需要最心爱的人。@p@n　为此，需要最惨烈的牺牲。',
    "Script/scenario05_4.binu8@79536": '　啊，原来如此。@n　啊，是啊，多么廉价的挑衅。',
    "Script/scenario05_5.binu8@71738": '「可是，匂宫的洛基却让我感到坚定。不，不对，不是这样的。洛基是奥丁之爱的象征。因此，必须保持暧昧才对。」',
    "Script/scenario05_7.binu8@76409": '@vFutaba_0585「……这个反应还真是青涩。说实话，我都开始心跳加速了。」',
    "Script/scenario05_7.binu8@87359": '　虽然加入还没多久。@n　也没发生过什么特别的事。',
    "Script/scenario06_1.binu8@82191": '@vMirai_0395「……真是的，真是的，总是在做些多余的事。看来直到最后，我也没能和你们互相理解呢。」',
    "Script/scenario06_2.binu8@91598": '@vRize_0768「逃走也没关系。直到有一天，你能再次面对这一切为止——」',
    "Script/scenario06_4.binu8@74379": '　通过那场试镜后，真是度过了一段天翻地覆的日子。',
    "Script/scenario06_4.binu8@86403": '@vKohaku_0716「最近环君总是心不在焉。该不会已经快把我忘了吧。」',
    "Script/scenario06_5.binu8@65081": '　你是自由的，所以会说“那就辞职不干了”吧。',
    "Script/scenario06_5.binu8@83599": '@vRize_0913「才不好！！虽然确实不好……」',
    "Script/scenario06_5.binu8@83710": '@vRize_0914「……濑和君的心意，我真的很高兴。没想到你竟然为我考虑到这种地步……我都吓了一跳。」',
    "Script/scenario06_6.binu8@66926": '　虽然和理世两人独处，但两人之间却弥漫着一种奇妙的尴尬。',
    "Script/scenario06_6.binu8@68215": '「刚才那样还不够体面。所以，请让我重新告诉你一次。」',
    "Script/scenario06_7.binu8@88113": '　起初，外界的声音确实很吵，但随着时间流逝，谈论我们关系的人越来越少了。',
    "Script/scenario06b_1.binu8@87919": '@vFutaba_0642「你到底怎么看天使酱？如果没戏的话，就请你干脆拒绝她吧！」',
    "Script/scenario06b_1.binu8@90723": '「……说不定，我只是憧憬那种甜甜的妹妹吧。」',
    "Script/scenario06b_3.binu8@85888": '@vMirai_0384「真的吗？那一定只是认知不同而已。」',
    "Script/scenario06b_3.binu8@86718": '@vMirai_0388「把任性的话说出来吧？因为你直到今天，一直都在受苦啊。」',
    "Script/scenario06b_4.binu8@72231": '@vFutaba_0688「这样啊这样啊。那可真是太好了呢——」',
    "Script/scenario06b_8.binu8@39905": '　她理所当然般大方承认了热恋报道，甚至堂堂正正地豁出去了。',
    "Script/scenario04_2.binu8@88119": '@vMeguri_0364「回想起那时候吧。你已经不再是一个只会把模仿当作武器的演员了。」',
    "Script/scenario04_3.binu8@69229": '@vNanana_0275「啊哈哈……不过，我觉得座长先生不是这么想的。他之所以让我演赫尔，一定是因为有双叶酱在。我们两个人，是一体的。」',
    "Script/scenario04_4.binu8@84538": '　虽然试着披上“普通”这层常识的外衣，但看来我并不喜欢那一套。',
    "Script/scenario04_4.binu8@88472": '　有时也会受到仿佛要把精神逼到绝境的对待，但只要能变得更好，我就拼命坚持了下来。',
    "Script/scenario04_5.binu8@68842": '　映照内心的特殊取景器。@n　所谓恋心，会让人对一切视而不见。',
    "Script/scenario04_5.binu8@70476": '@vFutaba_0512「——天使酱，我不会交给你。我绝不会原谅你。」',
    "Script/scenario04_5.binu8@80907": '@vFutaba_0545「那种荒谬的世界，我敬谢不敏。就算你求我，我也绝不会许下那种愿望。」',
    "Script/scenario04_6.binu8@57237": '　舞台监督看中了折原冰狐压倒性的存在感，似乎站出来要为她打造一座由她主演、对她而言最棒的舞台。',
    "Script/scenario04_6.binu8@60256": '@vMirai_0304「好久不见，理世。你还在继续当演员啊。」',
    "Script/scenario04_6.binu8@80495": '@vOboro_0219「啊，箱鸟同学憧憬的人，该不会是濑和君吧？那样的话，他一直就在你身后啊……」',
    "Script/scenario04_7.binu8@50622": '　座长的激励声响彻排练厅。@n　终于……兰比里斯剧团开始行动了。',
    "Script/scenario05_10.binu8@101482": '@n　——喂，你听说了吗？听说龙木小姐有被某个大剧团挖走的传闻。',
    "Script/scenario05_10.binu8@74238": '@vRairai_0487「哈？你在说什么呢。就因为那点事，怎么可能影响到演技。倒不如说，那应该会让巡的演技更加炉火纯青才对。」',
    "Script/scenario05_14.binu8@66691": '　机灵的台词、体察心意的细心、鼓舞他人的行动，这些我都做不到。',
    "Script/scenario05_2.binu8@72769": '@vFutaba_0576「我、我也来帮忙！别看我这样，我很擅长细致的工作！」',
    "Script/scenario05_5.binu8@77449": '「不，真的很厉害！至少我特别开心。真的谢谢你。我会怀着感激之情收下的。」',
    "Script/scenario05_5.binu8@86880": '@vMeguri_0624「我去附近的便利店买来的。因为是第一次买，所以还挺不好意思的。」',
    "Script/scenario05_6.binu8@80451": '@vMeguri_0660「呵呵，和理世比起来算好多了，不过你也挺马虎的嘛。只打扫看得见的地方。」',
    "Script/scenario05_6.binu8@96525": '@vHana_0177「要那种更夸张、更让人‘哇——！’的服装！难得是这么重要的舞台，不把她打扮得最漂亮怎么行呢！」',
    "Script/scenario05_6.binu8@97775": '@vFutaba_0577「环的家就够了。地方宽敞，弄乱了也没关系。只是家主本人会稍微碍事……」',
    "Script/scenario05_7.binu8@81201": '@vMeguri_0716「好啦，红茶泡好了哦——想要糖或牛奶的人告诉我一声。」',
    "Script/scenario05_8.binu8@67174": '@vRize_0630「……说起来，有件事我一直有点在意。」',
    "Script/scenario05_8.binu8@72131": '@vHana_0215「骗我的明明是巡酱嘛，气鼓鼓！」',
    "Script/scenario06_2.binu8@94010": '@vOboro_0285「……我啊，箱鸟同学。我最讨厌把我带到这个世上的母亲。孩子没法选择父母。事到如今，再哀叹自己的出身也无济于事吧。」',
    "Script/scenario06_4.binu8@76667": '@vRize_0839「不、不是那样！我也有过觉得开心的时候！正式演出顺利时，那种感动是无法用语言形容的！」',
    "Script/scenario06_7.binu8@99216": '@vRize_1055「这把牙刷，是巡的吧？那个茶杯，还有你想为我泡的红茶！这些不都是为了和巡一起生活吗！！」',
    "Script/scenario06_9.binu8@23027": '@vRize_1194「能悠闲地约会，也就只有现在了吧。」',
    "Script/scenario06b_3.binu8@66785": '　露出温柔笑容的新妈妈，仿佛是在故意扮演一个好母亲。',
    "Script/scenario06b_3.binu8@67418": '　本不存在真正的家人。@n　这是让虚假的家人获准生存的地方。',
    "Script/scenario06b_3.binu8@71198": '@vNanana_0487「要、要怎样才能……喜欢上那个人呢？我、我……很不擅长应付濑和君……」',
    "Script/scenario06b_6.binu8@74002": '@vFutaba_0715「……但是，不能忘记一件事。最重要的是最大限度地发挥天使酱的可爱。我想，那一定是我做不到、只有环才能做到的事。」',
    "Script/scenario06b_8.binu8@36556": '@vcs_Nanana_0025「这、这样可以吗！？」',
    "Script/scenario05_9.binu8@92949": '@vMeguri_0774「……对不起，濑和君。我把你也卷进来了。」',
    "Script/scenario04_4.binu8@90933": '@vHana_0153「我曾见过非常了不起的东西，激动得坐立难安，于是抱着‘如果能做些什么就好了’的想法来到了这个世界。直到现在，这份心情也没有改变。」',
    "Script/scenario05_2.binu8@84589": '@vRairai_0383「……还说什么‘初次见面’啊？我们都是演员，我怎么可能不知道你。嘛，不过你大概不认识我就是了。」',
    "Script/scenario04_2.binu8@92253": '@vMeguri_0370「我是在问，你想用你的那个，对环君的那个，哔一下、啪一下、再啵一下吗？」',
    "Script/scenario06_2.binu8@86430": '　只不过是碰巧合适罢了……我的实力还没有到能被称作天才的程度。',
    "Script/scenario06b_8.binu8@34557": '　正因为有摄像机，才会让人难以察觉。这里没有别人，只有我们两个人。现在，我希望你能明白这一点。',
    "Script/scenario05_2.binu8@91583": '@vYuuen_0177「哎呀，你又来了？巡还真是不长记性呢。」',
    "Script/scenario05_4.binu8@71140": '　不只是座长。@n　就连悠小姐，也越来越常一个人练习了。',
    "Script/scenario05_7.binu8@78409": '@vHana_0193「对！就是这个！你们那种熟稔的距离感是怎么回事！还有那种默契！姐姐我都要嫉妒了——！」',
    "Script/scenario05_10.binu8@90862": '　我很普通。@n　所谓特别，只会被赋予极少数人。',
    "Script/scenario06_1.binu8@87691": '@vF_StudentA_0028「原、原来是相关人士！我、我之前完全没认出来……！真是见外啊，既然是同班同学，早点告诉我不就好了——」',
    "Script/scenario06_4.binu8@87030": '　她那时在个人指导上还真是拼命啊。那时候的琥珀，确实让人不太敢接近。',
    "Script/scenario05_9.binu8@93924": '@vMeguri_0779「我也得向大家道歉才行。对不起，濑和君……」',
    "Script/scenario09_2.binu8@77717": '@vMirai_0860「……真吵啊。」',
    "Script/scenario06_2.binu8@80149": '@vMirai_0401「你在入团申请上写了箱鸟理世，对吧。所以，就这样。折原京子会让你加入剧团兰比利斯。」',
    "Script/scenario02_12.binu8@56878": '@vMika_0072「因为偶像比普通女孩更有商品价值。」',
    "Script/scenario08_1.binu8@97644": '@vKohaku_0813「巡离开之后，这个世界存在的意义就失去了一半。如今，所有人都已经离开了这个舞台。这里已经谁都不在了。」',
    "Script/scenario06b_6.binu8@74740": '　明知道他曾经对天使出手，却还是愿意帮助他吗？',
    "Script/scenario05_4.binu8@79654": '　这种话，不过是让我顺着心意去做的推销辞令。',
    "Script/scenario08_2.binu8@95040": '@vMinami_0014「喂，环。你不用再想那些多余的事了。那个散播无聊流言的社团，干脆退了吧。今后就由我来教你表演。我觉得这样一定更有效！」',
    "Script/scenario07_2.binu8@95459": '「什么星星啊。今天阴天，根本看不见心宿二。」',
    "Script/scenario09_5.binu8@81405": '　既然无法贯彻残酷，那就从一开始别考虑复仇。',
    "Script/scenario07b_4.binu8@71780": '@vMeguri_1535「呜——」',
    "Script/scenario06_4.binu8@71307": '@vMirai_0450「那时候，你已经不记得自己想成为什么了吗？」',
    "Script/scenario05_9.binu8@80270": '　我还以为他会展现出足以令人起鸡皮疙瘩的震撼演技，没想到紧接着却演得像泄了气一样。',
    "Script/scenario01_1.binu8@75876": '@vfutaba_0026「……你好。」',
    "Script/scenario01_5.binu8@75152": '「这就是所谓的很上镜吧。」',
    "Script/scenario01_4.binu8@89779": '　戏剧，是一种表达。@p@n　表达，是一种艺术。',
    "Script/scenario01_4.binu8@79286": '@vMeguri_0043「……干什么？你再怎么盯着我看，我也不会帮忙的哦。」',
    "Script/scenario01_2.binu8@69068": '@vfutaba_0040「呐，环。戏剧很有趣吗？我还是第一次看……」',
    "Script/scenario01_1.binu8@79175": '　双叶用眼神向我求助，仿佛在说“想想办法”。@n',
    "Script/scenario01_10.binu8@100945": '@vMeguri_0091「我喜欢这孩子。就交给我吧。」',
    "Script/scenario01_4.binu8@83925": '@vfutaba_0156「好、好的！请多多指教！！」',
    "Script/scenario01_5.binu8@76173": '　我忍不住提高了声音。@n　直到第三次呼唤，她才终于有所反应。',
    "Script/scenario02_3.binu8@93076": '　她投来令人浑身发毛的视线。',
    "Script/scenario02_11.binu8@72595": '　那个奈奈菜，绝不可能是出于自己的意志做出这种事。',
    "Script/scenario02_2.binu8@76871": '　这些道理我从一开始就明白——但如果可以，我还是不想亲耳听见。',
    "Script/scenario02_10.binu8@76051": '　不然的话。@p@n　如果她真的爱我。@p@n　如果她哪怕对我有一点体贴。@p',
    "Script/scenario02_10.binu8@77974": '　她为了让我出名而四处奔波，那副样子怎么看都不像是在演戏。',
    "Script/scenario02_4.binu8@74710": '　胧一边品着红茶，一边爽朗地笑着。@n　没想到他会出现在这种热闹的场合。',
    "Script/scenario03_1.binu8@67605": '　夸张得连我自己都忍不住脸红。',
    "Script/scenario03_6.binu8@81909": '　她毫不犹豫地流露出青涩的一面。',
    "Script/scenario03_3.binu8@93446": '　她温柔地拥住我的剧本。',
    "Script/scenario03_7.binu8@72652": '　然而，她给出的回答，却像是从遥不可及的高处落下的答案。',
    "Script/scenario03_4.binu8@80635": '@vMeguri_0298「……座长喜欢不成熟的孩子，对吧。」',
    "Script/scenario03_1.binu8@67724": '　不知不觉摆出姿势，这是职业病吗？',
    "Script/scenario04_4.binu8@89668": '　被问到的，是藏在心底最深处的感情。',
    "Script/scenario04_4.binu8@88666": '　那如花朵般的笑容背后，隐藏着观众难以想象的地狱。',
    "Script/scenario04_6.binu8@57779": '　其中最有希望的作品，一路闯到了最终审查。',
    "Script/scenario04_6.binu8@69525": '　那时的我，对此一无所知。',
    "Script/scenario04_1.binu8@87928": '@vMirai_0174「不愧是哥哥认可的女孩。演技方面明明一塌糊涂……可看人的眼光倒是不错。」',
    "Script/scenario04_4.binu8@91859": '　曾经作为演员的你——那时在我眼中如此耀眼的你，正是我憧憬的对象。',
    "Script/scenario04_6.binu8@65585": '　她直到最后都没有失去笑容。@n　不讲道理地、单方面地拒绝了我。',
    "Script/scenario04_4.binu8@83160": '「……我可以相信这个人吗？」',
    "Script/scenario05_4.binu8@69428": '　没想到两年后……在祖父的带领下，竟然成立了新的剧团。',
    "Script/scenario05_13.binu8@70324": '　曾经相信只要和大家在一起就什么都能做到，如今想来却觉得那实在太天真了。',
    "Script/scenario05_11.binu8@81912": '@vRairai_0564「为什么要阻止老头子？他那个自杀的学生怎么样都无所谓吧。老头子可是把普通人拉起来，创作出了不得了的戏剧。别在意那点小小的牺牲。」',
    "Script/scenario05_10.binu8@70703": '　即使频繁去他家，也不代表我的演技就有所进步。',
    "Script/scenario05_3.binu8@95031": '@n　——就连大师也会堕落啊。匂宫王海已经没有容身之处了。',
    "Script/scenario05_9.binu8@100973": '「什么都不做。在公演结束前，就当什么都没发生一样度过。至于匂宫的情况再说，但我不想去找犯人。」',
    "Script/scenario05_7.binu8@83355": '@vRairai_0382「太可笑了。聚集一群门外汉，能做出什么来？真是的，丢人也该有个限度。」',
    "Script/scenario05_9.binu8@86968": '　捂住耳朵，玩起捉迷藏。@n　鬼先生，请往这边来。',
    "Script/scenario05_11.binu8@81154": '@vRairai_0561「那个老头子，是不是因为过度指导演技，最后害得演员自杀了？！」',
    "Script/scenario05_10.binu8@70992": '　和他相处的时光，只是单纯的奖励。@n　我只是想为自己能在他的帮助下演得更好而感到自豪。',
    "Script/scenario06_5.binu8@84256": '　看起来根本没把这件事放在心上。',
    "Script/scenario06_5.binu8@79039": '　那番热切的劝阻，出乎我的意料。',
    "Script/scenario06b_1.binu8@80233": '「即便如此，也很厉害啊。让那么多人喜欢上自己，真的不是件容易的事。」',
    "Script/scenario06_5.binu8@62515": '　准备期间忙碌的感觉，和正式演出前的感受截然不同。',
    "Script/scenario06_8.binu8@22594": '　我紧紧握住她的手，决心再也不放开，尽情享受这份小小的幸福。',
    "Script/scenario06_2.binu8@104489": '　如果连演技都做不到，就再也找不到拒绝入团的理由了。',
    "Script/scenario06_10.binu8@62452": '@vRize_1376「因为我已经这样决定了，所以才会在这里。」',
    "Script/scenario06_4.binu8@78744": '　声音中充满了愤怒与憎恨。',
    "Script/scenario06b_3.binu8@84148": '　我最讨厌空洞的自己。',
    "Script/scenario06b_3.binu8@82089": '@vNanana_0524「好可怕……好可怕，好可怕，好可怕。你头脑聪明又敏锐，所以才会看穿我这样的心情，对吧？」',
    "Script/scenario06b_3.binu8@75437": '@vNanana_0503「环君……」',
    "Script/scenario06b_6.binu8@68002": '@vFutaba_0696「你少骗人了——」',
    "Script/scenario06_1.binu8@104014": '「别因为一次成功就得意忘形。接下来，理世面前还有许多故事等着你。你必须认真面对其中的每一个。」',
    "Script/scenario07_6.binu8@66615": '@vOmi_0091「……你太擅长演戏了。你不该只是属于这个剧团的演员，这一点你自己也明白吧。」',
    "Script/scenario07b_2.binu8@65644": '@vNanana_0993「那可真厉害啊，好羡慕。」',
    "Script/scenario07_3.binu8@73025": '　她善解人意，总能带着幽默说出我想听的话。',
    "Script/scenario07_1.binu8@106237": '　又或者，是在和那个因无休止的劳累而饱受折磨的父亲诀别时吧。',
    "Script/scenario07_2.binu8@80113": '　被深爱的丈夫背叛，还被迫接纳他的私生子……她一定痛苦得快要发疯了。',
    "Script/scenario07_1.binu8@108113": '　然而，即使看着她沐浴在喝彩声中的演技，我的内心也没有丝毫动摇。',
    "Script/scenario07_4.binu8@72036": '　所以才感觉不到痛。@n　明明降临在自己身上的灾祸，却能像事不关己一样看待。',
    "Script/scenario07_1.binu8@110014": '「就这样去奈奈菜的教室，真的可以吗？」',
    "Script/scenario08_3.binu8@76839": '　她究竟曾把多少感情，寄托在那短短几句台词里？',
    "Script/scenario08_1.binu8@100545": '　我决定不给这种感情命名。@n　因为一旦为它命名……难以忍受的痛苦一定会向我袭来。',
    "Script/scenario08_2.binu8@81325": '　少年迈着轻快的步子，纵身跳上了栏杆。',
    "Script/scenario08b_4.binu8@60652": '@vKohaku_1171「可是，这里……我记得好像有女仆来过……」',
    "Script/scenario08_5.binu8@97536": '　虚构的世界被耀眼的光芒包围，逐渐崩塌。',
    "Script/scenario08_4.binu8@57985": '　拜托，请你在这个世界上闪耀。@n　在今后的未来里，把我们最喜欢的戏剧演给世人看。',
    "Script/scenario09_4.binu8@71324": '　悲剧与泪水相拥。@n　白发红眸，正受到诅咒。',
    "Script/scenario09_4.binu8@87870": '　人无法把月亮握在手中。@n　也无法把不可能变成可能。',
    "Script/scenario09_3.binu8@67510": '@vMirai_0911「想要和诸神并肩，只有一种方法。那就是变得和诸神一样残酷。」',
    "Script/scenario09_5.binu8@90402": '　这一切，明明都是我自己选择的。@n　可我却把它忘记了。',
    "Script/scenario09_5.binu8@100857": '@vMika_0164「——因为只有憎恨，才能让我振作起来。」',
    "Script/scenario09_5.binu8@101608": '　她似乎在呼唤着什么，却始终没有得到回应。@n　至于那份痛苦的真正含义，恐怕只有她自己明白。',
    "Script/scenario09_1.binu8@43690": '　少女在月光下的公园里翩翩起舞。',
    "Script/scenario09_5.binu8@110904": '　我不想逃走。@n　我一直祈愿着，想要战斗。',
    "Script/scenario07b_2.binu8@81269": '@vMeguri_1349「是啊。就连我，也在度过今天，只为了让明天的你能够爱上我。」',
    "Script/scenario07_6.binu8@69992": '　即使在这种情况下，祖父也能毫不犹豫地振作起来。',
    "Script/scenario07_3.binu8@71634": '　不知不觉，我已经不再擅长演戏了。@n　一个连演员都当不成的我，到底是为了什么才留在这里？',
    "Script/scenario07b_5.binu8@51119": '@vMeguri_1700「那就至少慢慢走吧。急着赶到前面，也没有什么大事在等着我们。」',
    "Script/scenario07_4.binu8@58846": '　哪怕用尽一切手段，我也要以导演的身份闯出一番天地。',
    "Script/scenario07b_4.binu8@72129": '　咖啡馆里一片喧闹。@n　因为没有其他客人在，大家都尽情吵闹着。',
    "Script/scenario08_3.binu8@57238": '　摘录自某杂志的一篇采访。@n　然而，他作为演员登上这本杂志，却再也没有第二次。',
    "Script/scenario08_1.binu8@91170": '　不知从什么时候开始，父亲的暴力变得越来越严重。',
    "Script/scenario09_4.binu8@87870": '　人无法将月亮据为己有。@n　也无法把不可能变成可能。',
    "Script/scenario09_3.binu8@66635": '@vMirai_0908「再多一点，再多一点……再多一点！」',
    "Script/scenario09_5.binu8@90402": '　这一切明明都是我自己选择的。@n　可我却把它忘记了。',
    "Script/scenario09_5.binu8@100857": '@vMika_0164「——因为只有憎恨，才能让我振作起来。」',
    "Script/scenario09_5.binu8@108286": '@vRize_1491「——已经没有时间再等了。我们必须让理世走在我们前面。」',
    "Script/scenario09_1.binu8@61709": '@vFutaba_0928「诶？连我也要谈恋爱吗？呜哇，好恶心。」',
    "Script/scenario09_2.binu8@78654": '@vFutaba_0970「——环一定很想见折原先生。请帮他实现这个愿望。」',
    "Script/scenario04_4.binu8@79791": '「喂——！！」',
    "Script/scenario04_6.binu8@57941": '@n　——最终审查，是剧团展示指定角色的演出。',
    "Script/scenario05_12.binu8@75549": '@n　——不，和他的蛮横相比，这根本算不了什么。',
    "Script/scenario05_9.binu8@93561": '「巡」',
    "Script/scenario06b_3.binu8@69462": '　特别是……这样。',
    "Script/scenario06b_3.binu8@70171": '　不过。',
    "Script/scenario06b_3.binu8@76089": '　说起来。',
    "Script/scenario06b_3.binu8@76407": '　不过。',
    "Script/scenario06b_3.binu8@79442": '「啊，对了。」',
    "Script/scenario06b_3.binu8@79471": '「已经够了吧。」',
    "Script/scenario06b_3.binu8@88067": '　给你一个称心如意的结局。',
    "Script/scenario06b_3.binu8@89900": '　低沉而不安的声音。',
    "Script/scenario06b_4.binu8@65570": '「啊，抱歉。」',
    "Script/scenario06b_4.binu8@73651": '「原来如此。」',
    "Script/scenario06b_4.binu8@76997": '「奈奈菜。」',
    "Script/scenario06b_4.binu8@81887": '「谁知道呢。」',
    "Script/scenario06b_5.binu8@24550": '「这样啊。」',
    "Script/scenario06b_6.binu8@62067": '「啊，是吗。」',
    "Script/scenario06b_6.binu8@63287": '「这样啊。」',
    "Script/scenario06b_6.binu8@74883": '「啊，不过……」',
    "Script/scenario06b_6.binu8@75612": '「……谢谢。」',
    "Script/scenario06b_6.binu8@77222": '「真是的……」',
    # Act 4-6 expanded sample: replace malformed legacy machine translations.
    "Script/scenario04_4.binu8@77510": '@vRize_0404「……咦、等一下……」',
    "Script/scenario04_4.binu8@77577": '@vRize_0405「你、你说什么啊！现在谁还顾得上我啊！」',
    "Script/scenario04_4.binu8@77774": '@vRize_0406「环君！环君！你从刚才开始就一直闷不吭声！既然是朋友，就说点什么啊——！」',
    "Script/scenario04_4.binu8@77931": '「理、理世……小姐？那个……」',
    "Script/scenario04_4.binu8@78495": '@vcs_Master_0001「看来她已经醉得不省人事了……奇怪，我这里明明没有提供酒精饮料……」',
    "Script/scenario04_4.binu8@78918": '@vcs_Master_0002「不对，这里确实没有洋酒之类的酒精饮料。虽然味道上确实带有一点类似的风味……」',
    "Script/scenario04_4.binu8@79110": '「……啊，就是那个……」',
    "Script/scenario04_4.binu8@79499": '@vcs_Oboro_0003「真可怕啊。要是箱鸟小姐，恐怕光靠水和气氛就能醉得很开心吧。」',
    "Script/scenario04_4.binu8@79870": '「等一下。别把我晾在一边啊！」',
    "Script/scenario04_4.binu8@79926": '@vRize_0408「等等！环君，你在看哪里啊——！难得我就在你旁边，你应该看着我才对——！嗝。」',
    "Script/scenario04_4.binu8@80409": '@vRize_0410「好热、好热啊——。这到底是怎么回事啊——」',
    "Script/scenario04_4.binu8@80500": '「别在大庭广众之下露出皮肤啊！！那个一本正经的理世去哪儿了！」',
    "Script/scenario04_4.binu8@80787": '@vRize_0412「看吧看吧，这是女孩子的证明哦——？环君也喜欢吧——？啊哈，我现在是不是很妩媚？」',
    "Script/scenario04_4.binu8@80932": '「老板，有没有让醉鬼睡觉的地方？不对，请你准备一个出来！！」',
    "Script/scenario04_4.binu8@81069": '@vcs_Master_0003「……很遗憾，差不多到了打烊时间。能麻烦您负责把她带回去吗？」',
    "Script/scenario04_4.binu8@81491": '「这不就是把事情全丢给我了吗……」',
    "Script/scenario04_4.binu8@81538": '@vRize_0413「我要去环君家——。女孩子们都被邀请到环君家里，太狡猾了——」',
    "Script/scenario04_4.binu8@81763": '@vRize_0414「那就露宿街头？」',
    "Script/scenario04_4.binu8@81965": '@vHana_0139「好——！受召而来，突然登场！我是大家可靠的大姐姐，花酱哦——！」',
    "Script/scenario04_4.binu8@82415": '@vRize_0415「哇，是花酱——。花酱也一起来嘛——」',
    "Script/scenario04_4.binu8@82512": '@vHana_0141「呀——！理世酱，好可爱啊！真是不得了的傲娇程度！好，那就再让她多喝一点。我们去便利店买一大堆吧！」',
    "Script/scenario04_4.binu8@82845": '@vHana_0142「开、开玩笑的啦。放心吧，别看我这样，我很擅长照顾醉鬼的！」',
    "Script/scenario04_4.binu8@87015": '@vHana_0148「……完全不行……」',
    "Script/scenario04_4.binu8@87365": '@vHana_0149「我为什么会通过选拔呢？」',
    "Script/scenario04_4.binu8@87957": '@vHana_0150「……我甚至还没达到那个外行人的水平。」',
    "Script/scenario04_4.binu8@88256": '@vHana_0151「我自以为每天都在努力……可其他演员，根本是另一个层次。」',
    "Script/scenario04_4.binu8@88921": '@vHana_0152「——请让我退团吧。」',
    "Script/scenario04_4.binu8@89730": '@vOmi_0007「喜欢的话，就留下来。就算你不再当演员，也完全没有必要退团。」',
    "Script/scenario04_4.binu8@91582": '@vHana_0155「所以，理世酱……」',
    "Script/scenario04_4.binu8@92525": '　可是，现实又是怎样的呢？@n　和笑得神采飞扬的白坂小姐不同，我总觉得她似乎怀抱着某种迷惘……这只是我自以为是的想法吗？',
    "Script/scenario04_4.binu8@92919": '@vHana_0159「理世酱一聊到戏剧，就会变得特别能说！我们很投缘，有时甚至会聊得太久。就算她不当演员了，也能感觉到她真的很喜欢演戏！」',
    "Script/scenario04_4.binu8@93199": '「……那家伙很少把真心话说出来啊。」',
    "Script/scenario04_4.binu8@93972": '@vRize_0420「冰狐……我……」',
    "Script/scenario04_4.binu8@94065": '@vRize_0421「我想以配角的身份，站在你的身边。」',
    "Script/scenario04_5.binu8@82449": '@vFutaba_0551「听好了。天使酱喜欢环。这个事实荒唐得让我几乎要发疯……可即便如此，天使酱还是喜欢上他了。」',
    "Script/scenario04_5.binu8@85852": '@vFutaba_0559「……我确实对选角不满。要演天使酱被夺走的角色……就算死了我也不要。我甚至想撕掉剧本，以骚扰为由控告座长。」',
    "Script/scenario04_5.binu8@87779": '@vMirai_0266「这个世界真实的模样，非常丑陋。人如果不依靠戏剧般的幻想，就无法活下去。所以……我想把谎言一层层叠上去。」',
    "Script/scenario04_6.binu8@55999": '@vRize_0426「……冰狐。」',
    "Script/scenario04_6.binu8@56721": '@vRize_0430「你就等着看吧。」',
    "Script/scenario04_6.binu8@57868": '@vRize_0434「……这是求之不得的机会。」',
    "Script/scenario04_6.binu8@58270": '@vRize_0436「我会做到的……！」',
    "Script/scenario04_6.binu8@58536": '@vRize_0437「……在最终审查那天之前，所有安排都得取消。」',
    "Script/scenario04_4.binu8@78153": '@vRize_0407「你从以前开始就是这样，一到关键时刻就什么都不肯告诉我——！！」',
    "Script/scenario04_4.binu8@80211": '@vRize_0409「不许小看橙汁——！大人也喜欢喝果汁的——！」',
    "Script/scenario04_4.binu8@80592": '@vRize_0411「我才不是什么一本正经的人呢——！我只是个普通的女孩子啊——！」',
    "Script/scenario04_4.binu8@83323": '@vRize_0416「出发——！加油——！！」',
    "Script/scenario04_4.binu8@93610": '@vRize_0417「……嗯。」',
    "Script/scenario04_4.binu8@93718": '@vRize_0418「……为什么。」',
    "Script/scenario04_4.binu8@93832": '@vRize_0419「为什么我……不能成为配角？」',
    "Script/scenario04_5.binu8@66374": '@vRize_0422「请、请把昨天的事忘了！你什么都没看见。听见了吗！？」',
    "Script/scenario04_5.binu8@66613": '@vRize_0423「啊，我怎么会做出那种事……！真是丢死人了……！！」',
    "Script/scenario04_5.binu8@66855": '@vRize_0424「全都是你的错——！！」',
    "Script/scenario04_6.binu8@55661": '@vRize_0425「……我一定会让你刮目相看的。」',
    "Script/scenario04_6.binu8@56089": '@vRize_0427「你的演技，看起来孤独得可怕。」',
    "Script/scenario04_6.binu8@56162": '@vRize_0428「杀死共演者的人。独裁者。暮色中的少女，将所有月光掠夺一空。」',
    "Script/scenario04_6.binu8@56416": '@vRize_0429「不只是演技好。她散发出的存在感，实在太过异质。」',
    "Script/scenario04_6.binu8@56811": '@vRize_0431「我会成为一个不输给你的演员。」',
    "Script/scenario04_6.binu8@57194": '@vRize_0433「主演，折原冰狐。」',
    "Script/scenario04_6.binu8@58153": '@vRize_0435「我的演技，能够请冰狐来评判。」',
    "Script/scenario04_6.binu8@59016": '@vRize_0438「我是四号考生，箱鸟理世。请多关照！」',
    "Script/scenario04_6.binu8@60974": '@vRize_0441「怎、怎么会……！我明明还什么都没展示！」',
    "Script/scenario04_6.binu8@63871": '@vRize_0444「我、我的演技……为什么说不行……！！你明明还没看过……！！」',
    "Script/scenario04_6.binu8@64610": '@vRize_0445「怎、怎么会……！」',
    "Script/scenario04_6.binu8@64757": '@vRize_0446「……我明明只是想和冰狐一起演戏。」',
    "Script/scenario04_6.binu8@65833": '@vRize_0447「我……」',
    "Script/scenario04_6.binu8@66237": '@vRize_0448「……冰狐，你太过分了。」',
    "Script/scenario04_6.binu8@66557": '@vRize_0450「原来我没有资格当演员。」',
    "Script/scenario04_6.binu8@66915": '@vRize_0451「那孩子……到底想干什么？」',
    "Script/scenario04_6.binu8@67151": '@vRize_0452「……连我这种人去看那孩子的演技，又有什么意义呢。」',
    "Script/scenario04_6.binu8@67387": '@vRize_0453「折原冰狐主演，《卡利古拉》。」',
    "Script/scenario04_6.binu8@67937": '@vRize_0456「要演出连性命都能舍弃的演技，我这种人怎么可能做得到。」',
    "Script/scenario04_6.binu8@68146": '@vRize_0457「——我已经不当演员了。」',
    "Script/scenario04_6.binu8@70084": '@vRize_0459「只要开心就不行吗？」',
    "Script/scenario04_6.binu8@70201": '@vRize_0460「我明明只是想和冰狐一起演戏。」',
    "Script/scenario04_6.binu8@71088": '@vRize_0463「我已经……不当演员了……」',
    "Script/scenario04_5.binu8@67980": '咚咚',
    "Script/scenario04_5.binu8@69905": '　甚至不敢靠近。@n　我再次确认了，那个人、那个天使，正是我深爱的天使奈奈菜。',
    "Script/scenario04_5.binu8@77037": '@vFutaba_0531「……折原小姐和我之间没有任何交集。要向我伸出援手……我们的关系还远远不够。」',
    "Script/scenario04_5.binu8@81253": '@vMirai_0279「和天使奈奈菜小姐结合。那就是你的幸福，对吧？」',
    "Script/scenario04_6.binu8@58820": '@n　——箱鸟理世小姐。',
    "Script/scenario04_6.binu8@63569": '@vDirectorC_0008「如果因为朋友情谊，就把不合适的人选为凯瑞亚，那么就该重新审视整个企划。还得向各相关公司说明，折原冰狐无法胜任卡利古拉。」',
    "Script/scenario04_6.binu8@75991": '@vOboro_0213「所以你才会被赋予凯瑞亚这个角色。折原冰狐一定早就看透了这一点吧。可你却一直欺骗自己，所以才会被折原冰狐抛弃。」',
    "Script/scenario05_1.binu8@89020": '　在忙乱之间，奈奈菜把平时的咖啡送了过来。',
    "Script/scenario05_1.binu8@91487": '「……奈奈菜，你还在工作吗？要是有空，就陪我坐一会儿吧。一起喝杯咖啡。」',
    "Script/scenario05_1.binu8@91708": '「没在约会啊。我怎么可能会觉得奈奈菜碍事呢。」',
    "Script/scenario05_1.binu8@92018": '　我瞥了奈奈菜一眼。',
    "Script/scenario05_1.binu8@92353": '　奈奈菜绽放出明亮的笑容。',
    "Script/scenario05_1.binu8@92747": '　奈奈菜还穿着女仆装，坐到了我的身边。@n　不知是不是我的错觉，她今天的情绪似乎格外高涨。',
    "Script/scenario05_11.binu8@90755": '　坐在旁边的奈奈菜担心地向我搭话。',
    "Script/scenario05_11.binu8@91343": '　奈奈菜的声音，渐渐飘向远方。',
    "Script/scenario05_11.binu8@93271": '@vNanana_0378「差不多到练习时间了。奈奈和大家也该过去了……！」',
    "Script/scenario05_11.binu8@93606": '　啊，幸好奈奈菜就在身边。@n　只要身边没有人陪着，我就会感到难以忍受的不安。',
    "Script/scenario05_13.binu8@57492": '@vKohaku_0623「即便如此，巴德尔还是被杀了。看来，仅凭那种程度的楔子，依然不够。」',
    "Script/scenario05_13.binu8@61056": '@vNanana_0400「我只不过是个可怜的女人。仅此而已——一个毫无意义的女人。」',
    "Script/scenario05_13.binu8@61158": '　不对。@n　啊，不对。',
    "Script/scenario05_13.binu8@62581": '@vKohaku_0628「闭嘴。」',
    "Script/scenario05_13.binu8@63161": '@vMirai_0372「那只不过是真心话而已。她已经分不清现实与幻想了。」',
    "Script/scenario05_13.binu8@63897": '@vMeguri_0868「真令人火大……真令人火大。」',
    "Script/scenario05_13.binu8@64060": '@vMeguri_0869「我要把这一切全部吞下。」',
    "Script/scenario05_13.binu8@64347": '@vMeguri_0870「……赫尔死了，奥丁。」',
    "Script/scenario05_13.binu8@64595": '@vMeguri_0871「没什么。我只是说出了事实。」',
    "Script/scenario05_13.binu8@64780": '@vKohaku_0630「你恨我吗？」',
    "Script/scenario05_13.binu8@65219": '@vMeguri_0874「……说说过去吧。说说你我相遇时的回忆。我曾是奴隶，而你是王子。但我们发现，彼此心中都怀有相似的意志。」',
    "Script/scenario05_13.binu8@65462": '@vKohaku_0632「你的行为总是带来灾祸。即便如此，有时你也会派上用场，有时还会逗笑我。是你让我见识到了所谓的自由。」',
    "Script/scenario05_13.binu8@66203": '@vMeguri_0877「……啊，是啊。这就是我所认识的奥丁王。人人都说你已经彻底变了，可你果然还在这里。唯有这一点，是无可置疑的事实。」',
    "Script/scenario05_13.binu8@69194": '@vKohaku_0641「我再也不可能与你互相理解。你的自由对我而言就是祸害。那种温吞的诡辩，我已经听不下去了。」',
    "Script/scenario05_13.binu8@69389": '@vMeguri_0884「我鄙视你，奥丁。你的傲慢已经动摇了一切！！」',
    "Script/scenario05_13.binu8@71983": '@vYuuen_0219「洛基，拜托了，现在请安静一点。我明白你积累了很多不满。」',
    "Script/scenario05_13.binu8@73208": '@vMeguri_0893「没错，我最喜欢谎言了。只有谎言、欺瞒和敷衍一直爱着我。唯独真实从不站在我这边。」',
    "Script/scenario05_13.binu8@74047": '@vMeguri_0895「被奥丁驯服的猪。你那双监视一切的眼睛，究竟从什么时候开始变得浑浊了？你所爱的一直都是疯子的妄想。」',
    "Script/scenario05_13.binu8@75648": '@vMeguri_0900「不，我非常正常。真正疯了的是你们！！」',
    "Script/scenario05_13.binu8@76845": '@vRize_0702「我终于明白了。明白自己为什么会在这里。」',
    "Script/scenario05_13.binu8@78243": '@vRize_0705「冰狐的演技充满了感情。她披着角色的外壳，却始终在倾吐自己的心声。所以那演技才会如此打动人。」',
    "Script/scenario05_13.binu8@78814": '@vMeguri_0901「……我闻到了死亡与傲慢的气息。辛酸正在灼烧我的身体。啊啊，我快要疯了。真希望一切都赶快结束。」',
    "Script/scenario05_13.binu8@79532": '@vRize_0708「你恨我吗？」',
    "Script/scenario05_13.binu8@79900": '@vMeguri_0904「即使你屠杀了我的家人，即使你把我投入监狱，世界末日依然会到来。这个国家将在不久的将来灭亡。从奥丁看见未来的那一刻起，这一切就已注定。人物的失去不过是微不足道的小事，谁也无法违抗时代洪流。」',
    "Script/scenario05_13.binu8@80463": '@vRize_0711「……这个国家已经变了。在恐惧迫近的末日时，仍然蛮横地扩充军备。沉重的税负让百姓苦不堪言，不安又催生了恐慌。」',
    "Script/scenario05_13.binu8@80809": '@vRize_0712「奥丁大人已经变了。染指贵族的妻女，沉溺于色欲之中。民众的不满接连不断，也是理所当然。正如您所说，叛乱恐怕真的会发生。」',
    "Script/scenario05_14.binu8@64155": '@vRize_0713「那时候，什么也做不到。所以那孩子也什么都没有要求。无论过去还是现在，箱鸟理世都没有任何特别之处。」',
    "Script/scenario05_14.binu8@64453": '@vMirai_0375「我早就告诉过你愿望了。明明你知道我希望你做什么。」',
    "Script/scenario05_14.binu8@64923": '@vMirai_0328「如果有一天，在遥远的未来，我成为了故事的女主角……」',
    "Script/scenario05_14.binu8@65254": '@vRize_0715「那你为什么要拒绝我？明明在那次面试中，你拒绝了我。」',
    "Script/scenario05_14.binu8@67931": '@vRize_0719「我的工作是监视你。不过，我的守卫并不完美。而且，洛基，我不想亲手舍弃我珍爱的朋友。」',
    "Script/scenario05_14.binu8@68805": '@vMeguri_0908「……是啊。这就是我所认识的将军托尔。」',
    "Script/scenario05_14.binu8@68904": '@vRize_0721「我先走一步，洛基。我们来世再见。」',
    "Script/scenario05_14.binu8@69670": '「理世。」',
    "Script/scenario05_14.binu8@70295": '「那就是那家伙演技的精髓。他能自然而然地演出贴近演员与观众的表演。」',
    "Script/scenario05_14.binu8@71063": '@vRairai_0592「奥丁大人！叛军似乎已经攻破宫殿大门了！这里已经不安全，请立刻撤离！」',
    "Script/scenario05_14.binu8@71580": '@vRairai_0593「请冷静，陛下！事态已经恶化到最糟的地步了。所以现在立刻——」',
    "Script/scenario05_14.binu8@73161": '@vKohaku_0650「就差一点了！胜利的时刻马上就要到来！可是，为什么我的身体在发抖！难道我在恐惧某种无法理解的东西吗！」',
    "Script/scenario05_14.binu8@73401": '@vKohaku_0651「不对！我害怕的不是那种东西！我真正应该害怕的，是神话的实现！数百年、数千年后的未来，在一个发展到连我都无法理解的世界里，你们不曾产生一丝疑问，心安理得地享受和平！你们兴高采烈传颂的所谓北欧神话，实在是太过任性的故事了！」',
    "Script/scenario05_14.binu8@74149": '@vKohaku_0653「……看吧，未来的讲述者们。历史必须被准确地传颂。好好看清邪神洛基的末路吧。」',
    "Script/scenario05_14.binu8@74976": '@vMeguri_0909「……这座宫殿已经被叛军占领了。已经结束了。」',
    "Script/scenario05_14.binu8@75572": '@vMeguri_0910「……奥丁，你的愿望——」',
    "Script/scenario05_14.binu8@75986": '@vMeguri_0911「……我一点也不明白你的愿望……！」',
    "Script/scenario04_4.binu8@85467": '@vHana_0146「……好厉害！！」',
    "Script/scenario04_4.binu8@91292": '@vHana_0154「我很幸福。因为即使到了现在……我也还能像花朵一样绽放笑容。」',
    "Script/scenario05_13.binu8@59984": '　不是洛基……？',
    "Script/scenario05_13.binu8@63569": '@vMeguri_0866「难道你连这一步都已经预料到了吗？」',
    "Script/scenario05_13.binu8@67152": '@vKohaku_0636「……洛基。」',
    "Script/scenario05_13.binu8@67457": '@vKohaku_0637「……没什么。」',
    "Script/scenario05_13.binu8@68004": '　洛基装出平静的样子，进行着清澈纯粹的演技。',
    "Script/scenario05_13.binu8@68270": '@vMeguri_0881「奥丁！！」',
    "Script/scenario05_13.binu8@68329": '@vKohaku_0639「光是聪明还不够！洛基！无论你如何挣扎，都不可能战胜历史！听好了！我来让你看看超越历史的方法！」',
    "Script/scenario05_13.binu8@70070": '「加油……！！」',
    "Script/scenario05_13.binu8@71655": '@vYuuen_0218「洛基！」',
    "Script/scenario05_13.binu8@73432": '@vRairai_0590「……别再继续丢人现眼了。如果你还剩下一丝所谓的自尊，就立刻从这里离开。」',
    "Script/scenario05_13.binu8@74502": '@vMeguri_0896「……啊，是吗。」',
    "Script/scenario05_13.binu8@74725": '@vMeguri_0897「奥丁！！」',
    "Script/scenario05_13.binu8@79032": '@vRize_0707「……洛基。」',
    "Script/scenario05_14.binu8@69570": '　那是一场充满慈悲的演技，与坠入疯狂的洛基形成鲜明对比。',
    "Script/scenario05_14.binu8@70839": '「……那是……」',
    "Script/scenario05_14.binu8@74314": '　故事走向终局。@n　洛基与奥丁，彼此对峙。',
    "Script/scenario05_14.binu8@76235": '　不对。@n　我是在极其冷静的思考下，说出了反叛的话。',
    "Script/scenario05_14.binu8@76597": '@vKohaku_0656「……那是谎言。」',
    "Script/scenario05_14.binu8@77653": '@vOmi_0043「……可是，我大概错了。我并不正确。」',
    "Script/scenario05_14.binu8@78441": '@vYuuen_0207「希望你能理解他。」',
    "Script/scenario05_14.binu8@78672": '@vRize_0681「——我们走吧。」',
    "Script/scenario05_14.binu8@79113": '@vYuuen_0222「……谢谢你，来来小姐。谢谢你引导我走到今天，让我能够挺起胸膛，自称为演员。」',
    "Script/scenario05_14.binu8@79455": '@vYuuen_0224「我是一个可怜、丑陋而软弱的女人。我因焦躁和不安，甚至想要献出身体，抓住某样东西不放。也许在内心深处，我还怨恨过你，怨恨你为什么不肯放过我。」',
    "Script/scenario05_14.binu8@80772": '@vRairai_0600「恨我吧，巡。憎恨我。然后……连这份感情也化为你自己的东西。这样一来，你就无敌了。成为远远超越我们的伟大演员吧。」',
    "Script/scenario05_14.binu8@82793": '@vMeguri_0921「够了！你根本不知道我的感受，还在那里说什么！啊啊，我为什么会变成这样！面对杀害家人的仇人，我甚至连剑都拔不出来！我竟然把你那双野蛮的眼睛，和昔日的你重叠在一起！啊啊，对不起，我亲爱的孩子们！我这个父亲不合格！」',
    "Script/scenario05_14.binu8@83956": '@vKohaku_0662「就以现在清澈的你，迎接死亡吧。这就是我对你所期望的最后命运。」',
    "Script/scenario05_14.binu8@84206": '@vMeguri_0925「我所爱的一切都消失了。相信的东西无法得到救赎。这个世界上只剩下无法抗拒的绝望。无尽的痛苦，正将我的灵魂烧尽。」',
    "Script/scenario05_14.binu8@84662": '　随后，洛基相信着奥丁，迎来了死亡。@n　他没有完成叛乱，也没有刺出手中的刀，只是在思念着奥丁的同时，断了气。',
    "Script/scenario05_14.binu8@86832": '@vKohaku_0667「悲剧会让人成为英雄。英雄终将成为神，神终将编织神话！留下你的名字，传播你的高贵！由你来继承新的神话！」',
    "Script/scenario05_14.binu8@87344": '@vMeguri_9001「辛苦了。」',
    "Script/scenario05_14.binu8@87456": '@vKohaku_0669「……结束了吗？」',
    "Script/scenario05_14.binu8@87822": '@vMeguri_0928「……我好像演出了非常不稳定的一场戏。」',
    "Script/scenario05_14.binu8@87906": '@vKohaku_0671「但很精彩。巡的洛基，真的非常厉害。」',
    "Script/scenario05_14.binu8@88079": '@vMeguri_0929「来，站好。」',
    "Script/scenario05_14.binu8@88141": '@vMeguri_0930「大家，笑一个。」',
    "Script/scenario05_14.binu8@88364": '@vKohaku_0672「……好耀眼。」',
    "Script/scenario05_14.binu8@88656": '「……你们两个，真是……」',
    "Script/scenario05_14.binu8@89325": '@vNanana_0407「我想一直……待在这个地方。」',
    "Script/scenario05_4.binu8@61461": '@vYuuen_0180「好了好了，不可以吓唬她。」',
    "Script/scenario05_4.binu8@61734": '@vRairai_0406「……这家伙明明只是个小学生，架子倒是不小。对前辈说话也太没礼貌了。」',
    "Script/scenario05_4.binu8@61869": '@vYuuen_0181「明明是我们突然闯过来的。抱歉啊，这个人不太坦率。」',
    "Script/scenario05_4.binu8@62333": '@vMeguri_0483「气死我了！」',
    "Script/scenario05_4.binu8@62463": '@vRairai_0409「你喜欢戏剧吧？那就陪我们一下。我们正因为演员不够而发愁呢。」',
    "Script/scenario05_4.binu8@62619": '@vMeguri_0484「……你们是受祖父指使来的？什么嘛……结果还是想把我束缚起来。」',
    "Script/scenario05_4.binu8@62751": '@vRairai_0410「束缚你？你这人真是有够可笑。少沉浸在自己的世界里，小鬼。」',
    "Script/scenario05_4.binu8@63449": '@vRairai_0412「好啊，你这臭小鬼——！！看我现在就把你那副装模作样的脸弄哭！！」',
    "Script/scenario05_4.binu8@63575": '@vMeguri_0487「有本事你就动手。弄伤演员的脸，你以为能轻易了事吗？」',
    "Script/scenario05_4.binu8@63882": '@vYuuen_0182「果然是演员啊。太好了。其实我有件事想拜托你……能不能帮我们演出？我们正因为人手不足而发愁。」',
    "Script/scenario05_4.binu8@64253": '@vMeguri_0489「如果是祖父的命令，我会听从。然后呢？这次又是哪家剧团？」',
    "Script/scenario05_4.binu8@64373": '@vRairai_0414「命令？你在说什么傻话。我们是听说这里有个派得上用场的小鬼才来的。你不愿意就别来，省得碍手碍脚。」',
    "Script/scenario05_4.binu8@64586": '@vMeguri_0490「碍手碍脚！？」',
    "Script/scenario05_4.binu8@64728": '@vRairai_0415「不知道那个老头把你介绍给我们是打的什么主意，反正你也只会演些青涩得要命的东西吧？」',
    "Script/scenario05_4.binu8@64899": '@vYuuen_0183「来、来来小姐……这话说得太过分了。而且，是我们拜托她帮忙的……」',
    "Script/scenario05_4.binu8@65048": '@vMeguri_0491「……祖父还真是随随便便就把我介绍出去了。」',
    "Script/scenario05_4.binu8@65147": '@vMeguri_0492「好，我帮你们。然后用我的实力让你闭嘴。到时候，求我帮忙的人会变成你。」',
    "Script/scenario05_4.binu8@65363": '@vRairai_0416「哈，这才像话嘛，小鬼。至少我承认你脸皮够厚。」',
    "Script/scenario05_4.binu8@65474": '@vMeguri_0493「那么，你们属于哪个剧团？现在就带我过去吧。」',
    "Script/scenario05_4.binu8@65900": '@vYuuen_0185「我们不是剧团的人，只是普通人……是学生戏剧社的成员。」',
    "Script/scenario05_4.binu8@66143": '@vMeguri_0495「祖、祖父到底是什么意思……！？学、学生戏剧社……？」',
    "Script/scenario05_4.binu8@66565": '@vRairai_0420「我们在公园练戏时，一个闲得发慌的老头搭话。他还对我们的练习方法指手画脚……一开始我嫌烦，根本没理他，可那家伙虽然是外行，对戏剧倒挺了解。所以嘛，多少也听了些他的建议。」',
    "Script/scenario05_4.binu8@67029": '@vRairai_0421「他说人手不够，就给我们介绍个合适的小鬼。我们社团都快废部了，连演员都凑不齐。正好想找个有戏剧经验又闲得没事的人。没想到居然是个小学生。」',
    "Script/scenario05_4.binu8@68178": '@vRairai_0422「少自作多情了，谁对你抱期待啊。你只要努力别把台词说错就行！」',
    "Script/scenario05_4.binu8@68657": '@vRairai_0424「我叫天乐来来。你可别直呼我的名字，给我加上‘小姐’，表示尊敬。」',
    "Script/scenario05_4.binu8@68927": '@vYuuen_0186「我叫龙木悠苑。请多关照，巡小姐。」',
    "Script/scenario05_4.binu8@69031": '@vMeguri_0505「请多关照，龙木前辈。」',
    "Script/scenario05_4.binu8@80175": '@vMeguri_0541a「现在得意还太早了。匂宫巡怎么可能会输给别人。」',
    "Script/scenario05_4.binu8@83013": '@vMeguri_0550b「我不要那样！我不想输给琥珀！」',
    "Script/scenario05_4.binu8@84468": '@vMeguri_0554「你不是一直在追求作为导演的成就感吗？那我就让你使用匂宫巡。用我来演出一个足以匹敌琥珀的角色。」',
    "Script/scenario05_6.binu8@91092": '　无能的奈奈菜只是注视着名为不幸的水槽，反复从中获得安心。',
    "Script/scenario05_6.binu8@95067": '@vNanana_0331「——《菲莉亚》。」',
    "Script/scenario05_6.binu8@101510": '@vRize_0607「一、一点点。」',
    "Script/scenario05_7.binu8@82426": '　奈奈菜就在我身边，用她纤细的手臂和我一起分担重量。',
    "Script/scenario05_7.binu8@83051": '「没这回事。你不是还帮我写了剧本吗？要是没有奈奈菜，我真不知道会变成什么样。」',
    "Script/scenario05_7.binu8@87840": '　回过神来的奈奈菜，声音微微变调地说道。',
    "Script/scenario05_9.binu8@90080": '@vTeacherA_0003「所以，学校方面也非常为难。我们并不是说男女交往本身有错，但必须以有分寸的方式相处。」',
    "Script/scenario05_9.binu8@90571": '@vcs_TeacherA_0001_b「我不认为一向勤勉正直的你，会为了不正当的男女关系购买避孕用品。你声称只是为了恶作剧才买的，这应该不是谎话……可是，真相本身已经没有意义了。问题在于，毫无证据的猜测最终公之于众。」',
    "Script/scenario05_4.binu8@80396": '@vRairai_0456「哈哈，够狂。这样才配得上我们剧团的招牌女演员。」',
    "Script/scenario05_4.binu8@80637": '@vRairai_0457「……真的拜托你了。」',
    "Script/scenario05_4.binu8@85724": '@vMeguri_0558「呵呵。」',
    "Script/scenario05_4.binu8@64899": '@vYuuen_0183「来、来来小姐……这话说得太过分了。而且，是我们拜托她帮忙的……」',
    "Script/scenario05_4.binu8@66143": '@vMeguri_0495「祖、祖父到底是什么意思……！？学、学生戏剧社……？」',
    "Script/scenario05_4.binu8@67442": '@vMeguri_0497「原来如此……你是在给学生提供建议，从中获得满足感啊。」',
    "Script/scenario05_4.binu8@67681": '@vMeguri_0498「那他原来所属的剧团呢？真是的，真是个无可救药的男人。」',
    "Script/scenario05_4.binu8@68178": '@vRairai_0422「少自作多情了，谁对你抱期待啊。你只要努力别把台词说错就行！」',
    "Script/scenario05_4.binu8@68531": '@vRairai_0423「喂，臭小鬼。你叫什么名字？」',
    "Script/scenario05_4.binu8@68798": '@vMeguri_0503「请多关照，来来。」',
    "Script/scenario05_4.binu8@68843": '@vRairai_0425「你这家伙！！」',
    "Script/scenario05_4.binu8@69031": '@vMeguri_0505「请多关照，龙木前辈。」',
    "Script/scenario06b_7.binu8@32230": '@vFutaba_0726「那么，天使酱顶级偶像化计划，现在开始——！」',
    "Script/scenario06b_7.binu8@32447": '@vNanana_0804「那、那个……！」',
    "Script/scenario06b_7.binu8@32590": '@vNanana_0805「请、请多关照……！！」',
    "Script/scenario06b_7.binu8@33049": '@vFutaba_0728「在这个时代，女孩子的照片很容易出现在人们眼前。就这样轻松地多尝试一些，哪怕只提高一点知名度也好。」',
    "Script/scenario06b_7.binu8@33241": '@vNanana_0806「……原、原来如此！」',
    "Script/scenario06b_7.binu8@33932": '@vFutaba_0731「视频拍摄就全权交给环。先由你们两个人商量着试拍十条左右吧。要在短短十一秒里，把天使酱的魅力全部塞进去。」',
    "Script/scenario06b_7.binu8@34168": '「这么突然？摄影不是该由双叶来负责吗？」',
    "Script/scenario06b_7.binu8@34281": '@vFutaba_0732「有时候，保留一点外行人的感觉反而更好。而且总由我来拍也不行，最后只会全都变成我喜欢的风格。」',
    "Script/scenario06b_7.binu8@34503": '@vNanana_0807「双、双叶酱，好厉害……！居然考虑得这么周全……！」',
    "Script/scenario06b_7.binu8@34620": '@vFutaba_0733「因为这是为了把天使酱培养成偶像呀！」',
    "Script/scenario06b_7.binu8@34915": '@vNanana_0808「双、双叶酱……！你夸过的那条视频，完全没有人气……呜呜，果然像奈奈这样的……！」',
    "Script/scenario06b_7.binu8@35086": '@vFutaba_0734「视频做得好，并不代表一定会有人看。能不能爆红，有时也要看运气……可恶可恶可恶！」',
    "Script/scenario06b_7.binu8@35287": '@vNanana_0809「不过，看到大家给我点赞，总觉得很开心。好像大家的努力终于得到了认可……！」',
    "Script/scenario06b_7.binu8@35452": '@vFutaba_0735「呜哦——！为了让天使酱露出笑容，我也要加油——！」',
    "Script/scenario06b_7.binu8@36270": '@vFutaba_0738「……其实我很想把摄影棚整个租下来。不过现在只能先在环家里将就一下。」',
    "Script/scenario06b_7.binu8@36503": '@vFutaba_0739「没关系，许可已经拿到了。还能顺便帮店里宣传，所以一切都没问题！」',
    "Script/scenario06b_7.binu8@36700": '@vFutaba_0740「好了，请你安静地站着！还有，拿反光板的环，请保持安静。」',
    "Script/scenario06b_7.binu8@36808": '「太过分了。」',
    "Script/scenario06b_7.binu8@36923": '@vNanana_0810「我、我才没有这么可爱吧……？」',
    "Script/scenario06b_7.binu8@37063": '@vFutaba_0741「不，天使酱就是很可爱。这才是理所当然的。只不过平时没能好好发挥出来而已。」',
    "Script/scenario06b_7.binu8@37231": '「原来如此啊。」',
    "Script/scenario06b_7.binu8@37827": '「对吧？准备一些流行角色的服装，说不定就能让大家通过作品认识奈奈菜。」',
    "Script/scenario06b_7.binu8@38149": '@vNanana_0811「……那个，如果环君希望我出角色扮演，我可以试试。」',
    "Script/scenario06b_7.binu8@38301": '@vNanana_0812「如果可以的话……我更喜欢护士、巫女之类，不属于某部作品的装扮。」',
    "Script/scenario06b_7.binu8@39687": '@vNanana_0816「直、直播就算了吧……！因为我完全不知道该说些什么……！」',
    "Script/scenario06b_7.binu8@39866": '@vNanana_0817「不是不行！只是……我怕没办法让来看直播的人开心……」',
    "Script/scenario06b_7.binu8@40176": '@vFutaba_0746「开着摄像机，笑一笑、惊讶一下、动一动，这样就足够了。观众想看的就是可爱或性感。想看有趣内容的人，自然会去找有趣的主播。」',
    "Script/scenario06b_7.binu8@40778": '@vFutaba_0747「……难得环说得有道理。我也赞成直播。」',
    "Script/scenario06b_7.binu8@40895": '@vNanana_0819「呜、呜呜……！我、我会努力的……！！」',
    "Script/scenario06b_7.binu8@41199": '@vFutaba_0748「气死我了——～～～～！！为什么要落选天使酱！？那个评委根本没有眼光！啊啊，真让人火大！！」',
    "Script/scenario06b_7.binu8@41412": '@vNanana_0820「果、果然还是演技不够好吗……」',
    "Script/scenario06b_7.binu8@42499": '@vFutaba_0751「不求回报地努力，这就叫美德。我只是为了自己的愿望才待在这里。」',
    "Script/scenario06b_7.binu8@42690": '@vFutaba_0752「你最好小心，别被人寝取了。毕竟环可是把自己的敌人招进了身边。」',
    "Script/scenario06b_7.binu8@42978": '@vNanana_0822「环君、环君！我想再拍一次视频……！！」',
    "Script/scenario06b_7.binu8@43385": '「喂，奈奈菜。」',
    "Script/scenario06b_8.binu8@32792": '「……这下没救了。」',
    "Script/scenario06b_8.binu8@33471": '「紧张也是没办法的事。不过，身体可不能僵住。」',
    "Script/scenario06b_8.binu8@33669": '@vcs_Nanana_0014「好、好的……！」',
    "Script/scenario06b_8.binu8@33776": '「你的笑容还是有点僵硬呢。」',
    "Script/scenario06b_8.binu8@34063": '@vcs_Nanana_0016「好、好的……」',
    "Script/scenario06b_8.binu8@34146": '@vcs_Nanana_0017「那、那个……果然还是觉得像被人偷看……像被人监视……该怎么说呢，有点害怕……」',
    "Script/scenario06b_8.binu8@34379": '「没什么好怕的。因为取景器另一边的人，是我啊。」',
    "Script/scenario06b_8.binu8@34736": '@vcs_Nanana_0018「只有我们两个人……」',
    "Script/scenario06b_8.binu8@35126": '@vcs_Nanana_0020「只有我和环君两个人。如果连现在都不懂得享受……那就是非常坏的孩子了。」',
    "Script/scenario06b_8.binu8@35487": '「奈奈菜。」',
    "Script/scenario06b_8.binu8@35789": '@vcs_Nanana_0023「突、突然说这种话！那、那个……？奈奈、也……！」',
    "Script/scenario06b_8.binu8@36026": '@vcs_Nanana_0024「那、那个……？」',
    "Script/scenario06b_8.binu8@36379": '「再笑得开心一点。」',
    "Script/scenario06b_8.binu8@36411": '　不是为了工作。@n　大概正因为想为自己留下影像，我才有了努力的动力。',
    "Script/scenario06b_8.binu8@36757": '「我想把这一刻永远保存下来。」',
    "Script/scenario06b_8.binu8@36825": '@vcs_Nanana_0026「我、我好开心……！」',
    "Script/scenario06b_8.binu8@37072": '@vcs_Nanana_0027「好、好！我觉得自己还能继续努力！」',
    "Script/scenario06b_8.binu8@37325": '@vcs_Nanana_0028「好，来个胜利手势！」',
    "Script/scenario06b_8.binu8@37478": '@vFutaba_0753「对了，前几天女仆装的照片特别火。看来偶尔还是能派上用场的。」',
    "Script/scenario06b_8.binu8@37986": '@vFutaba_0755「……不过，能引出那种表情的不是相机，而是环。因为是环，她才会露出那样有魅力的表情。她看着镜头的眼神，就是恋爱少女的眼神。」',
    "Script/scenario06b_8.binu8@38223": '@vFutaba_0756「好了，闲聊到此为止。今天可是天使酱的主场，要打起精神来。」',
    "Script/scenario06b_8.binu8@38863": '@vNanana_0916「我、我太紧张了，啊呜啊呜啊呜……！！！ 」',
    "Script/scenario06b_8.binu8@39030": '「——加油。」',
    "Script/scenario06b_8.binu8@39192": '@vNanana_0918「……呼……」',
    "Script/scenario06b_8.binu8@41237": '@vNanana_0922「这种煞风景的指摘，可是犯忌的哦。」',
    "Script/scenario06b_8.binu8@41362": '@vNanana_0923「还请不要投诉，也不要退货。」',
    "Script/scenario06b_8.binu8@41523": '@vNanana_0924「哥哥这种生物，就是会爱妹妹的哦。」',
    "Script/scenario06b_8.binu8@41740": '@vNanana_0925「大家都在祝福奈奈和环君结为连理。」',
    "Script/scenario06b_8.binu8@41931": '@vNanana_0926「恭喜，恭喜，恭喜。」',
    "Script/scenario06b_8.binu8@42203": '@vNanana_0927「——题名：《七色壁炉》。」',
    "Script/scenario06b_8.binu8@42637": '@vNanana_0928「……我全都明白。」',
    "Script/scenario06b_8.binu8@42995": '@vNanana_0929「我们由与梦相同的事物构成，而我们短暂的生命也将随睡眠一同结束。」',
    "Script/scenario06b_8.binu8@43170": '@vNanana_0930「无论让自己留在岛上，还是回到那不勒斯，都取决于观众的心情。请用掌声解开我的枷锁，让我获得自由。」',
    "Script/scenario06b_8.binu8@43476": '@vNanana_0931「我很幸福。」',
    "Script/scenario06b_8.binu8@43518": '　我确实是幸福的。',
    "Script/scenario06b_8.binu8@43559": '@vNanana_0932「——我确实是幸福的。」',
    "Script/scenario06b_8.binu8@32637": '　穿着可爱女仆装的奈奈菜，露出了有些僵硬的笑容。',
    "Script/scenario06b_8.binu8@33551": '　不需要笑得天真烂漫。@n　只要能拍下奈奈菜可爱的一面就够了。',
    "Script/scenario06b_8.binu8@36882": '　从今往后，奈奈菜还会无数次在镜头前露出笑容。@n　只希望她不要忘记，在镜头的另一边，一直有我在。',
    "Script/scenario06b_8.binu8@39272": '@vNanana_0919「我是天使奈奈菜！谢谢大家今天来看我☆」',
    "Script/scenario06_1.binu8@83074": '@vRairai_0613「……啧。」',
    "Script/scenario06b_7.binu8@35717": '@vFutaba_0736「这种从头到脚打量的角度不是很好吗！把可爱美少女拍得又黏又有情调！你怎么就是不明白啊！？！」',
    "Script/scenario06b_7.binu8@36647": '「拍摄还真是个体力活啊。」',
    "Script/scenario06b_7.binu8@38477": '@vNanana_0813「那、那个……」',
    "Script/scenario06b_7.binu8@38575": '@vNanana_0814「如、如果要扮演某部作品的角色……我不想只是因为它受欢迎，或者因为想出名……我想扮演自己喜欢的角色。想、想好好喜爱那个角色……」',
    "Script/scenario06b_7.binu8@38916": '@vNanana_0815「如果是环君希望我扮演什么角色，那就另当别论了！？可、可是，如果只是靠这个来积累人气，我总觉得……有点不对……」',
    "Script/scenario06b_7.binu8@39247": '@vFutaba_0744「那种方法本身并没有错。迎合潮流也可以……但那不适合天使酱。」',
    "Script/scenario06b_7.binu8@40550": '「……不过我不会强迫你的。」',
    "Script/scenario06b_7.binu8@42007": '「……喂，双叶。」',
    "Script/scenario06b_7.binu8@42479": '　可是。',
    "Script/scenario06b_7.binu8@42667": '「……双叶。」',
    "Script/scenario06b_8.binu8@35608": '「我爱你。」',
    "Script/scenario06b_8.binu8@37628": '「啊，你说那个啊。奈奈菜也一直很耐心地配合我。」',
    "Script/scenario06_1.binu8@89837": '「……明明为了不让奈奈菜出演的事曝光，我还特意瞒着，没想到还是会被看出来啊。现在我才真正体会到，天使奈奈菜作为偶像的影响力。」',
    "Script/scenario06_2.binu8@89217": '咚咚',
    "Script/scenario06_3.binu8@51911": '@vMirai_0423「阴沉的北海天空下」',
    "Script/scenario06_3.binu8@52060": '@vMirai_0425「不知何时才会结束的诅咒」',
    "Script/scenario06_4.binu8@86326": '「哦、哦……抱歉，我之前没注意到。」',
    "Script/scenario06_4.binu8@88344": '「……你也找到了属于自己的形式啊。」',
    "Script/scenario06_5.binu8@68313": '@vRize_0879「……冰狐也是如此。她的做法……我根本不忍心正眼看下去。削减身体，磨损心灵，用一种注定无法长久的方法增强演技的冲击力。」',
    "Script/scenario06_6.binu8@83011": '@vRize_0964「教室不行。那里的人太多了。」',
    "Script/scenario06_6.binu8@83392": '@vRize_0967「……心跳得好快啊。」',
    "Script/scenario06_6.binu8@83934": '@vRize_0971「嗯，啾……」',
    "Script/scenario06_6.binu8@84374": '@vRize_0974「哈……！哈……！」',
    "Script/scenario06_6.binu8@84503": '@vRize_0975「还、还想要……」',
    "Script/scenario06_6.binu8@84607": '「理世……那个，你的胸口……碰到了……」',
    "Script/scenario06_6.binu8@84839": '@vRize_0977「如果你想摸的话……嗯，好、好啊……？只、只摸一点的话……」',
    "Script/scenario06_6.binu8@85197": '@vRize_0979「嗯，啾……啊，嘴唇的触感让我脑子都要坏掉了……这个，好厉害。」',
    "Script/scenario06_6.binu8@85889": '「……理世，你啊。」',
    "Script/scenario06_6.binu8@86411": '@vRize_0984「呜呜呜～～～！可、可是也没办法吧？昨、昨天你只做了一点点……」',
    "Script/scenario06_7.binu8@89999": '@vRize_1013「嗯，啾……」',
    "Script/scenario06_7.binu8@95389": '@vRize_1039「才、才不是那样呢！？如果是工作，我会认真做好的。」',
    "Script/scenario06_1.binu8@83697": '@vOboro_0268「呵呵，那还真让人高兴。不过，除了我之外，应该也有其他人表现得很出色吧。」',
    "Script/scenario06_10.binu8@51141": '　这是通过工作上的熟人介绍而接到的委托。',
    "Script/scenario06_10.binu8@63955": '@vRize_1383「题名：《茜色的幻惑》。」',
    "Script/scenario06_3.binu8@51513": '@vMirai_0421「——中原中也，《北方的海》。」',
    "Script/scenario06_3.binu8@52824": '　那甚至算不上演技，只是传达诗歌的工作。',
    "Script/scenario06_3.binu8@59625": '咚咚',
    "Script/scenario06_4.binu8@75900": '@vMirai_0463「好好回想起来。不要移开视线，别去看戏剧世界令人讨厌的那一面。理世小姐应该也很清楚吧。嫉妒与怨恨，彼此说着坏话；因为人际关系纠葛而无法顺利进行的现场；因为感情纠纷而爆发的无聊争斗。啊啊，真是尽是丑陋的东西。」',
    "Script/scenario06_4.binu8@91120": '　原来我一直因为有人希望我成为演员，而感到喜悦。',
    "Script/scenario06_4.binu8@91385": '　那一刻，我终于能发自内心地觉得，回到演员这条路上真是太好了。',
    "Script/scenario06_5.binu8@80859": '「我确实想给戏剧画上句号，也确实有过‘已经尽力而为’的想法。正因为如此，我才突然想到：继续参与戏剧的我，和过着普通生活的我。就在那时，我明白了——幸福对我而言，可以有很多种形式。」',
    "Script/scenario06_6.binu8@68656": '@vRize_0924「——我好开心。」',
    "Script/scenario06_6.binu8@75313": '@vFutaba_0771「因为我有天使酱嘛！讨厌的虫子也消失了，真开心！」',
    "Script/scenario06_6.binu8@82351": '「我也很开心，理世。原来想见你的人，并不只有我。」',
    "Script/scenario06_6.binu8@82537": '「正因为彼此不同，才会在偶然相逢时感到高兴。积极一点吧。」',
    "Script/scenario06_6.binu8@84543": '「理世……」',
    "Script/scenario06_6.binu8@86959": '「不过，我真的很开心。」',
    "Script/scenario06_7.binu8@105142": '「咦？可是清扫应该已经差不多结束了……」',
    "Script/scenario06_7.binu8@105390": '　理世那积极主动的话语，让我感到开心。',
    "Script/scenario06b_1.binu8@71744": '　一个疑问从喉咙深处涌出。@n　然而，看着奈奈菜的侧脸，疑问便彻底消失了。',
    "Script/scenario06b_1.binu8@71894": '@vRize_0723「不过，那真是一场精彩的戏。开演前我还担心会变成什么样……但大家都努力了。」',
    "Script/scenario06b_1.binu8@76720": '@vFutaba_0636「听说他今天要请假，好像是因为有会议什么的。似乎是来看《菲莉亚》演出的业内人士想和他谈谈。」',
    "Script/scenario06b_1.binu8@81455": '@vMeguri_0941「哎呀，进展真快。我是以前受你祖父剧团照顾过的编剧。听说现在已经小有名气了。」',
    "Script/scenario06b_1.binu8@82892": '@vMeguri_0948「奈奈菜也是。就算邀请了新的编剧，也不代表你就没有容身之处。想继续的话，就自己争取。这个世界就是竞争。」',
    "Script/scenario06b_1.binu8@85664": '咚咚',
    "Script/scenario06b_1.binu8@88113": '「等、等一下！我又没有被奈奈菜告白啊！？」',
    "Script/scenario06b_2.binu8@71526": '「你为什么会知道奈奈菜的排班啊……」',
    "Script/scenario06b_2.binu8@74511": '@vReiji_0060「……嗯？你为什么会在这里……哦？看来奈奈菜在这里，也不是猜错了。」',
    "Script/scenario06b_2.binu8@75524": '@vReiji_0062「……好久不见，奈奈菜。不用我说，你也知道我来是为了什么吧？」',
    "Script/scenario06b_2.binu8@76385": '@vMeguri_0971「正是如此。奈奈菜由兰比利斯剧团负责照顾。所以，无关的外人请回去重新排队吧？」',
    "Script/scenario06b_2.binu8@76571": '　没事的，奈奈菜。@n　这里和你曾经度过的地狱，完全不同。',
    "Script/scenario06b_2.binu8@78384": '@vReiji_0068「好啊，随你便！我本来就没把奈奈菜当回事！只是我妈叫我把她带回去，我才不得不……！！」',
    "Script/scenario06b_2.binu8@79282": '@vReiji_0070「听说你的表现后，她高兴得不得了。还说‘你果然还是想当偶像吧’。你就高兴吧，奈奈菜。看来你妈妈还打算把你培养成偶像。」',
    "Script/scenario06b_2.binu8@82698": '「别强人所难啊。」',
    "Script/scenario06b_2.binu8@82848": '@vNanana_0465「你还记得这个地方吗？」',
    "Script/scenario06b_2.binu8@82911": '「当然记得啊。」',
    "Script/scenario06b_2.binu8@83594": '@vNanana_0468「……可是我逃不掉。已经无可奈何了。因为，我是天使奈奈菜。」',
    "Script/scenario06b_2.binu8@83991": '@vNanana_0469「……可是这样会给大家添麻烦。」',
    "Script/scenario06b_2.binu8@84116": '@vNanana_0470「我的妈妈是天使美嘉。她是演艺圈里很有影响力的知名女演员。」',
    "Script/scenario06b_2.binu8@84286": '@vNanana_0471「这样下去会给大家添麻烦。所以，我不能违抗妈妈。」',
    "Script/scenario06b_3.binu8@67145": '@vMika_0111「奈奈菜真是个好孩子呢。」',
    "Script/scenario06b_3.binu8@67550": '@vNanana_0483「我想成为像妈妈那样的偶像。」',
    "Script/scenario06b_3.binu8@67696": '　因为知道有人期待着自己……我便主动立志成为偶像。',
    "Script/scenario06b_3.binu8@68488": '@vMika_0112「没关系。你在这里积累的经验，会成为你的力量。」',
    "Script/scenario06b_3.binu8@69439": '「请多关照。」',
    "Script/scenario06b_3.binu8@69577": '「请多关照，奈奈菜酱。」',
    "Script/scenario06b_3.binu8@70188": '@vMika_0114「给立志成为偶像的你出一道课题吧。」',
    "Script/scenario06b_3.binu8@70874": '@vMika_0117「没错。所以，你必须去爱上一段无法实现的恋情。他看你的眼神里没有一丝兴趣，因此最适合成为奈奈菜的恋爱对象。」',
    "Script/scenario06b_3.binu8@71372": '@vMika_0118「我们每天一起努力吧。没关系，你一定做得到。」',
    "Script/scenario06b_3.binu8@71766": '@vMika_0120「当然，睡觉前也一样。临睡前，要更用力地低声说‘我爱你’。」',
    "Script/scenario06b_3.binu8@72059": '@vNanana_0488「……只有这些吗？」',
    "Script/scenario06b_3.binu8@72576": '@vNanana_0490「喜、喜欢……」',
    "Script/scenario06b_3.binu8@72734": '　我想，自己花了相当长的时间才习惯这一切。',
    "Script/scenario06b_3.binu8@73117": '@vNanana_0492「喜欢、喜欢、喜欢、喜欢、喜欢、喜欢、喜欢、喜欢、喜欢……」',
    "Script/scenario06b_3.binu8@73299": '@vNanana_0493「最喜欢、喜欢、喜欢你、喜欢……」',
    "Script/scenario06b_3.binu8@74073": '　直到现在，我也不知道那究竟是不是正确的喜欢。',
    "Script/scenario06b_3.binu8@74363": '@vMika_0123「真是让人刮目相看啊，奈奈菜。」',
    "Script/scenario06b_3.binu8@74415": '@vMika_0124「比以前可爱多了。你已经成为一个惹人怜爱的少女了。」',
    "Script/scenario06b_3.binu8@74590": '　不知道是不是受那件事影响，我确实觉得自己改变了许多。',
    "Script/scenario06b_3.binu8@75318": '@vNanana_0502「……我是天使奈奈菜。」',
    "Script/scenario06b_3.binu8@75703": '　我已经不再反复看着照片说“喜欢”了。',
    "Script/scenario06b_3.binu8@76372": '「——别开玩笑了。」',
    "Script/scenario06b_3.binu8@77461": '@vNanana_0507「因为奈奈菜是个卑鄙、卑鄙的女人，只会演恋爱少女，对吧。」',
    "Script/scenario06b_3.binu8@77880": '@vMika_0110「辛苦你一直演恋爱少女了。多亏如此，你已经变成一个非常非常可爱的女孩。」',
    "Script/scenario06b_3.binu8@78046": '　连我自己也不明白。',
    "Script/scenario06b_3.binu8@78393": '@vMika_0125「奈奈菜，所以和我一起——」',
    "Script/scenario06b_3.binu8@78566": '@vNanana_0508「……算了。」',
    "Script/scenario06b_3.binu8@78732": '@vNanana_0509「我已经……」',
    "Script/scenario06b_3.binu8@79379": '@vNanana_0512「我已经不再做可爱的孩子了。」',
    "Script/scenario06b_3.binu8@79506": '@vNanana_0513「还说什么‘喜欢上他’。」',
    "Script/scenario06b_3.binu8@79607": '@vNanana_0514「还说什么‘偶像’。」',
    "Script/scenario06b_3.binu8@79732": '@vNanana_0515「……全都是你的错。全部、全部、全部，都是你的错。从头到尾，一切都是你的错。我、我、我……我明明不是你的奴隶……！！」',
    "Script/scenario06b_3.binu8@80067": '@vNanana_0516「太奇怪了，太奇怪了，肯定很奇怪。因为这本来就是异常。就因为我是出轨对象的孩子，你就要做到这种地步吗？」',
    "Script/scenario06b_3.binu8@80259": '@vNanana_0517「如果你只是因为憎恨我、讨厌我，所以利用我、榨干我，甚至逼我出卖身体……那我还可以理解。可是……可是你呢？」',
    "Script/scenario06b_3.binu8@80626": '@vNanana_0518「唯独那句话，我无论如何都无法原谅。你那句残酷的话，把我的一切都彻底粉碎了。」',
    "Script/scenario06b_3.binu8@83107": '　你甚至从来没想过要让那段恋情实现，对吧？',
    "Script/scenario06b_3.binu8@83308": '@vNanana_0529「我也想骄傲地说自己喜欢他！我也想像普通女孩一样，为一段不稳定的恋情患得患失！可是，那段感情……！」',
    "Script/scenario06b_3.binu8@83565": '@vNanana_0530「我脑子里一直有个声音。那个命令始终回响着，让我爱上他。」',
    "Script/scenario06b_3.binu8@83777": '@vNanana_0531「每次照镜子，我都厌恶那个只剩可爱的自己。毫无意义、毫无根据、无聊透顶的可爱——仿佛映照出了我的恋心。」',
    "Script/scenario06b_3.binu8@84082": '@vNanana_0532「我最讨厌那个只会装可爱的自己。」',
    "Script/scenario06b_3.binu8@84198": '@vNanana_0533「那份可爱，把我的卑劣表现得一清二楚。」',
    "Script/scenario06b_3.binu8@84397": '@vNanana_0534「真正可爱的人，不会像我这样肮脏。」',
    "Script/scenario06b_3.binu8@84621": '@vNanana_0535「啊啊，如果愿望能够实现，我真想从出生以前就重新来过。」',
    "Script/scenario06b_3.binu8@84720": '　想在一个与这里相隔遥远的新地方，从头开始一切。',
    "Script/scenario06b_3.binu8@84812": '@vNanana_0536「那样的话，我这次一定要好好活着，好好活着，好好活着——然后去恋爱。想像普通人一样，喜欢上你。」',
    "Script/scenario06b_3.binu8@68206": '　那就是人们赋予名为天使奈奈菜的少女的角色。',
    "Script/scenario06b_3.binu8@68404": '@vNanana_0484「演、演员什么的，奈奈菜做不到……！」',
    "Script/scenario06b_3.binu8@85305": '@vNanana_0538「……总觉得。」',
    "Script/scenario06b_3.binu8@85705": '@vNanana_0539「……不行的。因为我知道，环君……无论我的心情如何，你都不会喜欢上我。」',
    "Script/scenario06b_3.binu8@86223": '@vMirai_0386「所以，只要许愿就好。告白的话不能说错，一个字一个字都不能错。如果你想确认自己的感情是真实的——那就试试看吧。」',
    "Script/scenario06b_3.binu8@86676": '@vNanana_0541「可是，那样的话……」',
    "Script/scenario06b_3.binu8@87340": '@vMirai_0389「过程由我来准备。故事，就让白发红眼的我来编织吧。」',
    "Script/scenario06b_3.binu8@88976": '@vNanana_0545「我，天使奈奈菜，爱着濑和环君。」',
    "Script/scenario06b_3.binu8@89299": '　我一定从来都没有真正明白。',
    "Script/scenario06b_3.binu8@89588": '「啊，我很乐意。」',
    "Script/scenario06b_3.binu8@89723": '@vMirai_0391「好啦，大团圆大团圆，幸福结局。」',
    "Script/scenario06b_3.binu8@90083": '　要是奈奈菜是我的妹妹就好了。',
    "Script/scenario06b_3.binu8@90755": '「我……」',
    "Script/scenario06b_3.binu8@91091": '「喂——奈奈菜！差不多该起床了——」',
    "Script/scenario06b_3.binu8@91307": '@vNanana_0550「……呼呼……」',
    "Script/scenario06b_3.binu8@91396": '　睡在其中的奈奈菜毫无防备，肌肤裸露在外。',
    "Script/scenario06b_3.binu8@91624": '@vNanana_0551「……哥哥……」',
    "Script/scenario06b_3.binu8@91796": '「起床——！不然我就先走了——？」',
    "Script/scenario06b_3.binu8@91980": '@vNanana_0553「……唔……嗯……咦？环君？你为什么会在奈奈的房间里……」',
    "Script/scenario06b_3.binu8@92106": '　奈奈菜揉着惺忪的睡眼说道。',
    "Script/scenario06b_3.binu8@92171": '「照这个样子，看来还要花不少时间啊。不好意思，我先走了。」',
    "Script/scenario06b_3.binu8@92450": '@vNanana_0555「不、不要！等、等一下，环君……！不要把奈奈丢下！我想和你一起……！」',
    "Script/scenario06b_3.binu8@92689": '@vNanana_0556「只、只要等五分钟就好……！我马上就准备好……！」',
    "Script/scenario06b_3.binu8@92937": '@vNanana_0557「我、我会打扮得很可爱的，等我一下……！我想和你一起嘛——！」',
    "Script/scenario06b_3.binu8@93077": '@vNanana_0558「哇——！！等一下、等一下、等一下……！！」',
    "Script/scenario06b_3.binu8@93187": '@vNanana_0559「我、我刚才明明才说四分钟……！你骗人嘛……！」',
    "Script/scenario06b_4.binu8@63564": '「根本没赶上吧。结果还是花了二十五分钟啊？」',
    "Script/scenario06b_4.binu8@63647": '@vNanana_0562「对、对奈奈来说已经很努力了！平时可是要花一个半小时的！」',
    "Script/scenario06b_4.binu8@63847": '@vNanana_0563「就、就算奈奈再笨手笨脚，也不至于那么久吧！」',
    "Script/scenario06b_4.binu8@64150": '「女孩子还真辛苦啊。」',
    "Script/scenario06b_4.binu8@64194": '@vNanana_0565「……可是你还是等我了。果然不愧是奈奈的哥哥。」',
    "Script/scenario06b_4.binu8@64305": '「毕竟让你一个人走，可能会迷路。」',
    "Script/scenario06b_4.binu8@65258": '@vNanana_0570「……环君真是太宠人了。」',
    "Script/scenario06b_4.binu8@65318": '「谁让妹妹对我来说很特别呢。」',
    "Script/scenario06b_4.binu8@65596": '@vNanana_0572「……没关系。请把它弄得更乱一点。」',
    "Script/scenario06b_4.binu8@65757": '@vNanana_0573「因为我就是为了被哥哥弄乱，才特意整理好的。」',
    "Script/scenario06b_4.binu8@66574": '「……早上好，琥珀。你也是迟到组的吗？」',
    "Script/scenario06b_4.binu8@67079": '@vKohaku_0691「我吓了一跳。没想到自己真的会对奈奈菜酱产生欲望。」',
    "Script/scenario06b_4.binu8@67244": '@vKohaku_0692「我好像明白她为什么能作为偶像走红了。真厉害，也真可怕。对我来说，那是有点难以踏入的领域。」',
    "Script/scenario06b_4.binu8@67490": '@vKohaku_0693「环君也会觉得骄傲吧。既然有这么可爱的妹妹，每天一定都很开心。」',
    "Script/scenario06b_4.binu8@68220": '@vKohaku_0695「下一部剧本也由奈奈菜酱负责吧？我很期待哦！」',
    "Script/scenario06b_4.binu8@68346": '@vNanana_0580「……哪、哪有。」',
    "Script/scenario06b_4.binu8@68391": '　面对过于沉重的期待，奈奈菜缩起了身体。',
    "Script/scenario06b_4.binu8@68926": '@vFutaba_0675「啊——好无聊，好无聊。能不能掉颗陨石下来？……最好正好砸在环的头上。」',
    "Script/scenario06b_4.binu8@69096": '@vFutaba_0676「装得真像啊。明明一直假装对天使酱没兴趣，结果最后才说原来你们是兄妹，这不是典型的事后出牌吗。真想现在就捅你一刀！」',
    "Script/scenario06b_4.binu8@69339": '「冷静点，我也……对，我也有自己的苦衷。」',
    "Script/scenario06b_4.binu8@69700": '「我是有原因的。也是迫不得已的原因。」',
    "Script/scenario06b_4.binu8@70043": '@vFutaba_0679「兄妹关系才是最危险的吧——！！」',
    "Script/scenario06b_4.binu8@70337": '@vFutaba_0680b「如果我是天使酱的哥哥，就会装作偶然闯进她的房间，然后强行……嘿嘿，嘻嘻嘻……」',
    "Script/scenario06b_4.binu8@70503": '「你才是最危险的那只虫子吧。」',
    "Script/scenario06b_4.binu8@70831": '「你对奈奈菜的信仰还真可怕啊。」',
    "Script/scenario06b_4.binu8@70893": '@vFutaba_0683「这不是理所当然的吗？这就是偶像宅这种人类。……不过我自认为还是有分寸的。毕竟，只要天使酱幸福，那就足够了。」',
    "Script/scenario06b_4.binu8@71263": '@vFutaba_0684「哈啊～～～～好可爱，好可爱啊。可是，天使酱之所以这么可爱，是因为她恋爱过吧……好令人难受……偏偏对象还是这种家伙……」',
    "Script/scenario06b_4.binu8@71586": '@vFutaba_0685「……匂宫小姐也太善良了。一看胜算不大，就转到支持者那边去了。明明我本来想妨碍你们的……可恶，搞得好像我才是小人物一样。」',
    "Script/scenario06b_4.binu8@72055": '@vFutaba_0687「……环，你是怎么看天使酱的？」',
    "Script/scenario06b_4.binu8@72148": '「嗯？我当然把她当成世上最可爱的妹妹啊？」',
    "Script/scenario06b_4.binu8@72403": '「话说回来，我家奈奈菜是什么时候和匂宫关系变得这么好的？不久前明明还是完全无法想象的组合吧？」',
    "Script/scenario06b_4.binu8@72687": '「你这是什么敷衍的回答……」',
    "Script/scenario06b_4.binu8@72740": '@vFutaba_0690「我觉得匂宫小姐本来就很喜欢天使酱。你看，她就是那种害羞又可爱的女孩子，很适合拿来欺负。」',
    "Script/scenario06b_4.binu8@73054": '@vFutaba_0691a「哈？真是个不懂的人。带着爱意的欺负，是很甜美的。匂宫小姐可是非常明白这一点的。」',
    "Script/scenario06b_4.binu8@73253": '@vFutaba_0691b「她特别擅长引出女孩子害羞的一面……！」',
    "Script/scenario06b_5.binu8@19257": '@vcs_Nanana_0001「没想到你竟然愿意接受奈奈的心意……我、我真的好开心。」',
    "Script/scenario06b_5.binu8@20358": '「奈奈菜，你干什么一直盯着我？难道……」',
    "Script/scenario06b_5.binu8@20587": '「奈奈菜真是个积极主动的妹妹啊。」',
    "Script/scenario06b_5.binu8@20640": '@vcs_Nanana_0006「咦、咦咦咦！？不、可是，那、那个……呜呜……」',
    "Script/scenario06b_5.binu8@20810": '@vcs_Nanana_0007「因、因为书上说，普通的哥哥更喜欢主动的妹妹……！」',
    "Script/scenario06b_5.binu8@20945": '「这倒也不能说错……」',
    "Script/scenario06b_5.binu8@21405": '@vcs_Nanana_0009「只有哥哥才可以宠爱妹妹……之类的。」',
    "Script/scenario06b_5.binu8@21787": '@vNanana_0705「奈、奈奈也拼命学习了！为了成为适合哥哥的妹妹！」',
    "Script/scenario06b_5.binu8@21934": '「不用这么拼命也没关系。奈奈菜本来就很可爱了。」',
    "Script/scenario06b_5.binu8@22133": '@vNanana_0707「……如果不拼命追求这些，我就好像会变成一个冒牌妹妹。总觉得这段幸福的时光，会突然整个颠倒过来。」',
    "Script/scenario06b_5.binu8@22693": '「奈奈菜真是个笨蛋。」',
    "Script/scenario06b_5.binu8@22920": '「我们两个人一起幸福吧。我们已经度过了那么美好的夜晚……幸福早就已经被许下了。」',
    "Script/scenario06b_5.binu8@23191": '@vNanana_0711「我想只看眼前的一切，好好品味幸福的感觉。因为我是世界上最幸福的人！」',
    "Script/scenario06b_5.binu8@24073": '　奈奈菜停下话语，把视线投向了遥远的某处。',
    "Script/scenario06b_5.binu8@25046": '「是个不太走红的演员，前阵子还出演过某部舞台剧。呃，他演的是哪部剧来着……」',
    "Script/scenario06b_5.binu8@25263": '「算了，怎样都好。」',
    "Script/scenario06b_6.binu8@57660": '　为什么威廉·莎士比亚要把《暴风雨》写成一个关于宽恕的故事呢？',
    "Script/scenario06b_6.binu8@57910": '@vNanana_0721「……我知道。」',
    "Script/scenario06b_6.binu8@58077": '　正因为他一直在讲述复仇剧的愚蠢，才编织出了名为《暴风雨》的宽恕故事。',
    "Script/scenario06b_6.binu8@58816": '@vNanana_0727「……对不起。《暴风雨》的剧本对我来说太沉重了。」',
    "Script/scenario06b_6.binu8@59680": '@vMeguri_0985「如果连你都要退出，那濑和君大概也会一样吧。……真是遗憾。」',
    "Script/scenario06b_6.binu8@60188": '「辛苦了。」',
    "Script/scenario06b_6.binu8@60262": '「看你的样子，应该是好好拒绝了吧。我还以为以奈奈菜的性格，会没法彻底拒绝呢。」',
    "Script/scenario06b_6.binu8@60628": '「……接下来该怎么办呢？《暴风雨》的准备还早得很，我们一下子闲下来了。」',
    "Script/scenario06b_6.binu8@61553": '@vNanana_0735「我向环君表明了心意……然后愿望实现了……！出生以来第一次，我觉得奈奈也是幸福的……！所、所以……所以，那个……」',
    "Script/scenario06b_6.binu8@62619": '@vNanana_0738「——偶像！」',
    "Script/scenario06b_6.binu8@63182": '@vNanana_0740「嗯、嗯……！因为那是我从小以来的梦想……！」',
    "Script/scenario06b_6.binu8@63639": '@vNanana_0741「而、而且……作为环君的女朋友……！我想变得更有魅力！我想变得更加更加可爱！」',
    "Script/scenario06b_6.binu8@64790": '@vNanana_0746「太、太好了……！」',
    "Script/scenario06b_6.binu8@64847": '　不会唱歌也不会跳舞的奈奈菜，大概不可能以偶像的身份取得大成。',
    "Script/scenario06b_6.binu8@67249": '「看来只能脚踏实地地继续网络偶像活动了。以个人身份活动，对奈奈菜来说应该也更容易……」',
    "Script/scenario06b_6.binu8@67775": '@vFutaba_0695「哇！你在目不转睛地看天使酱的账号！现在才发现天使酱的魅力吗？」',
    "Script/scenario06b_6.binu8@68343": '「不是那样，听我说。」',
    "Script/scenario06b_6.binu8@68489": '「……其实是这样。」',
    "Script/scenario06b_6.binu8@68553": '「奈奈菜想重新开始偶像活动。不过，她是从一个毫无力量的普通人身份重新出发，我正在想该怎么办……」',
    "Script/scenario06b_6.binu8@60214": '@vNanana_0730「环、环君……！」',
    "Script/scenario06b_6.binu8@61101": '@vNanana_0733「那个、那个、那、那个……！！」',
    "Script/scenario06b_6.binu8@61321": '「……没事的，奈奈菜。我会好好听到最后。冷静下来，慢慢说吧。」',
    "Script/scenario06b_6.binu8@61455": '@vNanana_0734「好、好的……！」',
    "Script/scenario06b_6.binu8@61867": '@vNanana_0736「我、我想重新审视自己想做什么、想成为什么……那个……！」',
    "Script/scenario06b_6.binu8@62096": '　奈奈菜也正准备迈出新的一步。',
    "Script/scenario06b_6.binu8@62762": '@vNanana_0739「我想成为闪闪发光的偶像……！我想改变那个畏畏缩缩、胆小怕事的自己！因为我想成为一个优秀的女孩……！」',
    "Script/scenario06b_6.binu8@63307": '　少女梦想成为偶像，并不是什么稀奇的事。',
    "Script/scenario06b_6.binu8@63396": '　然而，隔着屏幕闪耀的她们，总是显得那么美丽。',
    "Script/scenario06b_6.binu8@63941": '@vNanana_0742「偶像就不能谈恋爱吗……！？」',
    "Script/scenario06b_6.binu8@64354": '「当然可以。因为恋爱中的女孩子，看起来就是这么有魅力。」',
    "Script/scenario06b_6.binu8@64517": '　让大家也看看这一点吧。',
    "Script/scenario06b_6.binu8@64957": '　立志成为偶像的女孩，多得就像扫帚扫都扫不完。',
    "Script/scenario06b_6.binu8@66212": '　如果网络偶像天使奈奈菜的复出，能轻易让世间沸腾，那该有多轻松啊。',
    "Script/scenario06b_6.binu8@67125": '「那倒也不是什么大不了的事吧。」',
    "Script/scenario06b_6.binu8@68396": '@vFutaba_0699「那你到底怎么了？突然这么郑重，真让人不舒服。」',
    "Script/scenario06b_6.binu8@68821": '@vFutaba_0701「天使酱要复出！？真的吗？这也太尊贵了吧，是认真的吗？咦、咦咦咦咦！？你要是骗我，我可是会把你的心脏挖出来哦？」',
    "Script/scenario06b_6.binu8@69034": '「虽、虽然她好像是认真的。你看，剧团那边也会暂时休息……」',
    "Script/scenario06b_6.binu8@69135": '@vFutaba_0702「太好了——！！成功了——！世界第一美少女回归了！啊啊，好开心，好开心！啊啊，好幸福！」',
    "Script/scenario06b_6.binu8@69315": '「冷静点，双叶。不过和以前不同，这次没有任何后台，我不知道该怎么培养她。以前好像都是熟悉这条路的专业人士替她安排好的。」',
    "Script/scenario06b_6.binu8@69850": '@vFutaba_0704「杂志写真之类的工作，以前也有人事先打点过吧。毕竟这是一个人脉比什么都重要的世界。」',
    "Script/scenario06b_6.binu8@70106": '「……老实说，我觉得很难。在竞争激烈的世界里，奈奈菜究竟能做到什么程度……但这是她自己说想做的事。作为哥哥，我想尊重妹妹的意愿。」',
    "Script/scenario06b_6.binu8@70405": '@vFutaba_0705「如果环是认真的……」',
    "Script/scenario06b_6.binu8@70518": '@vFutaba_0706「——那就现在立刻退出兰比利斯剧团吧。要实现天使酱的企划，同时脚踏两条船是不可能的。」',
    "Script/scenario06b_6.binu8@70739": '@vFutaba_0707「嗯——首先从脚踏实地的网络活动开始。勤快地发布可爱的照片，逐步积累关注度。当然要参加试镜，也必须积极参加角色扮演活动和同人展。」',
    "Script/scenario06b_6.binu8@71494": '「那、那个……？」',
    "Script/scenario06b_6.binu8@71523": '@vFutaba_0709「照片的加工和编辑也交给我吧。为了天使酱，我仓科双叶什么都做得出来。然后嘛，让环努力打工。服装费、拍摄费，今后处处都要花钱，所以体力活就拜托你了。」',
    "Script/scenario06b_6.binu8@72108": '@vFutaba_0710「只要这样脚踏实地地积累活动，提高关注度，事务所应该就会来联系，甚至会有大工作找上门。当然，能不能走到那一步，全看负责培养她的人有多努力。」',
    "Script/scenario06b_6.binu8@72429": '「你、你到底是什么人？」',
    "Script/scenario06b_6.binu8@72594": '@vFutaba_0711「哼，我只是天使酱的粉丝而已。嘛……我也很喜欢其他女孩子，所以周末经常带着相机去参加各种活动。」',
    "Script/scenario06b_6.binu8@72834": '「虽然可怕得无边无际……不过。」',
    "Script/scenario06b_6.binu8@73124": '@vFutaba_0712「……可靠？这句话不该对我说。周围的人再怎么努力，如果偶像本人不可爱，也没有意义。」',
    "Script/scenario06b_6.binu8@73396": '@vFutaba_0713「有天使奈奈菜站在我们这边，这本身就是最可靠的事！哈哈哈！能培养天使酱，简直像做梦一样！」',
    "Script/scenario06b_6.binu8@73636": '「你愿意帮忙吗？」',
    "Script/scenario06b_6.binu8@73677": '@vFutaba_0714「当然愿意。只靠环一个人，我也不放心。能不能把偶像培养起来，取决于身边的人。我为了让天使酱走红，什么都愿意做。」',
    "Script/scenario06b_6.binu8@73908": '「可靠过头了吧……」',
    "Script/scenario06b_6.binu8@74263": '@vFutaba_0716「你以为自己藏得很好，其实早就暴露了。天使酱这几天漂亮了很多，是环的功劳吧？」',
    "Script/scenario06b_6.binu8@74670": '「双叶……」',
    "Script/scenario06b_6.binu8@74835": '@vFutaba_0718「我可以踢你吗？」',
    "Script/scenario06b_6.binu8@74909": '@vFutaba_0719「我可以咬你吗？」',
    "Script/scenario06b_6.binu8@75064": '@vFutaba_0720「我想把环弄得乱七八糟。」',
    "Script/scenario06b_6.binu8@75454": '「双叶。」',
    "Script/scenario06b_6.binu8@75471": '@vFutaba_0722「所以，我希望喜欢的人能够露出笑容。为了这个，我才愿意帮助环。」',
    "Script/scenario06b_6.binu8@75807": '　奈奈菜变得无论何时何地都会向我撒娇。',
    "Script/scenario06b_6.binu8@75923": '@vNanana_0750「现在没有人在看哦。所以……」',
    "Script/scenario06b_6.binu8@76590": '「喂、喂喂……」',
    "Script/scenario06b_6.binu8@76702": '「……抱歉，你稍微等我一下。我被叫去教职员室了。」',
    "Script/scenario06b_6.binu8@76913": '@vNanana_0754「呜——请好好给钓上来的鱼喂食呀……」',
    "Script/scenario06b_6.binu8@77523": '　她一脸开心地把嘴唇凑了过来。',
    "Script/scenario06b_6.binu8@77677": '@vNanana_0757「嗯啾、嗯……！哈啊……啊……！」',
    "Script/scenario06b_6.binu8@77820": '@vNanana_0758「哈啊……嗯、啾……」',
    "Script/scenario06b_6.binu8@77998": '「……那我走了。」',
    "Script/scenario06b_6.binu8@78036": '@vNanana_0759「……好……」',
    "Script/scenario06_1.binu8@81895": '@vMirai_0394「谁知道呢。不过至少在学生时代，我觉得自己还没有腐烂到那种程度。」',
    "Script/scenario06_1.binu8@92917": '@vMeguri_0990「……突然说要转学，到底是怎么回事？事情来得太突然……我根本接受不了。」',
    "Script/scenario06_1.binu8@93505": '@vMeguri_0992「……我还有很多事想问你。我总觉得，自己好像就要想起某件重要的事了。可是现在……我已经不知道那究竟是什么。」',
    "Script/scenario06_1.binu8@96756": '@vMeguri_1003「疯狂的奥丁，以及始终相信他的洛基。我究竟有没有战胜琥珀呢？」',
    "Script/scenario06_2.binu8@88929": '　我连该如何呼吸都不知道。',
    "Script/scenario06_2.binu8@97355": '　哐当，哐当。',
    "Script/scenario06_2.binu8@103009": '　如果我也能像那样燃起斗志……是不是就能站到他们那一边呢？',
    "Script/scenario06_3.binu8@57953": '「我不知道。」',
    "Script/scenario06_3.binu8@58598": '　啊啊，人类的温度为什么会如此令人怜爱呢。',
    "Script/scenario06_3.binu8@65214": '@vMirai_0441「谁知道呢？我不知道理世小姐的答案。所以，我想代替冰狐，和你交锋一番。」',
    "Script/scenario06b_2.binu8@67644": '@vMeguri_0953「哎呀，真博学。不过对喜欢悲剧的奈奈菜来说，可能还是差了点吧？」',
    "Script/scenario06b_2.binu8@68962": '@vMeguri_0957「那么，奈奈菜，可以请你把《暴风雨》改编成剧本吗？」',
    "Script/scenario06b_2.binu8@69824": '@vNanana_0445「可、可是奈奈的剧本，真的很糟糕……《菲莉亚》也是因为收到了很多修改意见，才能勉强完成……」',
    "Script/scenario06b_2.binu8@70804": '　奈奈菜最终还是无法拒绝，只得点了点头。@n　果然，她很不擅长应付强硬的要求。',
    "Script/scenario06b_2.binu8@72354": '「有人把穿女仆装的奈奈菜发到了社交平台上，传闻就这样扩散开了。网络偶像天使奈奈菜已经引退，现在在咖啡店当店员。再加上《菲莉亚》的演出，话题度相当高。」',
    "Script/scenario05_9.binu8@93230": '「才不是那样！因为错的是——！」',
    "Script/scenario05_9.binu8@93924": '@vMeguri_0779「我也得向大家道歉才行。对不起，濑和君……」',
    "Script/scenario06_5.binu8@64065": '@vRize_0863「独角戏，题名：《箱鸟理世》。」',
    "Script/scenario06b_2.binu8@85884": '「……演技真好。不愧是名演员。」',
    "Script/scenario06b_2.binu8@87861": '「……那么，你是……」',
    "Script/scenario06b_2.binu8@90178": '「……当然。我们又不是在交往。」',
    "Script/scenario06b_4.binu8@77330": '「……只是因为我正好闲着。」',
    "Script/scenario06b_4.binu8@78621": '「慢慢来就好。」',
    "Script/scenario06b_4.binu8@79990": '「好开心。」',
    "Script/scenario06b_4.binu8@80776": '「谢谢你，奈奈菜。我也最喜欢奈奈菜了。」',
    "Script/scenario06b_4.binu8@81357": '「当然了……！」',
    "Script/scenario06b_2.binu8@85281": '@vMika_0086「和我重新开始吧？现在还来得及。你一定能成为一名出色的偶像。」',
    "Script/scenario06b_2.binu8@86582": '「其实你从一开始就知道奈奈菜在这里。先暴露出自己的真面目，然后还以为奈奈菜会乖乖听话吗？」',
    "Script/scenario06b_2.binu8@87063": '@vNanana_0474「妈妈？」',
    "Script/scenario06b_2.binu8@87229": '@vMika_0091「奈奈菜离家出走、偶像活动暂停之后……出乎意料的是，仍有许多粉丝在等她。在这个很容易被遗忘的世界里，这可是非常罕见的事。」',
    "Script/scenario06b_2.binu8@87503": '@vMika_0092「有些孩子，消失之后反而会身价倍增。而那场只演出一夜的《菲莉亚》，有人注意到了以游击形式登场的天使奈奈菜。转型做演员？偶像活动呢？周围的人自顾自地议论起来，她的价值也越来越高。」',
    "Script/scenario06b_2.binu8@87861": '「……那么，你是……」',
    "Script/scenario06b_2.binu8@87905": '@vMika_0093「没错。我发现了把她培养成真正偶像的价值。所以，我不会再让她接受那种用完即弃般的接待了。」',
    "Script/scenario06b_2.binu8@88089": '@vMika_0094「奈奈菜，你一定能理解吧？只要听我的话，就一定会顺利。因为你是如此柔弱、如此惹人怜爱的女孩。」',
    "Script/scenario06b_2.binu8@88351": '@vNanana_0475「……妈、妈妈……」',
    "Script/scenario06b_2.binu8@88839": '@vNanana_0477「那、那个……确实是这样……可是，现在……」',
    "Script/scenario06b_2.binu8@89008": '@vNanana_0478「嗯……可是，我已经……」',
    "Script/scenario06b_2.binu8@89441": '@vMika_0099「你……难道……」',
    "Script/scenario06b_2.binu8@89552": '@vMika_0100「奈奈菜……你这个孩子，真是……！」',
    "Script/scenario06b_2.binu8@89708": '@vMika_0101「真是个坚强又可爱的孩子。啊啊，原来如此，原来是这么回事。」',
    "Script/scenario06b_2.binu8@89874": '@vMika_0102「果然你还是属于我的。无论逃到哪里，你都逃不掉。绝对服从我的人偶。」',
    "Script/scenario06b_2.binu8@72689": '@vKohaku_0684「奈奈菜酱不打算复出当偶像吗？既然这么受欢迎，总觉得不复出太可惜了。」',
    "Script/scenario06b_2.binu8@72848": '@vFutaba_0664「……偶像界可是很残酷的。天使酱确实可爱到犯规，但不可能只靠可爱就一路走上去。」',
    "Script/scenario06b_2.binu8@70804": '　奈奈菜最终还是没能拒绝，只得点了点头。@n　果然，她很不擅长应对强硬的请求。',
    "Script/scenario06b_2.binu8@71924": '　奈奈菜消失在柜台后方。@n　接下来是她打工的时间。',
    "Script/scenario06b_2.binu8@75988": '　零时先生什么都不知道。@n　正因为不知道，他才能若无其事。',
    "Script/scenario06b_2.binu8@78886": '　零时先生背过身去。@n　然而，奈奈菜叫住了他。',
    "Script/scenario06b_2.binu8@79211": '　也许奈奈菜早就在思考这件事了。',
    "Script/scenario06b_2.binu8@85091": '　主动联系她的人，正是奈奈菜自己。',
    "Script/scenario05_13.binu8@64250": '　故事随着奥丁的暴虐而加速走向终局。',
    "Script/scenario05_13.binu8@76473": '　看得人痛苦不堪，简直无法直视。@n　与以压倒性存在感君临一方的奥丁相比，她的演技实在太过脆弱。',
    "Script/scenario05_14.binu8@64744": '@vRize_0714「……我没有拯救任何人的力量。虽然我能做的，只有待在那里而已。」',
    "Script/scenario05_4.binu8@73427": '@vMeguri_0523「谁说我任性了？我可不想被一个自私的座长说这种话。要是我真的任性，那也是受座长影响的。」',
    "Script/scenario05_4.binu8@78831": '　啪的一声。@n　座长那抹淡淡的笑意，刺得我心里一阵不快。',
    "Script/scenario05_4.binu8@84353": '　她的双眸燃烧着炽热的火焰。@n　匂宫巡前所未有地渴望着演戏。',
    "Script/scenario05_8.binu8@72359": '@vRize_0636「……巡正在和濑和君交往吗？」',
    "Script/scenario05_9.binu8@88723": '　令人惊讶的是，被邀请到他家做客的并不只有匂宫巡，还有许多女学生。',
    "Script/scenario05_9.binu8@98815": '@vFutaba_0618「匂宫小姐究竟做了什么！？你这个什么都不知道的大笨蛋！」',
    "Script/scenario06_2.binu8@83334": '@vRize_0749「啊……濑和君，醒了吗……？」',
    "Script/scenario06_2.binu8@85282": '@vRize_0757「是因为……那个孩子夺走了濑和君的角色吗？」',
    "Script/scenario06_2.binu8@90326": '@vRize_0763「我认识濑和君，也认识冰狐。所以我才会想：他们两边都有错，也都有道理……一定都经历过很多痛苦吧。」',
    "Script/scenario06_5.binu8@69100": '@vRize_0881「我讨厌那样的戏剧……讨厌这种必须牺牲某些东西的戏剧。我亲眼见过人被名为戏剧的怪物吞噬。濑和君、冰狐、巡……就连架桥小姐，最终也会变成那样的……！！」',
    "Script/scenario06_9.binu8@25192": '@vcs_Rize_0001「我不是那个意思！只是、只是像这样卿卿我我，实在太难为情了！真是的～～！」',
    "Script/scenario06b_1.binu8@86884": '@vNanana_0437「因为连恋爱都做不到的自己，空虚、茫然，实在是太悲惨了。」',
    "Script/scenario06b_2.binu8@89100": '@vNanana_0479「……现在，只要能和环君待在同一个剧团里……我就觉得很幸福。只要可以，我想永远留在这里，和大家一起演戏……！」',
    "Script/scenario04_2.binu8@80047": '　必须谨慎地接近。',
    "Script/scenario04_4.binu8@86517": '　没有经验也可以。@n　实力至上主义。@n　此外，还以追求终极的自我满足为目标。',
    "Script/scenario05_10.binu8@76316": '@vKohaku_0600「是吗？我还以为座长只是个单纯的自我中心主义者呢。」',
    "Script/scenario05_10.binu8@97505": '　他渐渐被座长厌恶，在剧团里也失去了容身之处。',
    "Script/scenario05_10.binu8@97987": '　他们对性格乖僻的我也很温柔，我也渐渐学会替别人着想。然而，后来剧团的台柱女演员被发现同时和四名剧团成员交往，最后上演了一出俗套的爱恨情仇剧，剧团也随之解散。',
    "Script/scenario05_3.binu8@80327": '@vKohaku_0540「所以说，真的很过分！座长总是说我缺乏感情、没有情绪，尽挑些伤人的话来说。那个人不管说话、态度还是性格，都扭曲得过头了吧。」',
    "Script/scenario05_6.binu8@100114": '　他竖起一根手指，摆出保密的姿势。@n　匂宫那可疑的笑容，让我一时说不出话来。',
    "Script/scenario06_2.binu8@91722": '　如果试着对那个不知何时才会到来的未来，暂时闭上眼睛呢？',
    "Script/scenario06_2.binu8@94322": '@vOboro_0286「是演员。对艺术之都尼克斯的居民来说，这并不稀奇。濑和君、匂宫小姐、天使小姐，父母都是演员。否则，也不会从小就想登上舞台吧。」',
    "Script/scenario06_4.binu8@74477": '@vMirai_0457「后来，我在培训学校遇见了冰狐。嗯嗯，果然，理世小姐就是冰狐所认识的那个理世小姐。」',
    "Script/scenario06b_3.binu8@79658": '　那声音毫无可爱可言，简直像怪物的咆哮。',
    "Script/scenario06b_3.binu8@82746": '　连那种事，我也做不到。',
    "Script/scenario06b_6.binu8@57958": '　我明白……我明白的。',
    "Script/scenario06b_6.binu8@65040": '　想在残酷的竞争中取胜，就必须舍弃许多东西，拼命努力才行。',
    "Script/scenario06b_7.binu8@40597": '　温柔地劝说着。',
    "Script/scenario05_14.binu8@76347": '　我无法容忍事情就这样按照你的心意发展。@n　啊啊，要是干脆把一切都毁掉，心情一定会很痛快吧。',
    "Script/scenario05_13.binu8@77065": '　这个以怪物般的演员身份轰动世间的她，已经没有任何人能够真正理解。',
    "Script/scenario06_4.binu8@72933": '@vRize_0830「我记得座长很欣赏我，妈妈当时高兴极了。她说我是她引以为傲的女儿，一遍又一遍地夸奖我……」',
    "Script/scenario06_5.binu8@64834": '@vRize_0867「因为这是理所当然的，不是吗？我并不是出于自己的意愿来到这个世界。只是周围的人擅自对我抱有期待……又强行推着我，让我去演戏。」',
    "Script/scenario06_5.binu8@71333": '　如果有巡和架桥小姐在，或许就能做到。',
    "Script/scenario06_7.binu8@92156": '「啊哈哈，抱歉抱歉。理世的手指又光滑又舒服，我一不小心就……」',
    "Script/scenario05_6.binu8@101544": '　这份青涩的反应，不知为何让我觉得很新鲜。',
    "Script/scenario06_3.binu8@51606": '　巡只是说，希望我演些什么。',
    "Script/scenario06_2.binu8@99052": '@vMirai_0410「——初次见面。我是折原京子。请大家多多关照。顺带一提，你们也可以叫我冰狐哦？」',
    "Script/scenario05_10.binu8@85510": '@vMeguri_0812「——不对！不对不对不对！你只是在说些莫名其妙的话，想把我糊弄过去！你只是为了给自己的做法找借口，才故意说得煞有介事！我才不会上当！你这个骗子！！」',
    "Script/scenario06b_4.binu8@77017": '@vNanana_0591「……环、环君！？」',
    "Script/scenario05_10.binu8@96693": '@vRairai_0538「和巡以及那个老头接触之后……也许是我误会了。我之所以能做出好戏，是因为那老头的指导和巡的才能。可我却误以为，这一切都是自己的功劳。」',
    "Script/scenario06_1.binu8@0758": '@vFutaba_0758「天使酱在舞台上确实很可爱，但想以此为借口接近她，简直不可饶恕！至少也该先跟我打过招呼再说。」',
    "Script/scenario05_2.binu8@68652": '@vRairai_0373「……现在理世的演技也只有六十分。她还远远没有完全进入角色。不过，你觉得呢？在我看来，你甚至还没达到托尔这个角色的要求。」',
    "Script/scenario05_2.binu8@93922": '@vMeguri_0455「明明我才是剧团里演得最好的人。明明我能用祖父教给我的技术进行表达。其实……我只是想亲手运用自己培养出来的才能。到底是谁在赌这种无聊的气？」',
    "Script/scenario05_7.binu8@74938": '@vFutaba_0583「不只是练习用的房间，连客厅也是。说实话，这里简直有种犯罪现场的气息。就算把女孩子绑来关在这里，恐怕也很难被人发现吧。」',
    "Script/scenario05_7.binu8@80238": '@vOboro_0233「濑和君和仓科小姐，是彼此最了解对方的关系吧。我不觉得他们在交往……不过，他们为什么会变得那么亲近呢？」',
    "Script/scenario05_11.binu8@86601": '@vDirectorA_0005「看来他讨厌天才，而比起天才，他更讨厌那些成功的普通人。所以他转行当了演出家，打着指导演技的名义，在精神上逼迫那种人。说白了，基本就是骚扰——」',
    "Script/scenario05_1.binu8@82351": '@vMeguri_0393「哥哥，哥哥！怎么样，只拿一张宣传单也行！《罗密欧与朱丽叶》可是女孩子也会喜欢的戏哦！不如带给喜欢的人、恋人，或者关系要好的朋友！一起创造美好的回忆，怎么样？」',
    "Script/scenario05_2.binu8@72088": '@vHana_0163「今天排练结束后，有空的人请留下来哦！我正在整理服装的创意，拜托大家给我提提意见！还有，我一个人列想要的东西清单也很辛苦，能来帮忙的话就太好了！」',
    "Script/scenario05_1.binu8@82351": '@vMeguri_0393「哥哥，哥哥！怎么样，只拿一张宣传单也行！《罗密欧与朱丽叶》可是女孩子也会喜欢的戏哦！不如带给喜欢的人、恋人，或者关系要好的朋友！一起创造美好的回忆，怎么样？」',
    "Script/scenario06_1.binu8@93220": '@vMeguri_0991「悠苑也跟着天兄走了……花则说什么要去修行，也离开了……我原本还以为大家终于能开开心心地待在一起，结果又变得寂寞了。」',
    "Script/scenario05_10.binu8@83997": '@vRairai_0514「听我说，巡。我这样做不是因为恨你。只是希望你的演技能变得更好。我一直以来在意的都只有演出，无论过去还是现在，从来没有改变。」',
    "Script/scenario05_2.binu8@93922": '@vMeguri_0455「明明我才是这个剧团里演得最好的人。明明我能用祖父教给我的技术进行表达。其实……我只是想亲手运用自己培养出来的才能。到底是谁在赌这种无聊的气？」',
    "Script/scenario05_12.binu8@87670": '@vKohaku_0615「暴力的时代拉开帷幕，人们的心愿被一一撕裂。即使世界正在天翻地覆，人们也渐渐忘却了怜悯。回荡的号角，正宣告着终结。世界树正在燃烧，这个世界也将燃烧殆尽！」',
    "Script/scenario04_6.binu8@73259": '@vOboro_0205「卡里古拉必须是孤独的。但仅仅毫无意义地与他为敌还不够。凯瑞亚理解卡里古拉。不……至少，他自以为理解。正因为如此，他才选择与卡里古拉为敌。」',
    "Script/scenario04_2.binu8@90009": '@vKohaku_0483「我把环君当成卡利古拉，试着演了一遍。所以，我觉得自己表现出了温柔的爱。之所以没能深入演出塞佐尼娅，是因为光有爱还不够，对吧？」',
    "Script/scenario06_3.binu8@55852": '@vminami_0005「你一定不是我的孩子，对吧？一定是这样。因为如果你是我的孩子，演技应该会更好才对。未来演得这么好……所以，未来才是我的女儿，对吧？」',
    "Script/scenario05_14.binu8@83183": '@vMeguri_0922「我直到现在都还在祈求啊！祈求你变回原来那个温柔的你，重新抱住我！祈求你变回我最喜欢的奥丁，再对我笑一笑！」',
    "Script/scenario05_10.binu8@73434": '　声音没有如我所愿地发出来。@n　我无法将意识集中到一点。',
    "Script/scenario04_7.binu8@39253": '@vMirai_0321「……确实，也许是这样。因为其他人都会追求各种附加价值，所以我才有点惊讶。」',
    "Script/scenario05_10.binu8@83614": '「……你脑子坏掉了吗？你本来不该是这样的……」',
    "Script/scenario05_1.binu8@99050": '　找到自己想演的东西，并坚持到底……这种经历，我一次也没有过。',
    "Script/scenario05_3.binu8@87734": '　我已经无法再直视那个少女的脸。@n　我厌恶着移开视线的自己，厌恶自己的软弱。',
    "Script/scenario06_1.binu8@86944": '@vF_StudentA_0025「顺、顺带问一句，洛基大人……也是这所学校的学生吗？难道说，难道说……！！」',
    "Script/scenario06b_3.binu8@91197": '　为了把那个怎么叫都叫不醒的睡美人弄醒，我闯进了妹妹的房间。',
    "Script/scenario05_10.binu8@86542": '@vRairai_0519「既然你想起了我的做法，就应该明白我有多认真。你曾经……打从心底里恨着这样的我。」',
    "Script/scenario06b_7.binu8@40638": '「偶像就是要被人看见，才能绽放光彩。要是因为害羞，那就先努力试试看吧。」',
    "Script/scenario05_5.binu8@78416": '　之后，我们一边反复对读、加深对洛基的理解，一边再次埋头投入排练。',
    "Script/scenario06b_1.binu8@81967": '　匂宫燃烧着野心。@n　有才能的人，正眺望着更高的境界。',
    "Script/scenario05_7.binu8@90206": '@vOboro_0244「我就喜欢那种腹黑劲儿。自从看过那份剧本，我对那个孩子的评价就直线上升。说是佩服得五体投地也不为过。」',
    "Script/scenario06b_3.binu8@74884": '@vNanana_0500「我终于……真正喜欢上一个人了。」',
    "Script/scenario06b_3.binu8@86518": '@vMirai_0387「如果你喜欢他，就做得到吧？只要这份感情是真的，为了让心愿实现，什么都做得到。」',
    "Script/scenario04_4.binu8@85327": '　我只是陪朋友去了那个地方……却被迫改变了自己原本的认知。',
    "Script/scenario06b_8.binu8@34784": '　和喜欢的人待在一起。@n　这份幸福有多么珍贵，我们应该都明白。',
    "Script/scenario05_8.binu8@78829": '@vMeguri_0756「大概是觉得待在那里浑身不自在，所以才追上你们两个的吧。」',
    "Script/scenario05_11.binu8@81357": '@vRairai_0562「……什么啊，那个老头说得没错嘛。为了让演技带有真实感，有时确实需要那种手段。所以，我只是在做正确的事。」',
    "Script/scenario06b_7.binu8@41798": '@vNanana_0821「通、通过选拔的孩子，真的好可爱……奈奈也不能输给她呢！」',
    "Script/scenario06_1.binu8@100949": '「只要继续下去，总有一天一定能抵达那里。理世可是我最看好的演员。」',
    "Script/scenario05_6.binu8@80181": '　既然是为了寻找什么而来到这里，@n　那么，若能带着什么回去，就是最好的结果了。',
    "Script/scenario05_13.binu8@79900": '@vMeguri_0904「即使你屠杀了我所爱的人们，即使你把我投入监狱，世界末日依然会到来。我的妻子、我的孩子，没有一个人逃过一劫，全都惨遭杀害。我的家人，就是因为轻信了那个荒谬的故事才死去的。」',
    "Script/scenario05_10.binu8@85510": '@vMeguri_0812「——不对！不对不对不对！你只是在说些莫名其妙的话，想把我糊弄过去！你只是为了给自己的做法找借口，才故意说得煞有介事！我才不会上当！你这个骗子！！」',
    "Script/scenario05_1.binu8@94689": '@vMeguri_0423「对家人来说，他是个比对任何人都严格的人。祖父的字典里，大概根本不存在‘亲情’这个词吧。从小，我就接受彻底的英才教育。在懂事以前，我的人生便已被决定要走上戏剧之路。我就是这样长大的。」',
    "Script/scenario05_10.binu8@82350": '@vRairai_0509「沉溺于爱情的你，需要一道会让你背负一生的伤口。那道伤口会把巡的演技升华成真实。人类本来就是消极的生物！艺术，正是从负面情感中诞生的！」',
    "Script/scenario05_10.binu8@85009": '@vMeguri_0810「我、我不知道……！我认识的，只有那个虽然刻薄、却依然可靠的天兄……！」',
    "Script/scenario05_10.binu8@87008": '@vMeguri_0815「……我不会再和天兄说话了。不过，我明白。我会按照天兄的心意去做。」',
    "Script/scenario05_10.binu8@91704": '@vMeguri_0821「天兄，你就不能对自己更有信心一点吗？虽然比我差了好几档，但以学生的水平来说，我觉得已经算不错了。」',
    "Script/scenario05_10.binu8@92239": '@vMeguri_0822「没错，天兄那种阴湿的地方，正是他的优点嘛。卑屈又悲惨，真是太棒了！」',
    "Script/scenario05_11.binu8@74558": '@vMeguri_0828「下一场演出，天兄也会一起参加吧？我很期待哦。」',
    "Script/scenario05_11.binu8@91939": '@vMirai_0354「你就是学生时代的天乐来来。在你崩溃、毁坏、发疯之前——你是匂宫小姐最喜欢的、可靠的天兄。」',
    "Script/scenario05_2.binu8@92603": '@vMeguri_0450「哼！谁想跑到祖父那种人身边去啊。我想和你一起演戏，是因为有悠苑小姐在！还有……姑且也因为天兄。」',
    "Script/scenario05_10.binu8@80272": '@vRairai_0503「我说了，那是你误会了。你是不是把《菲莉亚》当成歌颂美好的故事了？所以才想把洛基演成那种甜腻得发臭的角色。哈，真可笑。」',
    "Script/scenario05_10.binu8@91893": '　那是我和悠苑还在马卡里奥斯学院读书时的记忆。',
    "Script/scenario05_10.binu8@101331": '　难怪悠苑也能成为剧团的招牌。',
    "Script/scenario05_11.binu8@78395": '　看着悠苑泪流不止的模样，我心中竟涌起一阵近似兴奋的情绪。',
    "Script/scenario05_11.binu8@78610": '@vRairai_0557「你该感谢我，悠苑。这样一来，你作为演员就会更有深度。」',
    "Script/scenario05_11.binu8@82340": '　悠苑一事揭示的世间真相，让我看到了新的可能性。',
    "Script/scenario05_4.binu8@72629": '@vMeguri_0520「给琥珀？又要进行个人指导吗？」',
    "Script/scenario06_1.binu8@100554": '「琥珀嘛……她确实有天然呆的一面，我觉得大家也正是连这一点都一起喜欢着。」',
    "Script/scenario06b_6.binu8@59286": '　匂宫小姐遗憾地低声说道。',
    "Script/scenario06b_8.binu8@40194": '　不知为何，世人并没有把那件事当成问题。',
    "Script/scenario06_3.binu8@52888": '@vRize_0787「……濑和君？」',
    "Script/scenario06_3.binu8@56686": '@vRize_0788「……濑、濑和君？」',
    "Script/scenario05_14.binu8@83183": '@vMeguri_0922「我直到现在都还在祈求啊！祈求你变回原来那个温柔的你，重新抱住我！祈求你变回我最喜欢的奥丁，再对我笑一笑！」',
    "Script/scenario05_9.binu8@90956": '@vcs_TeacherA_0002_b「做出会引起误会的行为，结果还被人当场抓住……为什么我就不能做得更好一点呢？要是只是想恶作剧，本来可以做得更巧妙……为什么偏偏在我当班主任的时候发生这种事……」',
    "Script/scenario06_1.binu8@103378": '@vRize_0744「其实，我原本只打算复出当这一次演员。舞台落幕的瞬间，我觉得已经没有遗憾了。所以以后做幕后工作也好。能够这样积极地想，我已经很满足了。」',
    "Script/scenario04_1.binu8@104842": '@vHana_0093「不是这个意思！可为什么要启用一个已经不是演员的人？对于那些认真想要这个角色的人来说，这实在太让人吃惊了！」',
    "Script/scenario07_1.binu8@99109": '@vRize_1407「对你来说，演戏曾是活下去的手段。所以，冰狐不可能喜欢上演戏。」',
    "Script/scenario07_1.binu8@105202": '@vRize_1425「最后能见到你，真是太好了。谢谢你，冰狐。」',
    "Script/scenario07_3.binu8@56620": '　演出结束后，演员们脸上那种神清气爽的表情，深深烙印在我的眼中。',
    "Script/scenario07_3.binu8@58032": '@vMeguri_1094「明明我的演技比剧团里的任何人都好。本来该请你加入剧团的人，是我们才对吧！」',
    "Script/scenario07_3.binu8@76422": '@vDirectorB_0010「抱歉啊？好像到处都在传些奇怪的传闻……是不是给你添麻烦了？我只是找同伴商量了一下而已。」',
    "Script/scenario07_3.binu8@79829": '　其他人也是吗？@n　他所属剧团的台柱女演员，似乎是连普通人都听说过的超级大明星。',
    "Script/scenario07_4.binu8@66372": '　死亡的气息笼罩了小小的剧场。@n　怪物般的惨叫声与烧焦肉类的气味掠过鼻尖。',
    "Script/scenario07_5.binu8@58814": '　那家伙现在还没法独自站起来。',
    "Script/scenario07_5.binu8@63458": '　我稍微有些兴奋。@n　即使身处这样的状况，我脑子里也只能想着戏剧。',
    "Script/scenario07_5.binu8@71187": '　啊，原来如此。@n　看来，我并不是一无所有。',
    "Script/scenario07_6.binu8@73669": '　不是那样。@n　真的不是那样。',
    "Script/scenario07_6.binu8@81447": '@vMeguri_1199「傲慢的愿望是无法传达到的。我……明明只有在这里才能活下去。」',
    "Script/scenario07b_1.binu8@82272": '@vMeguri_1221「呐呐，天兄，下一场戏要怎么办？」',
    "Script/scenario07b_1.binu8@85059": '@vMeguri_1225「虽然我和你的美好回忆，也被天兄那不解风情的行为毁得一干二净了。」',
    "Script/scenario07b_1.binu8@85492": '@vMeguri_1227「不过，手法倒是不坏。多亏了天兄，我的演技才增添了几分魄力。」',
    "Script/scenario07b_2.binu8@72408": '@vMeguri_1317「那今天就先算了吧。我也不想给你添太多麻烦。」',
    "Script/scenario07b_2.binu8@74541": '@vMeguri_1326「只要天兄还认真对待戏剧，悠小姐就无法向他表白。越是喜欢天兄，就越不想妨碍他投入戏剧。」',
    "Script/scenario07b_2.binu8@79783": '@vMeguri_1345「我们的关系今后也不会改变。我相信，这样的距离才是最幸福的。」',
    "Script/scenario07b_4.binu8@72933": '@vHana_0289「绝对是两情相悦吧。可直到今天，关系一点进展都没有。你知道吗？前几天情人节，她明明收到了一看就很用心的手工巧克力，那个迟钝的轻小说男主角却随便道了声谢就完事了！？太不像话了！！」',
    "Script/scenario08_1.binu8@99434": '「琥珀真的很擅长演戏啊。」',
    "Script/scenario08_2.binu8@72373": '　只要闭上眼睛，那个画面就会浮现出来。@n　匂宫巡……此刻正被火焰焚烧的模样。',
    "Script/scenario08_2.binu8@72863": '@vOboro_0371「不过，濑和君，我希望你不要误会……最初期望这个虚构世界的，既不是匂宫小姐，也不是天乐先生。」',
    "Script/scenario08_2.binu8@73736": '@vOboro_0373「但是，匂宫小姐毕业之后，便没有人继续扮演这个世界了。只有作为主角的濑和君，是无法让故事继续下去的。」',
    "Script/scenario08_2.binu8@75445": '@vMirai_0584「——不朽地狱。就像用棉线勒住脖子一样，漫长时间这种巨大的毒素，正在一点点摧毁濑和君的内心。这种令人焦躁、绕远路的手段，正是冰狐会喜欢的做法吧。」',
    "Script/scenario08_2.binu8@91954": '@n　——濑和美波这种演员，我既没听说过，也没见过啊？',
    "Script/scenario08_2.binu8@92653": '　濑和美波……也就是说，我的母亲，似乎只是郊外一间小剧团里只能得到小角色的配角演员。',
    "Script/scenario08_5.binu8@76557": '@vFutaba_0813「——把架桥小姐当妹妹对待，真是无礼之徒。你的脑子腐烂了吗？」',
    "Script/scenario08_5.binu8@79100": '@vFutaba_0823「一开始，他大概是被架桥小姐的演技迷住了吧。但不只是这样。自从和兰比里斯剧团扯上关系后，我久违地又看到了那个变得热血起来的家伙。明明不久前还像个废人一样……」',
    "Script/scenario08_5.binu8@80070": '@vFutaba_0826「总之这里就交给你了。让那个逃避现实的笨蛋清醒过来，正是架桥小姐的职责。」',
    "Script/scenario08b_1.binu8@75528": '「……琥珀对戏剧有兴趣吗？」',
    "Script/scenario08b_4.binu8@60272": '　琥珀满脸开心地下了单。@n　……既然答对了，那就算了。',
    "Script/scenario08b_4.binu8@61722": '「琥珀喜欢卡布奇诺的什么地方？」',
    "Script/scenario09_2.binu8@66794": '　我不知道自己为什么会在这里。',
    "Script/scenario09_2.binu8@81321": '@vFutaba_0981「很遗憾，不符合对象。因为……」',
    "Script/scenario09_3.binu8@54427": '　和哥哥在一起。@n　我一直以来都只是为了这个愿望努力至今。',
    "Script/scenario09_3.binu8@55189": '　他什么都不明白。@n　这一份心意，一点也没有传达给他。',
    "Script/scenario09_3.binu8@55523": '　我根本就没有试图让他理解。',
    "Script/scenario09_3.binu8@60097": '　啊，原来如此。@n　我好像终于明白了。',
    "Script/scenario09_3.binu8@65134": '　哥哥所渴求的妹妹……是不懂爱、被戏剧囚禁的怪物。',
    "Script/scenario09_5.binu8@96155": '　然而，事态仍在不断恶化。',
    "Script/scenario09_5.binu8@97741": '　温柔地、温柔地，只是微笑。',
    "Script/scenario05_4.binu8@77431": '@vMeguri_0533「……我知道啊。毕竟你就是这么随便。」',
    "Script/scenario05_14.binu8@78045": '@vOmi_0045「来来，你和我很像。你大概会犯下和我一样的错误吧。所以至少看看我，从我身上学到教训。你可别变成我这样的人。」',
    "Script/scenario04_6.binu8@58686": '　如果没有抛弃一切、彻底成为真正演员的觉悟，我大概就无法超越冰狐。',
    "Script/scenario05_13.binu8@57297": '@vKohaku_0622「喂，洛基。我不是想惩罚你，只是想提前给你钉下一枚楔子。希望你能明白这一点。」',
    "Script/scenario05_5.binu8@74655": '@vMeguri_0580「真没礼貌。我从决定独立生活那天起，就一直在努力让自己什么都能做到。别把我和那个连自我管理都做不到的孩子相提并论。」',
    "Script/scenario06b_3.binu8@81127": '@vNanana_0521「用那种东西编织出来的感情，怎么可能是恋爱。因为那种虚假的行为，根本没有任何意义……！」',
    "Script/scenario06b_4.binu8@77068": '　时间是下午四点四十分。',
    "Script/scenario05_6.binu8@92466": '「又或者，是因为人们需要这样的故事吧。说到底，是需求和供给中的需求。」',
    "Script/scenario05_12.binu8@77272": '　……不，已经无所谓了吧。@n　现在，我只希望这次《菲莉亚》的演出能够成功。',
    "Script/scenario06_1.binu8@99823": '　那是一次不可思议的经历，仿佛我还没有完全从梦中醒来。',
    "Script/scenario06_6.binu8@67237": '「啊、那个……刚才我是趁着一时冲动说出来的……不是为了让巡信服而找的借口。」',
    "Script/scenario07_5.binu8@75349": '　嘴巴几次想要说些什么，却张开又合上。@n　即便如此，我还是找不到适合这个场合的话。',
    "Script/scenario07_4.binu8@56713": '　那个人只会选择自己认为是好事的事情去做。@n　至于这样会让别人怎么想，她根本不在乎。',
    "Script/scenario09_2.binu8@90601": '「凭我那种一时兴起的建议，你怎么可能进步到这种程度……！你从一开始……就已经会演那种戏了吧。为什么一直藏到现在……！！」',
    "Script/scenario07_6.binu8@75311": '「究竟是从什么时候开始，我觉得那道光如此碍眼？又是为什么，我再也无法爱上那份灼热了呢？」',
    "Script/scenario07b_2.binu8@85151": '@vHana_9001「啊，座长先生，您可别睡着了呀！像平时那样骂几句嘛！」',
    "Script/scenario07b_4.binu8@62578": '@vRairai_0751「哈！？我完全听不懂！你这家伙，该不会是在玩弄我们家巡吧？你要是敢伤害巡，我可不会放过你！听明白了吗，混蛋！」',
    "Script/scenario07b_5.binu8@44044": '　这种话，我没能说出口。@n　真要这么说，我和巡的关系不也是一样吗。',
    "Script/scenario07b_4.binu8@62423": '「那个……这很难解释……巡不喜欢把关系明确下来……」',
    "Script/scenario07b_2.binu8@87355": '@vRairai_0735「神啊，请看看我的内心。请不要让我就这样空虚地死去。若还有来世，请让我为了所有人的真正幸福，献上自己的生命。」',
    "Script/scenario09_3.binu8@80067": '　我没能得到月亮。@n　这个世上无论哪里……哪怕是舞台上，也找不到能够替代月亮的东西。',
    "Script/scenario09_5.binu8@97913": '　啊，这到底算什么。@n　我明明根本不了解你，却最讨厌你用那种仿佛很了解我的口吻说话！',
    "Script/scenario07_5.binu8@71757": '　我坚信那才是真正应该做的事。@n　不曾反省自己，只顾目不斜视地向前冲。',
    "Script/scenario09_3.binu8@76054": '　听好了，你们这些不知世间荒谬的人。@n　认清现实吧，你们这些自以为幸福无处不在的人。',
    "Script/scenario07_4.binu8@65054": '　剧团相关人员发现火灾后，试图用配备的灭火器进行初期灭火，但火势非但没有受到压制，反而越来越猛烈。',
    "Script/scenario07_4.binu8@59093": '　不用迎合畅销趋势，也不用顾虑他人的期待，只专心做好作品——没想到这种生活竟如此适合我。',
    "Script/scenario09_1.binu8@58268": '　我并没有特别为此感到寂寞……可即便如此，她当时说过的话，如今仍深深刻在我心底。',
    "Script/scenario09_5.binu8@96645": '　就在我想逃避现实、想着“既然如此，还不如就这样被火焰吞没”之时。',
    "Script/scenario09_2.binu8@84486": '　我亲眼看到了那颗动摇的心。@n　那个试图背叛自己心意的哥哥，竟让我觉得有些可爱。',
    "Script/scenario07_4.binu8@70326": '　之所以没有感到害怕，是因为吞噬了我们一切的那场火焰，美丽得令人火大吗？',
    "Script/scenario07_2.binu8@90084": '　因为那道目光投向了太过遥远的地方，我不由得担心起来，开口叫住了他。',
    "Script/scenario08b_4.binu8@67580": '「……那个朋友，对她来说大概并不是什么美好的回忆吧。既然如此，不如当作从未存在过，她或许会更幸福？」',
    "Script/scenario07_5.binu8@59105": '　既然你不在，那就由我来引导他。@n　在这个一切皆为虚构的世界里，我要推他一把。',
    "Script/scenario09_3.binu8@70591": '　如果时间的流逝真的会夺走快乐、痛苦、喜悦、煎熬，甚至喜欢、讨厌和爱这一切的话。',
    "Script/scenario09_2.binu8@93312": '　我知道那是危险的东西……可当时的我，没有控制它的方法。',
    "Script/scenario09_4.binu8@82634": '　那道光恰好与舞台上的灯光十分相似。@n　灼热、耀眼，曾是那么重要的一份感情。',
    "Script/scenario07_3.binu8@86284": '　我恨过。@n　是的，即使明白那只是我单方面的怨恨，也无法不去恨。',
    "Script/scenario07_6.binu8@85576": '　眼前已经被火焰包围。@n　就算侥幸能够站起来，也已经没有任何逃生的手段了。',
    "Script/scenario09_2.binu8@88484": '　即便那番话只是为了减轻自己的罪恶感，只要能在哥哥心中留下些什么，对我来说就已经足够了。',
    "Script/scenario09_3.binu8@48605": '@vMinami_0039「环。最近的你……似乎有些迟钝了。看来必须从头开始指导你才行。」',
    "Script/scenario09_5.binu8@108653": '@vFutaba_0991「不管怎么说都不行啦！快看，排练时间已经开始了！」',
    "Script/scenario09_4.binu8@90345": '@vMirai_1055「必须接受改变，并勇敢面对。大家都是这样从这里毕业的。所以……哥哥也该如此，对吧？和过去相比……看，你的悲伤应该也已经淡了不少吧？」',
    "Script/scenario07_3.binu8@79333": '　各种各样的纠葛在心中涌现。@n　过去的记忆如走马灯一般，一遍又一遍地闪回。',
    "Script/scenario09_2.binu8@94530": '　我曾经得意忘形。@n　那时的我还不知道，实现哥哥口中的美好幻想究竟有多么困难。',
    "Script/scenario07_3.binu8@73399": '@vYuuen_0239「……我明白。我也不能说自己已经做到了……但我一直强烈地希望，自己能够做到。」',
    "Script/scenario08_4.binu8@50443": '　我们被那个家束缚着。@n　无论过去还是今后，我们都只能这样活下去。',
    "Script/scenario07_5.binu8@63850": '@vKohaku_0756「……为什么座长不亲自演奥丁呢？明明那样应该比让我来演更简单。」',
    "Script/scenario09_2.binu8@78938": '@vFutaba_0971「什么都好。不必把它包装成一段佳话……只要能留下些什么，那样就已经足够了。」',
    "Script/scenario07_3.binu8@85199": '　他没有再说什么。@n　既没有追问，也没有劝说，只是妨碍了我一阵便离开了。',
    "Script/scenario09_3.binu8@77512": '　我想要的是不可能得到的东西。@n　比戏剧更胜一筹、比演戏更加不同的东西。',
    "Script/scenario07b_5.binu8@45302": '@vcs_Meguri_0006_b「是啊。一直目不转睛地盯着看……看起来相当兴奋呢？」',
    "Script/scenario09_2.binu8@84098": '　那是属于某个人的一场恋爱。@n　人们都说初恋无法实现……可对我来说，那就是对哥哥的爱。',
    "Script/scenario07b_4.binu8@58796": '「无论多么巨大的黑暗，我都不会害怕。让我们一起去寻找真正的幸福吧。无论走到哪里、无论走多远，我们都在一起。」',
    "Script/scenario07_3.binu8@84424": '　他像逃跑一样离开了那里。@n　他大概以为，只要熬过这个状况，一切总会有办法。',
    "Script/scenario07_3.binu8@67544": '@vHana_0251「没问题！毕竟这次可是龙木先生大放异彩的舞台。我们会打起精神准备的！」',
    "Script/scenario07_6.binu8@73292": '@vMeguri_1170「之后，王子就必须和狐狸道别了。到了那个时候，狐狸会哭出来吧？我就是在那时……把故事合上了。因为我无法继续看下去，感觉他们简直像是为了道别才成为朋友的。」',
    "Script/scenario09_1.binu8@54842": '@vFutaba_0905「……普通女孩子会为男孩子帅气的脸、性感的脖颈和锁骨……或者野性的肌肉、结实可靠的胸膛之类的地方心动。」',
    "Script/scenario07_6.binu8@80459": '@vMeguri_9002「一旦察觉到这一点，我就再也无法待在这里了。名为现实的噩梦，正在把我吞噬。」',
    "Script/scenario07_5.binu8@64520": '@vRairai_0717「那样做只是为了我自己，对巡又没有好处。你以为我究竟是为了什么，才会死死咬住这个世界不放？」',
    "Script/scenario07_5.binu8@77351": '@vKohaku_0792「拜托了，环君。带巡……带她去那片玫瑰所在的地方，好吗？」',
    "Script/scenario08b_4.binu8@66853": '@vHana_0314「即便如此，我还是觉得她没有错。那个朋友确实真实存在……只是发生了令人悲伤的错过。没能救到她，这件事始终让我无法释怀。」',
    "Script/scenario07b_5.binu8@46565": '@vMeguri_1601「而且，之后不是还要在排练室练习吗？不在那里卿卿我我，还能去哪里呢？」',
    "Script/scenario09_4.binu8@79764": '@vMirai_1008「是啊。我很羡慕那种距离。我想就近看着哥哥幸福地活下去。」',
    "Script/scenario07b_2.binu8@84695": '@vYuuen_0300「只是，偏偏遇上了一点不幸。熊熊燃烧的火焰，将一切都烧尽了。无论是谁，都没能察觉到那个预兆。我们曾试图守护它……却在梦想实现一半时醒了过来。」',
    "Script/scenario07b_1.binu8@103999": '「所以，这并不是什么恋爱的攻防，也不是别的什么……我只是珍爱着、细细品味着这段关系摇摆不定的模样。」',
    "Script/scenario07_4.binu8@62411": '　我至今为止，确实做过不少乱来的事。@n　对悠苑、白坂、那个老头……至于巡嘛……算了……。',
    "Script/scenario07b_4.binu8@64881": '@vRairai_0759「你和巡接吻了？明明还没交往……？哦……？」',
    "Script/scenario09_3.binu8@77328": '@vMirai_0950「无论此世还是彼世，都没有任何东西真正适合我。不过，我知道，而你也应该知道才对。」',
    "Script/scenario07b_5.binu8@41057": '「她说过类似不想拘泥于关系之类的话。所以我也不想被恋人、朋友之类的框架束缚，而是想以纯粹的心情和巡相处……」',
    "Script/scenario07_2.binu8@90963": '@vMeguri_1075「但就在最后关头，我察觉到了自己在那里存在的意义。无论多么愤怒……在内心深处，我还是忍不住想要相信。」',
    "Script/scenario09_3.binu8@66231": '　我到底想做什么呢。@n　就算能够展现出自己所能做到的、最棒的戏剧……那里面又有什么呢。',
    "Script/scenario07_3.binu8@67806": '@vHana_0252「哼哼哼！不然的话，天乐先生怎么可能拜托我呢！」',
    "Script/scenario09_5.binu8@105234": '@vMeguri_1770「理世会细心地照顾我，奈奈菜也会对我露出笑容。没关系，我还不是孤身一人。呐……是这样吧？」',
    "Script/scenario07b_1.binu8@99323": '@vMeguri_1278「每一道光芒都各不相同……其中一定寄托着某个故事。但我们能够理解的，只有光芒的外在而已。」',
    "Script/scenario08_1.binu8@81202": '@vMirai_0561「没什么。站上舞台，并不代表一定要编织台词。如果你需要朋友……只要许下这个愿望就好。没关系，即使他们不在，故事也会继续。因为你才是这个舞台的主角！」',
    "Script/scenario09_2.binu8@76575": '@vMirai_0856「不对，不是那样。剧本有两个：一个是在这个世界里不断逃避的剧本，另一个是变得足够强大、拒绝这个世界并回到现实的剧本。这一次，只是选择了后者而已。」',
    "Script/scenario09_2.binu8@90239": '@vMirai_0662「明明一直偷偷练习来着。怎么样？我只是照哥哥说的试着做了一遍而已。」',
    "Script/scenario09_1.binu8@57224": '@vMirai_0827「呵呵呵呵，你那一点我最喜欢了。如果可以的话，希望你也能和哥哥好好相处。」',
    "Script/scenario07_2.binu8@82790": '@vNanana_0984「说自己变得讨厌一个人，就说明曾经有过不讨厌他的时候吧。既然如此……我想，也一定曾经喜欢过。毕竟从出生到现在始终讨厌一个人，反而是非常非常困难的事。」',
    "Script/scenario08_2.binu8@79681": '「那个把一生都奉献给演戏的家伙，和眼前这个人完全是两回事。我确实从心底讨厌未来……但唯独他对戏剧的态度，我是认可的。」',
    "Script/scenario07_6.binu8@66388": '@vOmi_0090「说到底，我压根没打算让你加入剧团。都是因为来来那小子，一个劲儿地说些撒娇的话。」',
    "Script/scenario09_2.binu8@72960": '@vFutaba_0956「……不、不行……那不行。我没有戴着面具。认清这一点也很重要……」',
    "Script/scenario09_3.binu8@68348": '@vMirai_0915「将天空与大海混合，将美与丑融为一体，让笑声从痛苦中迸发——」',
    "Script/scenario07b_5.binu8@52529": '@vMeguri_1706「别着急。我打算和你共度一生。所以，我们慢慢享受吧。那一定是无与伦比的奢侈。」',
    "Script/scenario07b_5.binu8@51431": '@vMeguri_1701b「抵达之前的旅程本身就是乐趣。把它一口气跳过，未免也太奢侈了吧。」',
    "Script/scenario07_6.binu8@81261": '@vMeguri_1198「叫人面对现实这种话，是强者才说得出口的。努力、战斗、面对现实……他们根本没有考虑过弱者的处境。」',
    "Script/scenario09_4.binu8@92821": '「很奇怪吧。我明明应该知道什么才是重要的，也明明有过比一切都更爱着的东西。可是为什么……回过神来，它们却从指缝间一点点流失了。」',
    "Script/scenario07_5.binu8@66757": '@vYuuen_0294「我绝不认为一成不变是美德，也不认为永无终结就是幸福。追逐不朽之美的尽头，等待着我们的只有绝望。」',
    "Script/scenario08_5.binu8@78827": '@vFutaba_0822「环……大概是喜欢架桥小姐的。虽然我不知道那是不是恋爱……但至少，他一直比在意其他女孩子更加在意她。」',
    "Script/scenario07_4.binu8@57234": '@vRairai_0657「是兰比里斯剧团救了我。所以你不用再想些多余的事。」',
    "Script/scenario08_2.binu8@76113": '@vOboro_0377「在虚假的世界里，真相这种剧毒会格外有效。如果我们无法阻止这出戏，那就让导演亲手中断舞台。」',
    "Script/scenario09_4.binu8@80763": '@vMirai_1015「因失去妹妹而绝望的哥哥、失去心爱团员的下一任座长、作为出轨对象的女儿而不断背负重担的少女、没能救下朋友的失败者、没有才能的凡人，还有……啊，这里徘徊着许多灵魂。材料已经足够了。」',
    "Script/scenario08_4.binu8@52999": '@vMirai_0719「不，我明白。正因为明白，所以才讨厌。兄妹真是麻烦啊。一旦看穿对方在想什么，就会变得无计可施。」',
    "Script/scenario07_2.binu8@102523": '@vOmi_0048「你们是这个世界上失去光芒的废料。和我一样，是毫无价值的垃圾。既然如此……就该把你们集中到一起。」',
    "Script/scenario07b_4.binu8@69012": '@vYuuen_0308「与其有空插手别人的恋爱，不如先考虑一下自己的将来吧。来来先生，你还从没和任何人交往过吧？」',
    "Script/scenario08b_4.binu8@65841": '@vHana_0311「这个嘛？我也不知道。或许她所说的朋友根本不存在……只是她抱有这样的幻想吧。不过，我只是想替那样的她排解寂寞。」',
    "Script/scenario07b_2.binu8@88814": '@vRairai_0737「我们必须前往天上。你或许哪里都能去，但即使如此，也无法和我们一起走。」',
    "Script/scenario07b_2.binu8@74278": '@vMeguri_1325「天兄心里应该也多少在意悠小姐。不过关系之所以没有改变……是因为他明白，戏剧才是最重要的吧。」',
    "Script/scenario04_4.binu8@91672": '@vHana_0156「请遵从内心真正渴望的东西。无论是继续当演员，还是选择退出……都不要弄错自己喜欢的东西。」',
    "Script/scenario08b_4.binu8@64700": '@vHana_0308「……其实她最近一直非常消沉。听说她似乎和重要的朋友闹翻了……两个人渐渐疏远。因为她很珍惜那个朋友，所以……」',
    "Script/scenario09_2.binu8@77381": '@vFutaba_0967「有话想说就直接说出来！把现在对我说的话，原原本本地对环说出来！这种程度的事，不要犹豫！既然你是演员……至少把高潮部分的场面好好炒热起来……才对！！」',
    "Script/scenario06b_7.binu8@32736": '@vFutaba_0727「你知道SNS上的话题标签吗？前阵子流行过一个叫‘11秒写真’的标签，我们也让天使酱这样宣传一下吧。」',
    "Script/scenario07b_5.binu8@53223": '　我故意没有表示同意，也没有点头。@n　为了维持这段不变的关系，我觉得答案晚些再确认也无妨。',
    "Script/scenario09_4.binu8@76075": '@vMirai_0985「……是啊。我并不讨厌戏剧……但比起戏剧，我还有更喜欢、更珍贵的东西。为了那样东西……我明明已经做好了舍弃一切的觉悟。」',
    "Script/scenario07_5.binu8@65050": '　这样的对话，我们重复了一遍又一遍。@n　通过言语触碰彼此的内心。@n　每一次，我都更加明白座长究竟有多么珍惜巡。',
    "Script/scenario09_5.binu8@90905": '@vMeguri_1745「那时候我什么都不明白！你为我做过的事、拯救过我的事。明明正因为有戏剧，我才能创造出幸福的回忆！其实我一直、一直都得到了那么多的爱！」',
    "Script/scenario06b_7.binu8@41612": '@vFutaba_0749「绝对是从一开始就决定好合格者了！通过选拔的可是知名事务所重点培养的新人啊！！」',
    "Script/scenario07_2.binu8@91250": '@vMeguri_1076「……或许真是这样。嗯……一定是这样。虽然我从未当面对他们说过……但我一直把天兄和悠小姐，当成真正的家人。」',
    "Script/scenario09_4.binu8@91726": '「只要还活着，我、我们、你、你们……都是演员。最棒的作品必须是下一场戏。停下脚步、原地止步，就是放弃挑战。」',
    "Script/scenario09_1.binu8@56196": '@vMirai_9002「如果你在不知道那孩子是男人的情况下和她交谈、与她亲近……你还会有同样的感觉吗？等你知道她是男人后，会失望吗？」',
    "Script/scenario07b_5.binu8@45831": '@vMeguri_1598「有统计说，去电影院看爱情片的情侣中，有 95% 都想在放映期间做些色色的事。」',
    "Script/scenario07_6.binu8@68716": '@vOmi_0098「觉得开心的只有你而已。会原谅你的，大概只有来来和悠苑……其他人都会觉得你烦吧。天才就不该待在这种地方。快点往更高处去吧。」',
    "Script/scenario04_4.binu8@86634": '　即使到了现在，我也不知道自己为什么会被录取。可在众多申请者中脱颖而出，始终让我无法摆脱内疚。',
    "Script/scenario07_2.binu8@104964": '@vOmi_0057「你们的心已经折断，失去了容身之处，未来也被封死。今后你们在戏剧界什么都做不成。因为你们已经完了。」',
    "Script/scenario04_4.binu8@79275": '「……很久以前也发生过类似的事……不，不是喝酒之类的。理世只要闻到类似的东西，甚至只是闻到气味，就会变成这样……」',
    "Script/scenario08b_4.binu8@63886": '@vHana_0305「谢谢您！哎呀，我这个人比较怕寂寞……要是不说话，就会寂寞得死掉呢。」',
    "Script/scenario05_14.binu8@81526": '@vMeguri_0918「奥丁，就算你沦为暴君，残忍地杀害我的家人，我也无法亲手杀死你！」',
    "Script/scenario04_2.binu8@93017": '@vKohaku_0493「对！我想说的就是这个。」',
    "Script/scenario04_4.binu8@67352": '@vRize_0386「橙、橙汁！？」',
    "Script/scenario04_4.binu8@67960": '@vRize_0387「嗯、嗯，是啊。那我就不客气地收下了。」',
    "Script/scenario05_4.binu8@78110": '　然后，聊聊现在的事情吧。',
    "Script/scenario05_4.binu8@79728": '　看到我垂头丧气的样子，座长用他自己的方式鼓励着我。',
    "Script/scenario05_4.binu8@80489": '　对祖父的感情，就这样烟消云散了。',
    "Script/scenario05_5.binu8@90559": '@vMeguri_0640「我开动了。」',
    "Script/scenario05_8.binu8@73953": '@vHana_0216「巡、巡小姐居然在说濑和君的事……！呜哇！这可是大新闻啊！」',
    "Script/scenario05_9.binu8@94200": '@vMeguri_0780「事情就是这样。真的很抱歉。」',
    "Script/scenario05_9.binu8@95665": '@vRairai_0483「濑和，你也是。既然想当导演，就多为演员考虑考虑。要是你再可靠一点，说不定就不会发生这种事了。」',
    "Script/scenario05_9.binu8@96459": '　剧情急转直下，戏剧的天空乌云密布。',
    "Script/scenario05_9.binu8@96599": '　架桥琥珀完全没有察言观色，直接说了出来。',
    "Script/scenario05_9.binu8@97051": '@vKohaku_0590「——那个，巡小姐。我想说的是一种假设。」',
    "Script/scenario06_1.binu8@85294": '@vKohaku_0698「呜。」',
    "Script/scenario06_4.binu8@86546": '　那种闹别扭的语气，让我觉得有些怀念。',
    "Script/scenario06_6.binu8@70429": '@vRize_0936「哈啾……嗯嗯……！！」',
    "Script/scenario06_6.binu8@72304": '@vRize_0945「……呜呜呜……绝对只有我一个人……」',
    "Script/scenario06_6.binu8@82918": '@vRize_0963「……这边。」',
    "Script/scenario06_6.binu8@83535": '@vRize_0968「嗯……但是……」',
    "Script/scenario05_13.binu8@60231": '@vNanana_0398「不对。」',
    "Script/scenario05_13.binu8@62052": '@vNanana_0403「我——！！」',
    "Script/scenario05_13.binu8@69653": '@vMeguri_0885「别开玩笑了！！」',
    "Script/scenario05_13.binu8@76442": '@vRize_0700「巡。」',
    "Script/scenario05_13.binu8@77232": '@vMirai_0374「理世小姐。」',
    "Script/scenario05_14.binu8@78881": '@vMeguri_0914「——不对。」',
    "Script/scenario05_14.binu8@81038": '@vMeguri_0915「我……」',
    "Script/scenario05_14.binu8@89221": '@vNanana_0406「我第一次这样想。」',
    "Script/scenario06_6.binu8@83759": '@vRize_0970「不行吗？」',
    "Script/scenario06b_2.binu8@88619": '@vMika_0095「可是，奈奈菜。」',
    "Script/scenario06b_2.binu8@90072": '@vMika_0103「濑和君，你还没有对奈奈菜出手吧？」',
    "Script/scenario06b_3.binu8@70131": '@vMika_0113「呐，奈奈菜。」',
    "Script/scenario06b_3.binu8@83181": '@vNanana_0527「吵死了。」',
    "Script/scenario06b_3.binu8@85204": '@vNanana_0537「环君。」',
    "Script/scenario06b_4.binu8@65039": '@vNanana_0569「对、对不起……」',
    "Script/scenario06b_4.binu8@66126": '@vNanana_0574「环君。」',
    "Script/scenario06b_7.binu8@36175": '@vFutaba_0737「处男辛苦啦！！」',
    "Script/scenario07_3.binu8@68474": '@vRairai_0633「这样啊。」',
    "Script/scenario07_3.binu8@86961": '　所以，我……。',
    "Script/scenario07_4.binu8@50613": '@vRairai_0650「……真麻烦。」',
    "Script/scenario05_12.binu8@81544": '@n　——芙蕾雅，真是个卑劣的角色。',
    "Script/scenario05_12.binu8@96262": '　啊，糟糕，怎么办。@n　明明洛基笑得如此虚幻美丽……可我却丑陋成这样。',
    "Script/scenario05_13.binu8@67000": '　那个表现得如此暴虐的奥丁，一切都是幻象……其实，他就是那个曾经温柔的奥丁……。',
    "Script/scenario05_13.binu8@75779": '　——啊，世界啊。',
    "Script/scenario05_13.binu8@76335": '　被深渊魅惑的少女，任凭感情翻涌，继续放声呐喊。',
    "Script/scenario05_14.binu8@76131": '　感情、冲动、本能——让我说出了与台本完全相反的台词。',
    "Script/scenario05_4.binu8@79823": '　所以，还是坦率地接受这一点吧。@n　让我们稳住心神，鼓起干劲，努力不要输掉。',
    "Script/scenario05_4.binu8@79965": '　提高音量争吵，是小孩子才会做的事。@n　成熟女性就该优雅地化解这种场面。',
    "Script/scenario05_5.binu8@72291": '「我调查过匂宫至今演过的角色。她演过各种各样的角色……但共同点是，几乎全都是意志坚强的人。能够演出软弱的角色，实在太少了。」',
    "Script/scenario05_5.binu8@83979": '　啪嗒一声。@n　有什么东西从匂宫的口袋里掉了出来。',
    "Script/scenario05_5.binu8@84343": '　正因为他那副扭捏害羞的样子，才让匂宫越来越得意。',
    "Script/scenario05_9.binu8@94355": '@vcs_Futaba_0001「……这没什么问题吧？匂宫小姐并不是想进行不正当的男女交往。她只是想捉弄环而已……」',
    "Script/scenario05_9.binu8@96898": '　那带着戏剧腔调的声音传来。@n　匂宫仿佛被声音吸引，回过了头。',
    "Script/scenario06_2.binu8@84622": '「……从未来还活着的时候起，就一直是这样。每次看到那家伙的脸，我都会感到恶心和头痛。腹中翻涌着浓重的黑色情感，那本应不可能出现在兄妹之间的负面情绪。」',
    "Script/scenario06_2.binu8@87435": '「以未来的演技为榜样，模仿她、学习她、掌握她——未来、未来、未来，未来未来未来！！我被迫不断看着那家伙的演技，简直要疯了。」',
    "Script/scenario06_4.binu8@86122": '　就在这时。@n　意识被现实拉了回来。',
    "Script/scenario06_6.binu8@83488": '「理世……现在还是午休时间啊。」',
    "Script/scenario06_6.binu8@83819": '　这是一次避人耳目的午休。',
    "Script/scenario06_6.binu8@86636": '　真是喜欢接吻啊。',
    "Script/scenario06b_4.binu8@80359": '@vNanana_0601「哇、哇哇……！？环、环君！？」',
    "Script/scenario06b_7.binu8@36828": '　双叶的摄影技术确实远胜普通业余爱好者。',
    "Script/scenario07_3.binu8@65920": '　被年纪比自己小的女孩子从中调停，即使是天乐先生也——',
    "Script/scenario07_3.binu8@70541": '@vOmi_0069「少说傻话。我信任的，是亲手把戏剧的基础灌输给那家伙的我自己。」',
    "Script/scenario07_3.binu8@71035": '　痛快淋漓、个性百货，这就是兰比里斯剧团。',
    "Script/scenario07_5.binu8@74775": '@vKohaku_0784「……明白了。」',
    "Script/scenario07_6.binu8@73819": '　我不可能不知道。@n　那只狐狸和王子，后来怎么样了。',
    "Script/scenario07b_2.binu8@77512": '@vMeguri_1337「一旦开始交往，就会出现分手的可能。不交往的话，就能永远梦想着成为恋人。允许这种事存在的世界……一定充满了各种各样的幸福。」',
    "Script/scenario07b_2.binu8@89276": '@vMeguri_1369「不是那样。不是的。无论这里充满谎言与否……这里都是世界的尽头。」',
    "Script/scenario07b_4.binu8@68811": '@vMeguri_1523「嗯，我知道啊。因为我笨拙得让人都看不下去，完全不擅长谈恋爱嘛。」',
    "Script/scenario07b_5.binu8@50179": '@vRairai_0787「吵、吵死了！总是依赖幕后人员，像什么话！你也稍微帮点忙啊！」',
    "Script/scenario08_1.binu8@92722": '@vOboro_0357「啊。」',
    "Script/scenario08b_5.binu8@37188": '@vKohaku_1190「夜晚的声音很美。风、树木、光，都在注视着我。寂静的音乐也在推着我前进。」',
    "Script/scenario09_2.binu8@80685": '@vMirai_0871「哥哥一定需要一个像双叶酱那样的朋友吧。要是我也有一个像双叶酱那样的朋友……」',
    "Script/scenario09_3.binu8@57146": '@vMirai_0701「呐，哥哥。我……对哥哥——」',
    "Script/scenario09_3.binu8@72627": '@vMirai_0929「我是卡利古拉。」',
    "Script/scenario09_4.binu8@76589": '@vMirai_0987「嗯、嗯。我明白，我明白的。明白到让我想哭。没有任何人理解过我。每次伸出手帮助我的，始终只有我自己。但是，未来已经很努力了。真的，已经非常努力了。」',
    "Script/scenario09_4.binu8@78679": '@vMirai_1000「我明白了。」',
    "Script/scenario09_4.binu8@93717": '@vMirai_1062「呐，哥哥。妹妹为什么不能喜欢上哥哥呢？」',
    "Script/scenario05_10.binu8@78776": '@vRairai_0500「别妨碍我，濑和。你的存在才是最让人碍眼的。」',
    "Script/scenario05_10.binu8@82632": '「你这自作主张的家伙……！你知道巡因此受了多少伤吗……！她现在状态不好，也是因为——」',
    "Script/scenario05_10.binu8@82790": '@vRairai_0510「不是那样，濑和。巡演技不佳，是因为她自己的内心冲突，和我无关。」',
    "Script/scenario05_10.binu8@88246": '@vRairai_0523「喂，濑和。你也该想起来了吧。」',
    "Script/scenario05_11.binu8@75190": '@vRairai_0551「但我没办法就这样坦然接受。因为我曾经真心渴望过……因为我曾以成为演员为目标……我想至少相信自己直到最后。」',
    "Script/scenario05_11.binu8@90996": '「……呃……！」',
    "Script/scenario05_11.binu8@94408": '　我打开了排练室的门。@n　我原以为那里一定会展开往常的景象——。',
    "Script/scenario05_11.binu8@98488": '@vRize_0663「居然要以这种状态迎来正式演出……」',
    "Script/scenario05_11.binu8@100987": '@vRize_0664「嗯、嗯……我以为你迟到了，所以打电话问了一下……他说今天要休息……」',
    "Script/scenario05_11.binu8@102086": '@vNanana_0380「……环君，果然，匂宫小姐她……」',
    "Script/scenario05_11.binu8@102829": '@vRize_0666「……座长，您究竟……」',
    "Script/scenario05_11.binu8@104100": '@vRize_0670「……我、我也觉得这里……让人很舒服。」',
    "Script/scenario05_12.binu8@73512": '@vRairai_0579「……喂，濑和。你打算怎么办？待在这里也只会碍事吧？」',
    "Script/scenario05_13.binu8@76956": '@vMirai_0373「……理世小姐。」',
    "Script/scenario05_14.binu8@82182": '@vKohaku_0658「……那就是你的真相吗？」',
    "Script/scenario05_14.binu8@85062": '@vKohaku_0664「……我知道你是无罪的。我知道你不可能发动叛乱。甚至知道你不可能杀死我——这些我全都知道。」',
    "Script/scenario05_14.binu8@89397": '　这和我曾在纯白房间里渴望毫无意义的停滞时，完全不同。',
    "Script/scenario05_8.binu8@67811": '@vFutaba_0596「……环这家伙，居然连匂宫小姐都下手了……！咕呜呜……」',
    "Script/scenario05_8.binu8@68829": '@vFutaba_0598「我一直觉得奇怪。环把家人的私人物品都收进各自房间……生活区域里本来应该只有环的东西才对。」',
    "Script/scenario05_8.binu8@75738": '@vFutaba_0606「……继天使酱之后，连匂宫小姐也……为什么会做出那种事……」',
    "Script/scenario05_9.binu8@83078": '@vRize_0651「巡、巡！？你今天也要去濑和君家吗……？一直打扰他，真的好吗……」',
    "Script/scenario05_9.binu8@83372": '@vRize_0652「虽、虽然也不是不方便……！！那、那样的话，我也……！」',
    "Script/scenario05_9.binu8@94725": '@vRize_0655「……不过，这可真伤脑筋。停学三天也就算了……居然连宣传活动都不能在学校里进行……」',
    "Script/scenario06_1.binu8@87532": '@vF_StudentA_0027「濑和君是不是也出演了什么角色！？」',
    "Script/scenario05_1.binu8@82672": '　比如“你是谁”之类的话。@n　这种话，大概不能说出口吧……。',
    "Script/scenario05_10.binu8@76915": '@vKohaku_0602a「……哦～～……」',
    "Script/scenario05_1.binu8@91615": '@vNanana_0304「……诶？可、可是……这样会打扰你的……」',
    "Script/scenario05_11.binu8@76094": '@vYuuen_0202「……怎么会，为什么……！」',
    "Script/scenario05_11.binu8@93748": '「兰比里斯剧团出事了……巡她，那个……」',
    "Script/scenario05_11.binu8@93908": '「是什么来着……啊，可恶！真让人烦躁……！」',
    "Script/scenario05_12.binu8@91771": '@vRize_0695「……巡……！」',
    "Script/scenario05_2.binu8@72599": '@vHana_0164「濑和君决定留下来啦！呵呵呵！信赖度百分之百！」',
    "Script/scenario05_2.binu8@75981": '　……原来理世不擅长拒绝别人啊。',
    "Script/scenario05_2.binu8@76602": '@vRize_0555「濑和君……不、不行，再继续下去的话……」',
    "Script/scenario05_2.binu8@77172": '@vRize_0559「够、够了……快继续往下进行啊……！」',
    "Script/scenario05_2.binu8@77331": '@vRize_0560「你倒是说点什么啊……！为什么会变成这样……！」',
    "Script/scenario05_3.binu8@82232": '@vKohaku_0548「只要找到属于我的月亮，我就能彻底成为奥丁。我清楚地感受到了这一点。可是，我无法把它化为具体的形式……所以我思考了一下。」',
    "Script/scenario05_3.binu8@94141": '　祖父认可了我的才能。@n　正因如此……他没有把我当成孩子，而是当成一名演员来对待。',
    "Script/scenario05_4.binu8@71050": '@vMeguri_0513「……明明平时都是商量之后再做决定的。」',
    "Script/scenario05_5.binu8@70386": '「……你的演技里，传达出了一丝类似愤怒的情绪。该说是强烈的意志……还是憎恨呢？你有什么头绪吗？」',
    "Script/scenario05_5.binu8@74506": '「不、不……因为我印象中的匂宫，总是颐指气使地使唤周围的人，所以我还以为你不擅长家务和做饭……」',
    "Script/scenario05_8.binu8@68201": '@vMeguri_0724「特殊关系……那是什么？我们之间明明没什么……」',
    "Script/scenario05_8.binu8@69110": '@vFutaba_0599「今天借用洗手间时，我发现洗手台上有两把牙刷。咦？我就想，妹妹的牙刷为什么会摆出来呢……可是，那其实是……」',
    "Script/scenario05_9.binu8@82750": '「喂、喂……太近了！而且，巡的家和我家是相反方向吧……！」',
    "Script/scenario09_4.binu8@97837": '「这样下去是不行的。」',
    "Script/scenario02_4.binu8@62534": '　如果不能彻底理解现实、自己、才能和本性……就不可能成为什么样的人。',
    "Script/scenario01_2.binu8@73136": '　这是一个为被杀害的父亲、被现任国王叔父夺走的王后母亲复仇的故事。',
    "Script/scenario01_2.binu8@80616": '　一个出乎意料的人被吸引住了。',
    "Script/scenario04_5.binu8@79744": '@vFutaba_0539「未来真是美好得让人头脑发狂。」',
    "Script/scenario07_3.binu8@63648": '@vRize_1449「会被王海先生责备的……」',
    "Script/scenario07_3.binu8@63876": '@vOmi_0064「真是没救了，我家这个笨孙子。」',
    "Script/scenario07_3.binu8@64983": '@vRairai_0623「少啰嗦了，巡！别以为谁都能像你一样轻易做到！我们这边可全都是普通人！」',
    "Script/scenario07_4.binu8@73539": '@vRairai_0693「不行，这样下去不行。」',
    "Script/scenario07_4.binu8@74274": '@vRairai_0694「巡，你……！」',
    "Script/scenario07_4.binu8@74753": '@vRairai_0696「明明如此，你为什么还要……！！」',
    "Script/scenario07_5.binu8@73450": '@vKohaku_0782「明明是如此渴望，甚至只要说出来就会动摇。」',
    "Script/scenario07b_2.binu8@68480": '@vNanana_1005「不是的，诞生了多少不幸，就会有多少幸福嘛！所以当我大口吞下不幸时，甜得仿佛融化了一样的滋味，就会充满口腔！」',
    "Script/scenario07b_5.binu8@47117": '@vMeguri_1604「大家都很忙吗？啊，两个人一起练习也很辛苦吧。到底该怎么办才好呢——」',
    "Script/scenario08b_5.binu8@45876": '@vKohaku_1292「请稍微休息一下。也请暂时道别。」',
    "Script/scenario09_1.binu8@50737": '@vMirai_0810「因为和我很像，所以也很漂亮嘛。」',
    "Script/scenario09_1.binu8@51293": '@vMirai_0813「不是姐妹……是兄妹啦。」',
    "Script/scenario09_1.binu8@57065": '@vFutaba_0912「诶？不，谢谢，我就不用了。请放过我……这种事，那个，我真的做不到。」',
    "Script/scenario09_2.binu8@69516": '@vMirai_0837「呵呵呵，谁知道呢。」',
    "Script/scenario09_2.binu8@91954": '「为什么？你这家伙……那当然是因为……」',
    "Script/scenario09_5.binu8@90798": '@vMeguri_1744「不是的，不是那样！！」',
    "Script/scenario05_9.binu8@87194": '　震撼独家报道！！@n　学生剧团成员的不纯异性交往！！@n　深闺千金“匂宫巡”的夜间演技指导！！',
    "Script/scenario05_14.binu8@88506": '@vmix_all「谢谢大家！」',
    "Script/scenario05_7.binu8@93370": '「……果然，戏剧真有意思。朧的诠释很新鲜，也让我明白，每个人都有自己理解故事的方式。」',
    "Script/scenario05_8.binu8@82205": '@vM_StudentA_0007「诶，戏剧？什么什么，你也在演吗？」',
    "Script/scenario05_8.binu8@82666": '@vM_StudentA_0010「……嘻嘻。」',
    "Script/scenario06_1.binu8@83586": '@vF_StudentA_0011「椎名同学，你在舞台上好帅啊——！存在感特别强！」',
    "Script/scenario06_1.binu8@85899": '@vF_StudentA_0022「哇！仔细一看，确实能看出几分相似……！！声音也很像！诶——不要，我现在心跳得好快！」',
    "Script/scenario06_1.binu8@86306": '@vM_StudentA_0013「什么什么？怎么了？架桥怎么了？」',
    "Script/scenario06_1.binu8@86409": '@vF_StudentB_0005「喂，有什么有趣的事也让我听听嘛——」',
    "Script/scenario06_1.binu8@87532": '@vF_StudentA_0027「濑和君是不是也出演了什么角色！？」',
    "Script/scenario07_2.binu8@89094": '@vMeguri_1065「提议的人是悠小姐。一部是安托万·德·圣埃克苏佩里的《小王子》，另一部是宫泽贤治的《银河铁道之夜》。」',
    "Script/scenario07_2.binu8@89913": '@vMeguri_1069「不是月夜。因为是银河，所以才会发光。」',
    "Script/scenario07_2.binu8@90500": '@vMeguri_1073「说实话，菲莉亚演出的时候，我的状态很危险。我迷失了自己的位置……根本无法好好演戏。」',
    "Script/scenario07_2.binu8@90760": '@vMeguri_1074「我无法压抑对天兄的憎恨。我把愤怒注入洛基这个人格，在舞台上肆意发泄。」',
    "Script/scenario07_2.binu8@91655": '@vMeguri_1077「那大概是为了引出我的愤怒演技，而自以为是地安排的恶作剧吧。恐怕连最后让我原谅你，也都算在计划之内。啊，真是的……光是想起来就让人火大。我还真是个小孩子。」',
    "Script/scenario07_2.binu8@91973": '「作为恶作剧来说，可一点也不好笑。」',
    "Script/scenario07_2.binu8@92699": '@vMeguri_1080「我当然明白。我虽然是天才，却还是个对世事一无所知的半吊子。直到今天，我也不是靠自己的力量一路走来的。」',
    "Script/scenario07_2.binu8@92921": '@vMeguri_1081「是兰比里斯剧团陪在我身边。所以我才能努力走到现在。」',
    "Script/scenario07_2.binu8@94134": '@vMirai_0534「从现在起，我要和巡小姐约会。」',
    "Script/scenario07_2.binu8@94273": '「这么晚吗？」',
    "Script/scenario07_2.binu8@95545": '@vMirai_0541「真是个不解风情的人。」',
    "Script/scenario07_2.binu8@96987": '@vKohaku_0734「演戏真不可思议。融化、沉淀、纠缠……就像要和另一个存在融合一样。所以直到现在，奥丁的感情仍然留在这里。」',
    "Script/scenario07_2.binu8@97259": '@vKohaku_0735「这不是什么弊害，也是全新的我。所谓多次元地活着，不过是我这个人众多侧面中的一面。」',
    "Script/scenario07_2.binu8@97819": '@vKohaku_0736「有人让我明白了相似的感情。通过触碰痛苦与悲伤，我理解了奥丁的心意。所以我才能把这场戏演到最后。」',
    "Script/scenario07_2.binu8@98163": '@vKohaku_0737「没有什么技术上的事，只是听他讲了些往事而已。」',
    "Script/scenario07_2.binu8@98788": '「……天乐座长他……」',
    "Script/scenario07_2.binu8@98908": '@vKohaku_0740「消失在舞台侧幕。大家演完自己的戏份后，都会回到原来的位置。」',
    "Script/scenario07_2.binu8@99682": '@vKohaku_0742「可是，舞台监督不允许你察觉这一点。所以你才会演出连自己都不知道的自己。」',
    "Script/scenario07_2.binu8@100452": '@vKohaku_0743「因为那就是天乐座长的愿望。」',
    "Script/scenario07_2.binu8@100524": '@vKohaku_0744「我把奥丁演到底，才是那个人的愿望。而且，我的内心是空的。倒进去的水，不会轻易溢出来。」',
    "Script/scenario07_2.binu8@101367": '　听说悠苑的转会计划被我毁掉时，我打从心底感到震惊。',
    "Script/scenario07_2.binu8@102064": '@vRairai_0616「老头，我……」',
    "Script/scenario07_2.binu8@102106": '@vRairai_0617「我想成立自己的剧团。为此，我想借用你的知名度。」',
    "Script/scenario07_2.binu8@102223": '@vOmi_0047「……随你便。」',
    "Script/scenario07_2.binu8@102709": '@vRairai_0618「哈，正合我意。比起被人寄予期待，还是没人期待我更适合。」',
    "Script/scenario07_2.binu8@102814": '@vOmi_0049「……不过，来来。」',
    "Script/scenario07_2.binu8@103514": '@vYuuen_0232「好久不见，王海先生。」',
    "Script/scenario07_2.binu8@105221": '@vOmi_0058「让我看看你们那副狼狈不堪、烂得像垃圾的演技。爬在地上，弄得满身泥巴，证明自己的价值。放心……舞台之上，世界是平等的。无论有什么理由，只要幕布升起，就能战斗。」',
    "Script/scenario07_2.binu8@105925": '@vRairai_0621「你这老混蛋终于肯干劲十足地动起来了吗？」',
    "Script/scenario07_2.binu8@106000": '@vOmi_0060「可别输给一个已经隐退的老头啊，来来。」',
    "Script/scenario07_3.binu8@54654": '@vOmi_0063「去加入适合你能力的剧团。这里对你来说还太早了。」',
    "Script/scenario07_3.binu8@54964": '@n　——唯独兰比里斯剧团，你最好别加入。',
    "Script/scenario07_3.binu8@55157": '　兰比里斯剧团的恶评，从四面八方传来。',
    "Script/scenario07_3.binu8@56554": '@vMeguri_1090「……是我做不到的演技。」',
    "Script/scenario07_3.binu8@56837": '@vMeguri_1091「……我绝对要加入。」',
    "Script/scenario07_3.binu8@57691": '@vMeguri_1093「我想加入兰比里斯剧团。除此之外，免谈。」',
    "Script/scenario07_3.binu8@59100": '@vMeguri_1097「我想演出能让自己满意的戏。看到兰比里斯的处女公演时，虽然不甘心，但我感觉到了自己欠缺的东西。在这里，我一定能让演技更上一层楼。理由仅此而已，就已经足够了。」',
    "Script/scenario07_3.binu8@59793": '@vMeguri_1098「……怎么？你终于打算承认了吗？」',
    "Script/scenario07_3.binu8@60425": '@vRize_1436「每天都在吵架。双方把各自的意见狠狠撞在一起……王海先生也总是在吼叫。但演员们也会顶回去，所以几乎每次都闹得不可开交。」',
    "Script/scenario07_3.binu8@61012": '@vRize_1438「一个小时后，龙木先生在配备的浴室里发现了昏迷的她。听说她因为被天乐先生的话激怒，想通过真的溺水来获得真实感。她奄奄一息地说……下一次，我一定要赢回来。」',
    "Script/scenario07_3.binu8@61665": '@vRize_1440「不，只是嘲笑她说别因为做到这种程度就得意……之后便是一阵恶毒的辱骂。结果，那个女孩子似乎退出了剧团。」',
    "Script/scenario07_3.binu8@62006": '@vMeguri_1106「没错。虽然他是个高压、粗暴、总是无端攻击周围人的小混混……但他一直按照自己的正义行事。也因为经常被误解，似乎在许多剧团都惹出过麻烦……不过在兰比里斯，应该没问题。」',
    "Script/scenario07_3.binu8@62490": '@vMeguri_1107「有什么不好？天兄应该也是明知故犯吧。可是，那就是天兄热爱戏剧的方式，所以也没办法。」',
    "Script/scenario07_2.binu8@89638": '「这理由可真够酷的。」',
    "Script/scenario07_2.binu8@90361": '「不是问你‘随便’。」',
    "Script/scenario07_2.binu8@93723": '@vMirai_0531「我已经像那只蝎子一样——」',
    "Script/scenario07_2.binu8@93787": '@vMirai_0532「如果真的是为了所有人的幸福——」',
    "Script/scenario07_2.binu8@93913": '@vMirai_0533「就算把我的身体烧上一百遍，也无所谓。」',
    "Script/scenario07_2.binu8@96360": '「……琥珀。」',
    "Script/scenario07_2.binu8@97571": '「……真是惊人。你的演技深度让我叹服。不过……你究竟是怎么掌握奥丁的演技的？你以前不是只会模仿别人吗？」',
    "Script/scenario07_2.binu8@98598": '@vKohaku_0739「啊，龙胆花开了。已经完全入秋了呢。」',
    "Script/scenario07_2.binu8@99557": '「……是的，那个人曾经告诉过我一个非常重要、却又充满矛盾的故事。」',
    "Script/scenario07_3.binu8@55519": '@vMeguri_1087「这是……」',
    "Script/scenario07_3.binu8@55982": '@vMeguri_1088「……好厉害。」',
    "Script/scenario07_3.binu8@57298": '@vRize_1428「真是服了……」',
    "Script/scenario07_3.binu8@63005": '@vRize_1445「……真冷淡啊。」',
    "Script/scenario07_3.binu8@63579": '@vMeguri_1112「呵呵呵，理解得真快，帮大忙了。」',
    "Script/scenario07_3.binu8@65338": '@vOmi_0065「吵死了，你们这帮臭小鬼！！别再进行这种难看的斗嘴了！！」',
    "Script/scenario07_3.binu8@65600": '@vRize_1451「请、请住手！现在可是宝贵的排练时间！私人争吵请留到之后！」',
    "Script/scenario07_3.binu8@65745": '　没错，调停争吵本来就是理世的职责。',
    "Script/scenario07_3.binu8@66003": '@vRairai_0624「我不知道啊！！我又没错！！全都是巡的错！！」',
    "Script/scenario07_3.binu8@66730": '@vRairai_0626「下一场戏要让你演主角。别依赖别人，靠自己战斗。你演的那个恶女，本来就是这种性格吧。」',
    "Script/scenario07_3.binu8@67212": '@vRairai_0627「喂，白坂。」',
    "Script/scenario07_3.binu8@67311": '@vRairai_0628「这次的舞台，尽量做得华丽壮观些。虽然会给你们幕后人员增加负担……」',
    "Script/scenario07_3.binu8@67719": '@vRairai_0629「……喂，我什么时候说是为了悠苑了？」',
    "Script/scenario07_3.binu8@67945": '@vRairai_0630「你这混蛋。」',
    "Script/scenario07_3.binu8@68326": '@vHana_0255「没错！这份笑容就是最好的证明！看来这种方式更适合我呢！」',
    "Script/scenario07_3.binu8@68572": '@vRairai_0634「我可不会道谢啊。」',
    "Script/scenario07_3.binu8@68790": '@vRairai_0636「……不过嘛……只要你现在幸福，那就好。你可是不可或缺的人才。」',
    "Script/scenario07_3.binu8@69240": '@vHana_0259「如果需要溺水的演技，我随时都可以复出演员哦！」',
    "Script/scenario07_3.binu8@69343": '@vRairai_0637「笨蛋，你一辈子都给我待在幕后。就这样像花一样笑着吧。」',
    "Script/scenario07_3.binu8@69498": '@vRairai_0638「也有人会被你的笑容拯救。所以你就一直待在这里吧。」',
    "Script/scenario07_3.binu8@69836": '@vOmi_0066「喂，白坂。」',
    "Script/scenario07_3.binu8@69872": '@vHana_0261「怎么了，王海先生？」',
    "Script/scenario07_3.binu8@70688": '@vHana_0264「呵呵呵，就当是这样吧。那么，我明白了。」',
    "Script/scenario07_3.binu8@70791": '　巡的加入，似乎会给兰比里斯剧团带来各种各样的影响。',
    "Script/scenario07_3.binu8@71806": '@vRairai_0639「……我没有错。」',
    "Script/scenario07_3.binu8@72078": '@vDirectorB_0000「您是一位聪慧的女性。声音清亮，讲话方式也让人听着很舒服。直到今天，您一定付出了很多努力吧。」',
    "Script/scenario07_3.binu8@72880": '@vYuuen_0238「惭、惭愧……」',
    "Script/scenario07_3.binu8@73147": '@vDirectorB_0003「我讨厌只有表面的演技。所以最近总是被那些只会装模作样的演员弄得厌烦。我希望你能把自己的内在彻底展现出来。」',
    "Script/scenario07_3.binu8@73692": '@vDirectorB_0005「可是，悠苑小姐的演技里，缺少了一点情感。看着实在令人惋惜。」',
    "Script/scenario07_3.binu8@73866": '@vYuuen_0240「情感吗……？」',
    "Script/scenario07_3.binu8@74322": '@vDirectorB_0007「所以，悠苑小姐，下次要不要来我们排练室参观？我想你一定能得到很多东西。」',
    "Script/scenario07_3.binu8@74754": '@vYuuen_0242「怎、怎么会……我实在不敢当……！」',
    "Script/scenario07_3.binu8@74949": '@vDirectorB_0008「我是真心希望，能够让你作为女演员绽放光彩。」',
    "Script/scenario07_3.binu8@75297": '@vLeaderA_0000「我听说了，悠苑。」',
    "Script/scenario07_3.binu8@76283": '@vDirectorB_0009「你好，悠苑小姐。」',
    "Script/scenario07_3.binu8@76331": '@vYuuen_0246「晚、晚上好！」',
    "Script/scenario07_3.binu8@76632": '@vDirectorB_0011「但我的想法就像上次见面时说的那样。我想让你成名，仅此而已。」',
    "Script/scenario07_3.binu8@76892": '@vDirectorB_0012「今天我想和你聊聊戏剧。愿意陪我走一趟吗？」',
    "Script/scenario07_3.binu8@77246": '@vDirectorB_0013「……那么，我们走吧。」',
    "Script/scenario07_3.binu8@77804": '@vYuuen_0250「啊、那个……这里是……」',
    "Script/scenario07_3.binu8@78331": '@vYuuen_0252「啊、啊、那个……」',
    "Script/scenario07_3.binu8@78544": '@vYuuen_0253「我、我……那种事，我有点……」',
    "Script/scenario07_3.binu8@78754": '@vDirectorB_0017「……如果你不愿意，也没关系。但你真的觉得这样就好吗……？」',
    "Script/scenario07_3.binu8@79292": '@vYuuen_0255「……我、我……」',
    "Script/scenario07_3.binu8@80539": '@vDirectorB_0020「你果然是一位聪慧的女性。」',
    "Script/scenario07_3.binu8@81568": '@vRairai_0641「痛死我了，混账！！话说你这家伙，居然带着女人，真碍眼！接下来是要去酒店亲热吗！？啊！？」',
    "Script/scenario07_3.binu8@81742": '@vDirectorB_0024「……我们走吧，悠苑小姐。」',
    "Script/scenario07_3.binu8@82139": '@vYuuen_0259「来来先生……？」',
    "Script/scenario07_3.binu8@82271": '@vRairai_0643「喂喂，这是什么情况啊，真不得了啊？……嗯？如果我的记忆没错，你不是已经结婚了吗？」',
    "Script/scenario07_3.binu8@82573": '@vDirectorB_0027「……您似乎产生了误会。我只是照顾喝醉的朋友而已。对吧，悠苑小姐？」',
    "Script/scenario07_3.binu8@82966": '@vRairai_0644「啊……是这样吗？抱歉，是我误会了。」',
    "Script/scenario07_3.binu8@83287": '@vDirectorB_0029「去一个不会有人打扰的地方，慢慢聊吧。」',
    "Script/scenario07_3.binu8@83362": '@vYuuen_0261「……我明白了。」',
    "Script/scenario07_3.binu8@83886": '@vRairai_0645「啊？数量不够啊？我家可是挺远的。」',
    "Script/scenario07_3.binu8@83979": '@vDirectorB_0031「真有趣。我可没有做什么亏心事啊。」',
    "Script/scenario07_3.binu8@84235": '@vRairai_0646「你人不错啊。喜欢和聪明人说话。」',
    "Script/scenario07_3.binu8@85915": '@vRairai_0556「我不知道。我只是不喜欢你而已。」',
    "Script/scenario05_10.binu8@100289": '@vRairai_0543「……悠苑？」',
    "Script/scenario05_10.binu8@100494": '　龙木悠苑。@n　与我一同度过青春的同班同学。',
    "Script/scenario05_11.binu8@76759": '@vRairai_0553「悠苑，你和我是同一边的人。这种事，就交给天才大人去做吧。」',
    "Script/scenario05_11.binu8@77807": '毁掉龙木悠苑演艺生涯的我，心情畅快无比。',
    "Script/scenario05_11.binu8@86397": '@vDirectorA_0004「因为你看……毁掉龙木悠苑转团机会的，不就是那家伙吗？散布根本不存在的陪酒传闻，夺走了她的演艺人生。」',
    "Script/scenario05_12.binu8@76372": '龙木悠苑面带不安，开口说道。',
    "Script/scenario05_12.binu8@82971": '被撕裂了心意、被夺走了未来的龙木悠苑，却仍然没有离开他身边。原因就在于——',
    "Script/scenario05_14.binu8@80701": '@vRairai_0599「是啊。」',
    "Script/scenario05_14.binu8@83447": '@vKohaku_0659「……洛基，我……」',
    "Script/scenario05_14.binu8@83866": '@vKohaku_0661「所以，洛基……」',
    "Script/scenario05_14.binu8@87736": '@vKohaku_0670「那是一场……精彩绝伦的演技。」',
    "Script/scenario05_9.binu8@79372": '龙木悠苑温柔地笑了。',
    "Script/scenario05_9.binu8@93581": '@vMeguri_0777「是匂宫，对吧？别随便叫我的名字。」',
    "Script/scenario05_9.binu8@94588": '@vOboro_0261「这是体面的问题吧。不过，也是个重要问题。尤其是对站在人前的人来说。」',
    "Script/scenario05_9.binu8@95603": '@vYuuen_0195「这个……话虽如此……」',
    "Script/scenario06b_2.binu8@84651": '@vMika_0083「奈奈菜。」',
    "Script/scenario06b_2.binu8@84741": '@vMika_0084「啊，太好了。你还好好的吗？我一直很担心你……因为你突然就不见了。」',
    "Script/scenario06b_2.binu8@85233": '@vNanana_0472「妈妈，我……」',
    "Script/scenario06b_2.binu8@85444": '@vNanana_0473「那、那个，妈妈……！我、我做不到那种事……那样不好的做法，我做不到……」',
    "Script/scenario06b_2.binu8@86121": '@vMika_0088「……你是谁？」',
    "Script/scenario06b_2.binu8@90683": '@vMika_0105「……果然是你啊。我的判断没有错。」',
    "Script/scenario06b_2.binu8@90804": '@vNanana_0482「不、不要，妈妈……！现在已经和那些没有关系了……！」',
    "Script/scenario06b_2.binu8@90921": '@vMika_0106「当然有关系，奈奈菜。看来你已经忘记了，那我就好好帮你想起来。」',
    "Script/scenario06b_2.binu8@91309": '@vMika_0108「女人会因恋爱而变得美丽。不懂爱是什么的女人，不可能被谁爱上。」',
    "Script/scenario06b_2.binu8@91675": '@vMika_0110「到此为止，恋爱少女的演技辛苦你了。多亏如此，你已经变成了一个非常、非常可爱的女孩。」',
    "Script/scenario06b_4.binu8@73677": '@vFutaba_0693「环也会为此感到自豪吧。请你认真意识到，自己现在是幸福的。」',
    "Script/scenario06b_4.binu8@74068": '@vNanana_0582「是、是的……！我会像匂宫小姐说的那样，努力了很多……！」',
    "Script/scenario06b_4.binu8@74362": '@vNanana_0583「咦、咦！？明明已经好好化过妆了……！」',
    "Script/scenario06b_4.binu8@74481": '@vMeguri_0974「呵呵呵，真是可爱呢。」',
    "Script/scenario06b_4.binu8@76729": '@vNanana_0590「我会在十七点，等你到平时去的公园。环君，我有重要的话要对你说。」',
    "Script/scenario06b_4.binu8@80939": '@vNanana_0603「……好开心。」',
    "Script/scenario06b_4.binu8@81028": '@vNanana_0604「原来现实中真的有这么幸福的事啊。环君……环君、环君、环君……！」',
    "Script/scenario06b_4.binu8@81213": '@vNanana_0605「……再喜欢我一点。再爱我一点。抱紧奈奈菜，直到你彻底失去理智。」',
    "Script/scenario05_4.binu8@69547": '@vMeguri_0507「——剧团兰比里斯。」',
    "Script/scenario06b_4.binu8@75423": '@vNanana_0586「我想，应该也能提高成功率！」',
    "Script/scenario06b_4.binu8@75510": '@vMeguri_0977「谁知道呢。可是，我觉得现在正是成功率最高的时候……」',
    "Script/scenario06b_4.binu8@76184": '@vNanana_0587「我、我会努力的！一定会努力的！匂宫小姐都这样推我一把了！」',
    "Script/scenario06b_4.binu8@76358": '@vMeguri_0980「嗯，加油哦。」',
    "Script/scenario06b_4.binu8@76624": '@vNanana_0588「……好！」',
    "Script/scenario06b_4.binu8@77177": '@vNanana_0592「我、我还没有做好心理准备……！能、能不能再慢一点过来……！」',
    "Script/scenario06b_4.binu8@77587": '@vNanana_0593「因、因为我想让你看到最可爱的我……！！」',
    "Script/scenario06b_4.binu8@78665": '@vNanana_0596「是、是的……！」',
    "Script/scenario06b_5.binu8@24365": '@vNanana_0715「……不。」',
    "Script/scenario06b_5.binu8@24937": '「……啊，这样啊。」',
    "Script/scenario04_4.binu8@84925": '@vHana_0145「啊……这个世界，原来这么无聊啊。」',
    "Script/scenario04_4.binu8@86251": '而我会对演戏产生兴趣，我想也是自然而然的事。',
    "Script/scenario04_4.binu8@89602": '@vOmi_0006「你……现在还喜欢戏剧吗？」',
    "Script/scenario04_4.binu8@93758": '那句话，是在意识混沌之中脱口而出的。',
    "Script/scenario05_13.binu8@71687": '啊啊，真恶心，真恶心。@n　明明发生了那种事，居然还一味地相信。',
    "Script/scenario05_13.binu8@72905": '啊啊，头好痛。@n　怒火仿佛要将我的内心燃烧殆尽。',
    "Script/scenario05_14.binu8@65483": '她就是这样说着强硬的话，把别人拒之门外。@n　那是那孩子的处世方式。',
    "Script/scenario05_14.binu8@67162": '在名为戏剧的、孤独而漆黑的世界里，他始终毫不怀疑地陪在她身边。',
    "Script/scenario05_14.binu8@74390": '啊啊，真是丑陋的人。@n　你为什么会愚蠢到这种地步呢？',
    "Script/scenario05_14.binu8@74695": '啊啊，好恶心，好恶心。@n　那种任性的行为……真让人恶心。',
    "Script/scenario05_14.binu8@75707": '那才是真正的台词。@n　接下来，洛基本该察觉一切，并付诸行动。',
    "Script/scenario05_14.binu8@88923": '啊啊，好厉害，好厉害。@n　大家真的都好厉害。',
    "Script/scenario05_14.binu8@89002": '是你们为我那部曾以为毫无价值的故事，添上了如此多的色彩。',
    "Script/scenario06b_2.binu8@83100": '@vNanana_0466「……从那天起，我一直一直在逃避……不知不觉间，我还以为自己已经逃掉了……可是，现实果然没那么容易。」',
    "Script/scenario06b_2.binu8@83319": '@vNanana_0467「在佩特里科尔，大家保护我的时候，我真的好开心。啊啊，原来奈奈菜也交到朋友了……」',
    "Script/scenario06b_3.binu8@79115": '啊啊，好吵，好吵，好吵……！',
    "Script/scenario06b_3.binu8@82015": '她会一边蔑视着我，说我是个可悲又凄惨的女人吧。',
    "Script/scenario06b_4.binu8@66297": '@vKohaku_0688「啊，是环君和奈奈菜！发现迟到的同伴啦！」',
    "Script/scenario06b_4.binu8@67925": '@vKohaku_0694「是个让人觉得很开心的故事。害得我昨天晚上都熬夜了。」',
    "Script/scenario06b_4.binu8@74922": '@vNanana_0585「不用这么着急行动的……！仔细一点、慢慢地拉近距离，也可以的吧……」',
    "Script/scenario06b_5.binu8@22331": '@vNanana_0708「啊哈哈……很奇怪吧。我也觉得很奇怪。可是，正因为幸福，才会害怕失去它……」',
    "Script/scenario06b_7.binu8@33292": '@vFutaba_0729「不过，光是追赶潮流可不行呢。现在已经被用烂了，必须做到自己掀起新的潮流才行……！」',
    "Script/scenario06b_7.binu8@36411": '「擅自拿店里的女仆装来穿，好像不太妥当吧……？」',
    "Script/scenario06b_6.binu8@60405": '@vNanana_0731「匂宫先生尊重我的感情，这一点倒是不错。」',
    "Script/scenario08_1.binu8@75963": '我开始想了解名为演员的这种生物。@n　这份冲动，这份心情，一定是真实的。',
    "Script/scenario08_1.binu8@83269": '@vMirai_0568「那就再好不过了。」',
    "Script/scenario08_1.binu8@88087": '「……但这也不能说明她爱我。毕竟，那家伙根本没把我当成异性。」',
    "Script/scenario08_2.binu8@84406": '这问题问得真可怜。@n　既然都说出了口……明明应该已经知道答案了。',
    "Script/scenario08_3.binu8@55990": '「我把别人教给我的东西，按照自己的方式慢慢消化，然后每天不断摸索。我也和母亲商量了很多，逐渐完成了自己心目中的样子。结果，就成了濑和环的‘T氏’。」',
    "Script/scenario08_3.binu8@62757": '@vMirai_0641「『在阴沉的北海天空下』」',
    "Script/scenario08_3.binu8@62906": '@vMirai_0643「『不知何时终结的诅咒』」',
    "Script/scenario08_3.binu8@69659": '@vMirai_0655「『在阴沉的北海天空下』」',
    "Script/scenario08_3.binu8@69935": '@vMirai_0657「『不知何时终结的诅咒』」',
    "Script/scenario08_3.binu8@73586": '「朗读得不错，未来。保持这个状态，再让我看看更多精彩绝伦的演技。」',
    "Script/scenario08_4.binu8@68226": '「……是啊。嗯，正如你所说。我做了一个非常讨厌的梦。一个连回想都不愿意的噩梦。」',
    "Script/scenario08_4.binu8@68556": '「真的太好了……看到你的脸，我就安心了。那是个真实得可怕的梦……」',
    "Script/scenario08_5.binu8@75555": '@vKohaku_0855「……呵、呵呵。」',
    "Script/scenario08_5.binu8@80860": '我本以为那是出于好意，选择相信了它，结果却得到了完全相反的答案。',
    "Script/scenario08_5.binu8@94480": '「……原来并不是二选一啊。」',
    "Script/scenario08b_4.binu8@60094": '「——卡布奇诺。」',
    "Script/scenario08b_4.binu8@60173": '@vKohaku_1169「答对啦！不愧是环君。好啦，就点这个吧！」',
    "Script/scenario08b_4.binu8@61677": '@vKohaku_1176「嗯？奇怪的环君。」',
    "Script/scenario08b_4.binu8@62536": '@vHana_0300「你好。」',
    "Script/scenario08b_4.binu8@62908": '@vHana_0302「啊，抱歉，忘了自我介绍！我叫白坂花。其实，我本来约了朋友在这里见面，可她好像放我鸽子了……如果你不介意的话，能陪我聊几句、听我发发牢骚吗？」',
    "Script/scenario08b_4.binu8@63291": '@vHana_0303「账单由我来付。请尽管点自己喜欢的东西。」',
    "Script/scenario08b_4.binu8@63604": '「这样好吗，琥珀？」',
    "Script/scenario08b_4.binu8@63783": '「……这样啊。」',
    "Script/scenario08b_4.binu8@64070": '@vKohaku_1182「你是个像兔子一样的女孩子呢。」',
    "Script/scenario08b_4.binu8@64252": '@vHana_0306b「所谓杀死兔子，其实是一种认知。兔子一旦被认定为会因孤独而死，最终就真的会腐朽。」',
    "Script/scenario08b_4.binu8@64568": '@vHana_0307「嗯……是这样呢。」',
    "Script/scenario08b_4.binu8@65187": '@vHana_0309「哈哈……立场和想法，会让事情变得复杂。所以……我们最后会闹翻，或许也是注定的。」',
    "Script/scenario08b_4.binu8@67346": '「……这样吗？」',
    "Script/scenario08b_4.binu8@68140": '@vHana_0318「啊哈哈，说了些奇怪的话呢。」',
    "Script/scenario08b_4.binu8@68272": '@vHana_0319「既然她那么喜欢那个朋友，遗忘就不可能成为救赎。那只不过是逃避。」',
    "Script/scenario08b_4.binu8@68461": '@vHana_0320「我没有说那样不好……只是那样什么都解决不了。仅此而已。」',
    "Script/scenario08b_4.binu8@68588": '@vHana_0321「我只是希望理世能再笑一次。为此所需要的，应该不是逃避。」',
    "Script/scenario08b_4.binu8@68760": '「……是这样啊……」',
    "Script/scenario09_1.binu8@41042": '@vF_ChildA_0000「双叶，你喜欢班里的哪个男生？」',
    "Script/scenario09_1.binu8@41167": '人类是一种愚蠢的生物。',
    "Script/scenario09_1.binu8@41499": '@vFutaba_0864「我喜欢你。」',
    "Script/scenario09_1.binu8@41778": '@vFutaba_0865「那个……那么……」',
    "Script/scenario09_1.binu8@42228": '@vFutaba_0867「我喜欢女孩子。」',
    "Script/scenario09_1.binu8@43862": '@vFutaba_0869「好漂亮。」',
    "Script/scenario09_1.binu8@45618": '@vFutaba_0874「啊啊……真的，好漂亮……」',
    "Script/scenario08b_5.binu8@34800": '@vKohaku_0450「你必须睡觉，要慢慢地好好睡一觉。」',
    "Script/scenario08b_5.binu8@34919": '@vKohaku_0451「顺其自然就好，不要为多余的事情苦恼。你睡着的时候，我会陪在你身边。」',
    "Script/scenario08b_5.binu8@35131": '@vKohaku_0452「等你醒来，这个世界也会重新恢复原本的滋味吧。」',
    "Script/scenario08b_5.binu8@35255": '@vKohaku_0549「——环君。你愿意成为我的月亮吗？」',
    "Script/scenario08b_5.binu8@36065": '她脚步轻快，脸上带着笑容。',
    "Script/scenario08b_5.binu8@36346": '「……琥珀很适合夜晚呢。真的，就像月亮一样的女孩子。」',
    "Script/scenario08b_5.binu8@36502": '@vKohaku_1187「哎呀，我好开心。这算是你给我的最高级的夸奖吧？」',
    "Script/scenario08b_5.binu8@36710": '「……公园。」',
    "Script/scenario08b_5.binu8@36763": '「要不要……稍微绕个路再回去？」',
    "Script/scenario08b_5.binu8@36822": '我指向了夜晚的公园。',
    "Script/scenario08b_5.binu8@36928": '@vKohaku_1189「……呵呵，好开心。」',
    "Script/scenario08b_5.binu8@37359": '「……真令人怀念啊。」',
    "Script/scenario08b_5.binu8@37500": '「我不可能感到寂寞。因为现在的我，依然很满足。」',
    "Script/scenario08b_5.binu8@37595": '@vKohaku_0002「……你们这些脸色苍白、瑟瑟发抖地看着这出戏的‘观众’……是打算扮演没有台词的演员吗？还是无聊大戏的观众？」',
    "Script/scenario08b_5.binu8@37919": '@vKohaku_0003「死神毫不留情地催促着我。」',
    "Script/scenario08b_5.binu8@38000": '@vKohaku_0004「霍拉旭，已经不行了。至少，你一定要活下去，把事情的经过原原本本地告诉那些一无所知的人，让他们能够理解……！」',
    "Script/scenario08b_5.binu8@39122": '「琥珀，我……！」',
    "Script/scenario08b_5.binu8@39275": '「我的妹妹……」',
    "Script/scenario08b_5.binu8@39337": '「你明明是我的……可我却……！我对你的感情，已经不只是对妹妹……」',
    "Script/scenario08b_5.binu8@39444": '身体因这残酷的现实而颤抖。@n　在一次又一次重复的试炼中，我终于不再受骗。',
    "Script/scenario08b_5.binu8@40230": '@vKohaku_1195「……怎么了，环君？冷吗？难受吗？那样的话，我们快点回家吧。」',
    "Script/scenario08b_5.binu8@40515": '「我想起来了。我恢复清醒了。不对……我从一开始就是清醒的。只是内心自我毁灭了而已。」',
    "Script/scenario08b_5.binu8@40805": '「让你陪我演了这么无聊的一出戏，还把令人不适的剧情强加给你，真的很对不起。……琥珀，我……你不是我的妹妹……」',
    "Script/scenario08b_5.binu8@41163": '@vKohaku_1198「……环君当哥哥就好。我不必成为真正的我。做环君的妹妹，我很喜欢。」',
    "Script/scenario08b_5.binu8@41316": '「琥珀……可是，那……」',
    "Script/scenario08b_5.binu8@41357": '@vKohaku_1199「请不要再说下去了。求你，不要毁掉这出戏。」',
    "Script/scenario08b_5.binu8@41474": '我紧紧握住了拳头。',
    "Script/scenario08b_5.binu8@41698": '「可是，我对你做了那么过分的事……！」',
    "Script/scenario08b_5.binu8@42114": '@vKohaku_1202「……我曾想成为你的月亮。想成为不可能之物……想成为对你来说重要的东西。所以，没关系。我是你的妹妹，因为那就是你想实现的愿望。」',
    "Script/scenario08b_5.binu8@42615": '@vKohaku_1204「你是我可靠的哥哥。」',
    "Script/scenario08b_5.binu8@42684": '「你是我可爱的妹妹。」',
    "Script/scenario08b_5.binu8@42974": '@vKohaku_1205「嗯，我也是。我最喜欢环君了。」',
    "Script/scenario08b_5.binu8@44074": '「那当然。月亮怎么可能会消失呢。」',
    "Script/scenario08b_5.binu8@44272": '@vKohaku_1281「好热啊，环君。」',
    "Script/scenario08b_5.binu8@44317": '「啊啊，好热啊。」',
    "Script/scenario08b_5.binu8@44568": '@vKohaku_1283「好热……连站起来的力气都没有了。我已经累了。」',
    "Script/scenario08b_5.binu8@44768": '@vKohaku_1284「那个……我们今天为什么会来这里来着？」',
    "Script/scenario08b_5.binu8@44861": '「谁知道呢……我忘了。」',
    "Script/scenario08b_5.binu8@45020": '「……算了，怎样都好。只要有琥珀陪着我，我就很幸福了。」',
    "Script/scenario08b_5.binu8@45399": '「要不要去游泳池？我想看看琥珀穿泳衣的样子。」',
    "Script/scenario08b_5.binu8@45755": '「好热啊……」',
    "Script/scenario08b_5.binu8@45784": '@vKohaku_1291「那么，环君。」',
    "Script/scenario08b_5.binu8@46247": '@vKohaku_1294「环君，我最喜欢你了。」',
    "Script/scenario08b_4.binu8@61882": '@vKohaku_1178「醇厚又甘甜，真棒。苦味和香气交织在一起，形成了恰到好处的美味……嗯，简直是奇迹般的平衡！」',
    "Script/scenario08b_4.binu8@65442": '@vHana_0310「……可是，奇怪的是……从某一天开始，我就找不到那个朋友了。不知道她去了哪里……记忆也变得模糊……甚至连名字都忘了……她从这个世界上消失了。像逃跑一样，离开了。」',
    "Script/scenario08b_4.binu8@66476": '@vHana_0313「除了我以外，没有任何人愿意承认她朋友的存在。他们认定那只是不存在的幻想，否定了她。事实上，周围人说的才是正确的。她的话，没有任何依据。」',
    "Script/scenario09_1.binu8@41226": '人们把自己所持有的认知当成理所当然，下意识地以此为前提提出问题。',
    "Script/scenario09_1.binu8@45262": '@vFutaba_0873「……哈、哈啊……！！」',
    "Script/scenario09_1.binu8@46242": '@vFutaba_0876「……那、那个……！？」',
    "Script/scenario09_1.binu8@46440": '睫毛好长，眼睛闪闪发亮……！还、还有香味，啊、啊啊啊……！！',
    "Script/scenario09_1.binu8@46820": '@vFutaba_0877「为、为什么……？因、因为……很、很、很漂亮……所以……」',
    "Script/scenario09_1.binu8@47497": '@vMirai_0798「……嗅嗅，嗅嗅，好香的味道……你身上好香啊。」',
    "Script/scenario09_1.binu8@47607": '@vFutaba_0879「咦、咦！？不、不是，我是说……要论香味，明、明明是您……！！！ 」',
    "Script/scenario09_1.binu8@47935": '@vMirai_0800「难道说，你喜欢女孩子？」',
    "Script/scenario09_1.binu8@48247": '@vFutaba_0881「才、才不是那样……！！我只是觉得很漂亮，所以……看、看入迷了而已……！」',
    "Script/scenario09_1.binu8@48642": '@vMirai_0802「我知道活着意味着不自由。不过，没关系。在我面前，你不必做一个‘正确’的人。」',
    "Script/scenario09_1.binu8@48916": '@vMirai_0803「所谓正确，会扼杀个性。一直戴着那副面具的话，真正的你就会消失。」',
    "Script/scenario09_1.binu8@49062": '@vFutaba_0883「……我、我……！」',
    "Script/scenario09_1.binu8@49320": '@vMirai_0804「你喜欢女孩子，对吧？」',
    "Script/scenario09_1.binu8@49530": '@vFutaba_0885「看起来就和路边的石头一样。」',
    "Script/scenario09_1.binu8@49971": '@vFutaba_0888「喜欢女孩子，并不代表谁都可以。那如果是男孩子，你也会喜欢任何一个吗？当然不是吧。我只是……喜欢上的对象，恰好是女孩子而已，仅此而已。」',
    "Script/scenario09_1.binu8@50377": '@vFutaba_0889「……那、那是……！！」',
    "Script/scenario09_1.binu8@50793": '@vFutaba_0891「……是的……」',
    "Script/scenario09_1.binu8@50962": '@vcs_Mirai_0001「其实呢，百合子。」',
    "Script/scenario09_1.binu8@51018": '@vFutaba_0892「请、请不要给我起奇怪的外号！」',
    "Script/scenario09_1.binu8@51531": '@vMirai_0816「哥哥。」',
    "Script/scenario09_1.binu8@51717": '@vFutaba_0896「好、好奇怪的名字啊！啊哈、啊哈哈……！！」',
    "Script/scenario09_1.binu8@51932": '@vFutaba_0897「姐姐、环酱？」',
    "Script/scenario09_1.binu8@51989": '@vMirai_0818「哥哥，环君。」',
    "Script/scenario09_1.binu8@52191": '@vFutaba_0899「不、不是！等等！这、这是什么情况！？那是男的……！？骗人的吧！？」',
    "Script/scenario09_1.binu8@52317": '@vMirai_0819「我们家是剧团世家。最近正在进行女装男装的课题训练。因为身体还没有发育完全，所以看起来就像女孩子。不过，这才是真相。」',
    "Script/scenario09_1.binu8@52760": '@vMirai_0820「啊，你看？说不定正好能看到他真正的样子哦。」',
    "Script/scenario09_1.binu8@53398": '@vMirai_0821「……即使知道了真相，你还喜欢那孩子吗？嗯？你喜欢的是女孩子来着，对吧？」',
    "Script/scenario09_1.binu8@53682": '@vMirai_0822「我只是有点在意。想知道你得知真相后会有什么反应。」',
    "Script/scenario09_1.binu8@53907": '@vFutaba_0902「不、不对……不，也不能说不对……！或许……也不能说不对……」',
    "Script/scenario09_1.binu8@54128": '@vFutaba_0903「……我、我很糟糕吗……？我、我不太明白……」',
    "Script/scenario09_1.binu8@55635": '@vFutaba_0908「我想要那位美少女的一切。明明被那份美丽弄得心里怦怦直跳……可一知道对方是男的，兴奋转眼间就消失了。对我来说，她变成了无所谓的存在。」',
    "Script/scenario09_1.binu8@55938": '@vFutaba_0909「如果真的喜欢，即使这样也能爱下去吗？那就是真正的爱吗？我不知道，我不知道……我甚至不想知道。因为我喜欢的是女孩子。」',
    "Script/scenario09_1.binu8@56639": '@vMirai_0825「……是啊。大家都是从某种既定的形式开始的。因为是男人，因为是女人，因为是哥哥，因为是妹妹——」',
    "Script/scenario09_1.binu8@56877": '@vMirai_0826「你和哥哥似乎很合得来呢。如果你们有着不同的喜好，说不定会成为很般配的恋人。」',
    "Script/scenario09_1.binu8@57382": '@vFutaba_0913「……那就算了。我对男人没兴趣……」',
    "Script/scenario09_1.binu8@57472": '@vMirai_0828「没关系。哥哥不会喜欢上你，也不会爱上你。所以，你们可以保持一段彼此方便的关系。」',
    "Script/scenario09_1.binu8@57648": '@vFutaba_0914「什么？那个人也和我一样，觉醒了同性恋倾向吗？」',
    "Script/scenario09_1.binu8@58948": '「那个，仓科同学。」',
    "Script/scenario09_1.binu8@59039": '「那个，今天轮到我们值日打扫……嗯……」',
    "Script/scenario09_1.binu8@59119": '@vFutaba_0919「是、是的！」',
    "Script/scenario09_1.binu8@60683": '@vFutaba_0923「我喜欢女孩子！我只能爱女孩子！」',
    "Script/scenario09_1.binu8@60782": '「啊？咦？你、你在说什么……？这是指那种性癖吗……？」',
    "Script/scenario09_1.binu8@60892": '@vFutaba_0924「没错！这有什么不对吗！」',
    "Script/scenario09_1.binu8@61190": '「这家伙怎么突然变得这么自来熟！？」',
    "Script/scenario09_1.binu8@61267": '@vFutaba_0926「吵死了！这就是我，没办法吧！」',
    "Script/scenario09_1.binu8@61545": '「不，我可是彻头彻尾的普通人。我对同性恋没兴趣，是那种会正常喜欢上班里女孩子的人！」',
    "Script/scenario09_1.binu8@62107": '@vFutaba_0930「哇，居然直接叫名字！好可怕，好恶心！」',
    "Script/scenario09_1.binu8@62173": '「……双叶。」',
    "Script/scenario09_1.binu8@62247": '「开始打扫吧。」',
    "Script/scenario09_1.binu8@62273": '@vFutaba_0932「真拿你没办法。」',
    "Script/scenario09_1.binu8@62981": '@vFutaba_0933「就算戴着面具，我也会让你能够做真实的自己。」',
    "Script/scenario09_1.binu8@63133": '@vFutaba_0934「因为你口气很臭，能不能从性别开始重新来过？」',
    "Script/scenario09_1.binu8@42279": '我无法不爱上那个纤细而美丽的存在。',
    "Script/scenario09_1.binu8@55064": '@vFutaba_0906「可是我不一样。我既不会因为那些男性特征而喜欢上你，也不会因此讨厌你。我只是……什么感觉都没有而已。」',
    "Script/scenario09_1.binu8@59327": '我是不擅长交朋友的类型，而这家伙则是根本不会交朋友的类型。',
    "Script/scenario09_2.binu8@66740": '@vFutaba_0935「……真让人生气。」',
    "Script/scenario09_2.binu8@67545": '@vMirai_0831「嗯，是啊。」',
    "Script/scenario09_2.binu8@67800": '@vMirai_0832「我只是准备了剧本而已。真正出演的是你们。」',
    "Script/scenario09_2.binu8@68082": '@vFutaba_0940「……为什么不让自己登场？你应该也有一两个愿望才对。」',
    "Script/scenario09_2.binu8@68247": '@vMirai_0833「我登场过哦。折原京子，你不记得了吗？」',
    "Script/scenario09_2.binu8@68336": '@vFutaba_0941「记、记得……可是那是……」',
    "Script/scenario09_2.binu8@68440": '@vMirai_9003「那和所谓清纯少女可不一样。你想和哥哥结合的话，尽管随你便。我所祈求的，是除此之外的东西。」',
    "Script/scenario09_2.binu8@68752": '@vFutaba_0943「明明喜欢着他……为什么？我无法理解你的想法。」',
    "Script/scenario09_2.binu8@69290": '我还是无法理解。',
    "Script/scenario09_2.binu8@69343": '@vMirai_0836「双叶是个很有趣的孩子。你看，在这里挺起胸膛来？」',
    "Script/scenario09_2.binu8@69447": '@vFutaba_0946「你是在故意刺激我吗？」',
    "Script/scenario09_2.binu8@70273": '@vFutaba_0947「……那是不一样的。任何人都不能代替任何人。对环来说，妹妹只有你一个。」',
    "Script/scenario09_2.binu8@70438": '@vMirai_0840「是吗？只要存在‘妹妹’这种关系，换成谁不都一样吗……」',
    "Script/scenario09_2.binu8@70578": '@vMirai_0841「对了，双叶，我一直想问你一件事。」',
    "Script/scenario09_2.binu8@71111": '@vMirai_0843「可是，你对女装的环一见钟情了。这是无法推翻的事实。」',
    "Script/scenario09_2.binu8@71245": '@vFutaba_0951「所以知道他是男的之后我才幻灭了啊！！如果环是女孩子，我想我现在也还在喜欢他！」',
    "Script/scenario09_2.binu8@73755": '@vMirai_0848「真棒。」',
    "Script/scenario09_2.binu8@74255": '@vMirai_0851「什么‘啊’？你们即兴发挥得太过头，我的舞台都被搅得一团糟了。哥哥承认了现实，世界就会恢复原本的色彩。太好了，双叶。是你们赢了。」',
    "Script/scenario09_2.binu8@74560": '@vFutaba_0959「赢了……？折原小姐接下来会怎么样？」',
    "Script/scenario09_2.binu8@74683": '@vMirai_0852「还能怎么样，只会消失而已。我已经是这个世界上不存在的人了，只凭怨恨和诅咒徘徊至今……所以，我会坠入赫尔海姆。」',
    "Script/scenario09_2.binu8@75733": '@vFutaba_0962「哈！？你都做到创造出这样的世界了，最后就只想说这个吗！？」',
    "Script/scenario09_2.binu8@77802": '@vMirai_0861「我讨厌没有意义的事。我和哥哥的关系，就这样结束才是最美的。兄妹之爱以悲剧收场，这可是古典作品的规矩。」',
    "Script/scenario09_2.binu8@78032": '@vFutaba_0968「谁管你那些啊！？就用现代文化的优点狠狠反驳它！现在这个时代承认各种各样的个性！同性之爱也好，兄妹之爱也好，根本没有必要以悲剧收场……！」',
    "Script/scenario09_2.binu8@78454": '@vFutaba_0969「即便如此！即便如此……现在折原小姐就在这里……至少，让你们说一句话也好……」',
    "Script/scenario09_2.binu8@78792": '@vMirai_0863「会变得很残酷哦，可以吗？我觉得最后只会变成一场血淋淋的对话……」',
    "Script/scenario09_2.binu8@79212": '@vcs_Futaba_0005「吵架就吵架。你们两个明明应该更坦诚地交谈。本来应该是彼此最亲近的人……只是说得还不够。你们应该更加、更加地交心。」',
    "Script/scenario09_2.binu8@79658": '@vFutaba_0973「当然。既然要打碎，就彻底打碎，连一点痕迹都不留下。」',
    "Script/scenario09_2.binu8@79828": '@vFutaba_0974「这是你没有珍惜妹妹的惩罚。」',
    "Script/scenario09_2.binu8@80286": '@vMirai_0868「喂，双叶。」',
    "Script/scenario09_2.binu8@80625": '@vFutaba_0978「啊——原来是这种感觉啊。」',
    "Script/scenario09_2.binu8@81060": '@vMirai_0873「真是身不由己啊。」',
    "Script/scenario09_2.binu8@81545": '@vMirai_0876「……不过，你看起来会在那样的恋情中毁掉自己呢？」',
    "Script/scenario09_2.binu8@81634": '@vFutaba_0983「说好了不能提这件事。」',
    "Script/scenario09_2.binu8@81691": '@vMirai_0877「啊哈哈……那我也差不多该走了。」',
    "Script/scenario09_2.binu8@81768": '@vFutaba_0984「好。打人的时候要把重心压低，瞄准要害。」',
    "Script/scenario09_2.binu8@81876": '@vMirai_0878「谢谢你给我这么棒的建议。」',
    "Script/scenario09_2.binu8@82047": '@vMirai_0879「……哥哥就拜托你了。」',
    "Script/scenario09_2.binu8@82118": '@vFutaba_0985「我会在力所能及的范围内照顾他。毕竟我们是孽缘嘛。」',
    "Script/scenario09_2.binu8@82701": '不知从什么时候起，我察觉到那份萌发的感情就是恋爱。',
    "Script/scenario09_2.binu8@82855": '@vMirai_0881「哥哥。」',
    "Script/scenario09_2.binu8@83053": '@vMirai_0882「啊，是吗？原来我就是这样构成的啊。」',
    "Script/scenario09_2.binu8@83145": '如果从懂事起就是这样……那大概永远都不会改变吧。',
    "Script/scenario09_2.binu8@83403": '@vMirai_0884「从基因层面开始，我就被刻下了对你的爱。」',
    "Script/scenario09_2.binu8@84326": '啊，嗯，一定是这样吧。',
    "Script/scenario09_2.binu8@84373": '@vMirai_0888「被妹妹爱着的哥哥，当然会喜欢上妹妹。」',
    "Script/scenario09_2.binu8@84640": '@vMirai_0889「——‘你是妹妹吧？’这样的话，都写在你的脸上了。」',
    "Script/scenario09_2.binu8@84865": '@vMirai_0890「反正哥哥最终还是会喜欢上妹妹以外的某个人。」',
    "Script/scenario09_3.binu8@47868": '@vMinami_0037「啊啊，我可爱、可爱的未来！你真是个出色的演员！」',
    "Script/scenario09_3.binu8@48769": '「……妈、妈妈。」',
    "Script/scenario09_3.binu8@49103": '「才、才不是那样……！！」',
    "Script/scenario09_3.binu8@49203": '「我一直在努力啊。从《红房间》公演开始，我才真正觉得演戏很开心。所以，我会比以前更加努力……！」',
    "Script/scenario09_3.binu8@49739": '可即便如此，我依然相信哥哥。@n　相信他那时候说过的话。',
    "Script/scenario09_3.binu8@50090": '@vMirai_0678「这样就可以了吗，妈妈？」',
    "Script/scenario09_3.binu8@50508": '@vMinami_0045「你真的很擅长成熟的演技呢！什么时候增加了这么多表现手段？」',
    "Script/scenario09_3.binu8@50838": '@vMirai_0680「……哥哥？」',
    "Script/scenario09_3.binu8@51585": '「其实我早就知道了。我的出道，不过是妈妈靠人脉替我准备好的一把椅子，并不是凭实力夺来的。我因为偶然获得的评价而产生误会，就这样一路走到了今天。」',
    "Script/scenario09_3.binu8@51860": '被戏剧世界迷住的哥哥，不知从什么时候开始，渐渐厌恶起我来。',
    "Script/scenario09_3.binu8@52006": '「……我说，未来。我很羡慕你，羡慕到让人恨得牙痒痒……」',
    "Script/scenario09_3.binu8@52588": '@vMirai_0689「哥哥……」',
    "Script/scenario09_3.binu8@52682": '@vMirai_0690「哥哥……讨厌我吗？」',
    "Script/scenario09_3.binu8@52842": '「啊啊，讨厌。我讨厌你的才能、能力、演技、表现力，讨厌你的一切。太恨了，恨得我脑子都快不正常了。」',
    "Script/scenario09_3.binu8@53352": '@vMirai_0897「我明明只是想和哥哥一起，演出闪耀的戏剧。」',
    "Script/scenario09_3.binu8@53480": '如果那里没有哥哥……我又有什么努力的理由呢？',
    "Script/scenario09_3.binu8@53590": '@vMirai_0691「那我放弃好了。我不想为了不被哥哥讨厌而继续演戏。」',
    "Script/scenario09_3.binu8@53721": '那才是我的真心话。@n　可是，那是不能说出口的真心话。',
    "Script/scenario09_3.binu8@54530": '即使作为演员取得了多大的成功，只要那里没有哥哥，对我而言就毫无意义。',
    "Script/scenario09_3.binu8@54876": '「被我讨厌又有什么错？明明被才能所爱，却还想把它丢掉……那才是罪孽深重！别说什么‘因为不想被我讨厌’这种虚伪的理由！」',
    "Script/scenario09_3.binu8@55124": '@vMirai_0694「……哥哥真是个笨蛋。」',
    "Script/scenario09_3.binu8@55292": '@vMirai_0898「明明其实已经知道了，明明已经察觉到了。却不肯承认，难道是因为还想把自己当成一个常识人吗？」',
    "Script/scenario09_3.binu8@56096": '@vMirai_0698「不过，没关系。如果哥哥下不了决心，那就由我来告诉你。嗯，这样你会更开心吧？」',
    "Script/scenario09_3.binu8@56281": '「……住手，未来。」',
    "Script/scenario09_3.binu8@56762": '「不对，我不是那样。这不对。」',
    "Script/scenario09_3.binu8@56815": '@vMirai_0700「没关系，哥哥。这一定就是命运。兄妹从一开始就是这样构成的。只是那些坏大人罗列出方便自己的理由，否定了这一点而已。」',
    "Script/scenario09_3.binu8@57508": '「……看来你误会了。」',
    "Script/scenario09_3.binu8@57700": '「你要穷尽演戏这条道路。这是命令。」',
    "Script/scenario09_3.binu8@57877": '哥哥毫无疑问地●爱着我，可这明明是不容动摇的事实。',
    "Script/scenario09_3.binu8@57993": '「因为不想被我讨厌，所以要放弃演戏？别开玩笑了。我早就已经厌倦你的存在了。」',
    "Script/scenario09_3.binu8@58287": '「别抱着天真的想法，小鬼。你以为戏剧是什么？别在意那些无关紧要的事，别绕远路。」',
    "Script/scenario09_3.binu8@58472": '每当我出演某个角色，哥哥就会更加讨厌身为妹妹的我。',
    "Script/scenario09_3.binu8@58748": '「如果你想登上顶峰，就把一切都丢掉，抱着必死的觉悟去面对！你可是濑和未来，是这个家的招牌演员！」',
    "Script/scenario09_3.binu8@59054": '@vMirai_0704「可是，我……我想和哥哥……」',
    "Script/scenario09_3.binu8@59304": '「就算如此！我也最讨厌你！！」',
    "Script/scenario09_3.binu8@59927": '「我们只有演戏这一条路。就算你放弃当演员，又能得到什么？妈妈绝不会放过我们。」',
    "Script/scenario09_3.binu8@60179": '「我们是演员，是生来就注定要当演员的人。只能在这个世界活下去的我们，将不停寻找一个能够照到阳光的地方。」',
    "Script/scenario09_3.binu8@61326": '@vMirai_0714「……哥哥，你在发抖哦。因为做了不像自己的事，所以害怕了吧。」',
    "Script/scenario09_3.binu8@61596": '「啊啊，没错。很害怕，当然害怕！可是，我相信这样做对你有好处。」',
    "Script/scenario09_3.binu8@61789": '我希望你能够……离开哥哥，独自成长。',
    "Script/scenario09_3.binu8@61839": '@vMirai_0715「哥哥……」',
    "Script/scenario09_3.binu8@62275": '@vMirai_0775「初次见面，我叫折原冰狐。请大家多多关照。」',
    "Script/scenario09_3.binu8@62715": '@vaudienceA_0005「出现了个不得了的新人啊……！！」',
    "Script/scenario09_3.binu8@63583": '「……啊啊，真是一群混账东西。」',
    "Script/scenario09_3.binu8@63642": '哥哥的憎恨如雨般落在那纤细的背上。@n　不知为何，那道目光却让我感到无比舒畅。',
    "Script/scenario09_3.binu8@63846": '@vMirai_0899「……没关系，哥哥。我会好好做下去的。」',
    "Script/scenario09_3.binu8@63953": '啊啊，被我亲手杀死的才能，正在身后注视着我。',
    "Script/scenario09_3.binu8@64588": '@vMinami_0055「未来，你……没事吧？要不要休息一下……」',
    "Script/scenario09_3.binu8@64911": '@vMirai_0902「我不是未来，妈妈。我是折原冰狐。」',
    "Script/scenario09_3.binu8@65229": '@vMirai_0903「……疲惫没有消失。身体好沉。啊啊，可是，排练的时间……」',
    "Script/scenario09_3.binu8@65547": '@vMirai_0904「对了……是那个厌食症少女的角色。啊，感觉不错，已经瘦下来了……药，再增加一点……然后……」',
    "Script/scenario09_3.binu8@66400": '我不知道。@n　可是，也没有人会回答我。',
    "Script/scenario09_3.binu8@67159": '@vMirai_0909「呜呵呵呵呵呵呵呵呵呵呵呵呵呵呵呵呵」',
    "Script/scenario09_3.binu8@67437": '@vMirai_0910「卡里古拉。」',
    "Script/scenario09_3.binu8@68532": '@vMirai_0916「——妹妹与哥哥结合这件事。」',
    "Script/scenario09_3.binu8@68600": '把自己与伟大的过去杰作重叠起来，我自己也觉得愚蠢。',
    "Script/scenario09_3.binu8@69159": '@vMirai_0918「只有在舞台上，演员才能活下去。或许在那里，我能够战斗。」',
    "Script/scenario09_3.binu8@69483": '@vMirai_0919「呵、呵呵呵呵呵呵呵呵呵呵呵呵呵呵呵呵！」',
    "Script/scenario09_3.binu8@70020": '我感受着自己的卡里古拉在呼吸。@n　啊啊，连身体不适都能让我感到如此幸福。',
    "Script/scenario09_3.binu8@70171": '@vMirai_0921「……痛苦并不是永恒的。居然连这种事都没能察觉。」',
    "Script/scenario09_3.binu8@70514": '我竟然把那当成理所当然，真是愚蠢。',
    "Script/scenario09_3.binu8@71085": '对戏剧的憎恨、对哥哥的●情，明明全都是构成“我”这个存在的东西！',
    "Script/scenario09_3.binu8@72075": '@vMirai_0926「……必须好好演下去才行。」',
    "Script/scenario09_3.binu8@72231": '@vMirai_0927「……哥哥。」',
    "Script/scenario09_3.binu8@72331": '@vMirai_0928「我明白了。明白活在戏剧中的意义，也明白作为演员活着的意义。所以，你一定要来看……」',
    "Script/scenario09_3.binu8@73395": '@vMirai_0933「要诅咒这个世界，呼喊它的荒谬吗？」',
    "Script/scenario09_3.binu8@73877": '@vMirai_0936「我曾想和哥哥一起获得幸福。」',
    "Script/scenario09_3.binu8@73948": '@vMirai_0937「只能说，那是不可能实现的事。」',
    "Script/scenario09_2.binu8@75446": '@vcs_Mirai_0002「如果你指的是哥哥，那就不对了。我和哥哥在那一天已经决裂，把彼此的道路不会再交汇这件事刻进了心里。所以，事到如今，我没有必要再见哥哥……」',
    "Script/scenario09_2.binu8@75900": '@vFutaba_0963「他们明明相爱到快要发疯了啊！可即便如此，两个人还是没能结合，最后分开了！环因为无法接受这样的现实而绝望！现在也还在被后悔和痛苦折磨，仿佛快要死掉了！」',
    "Script/scenario09_2.binu8@82964": '即使努力回想，我也发现自己从一开始就爱着哥哥。',
    "Script/scenario09_2.binu8@83252": '@vMirai_0883「我爱哥哥，就像呼吸一样自然。」',
    "Script/scenario09_2.binu8@83332": '为什么其他兄妹之间不会萌生恋情呢？',
    "Script/scenario09_2.binu8@85290": '喜欢上那个喜欢自己的人。@n　无论对方是哥哥还是妹妹，都没有任何不同。',
    "Script/scenario09_2.binu8@85446": '「未来，我们一起成为出色的演员吧。」',
    "Script/scenario09_2.binu8@85517": '@vMirai_0609「嗯，是啊。为了妈妈，我们也要努力才行。」',
    "Script/scenario09_2.binu8@86127": '对无法演戏的我，铺天盖地的都是辱骂。',
    "Script/scenario09_2.binu8@86725": '@vMirai_0893「……哥哥。」',
    "Script/scenario09_2.binu8@86769": '母亲让我们兄妹彼此竞争。',
    "Script/scenario09_2.binu8@86926": '「未、未来……」',
    "Script/scenario09_2.binu8@87121": '「我、我……」',
    "Script/scenario09_2.binu8@87697": '如果我一直落魄下去，哥哥就会同情我。',
    "Script/scenario09_2.binu8@87801": '即使不是那样……他也不会对我抱有敌意。',
    "Script/scenario09_2.binu8@87899": '而且，无论如何，我都无法真心想让自己的演技变得更好。',
    "Script/scenario09_2.binu8@88107": '@vMinami_0054「真是个废物。今晚做好觉悟吧。我会彻底指导你的。」',
    "Script/scenario09_2.binu8@89201": '@vMirai_0896「……糟糕了。」',
    "Script/scenario09_2.binu8@89748": '「……那算什么。」',
    "Script/scenario09_2.binu8@90038": '「这不对吧……刚才那到底是什么？我问你那是什么……！！」',
    "Script/scenario09_2.binu8@90843": '@vMirai_0663「为什么？哥哥问了个奇怪的问题呢。很简单啊，因为没有必要把它展现出来。」',
    "Script/scenario09_2.binu8@91019": '「你说你没打算展示？那算什么？我根本不明白……！」',
    "Script/scenario09_2.binu8@92359": '「……因为我想和你一起……」',
    "Script/scenario09_2.binu8@92447": '「一起站在舞台上，演一出戏。」',
    "Script/scenario09_2.binu8@93455": '@vMirai_0669「那我会很开心。嗯，我也是……如果能和哥哥一起，说不定我也愿意试试看。和哥哥同台，一定会很有趣。」',
    "Script/scenario09_2.binu8@93958": '@vMirai_0670「嗯，会的。因为那是很重要的事。」',
    "Script/scenario09_2.binu8@94408": '「朗读得不错，未来。保持这个状态，再让我看看更多精彩绝伦的演技。」',
    "Script/scenario09_4.binu8@70833": '本来应该在这里结束的故事。',
    "Script/scenario09_4.binu8@71719": '诅咒着荒谬世界的演员小姐。@n　既然如此，从今天起，你就成为月亮吧。',
    "Script/scenario09_4.binu8@72040": '@vMirai_0961「祈愿就能实现，诅咒就能杀人，呼喊就能得到回应——一个如此方便的世界！」',
    "Script/scenario09_4.binu8@72209": '@vMirai_0962「来写吧！来画吧！来创造吧！来歌唱吧！来呐喊吧！」',
    "Script/scenario09_4.binu8@72351": '@vMirai_0963「向割舍了心意的哥哥复仇！向强迫我演戏的母亲定罪！向安然活着的凡人降下天罚！然后，向一直忍受悲剧的自己——给予救赎！」',
    "Script/scenario09_4.binu8@72955": '@vMirai_0966「月亮，本来就是无法得到的东西。」',
    "Script/scenario09_4.binu8@73234": '@vMirai_0968「哎呀，你还真擅长撒谎呢。不过，真的可以吗……？」',
    "Script/scenario09_4.binu8@74129": '@vMirai_0972「我只是完成了最棒的演出。没有理由被任何人指责。」',
    "Script/scenario09_4.binu8@74260": '@vMirai_0973「你根本什么都不明白。」',
    "Script/scenario09_4.binu8@74354": '@vMirai_0974「——那就是你的罪。是濑和未来引发的绝望，留下的伤痕。」',
    "Script/scenario09_4.binu8@74940": '@vMirai_0979「……怎么会这样。」',
    "Script/scenario09_4.binu8@75031": '@vMirai_0980「为什么？为什么会变成这样？我、我不是这个意思……！」',
    "Script/scenario09_4.binu8@75268": '@vMirai_0982「我终于找到了自己演技的顶点。我想把它展现出来……想得到哥哥的夸奖。我知道他可能无法理解，也知道他可能会生气……可是，那种像小孩子一样的心情，我就是无法压抑。」',
    "Script/scenario09_4.binu8@77670": '@vMirai_0993「其实啊……」',
    "Script/scenario09_4.binu8@77755": '@vMirai_0994「我想超越兄妹的界限，成为哥哥的恋人。」',
    "Script/scenario09_4.binu8@78224": '@vMirai_0998「——只是希望哥哥能够幸福。真的，就只是这样而已。」',
    "Script/scenario09_4.binu8@78900": '@vMirai_1002「我不需要戏剧才能，也不需要兄妹之爱。我……想出生在一个与哥哥毫无关系的世界。」',
    "Script/scenario09_4.binu8@79222": '@vMirai_1004「不是的。无论我是妹妹还是不是妹妹，我都喜欢哥哥。我不是因为自己是妹妹、你是哥哥，才喜欢上你的。」',
    "Script/scenario09_4.binu8@79454": '@vMirai_1006「如果我的存在会让哥哥变得不幸，那我就希望自己成为那样的人。然后，和哥哥成为普通的朋友……一直待在他身边。就像那个孩子一样……」',
    "Script/scenario09_4.binu8@80045": '@vMirai_1011「所以，如果要祈求一个方便的世界……我想放弃戏剧才能，忘掉对哥哥的感情，成为濑和未来以外的某个人。」',
    "Script/scenario09_4.binu8@80512": '@vMirai_1014「……那么，角色就决定了。梗概也差不多完成了。来吧，得把演员们从火焰中带出来才行。幸运的是，世上有很多因不幸而绝望的人。」',
    "Script/scenario09_4.binu8@81842": '@vMirai_1024「退回到这里。所以，无论如何都必须守护这个故事。演出中或许会有擅自即兴发挥的无赖……不过没关系。想要一个方便世界的人，还有很多。」',
    "Script/scenario09_4.binu8@82132": '@vMirai_1025「故事不是一个人就能编织出来的。正因为有大家的愿望，才能构筑出虚构。」',
    "Script/scenario09_4.binu8@83305": '无法用道理解释的怒火，在全身血管中奔涌。',
    "Script/scenario09_4.binu8@83670": '@vMirai_1035「啊啊，多么蛮不讲理的世界。难道我走错了该走的路吗？不，不是。说到底，我根本就没有未来！」',
    "Script/scenario09_4.binu8@84190": '@vMirai_1037「我最讨厌你，我最讨厌你，我最讨厌你……我最讨厌你这种人……！」',
    "Script/scenario09_4.binu8@84957": '@vMirai_1040「……说到底，最坏的人是你。明明要求我走上演戏这条路……却没有发自内心地支持我，也没有爱过我的演出！」',
    "Script/scenario09_4.binu8@85527": '@vMirai_1042「所以我才想要重生！想成为一个没有戏剧才能、没有兄妹之爱的普通少女！我的幸福终点，就是折原京子。」',
    "Script/scenario09_4.binu8@85991": '@vMirai_1044「没有被自卑折磨，也没有为兄妹之爱挣扎，只是享受着平静的日常。那才是让所有人幸福的唯一方法。可是……被你彻底毁掉了。」',
}

OVERRIDES.update({
    'Script/scenario03_3.binu8@79666': '@vMeguri_0266「时代拉开争斗的帷幕，被解放的洛基率领巨人族向众神发起复仇之战。战火吞噬了一切，世界也迎来终焉。这就是俗话所说的，诸神黄昏（Ragnarok）。」',
})

OVERRIDES.update({
    'Script/scenario05_7.binu8@74069': '@vMeguri_0707「今天没想喝伯爵茶。所以今天……」',
    'Script/scenario05_7.binu8@75803': '@vHana_0189「不过，只要是有趣的东西就行啦！」',
    'Script/scenario05_7.binu8@76202': '@vRize_0612「……大、大家都挺有经验的呢……」',
    'Script/scenario05_7.binu8@79586': '@vFutaba_0588「怎么了？」',
    'Script/scenario05_7.binu8@81035': '@vRize_0617「……为什么突然问我？」',
    'Script/scenario05_6.binu8@97934': '@vHana_0180「好耶～！濑和君的家，好期待啊～！啊，理世也会去的对吧？会一起来的对吧？」',
})

OVERRIDES.update({
    'Script/scenario05_6.binu8@80852': '@vMeguri_0661「那孩子明明很擅长照顾别人，一涉及自己的事就立刻什么都做不了了。而且还特别笨拙。要是让她拿菜刀，恐怕就得叫救护车了。」',
    'Script/scenario05_6.binu8@81184': '@vMeguri_0662「所以我偶尔会帮她打扫。你也多关照她一下吧。那孩子可是会以难以置信的速度把家里弄得一团糟。」',
    'Script/scenario05_6.binu8@86043': '@vMeguri_0680「……这三天……要是至少能给你带来片刻安宁就好了。」',
    'Script/scenario05_6.binu8@89372': '@vMeguri_0692「我出门了。亲爱的。」',
    'Script/scenario05_6.binu8@93145': '@vNanana_0323「……那你自己试着写写看，不就知道了吗？」',
    'Script/scenario05_6.binu8@94097': '@vNanana_0328「这就是衡量不幸的尺度。」',
    'Script/scenario05_6.binu8@94559': '@vNanana_0330「我是这个世界上第几不幸的人？」',
    'Script/scenario05_6.binu8@94302': '@vNanana_0329「所以，这不是什么创作活动。」',
    'Script/scenario05_6.binu8@95067': '@vNanana_0331「——《菲莉亚》。」',
    'Script/scenario05_6.binu8@95827': '@vHana_0175「距离正式公演已经不到二十天了，可服装制作完全来不及！所以！现在开始招募志愿者！这周末请大家牺牲休息时间来帮忙！」',
    'Script/scenario05_6.binu8@97934': '@vHana_0180「好耶～！濑和君的家，好期待啊～！啊，理世也会去的对吧？会一起来的对吧？」',
})

OVERRIDES.update({
    'Script/scenario05_8.binu8@64039': '@vRize_0625「花小姐……！」',
    'Script/scenario05_8.binu8@64435': '@vRize_0626「那、那个……是因为预算的关系……」',
    'Script/scenario05_8.binu8@70054': '@vFutaba_0602「哼哼哼～，可别小看偶像粉丝！」',
    'Script/scenario05_8.binu8@72719': '@vMeguri_0737「……留宿是上周末的事。不过，什么特别的事都没有。只是请他陪我留宿，练习演技而已。牙刷……是那时候忘在那里的。」',
    'Script/scenario05_8.binu8@73106': '@vMeguri_0738「当然没关系。」',
})

OVERRIDES.update({
    'Script/scenario05_9.binu8@93092': '@vMeguri_0775「是我不好。当时的我太蠢了。真是个笨女人……我怎么会是这么不知羞耻的女人呢。」',
    'Script/scenario05_9.binu8@93384': '@vMeguri_0776「……就像老师所说的那样。真相和正论本身没有意义，重要的是它们究竟意味着什么。」',
    'Script/scenario05_9.binu8@93581': '@vMeguri_0777「叫我匂宫。别随便叫我的名字。」',
    'Script/scenario05_9.binu8@96043': '@vRairai_0484「喂，巡，你可以回去了。从今天开始要停学了吧？就待在房间角落里，好好冷静一下。」',
})

OVERRIDES.update({
    'Script/scenario05_14.binu8@64744': '@vRize_0714「……我没有拯救别人的力量。虽然我能做的，只有待在那里而已。」',
    'Script/scenario05_14.binu8@65059': '@vMirai_0329「我希望我的王子殿下……就是理世小姐。」',
    'Script/scenario05_14.binu8@66621': '@vRize_0716「只能一心一意地演下去。」',
    'Script/scenario05_14.binu8@77817': '@vOmi_0044「我只是在拼命努力，想成为一个正确的人。我只是遵循自己的信念，认为那样做是为了大家好。若连这份信念都要后悔，反而是对自己犯下的过错的亵渎。」',
    'Script/scenario05_14.binu8@80077': '@vYuuen_0226「不是那样的。因为现在……我已经和这些能展现如此精彩演技的孩子们，一起完成了这场演出。」',
})

OVERRIDES.update({
    'Script/scenario05_12.binu8@74140': '@vRairai_0581「用你的双眼亲自确认，我的做法究竟对不对。」',
    'Script/scenario05_12.binu8@84528': '@vMeguri_0855「我们走吧。」',
    'Script/scenario05_12.binu8@84932': '@vMeguri_0856「……不费吹灰之力。」',
    'Script/scenario05_12.binu8@90595': '@vaudienceA_0000「这真的是学生能演出来的水平吗？」',
    'Script/scenario05_12.binu8@93611': '@vNanana_0384「啊，我真是个卑劣的人。」',
    'Script/scenario05_12.binu8@94193': '@vRairai_0589「——有一个适合你的角色。」',
    'Script/scenario05_12.binu8@94875': '@vNanana_0385「……我在想，他其实早就知道了。」',
    'Script/scenario05_12.binu8@98296': '@vNanana_0393「——因为换成别人也无所谓，换成我也一样，谁都可以。」',
})

OVERRIDES.update({
    'Script/scenario05_10.binu8@80548': '@vRairai_0504「不对！洛基不是神，是人！所谓人类，是更加邪恶、卑劣、无可救药的存在。别用这种片面的解读，就把他概括了！」',
    'Script/scenario05_10.binu8@85366': '@vRairai_0518「你不可能不明白吧。我就是这样……活了二十三年。」',
    'Script/scenario05_10.binu8@87397': '@vMeguri_0817「叫我匂宫，懂吗？别那么随便地叫我的名字。」',
})

OVERRIDES.update({
    'Script/scenario05_10.binu8@74733': '@vFutaba_0623「……阴沉鬼座长，请安静。女孩子可是柔弱的生物。正因为你这样，才会被叫作阴沉男。」',
    'Script/scenario05_10.binu8@76101': '@vFutaba_0626「略略略——！！」',
    'Script/scenario05_10.binu8@77172': '@vMeguri_0800「唔――！？」',
    'Script/scenario05_10.binu8@78925': '@vRairai_0501「都是因为你多管闲事，我们的公演才差点砸了。你也该给我好好认清这一点了。」',
})

OVERRIDES.update({
    'Script/scenario05_11.binu8@73114': '@vRairai_0546「喂喂，等等。一个除了卖弄色情就一无是处的普通女人，怎么可能被别的剧团挖走？哪有这种好事。」',
    'Script/scenario05_11.binu8@75190': '@vRairai_0551「可我不可能心甘情愿地接受。因为我曾真心渴望过……曾以成为演员为目标……所以直到最后，我都想相信自己。」',
    'Script/scenario05_11.binu8@76565': '@vRairai_0552「我做的是正确的事。没有实力的人，不该爬到更高的位置上。」',
    'Script/scenario05_11.binu8@76759': '@vRairai_0553「悠苑，你和我是同一边的人。这种事，交给天才去做就行了。」',
    'Script/scenario05_11.binu8@77696': '@vRairai_0555「这个世界确实很扭曲。不过，我会连这份扭曲也一并爱下去。」',
    'Script/scenario05_11.binu8@80684': '@vRairai_0560「――我知道这种手段。我过去一定见过。」',
    'Script/scenario05_11.binu8@81912': '@vRairai_0564「那老头子为什么要停手？死掉的学生怎么样都无所谓吧。那老头子可是把普通人拉了起来，创作出了不得了的戏剧。区区一点牺牲，有什么好在意的。」',
    'Script/scenario05_11.binu8@84238': '@vDirectorA_0000「你的才能真是出色。请务必来我们剧团吧？」',
})

OVERRIDES.update({
    'Script/scenario05_2.binu8@70015': '@vKohaku_0527「太暴力不行，但太温柔也不对。想起来，挖出来——找找你至今演过的相似角色。奥丁是什么样的人？他最像谁？」',
    'Script/scenario05_2.binu8@81092': '@vRize_0573「……嗯？」',
    'Script/scenario05_2.binu8@87752': '@vOmi_0016「如果要谈才华，你才是更优秀的那个。比来来优秀，比悠苑优秀，也比理世优秀。你……是被戏剧之神眷顾的人。」',
    'Script/scenario05_3.binu8@73822': '@vMeguri_0464「所以呢？这种无关紧要的小事有什么意义？在我看来，根本就是无聊透顶的小事，不是吗？」',
    'Script/scenario05_4.binu8@78798': '@vMeguri_0537「嗯？」',
    'Script/scenario05_7.binu8@74165': '@vOboro_0227「哦，居然有伯爵茶。匂宫小姐还真懂茶啊。」',
    'Script/scenario05_10.binu8@93459': '@vYuuen_0196「来、来来小姐，请冷静！一定只是玩笑而已！」',
    'Script/scenario05_11.binu8@78983': '@vYuuen_0205「你疯了。来来小姐什么时候变成这样了……！」',
    'Script/scenario05_11.binu8@86601': '@vDirectorA_0005「听说他讨厌天才，而比起天才，他更憎恨那些获得成功的普通人。所以他转行做了演出家，以演技指导为名，把那些人逼入精神绝境。说穿了，简直就是在恶意报复――」',
})

OVERRIDES.update({
    'Script/scenario05_1.binu8@75777': '@vRairai_0360「你还不够成熟，不足之处还有很多。别误会了……我说的不是演技。」',
    'Script/scenario05_1.binu8@75933': '@vRairai_0361「你是天才，这一点我早就知道了。问题在于，即使是天才，也未必能把这个角色演到底。」',
    'Script/scenario05_1.binu8@76622': '@vRairai_0364「先坐下吧。啊，对了……这肯定会是一段很长的谈话。」',
    'Script/scenario05_1.binu8@77494': '@vRairai_0367「你需要的东西，是绝望。只有看清这个世界的荒诞，你才能接近真实。真正理解……人类幸福究竟是什么。」',
    'Script/scenario05_1.binu8@78045': '@vRairai_0369「只要能激发演员的力量，我什么都愿意做。没错……我就是这样的人。」',
    'Script/scenario05_1.binu8@78737': '@vMeguri_0383「哎呀？我们现在不正是在为大家出力吗？」',
    'Script/scenario05_1.binu8@78848': '@vMeguri_0384「……能来帮我发传单吗？」',
    'Script/scenario05_1.binu8@90117': '@vNanana_0299「诶！？」',
    'Script/scenario05_4.binu8@62865': '@vMeguri_0485「是吗？」',
})

OVERRIDES.update({
    "Script/scenario07_2.binu8@77951": '@vMirai_0511「……你真的要回去吗？就算回到那里，天使也已经无处容身了哦？」',
    "Script/scenario07_2.binu8@78084": '@vNanana_0970「嗯，我知道。可是，我觉得不能一直逃下去。」',
    "Script/scenario07_2.binu8@78204": '@vMirai_0512「我不太明白呢。逃走真的有那么糟糕吗？那样不就等于否定了身处这个世界的所有人吗？」',
    "Script/scenario07_2.binu8@78410": '@vNanana_0971「……至少我和这里的人不一样。我甚至没有试着战斗，只是一味摆出受害者的样子。」',
    "Script/scenario07_2.binu8@78584": '@vMirai_0513「要去面对母亲，然后呢？那个人真正的想法，你应该也很清楚吧。」',
    "Script/scenario07_2.binu8@78954": '　她一脸兴味索然地移开了视线。',
    "Script/scenario07_2.binu8@79354": '　她拥抱着这份天真而率直的心意。',
    "Script/scenario07_2.binu8@79428": '@vNanana_0975「我和妈妈之间，只是一直缺少沟通。我们本该多谈一谈。当然，我不可能接受她做的一切，最后或许还是会分道扬镳……但如果不去面对，就什么都不会开始。」',
    "Script/scenario07_2.binu8@79758": '@vMirai_0516「你的继母在意的只有她的儿子，而不是你。对她来说，你的存在只要能成为那孩子的垫脚石就够了。」',
    "Script/scenario07_2.binu8@80024": '　我试着不只站在自己的立场上，也站在母亲的立场上想一想。',
    "Script/scenario07_2.binu8@80259": '@vNanana_0977「你收养我，已经十多年了。妈妈虽然说那是为了复仇……可在那段时间里，她真的、真的一直对我很好。我不能忘记这一点。」',
    "Script/scenario07_2.binu8@80532": '@vMirai_0517「那个露出慈爱面容的猎人，只有在要杀死猎物时，才会显露自己的本性。」',
    "Script/scenario07_2.binu8@80737": '@vNanana_0979「就算那份感情从一开始就是有所图谋……她也在十多年间，将某种近似爱的东西倾注给了我，疼爱着我。所以，我首先必须向她道谢。毕竟，抚养我长大、让我走到今天的人，正是我的母亲。」',
    "Script/scenario07_2.binu8@81067": '　一两个月的话，我还可以理解。@n　一年的话，或许也还能做到。',
    "Script/scenario07_2.binu8@81173": '　她把十年的岁月倾注在这样的我身上。@n　我不能无视母亲在那段岁月里的挣扎。',
    "Script/scenario07_2.binu8@81470": '@vNanana_0980「那我可不能原谅。就算是我，也会有真正生气的时候。」',
    "Script/scenario07_2.binu8@81589": '@vNanana_0981「——我要好好面对她，把积压在心里的话全部说出来。」',
    "Script/scenario07_2.binu8@81777": '　即使觉得那是哪里弄错了，我也从不指出，只是陪着笑，把一切都咽下去，当作没看见。',
    "Script/scenario07_2.binu8@81923": '　放弃与家人对话的，难道不正是我自己吗？',
    "Script/scenario07_2.binu8@82018": '@vNanana_0982a「这可是做好了断绝关系觉悟的争吵哦。」',
    "Script/scenario07_2.binu8@82076": '@vNanana_0982b「请放心！至于胆量……我已经在兰比里斯剧团里练出来了。」',
    "Script/scenario07_2.binu8@82197": '@vMirai_0519「……我才不担心呢。说到底，我一直只把天使当成一个称手的工具而已。」',
    "Script/scenario07_2.binu8@82370": '　少女稍稍垂下眼帘，露出悲伤的神色。',
    "Script/scenario07_2.binu8@83418": '@vNanana_0987「我们曾彼此憎恨、彼此厌恶、彼此蔑视。看着你们两个，我才想起，喜欢与讨厌之间的界线，原来只有一线之隔。」',
    "Script/scenario07_2.binu8@83983": '　两人的目光交错，想法也在此刻重合。',
    "Script/scenario07_2.binu8@84167": '@vNanana_0989「可偏偏还都觉得自己才是最可怜的那个，所以才最麻烦。」',
    "Script/scenario07_2.binu8@84552": '　临走前，她说道。',
    "Script/scenario07_2.binu8@84590": '@vMirai_0528「红莲火焰的另一侧，就是真相。这个世界里看到的东西，并不是真相的全部。」',
    "Script/scenario07_2.binu8@84721": '　她露出一抹淘气的笑容。',
    "Script/scenario07_2.binu8@84947": '　在意识逐渐模糊之际，我将她的话牢牢记在心里。',
    "Script/scenario07_2.binu8@85027": '　我隐约已经明白了。@n　早就觉得，事情应该就是这样。',
    "Script/scenario07_2.binu8@85124": '@vMirai_0530「……你还来得及重新开始。光是这一点，就已经比我强上好几倍了。」',
    "Script/scenario07_2.binu8@85283": '　又一幕故事，缓缓落下帷幕。',
    "Script/scenario07_2.binu8@85457": '@n　——引自《坎帕内拉》。',
    "Script/scenario07_2.binu8@85521": '　在频繁前往剧场的日子里，我感觉自己似乎终于找到了一个答案。',
    "Script/scenario07_2.binu8@85732": '　她如同一面映照内心的镜子，将潜藏在腹中的欲望原原本本地表现出来。',
    "Script/scenario07_2.binu8@86008": '　她没有所谓的内在。@n　空洞，虚无。',
    "Script/scenario07_2.binu8@86686": '@n　——够了，还是停下来吧。',
    "Script/scenario07_2.binu8@86902": '@n　——你以为自己找到了答案，就尽管自鸣得意吧。',
    "Script/scenario07_2.binu8@87111": '@n　——凭什么要让你这种人理解我。',
    "Script/scenario07_2.binu8@87337": '@vMeguri_1057「天气变得很热了呢。咖啡店的冰咖啡喝下去真舒服。」',
    "Script/scenario07_2.binu8@87617": '「我不太能喝冰的。……早知道就点冷茶了。」',
    "Script/scenario07_2.binu8@87727": '@vMeguri_1059「既然点了，可不许剩下哦。」',
    "Script/scenario07_2.binu8@87831": '　既然是我点的，就会好好喝到最后。',
    "Script/scenario07_2.binu8@88170": '@vMeguri_1061「她能不能作为演员派上用场，还很难说呢。演技只能算一般……不，或许还在平均水平之下。」',
    "Script/scenario07_2.binu8@88308": '「对期待着真正的她的你来说，应该是个意外吧。」',
})

OVERRIDES.update({
    "Script/scenario07_1.binu8@92299": '　呐，你知道吗，环君？@n　我们本来可以成为非常幸福的恋人。',
    "Script/scenario07_1.binu8@96213": '　面对她那样的生存方式……我也不由得被深深打动了。',
    "Script/scenario07_1.binu8@100183": '　只要变得更出色，只要出道，只要得到认可。',
    "Script/scenario07_1.binu8@104465": '　聚光灯熄灭了。@n　这场演出也即将迎来结束。',
    "Script/scenario07_1.binu8@104583": '@vMirai_0508「理世小姐……请活下去，获得幸福。然后，偶尔去冰狐的墓前祭拜，好吗？请告诉冰狐，你一直在继续演戏，也因此获得了幸福。」',
    "Script/scenario07_2.binu8@86550": '　没有感情，也没有热量。@n　停滞不动的情感波澜，就这样表现出了人生的幸福程度。',
    "Script/scenario07_2.binu8@102348": '　这种发霉的老旧思想，已经不适合这个时代了。',
    "Script/scenario07_6.binu8@76133": '「在那聚光灯灼热的另一边，究竟有什么呢？」',
    "Script/scenario07b_1.binu8@86496": '@vMeguri_1233「因为你一直记得，所以才会回应我，对吧？不然的话，仅仅听到‘喜欢的女孩子’这句话，你不可能联想到我的。」',
    "Script/scenario07b_1.binu8@88270": '@vMeguri_1241「要是你需要的话，我有哦。」',
    "Script/scenario07b_1.binu8@90495": '　有巡，有我。@n　幸福所需的条件，仅凭这些就已经满足了。',

    "Script/scenario08_1.binu8@84348": '@vOboro_0330「哈哈，真过分啊。人当然会感到寂寞、悲伤、怜悯，也会变得开朗。人也能爱上别人啊。」',
    "Script/scenario08_1.binu8@89895": '　那是如同随波摇曳般平静的回答。',
    "Script/scenario08_1.binu8@101435": '@vOboro_0360「可是，这是一种人为造出的感情，并不属于真正的我。」',
    "Script/scenario08_2.binu8@79157": '　京子露出闷闷不乐的表情。',
    "Script/scenario08_2.binu8@81169": '　那个男孩以夜空为背景嘲笑着。@n　他带着神秘的微笑，将悲伤的目光投向我。',
    "Script/scenario08_2.binu8@90433": '@vMirai_0618「谁知道呢？那是我今天读到的神话里，神明们做过的事。看起来，似乎是兄妹之间会做的事。」',
    "Script/scenario08_2.binu8@99459": '　只有得到母亲认可的那一方，才能结束今天。',
    "Script/scenario08b_4.binu8@67860": '　只要忘记、失去，然后消失……连悲伤的回忆也会一并消失，不是吗？',

    "Script/scenario07_6.binu8@61401": '　当时，身为斯巴达式指导化身的祖父很早就看中了我的才能，强行对我施以魔鬼般的训练。',
    "Script/scenario07_6.binu8@61756": '　面对祖父那不讲理的教育，我心中的憎恨压过了恐惧。',
    "Script/scenario07_6.binu8@67065": '　祖父像是要窥探我的内心深处一般说道。',
    "Script/scenario07_6.binu8@68510": '　祖父的话，深深刺入了我的心脏。',
    "Script/scenario07_6.binu8@76808": '@vMeguri_1183「……别说这个了。比起这些，我们得考虑下一场演出的题材。」',
    "Script/scenario07_6.binu8@84720": '　翻页声响起。@n　这段漫长、漫长的故事，终于迎来了终结。',

    "Script/scenario07_6.binu8@63047": '　当然，舆论开始抨击祖父，他也因此逐渐失去了在业界的立足之地。',
    "Script/scenario07_6.binu8@63312": '　起初还在逞强的祖父，我能清楚感受到他的心也随着时间流逝而逐渐崩溃。',
    "Script/scenario07_6.binu8@63849": '　亲戚们全都厌恶祖父，而祖父也从未向这份血缘关系寻求过什么。',
    "Script/scenario07_6.binu8@64004": '　对祖父而言，只要我这个存在还在身边，就已经足够了。',
    "Script/scenario07_6.binu8@64162": '　随着祖父的心逐渐衰弱，他对我的斯巴达式教育也慢慢停止了。',
    "Script/scenario07_6.binu8@65094": '　可即使祖父的支配有所松动，我也早已走到了无法回头的地步。',
    "Script/scenario07_6.binu8@67065": '　祖父像是要窥探我的内心深处一般说道。',
    "Script/scenario07_6.binu8@68510": '　祖父的话，深深刺入了我的心脏。',
    "Script/scenario07_6.binu8@70505": '@vMeguri_1161「祖父，你就是这样夺走我珍视的东西的吗？」',

    "Script/scenario07_3.binu8@60046": '@vMeguri_1099「真是祖父和天哥风格的宣传语呢。」',
    "Script/scenario07_4.binu8@68193": '　绝望压在我的背上。@n　面对已经断气的祖父遗体，我的身体一动也不能动。',
    "Script/scenario07_4.binu8@71390": '@vMeguri_1134「爷爷……」',
    "Script/scenario07_6.binu8@63047": '　当然，舆论开始抨击祖父，他也因此逐渐失去了在业界的立足之地。',
    "Script/scenario07_6.binu8@63668": '　没有任何人愿意替那个顽固又粗暴的祖父说话。',
    "Script/scenario07_6.binu8@63849": '　亲戚们全都厌恶祖父，而祖父也从未向这份血缘关系寻求过什么。',
    "Script/scenario07_6.binu8@64004": '　对祖父而言，只要我这个存在还在身边，就已经足够了。',
    "Script/scenario07_6.binu8@64162": '　随着祖父的心逐渐衰弱，他对我的斯巴达式教育也慢慢停止了。',
    "Script/scenario07_6.binu8@65094": '　可即使祖父的支配有所松动，我也早已走到了无法回头的地步。',

    "Script/scenario07_3.binu8@81127": '　这是一个无法反抗的局面。@n　事到如今，也只能接受这个无可奈何的现实。',
    "Script/scenario07_5.binu8@58442": '　我还有一件放心不下的事。@n　要是就这样放着不管，肯定会有人彻底崩溃。',
    "Script/scenario07b_2.binu8@71273": '　光是想到匂宫巡，我就被胸口仿佛要撕裂般的感情驱使着。',
    "Script/scenario09_4.binu8@72156": '　是我亲手把纸和笔交给了我自己。',
    "Script/scenario06_9.binu8@24558": '@vRize_1198「嗯，我觉得也没那么温柔啦……啊，到了。」',
    "Script/scenario06b_1.binu8@85537": '　他们误以为毫无欲望是一种高贵。@n　那副模样，就像一个正在抹杀自我的人偶。',
    "Script/scenario08_1.binu8@78652": '　没错，就是所谓的体罚。@n　虽然已经错得离谱了……但对我来说，那是令人舒适的疼痛。',
    "Script/scenario08_2.binu8@101922": '　那是一种奇妙的优越感。@n　仿佛自己站在压倒性的高处，像国王一样施舍他人。',
    "Script/scenario08_5.binu8@96695": '　我遮掩起丑陋的自己。@n　也在不知不觉间，迷失了那个高贵的自己。',

    "Script/scenario09_4.binu8@77850": '@vMirai_0995「——并不是这样。」',
    "Script/scenario09_4.binu8@78859": '　所以，我所祈求的是——。',
    "Script/scenario09_4.binu8@80441": '　同时，对我来说，那也是一种妨碍。',
    "Script/scenario09_4.binu8@83901": '　就连过去理所当然叫出口的那两个字，如今也无法摆脱违和感。',
    "Script/scenario09_4.binu8@84329": '　层层叠叠的面具，经历了漫长岁月。@n　这是那个为了成为演员而过度抹杀自我的少女，最终走到的结局。',
    "Script/scenario09_4.binu8@84910": '　未来用力地、用力地喊叫着。',
    "Script/scenario09_4.binu8@95065": '　一遍又一遍。@n　啊，那句话逐渐渗入了我的胸口。',
    "Script/scenario09_4.binu8@97030": '　眼角湿润，心中却燃烧着热度。@n　看着眼前冲天的火柱，我……自然而然地握紧了拳头。',
    "Script/scenario09_4.binu8@97766": '　啊，这种在胸口扩散开的感觉，究竟是什么呢。',
    "Script/scenario09_5.binu8@91995": '　腐朽的玫瑰逐渐凋零。@n　不曾吐出一句恶言，只是沉默地匍匐在地。',
    "Script/scenario09_5.binu8@92925": '　在逐渐模糊的意识中，我凝望着熊熊燃烧的火焰，思绪飘向那注定无可救赎的结局。',
    "Script/scenario09_5.binu8@98201": '　不，我应该知道这个。@n　我一定曾经好好品尝过它。',
    "Script/scenario09_5.binu8@104412": '　即使向神明喊出“请等一下”，悲伤也不会因此停下脚步。',

    "Script/scenario07b_1.binu8@98814": '　夕阳下的校舍，隐约散发着颓废的气息。',
    "Script/scenario07b_1.binu8@99150": '「从这里看到的景色，很美吗？」',
    "Script/scenario07b_1.binu8@99906": '@vMeguri_1280「话说回来，环还是处男吗？」',
    "Script/scenario07b_1.binu8@99969": '「……什么？」',
    "Script/scenario07b_1.binu8@102025": '@vMeguri_1289「你想在几岁之前夺走某人的初夜呢？」',
    "Script/scenario07b_1.binu8@102627": '「——噗！？」',
    "Script/scenario09_1.binu8@47387": '　明明随便应付一下就好，却没能想出合适的回应，只能继续手足无措。',
    "Script/scenario09_1.binu8@52120": '　我强忍着没有出声，却遭遇了此生最大的震惊。',
    "Script/scenario09_1.binu8@53235": '　只要脱去作为女孩子的外壳，哎呀，真不可思议。',
    "Script/scenario09_1.binu8@55271": '　没有感情，没有感动，也没有兴趣。@n　对我来说，所谓男人就是无关紧要的存在。',
    "Script/scenario09_1.binu8@58128": '　她保留着当时的风采，成为舞台上的明星，去了一个我再也无法触及的地方。',

    "Script/scenario07_5.binu8@57914": '@vRairai_0700「悠苑、白坂……你们可别误会了。」',
    "Script/scenario07_5.binu8@61901": '　我用力对架桥说道。',
    "Script/scenario07_5.binu8@68047": '　大量的信息，已经无法在脑中处理。',
    "Script/scenario07_5.binu8@70051": '　察觉到那份感情后，每一天看起来都染上了色彩。',
    "Script/scenario07_5.binu8@70740": '　正因为把后背交给绝望，我的表演才增添了真实感。',
    "Script/scenario07_5.binu8@70920": '　没有情绪，也没有氛围。@n　没有意义，悲惨而又无情地，被甩开了。',
    "Script/scenario07_5.binu8@71502": '　如果不把失恋的痛苦向谁发泄出来，我感觉自己就快要疯了。',
    "Script/scenario07_6.binu8@63199": '　那些至今还在吹捧匂宫王海的人，纷纷开始指责祖父。',
    "Script/scenario07_6.binu8@63312": '　起初还在逞强的祖父，我能清楚感受到他的心也随着时间流逝而逐渐崩溃。',
    "Script/scenario07_6.binu8@65377": '　心已经彻底崩溃的祖父，正试图背离“我”这个存在。',
    "Script/scenario07_6.binu8@70747": '　随后，《哈姆雷特》的演出拉开了帷幕。',
    "Script/scenario07_6.binu8@77330": '　这究竟是一场为了谁的菲莉亚演出？@n　这究竟是一场献给谁的菲莉亚演出？',
    "Script/scenario07_6.binu8@78244": '　世界出现了裂痕。',
    "Script/scenario07_6.binu8@78730": '　匂宫低下头。@n　他的视线在虚空中彷徨。',
    "Script/scenario07_6.binu8@79585": '　大家的心意，倾注进我的胸口。',
    "Script/scenario07_6.binu8@86473": '　火势加速蔓延。',
    "Script/scenario09_2.binu8@66598": '　我按住阵阵抽痛的太阳穴，在模糊的记忆中找出了真实的答案。',
    "Script/scenario09_2.binu8@72499": '　我被引导着、被掳走着，试着想象那个“如果”的世界。',
    "Script/scenario09_2.binu8@75847": '　愤怒的情绪不断沸腾、涌上心头。',
    "Script/scenario09_2.binu8@80369": '@vMirai_0869「……如果可以的话，希望你永远喜欢女孩子。」',
    "Script/scenario09_2.binu8@80524": '@vMirai_0870「这样一来……你看，我就能一直做哥哥的朋友了。」',
    "Script/scenario09_2.binu8@83489": '　这个世界实在太不完整了。@n　不了解妹妹这种生物的人，擅自构筑出了社会的常识。',
    "Script/scenario09_2.binu8@87994": '　对我来说，戏剧不过是用来与哥哥争斗的方法。',
    "Script/scenario09_2.binu8@88245": '　只要杀死自己的内心，就什么都不必害怕。',
    "Script/scenario09_2.binu8@92639": '　深深地、深深地刺入了我的胸口。@n　面对预想之外的甜蜜，我的大脑在一瞬间仿佛被摧毁了。',

    "Script/scenario09_3.binu8@50244": '　连手脚的指尖，都布满了纤细的感觉。',
    "Script/scenario09_3.binu8@50398": '　我已经能够有意识地、主动地，将“我”这一存在覆盖重写。',
    "Script/scenario09_3.binu8@50885": '　哥哥看向我的目光中，寄宿着憎恨的火焰。',
    "Script/scenario09_3.binu8@50974": '　即使说着“一起走吧”这样的甜言蜜语，现实也不会顺利得遂人心愿。',
    "Script/scenario09_3.binu8@53127": '　讨厌？我？为什么？不，这种事，我从一开始就已经明白了……。',
    "Script/scenario09_3.binu8@57099": '「别说傻话了，未来！」',
    "Script/scenario09_3.binu8@58570": '　我越是作为演员成长，心中的憎恨就越深。',
    "Script/scenario09_3.binu8@61880": '　悲伤溢满了双眼。',
    "Script/scenario09_3.binu8@62199": '　至于之后的故事，并没有什么特别的意义。',
    "Script/scenario09_3.binu8@63027": '　我甚至开始觉得，“濑和未来”这个人格……好像只是某个角色。',
    "Script/scenario09_3.binu8@64036": '　要是稍微偷懒、想着差不多就行了，那些家伙恐怕就会露出獠牙扑上来。',
    "Script/scenario09_3.binu8@65444": '　算了，什么都无所谓。@n　只要看一眼剧本，我就会想起自己被要求成为的模样。',
    "Script/scenario09_3.binu8@65723": '　如果真心想追求某样东西，我就做好了除此之外全部舍弃的觉悟。',
    "Script/scenario09_3.binu8@67475": '　这是终结的开始。',
    "Script/scenario09_3.binu8@69299": '　这个角色找上门来时，我竟然感受到了命运。',
    "Script/scenario09_3.binu8@71965": '　万物同等尊贵，万物同等如尘——这才是真实！',
    "Script/scenario09_3.binu8@72674": '　在暮色中发笑。',
    "Script/scenario09_3.binu8@73466": '　我要将一切矛盾背负在身，向你们展示我的生存方式。',
    "Script/scenario09_3.binu8@77169": '　月亮、爱，还有哥哥——。',
    "Script/scenario09_3.binu8@79542": '　感觉不到疼痛。@n　如果是疼痛，我早在很久以前就已经厌倦了！',
    "Script/scenario09_4.binu8@71406": '　饱受不幸折磨的少女们，用纸与笔展开复仇。',
    "Script/scenario09_4.binu8@71825": '　魔法使的制造方法。@n　那是悲剧、泪水，以及白发红眼的混合物。',
    "Script/scenario09_4.binu8@77906": '　那是第二个愿望。',
    "Script/scenario09_4.binu8@78729": '　亲眼看见那片火焰之海后。',
    "Script/scenario09_4.binu8@79995": '　我毫不犹豫地回答了。',
    "Script/scenario09_4.binu8@81202": '@vMirai_1017「谁知道呢？戏剧这种东西，无论何时都少不了意外嘛。」',
    "Script/scenario09_4.binu8@92515": '　让我清清楚楚地说出来吧。',
    "Script/scenario09_4.binu8@98334": '「我想救一个人。所以，双叶，你也要一起！」',
    "Script/scenario09_4.binu8@98405": '　灵魂在呐喊。',
    "Script/scenario09_5.binu8@80519": '　对母亲来说，那正是活着的意义。@n　然而……母亲同样也是受害者之一。',
    "Script/scenario09_5.binu8@80844": '　她担心那个被独自遗留在火焰包围的剧场里的继女。',
    "Script/scenario09_5.binu8@83377": '　瘫软的身体，连站起来的力气都不剩了。',
    "Script/scenario09_5.binu8@83472": '　太阳穴一阵阵抽痛，仿佛在宣告自己的存在。',
    "Script/scenario09_5.binu8@84543": '　我用力咬紧嘴唇。',
    "Script/scenario09_5.binu8@86432": '　我向身处另一边的某个人诉说。',
    "Script/scenario09_5.binu8@90272": '@n——想逃就逃吧。这是你的自由。',
    "Script/scenario09_5.binu8@91659": '　在那个不在的人的世界里，我究竟该把话传达给谁？',
    "Script/scenario09_5.binu8@92468": '　啊，这就是现实。@n　这是无法反抗、让我想移开视线的真相。',
    "Script/scenario09_5.binu8@92756": '　即使想使出力气，身体也纹丝不动。',
    "Script/scenario09_5.binu8@93386": '　我不由得流下了眼泪。',
    "Script/scenario09_5.binu8@93490": '　火焰吞噬了怒火，发出低沉的咆哮。',
    "Script/scenario09_5.binu8@93555": '　承载着世间一切的不合理，火焰冲天燃烧。',
    "Script/scenario09_5.binu8@95950": '　脖颈被猛地向后一拽，我的意识随之苏醒。',
    "Script/scenario09_5.binu8@97307": '　他温柔地说道。',
    "Script/scenario09_5.binu8@99356": '　话语自然而然地诞生了。',
    "Script/scenario09_5.binu8@99563": '　献给那朵已经枯萎、燃烧殆尽的心爱玫瑰。',
    "Script/scenario09_5.binu8@100007": '　我们曾经活着。@n　如今穿上学生制服，继续活在当下。',
    "Script/scenario09_5.binu8@100450": '　母亲握住我的手，含着泪向我忏悔。',
    "Script/scenario09_5.binu8@100536": '@vMika_0162「恨到连脑子都快要坏掉了。」',
    "Script/scenario09_5.binu8@101414": '　一边哭泣，一边竭力挤出声音。',
    "Script/scenario09_5.binu8@102614": '　可是，自那场火灾之后……我心中一直有种如同附身之物脱落般的感觉。',
    "Script/scenario09_5.binu8@103470": '　所以，冰狐……希望你能在那里守望着。',
    "Script/scenario09_5.binu8@104069": '　这句真切的话，意味着什么。',
    "Script/scenario09_5.binu8@104525": '　时间无情地流逝，转眼间便把我们抛在了身后。',
    "Script/scenario09_5.binu8@104785": '　笑容始终藏在暮色之中。',
    "Script/scenario09_5.binu8@106400": '@n——谢谢你教会那个孩子什么是爱。',
    "Script/scenario09_5.binu8@107821": '　我们约定过吗？@n　她强硬地拉起我的手，带我走向某处。',
    "Script/scenario09_5.binu8@108239": '　理世带着恶作剧般的语气说道。',
    "Script/scenario09_5.binu8@108479": '　被带去的地方是——。@n　啊，多么令人怀念，米拉剧场。',
    "Script/scenario09_5.binu8@110244": '@vMeguri_1784「……啊，真是的，真的……！」',
    "Script/scenario09_5.binu8@110528": '　好痛，好痛，好痛啊。@n　可是，大家的话语和心意，减轻了这份疼痛。',
    "Script/scenario09_5.binu8@111133": '　想起那些人时，难以用语言形容的感情便涌上心头。',
    "Script/scenario09_5.binu8@112779": '　灯光的辉芒告诉了我。@n　在耀眼的光芒中，我窥见了幸福。',
    "Script/scenario09_5.binu8@112882": '@vMeguri_1793「——剧团，卢佩尔卡里亚。」',
    "Script/scenario09_5.binu8@113348": '　看到少女身影的瞬间，巡的眼中燃起了热度。',
    "Script/scenario09_5.binu8@113529": '@vKohaku_1296「呐，巡姐姐，我有件事想拜托你。」',
    "Script/scenario09_5.binu8@113727": '　两人的视线交错。',
    "Script/scenario09_5.binu8@114174": '　然后，故事拉开了帷幕。',
    "Script/scenario09_5.binu8@114224": '　即使身上添满了伤口，少女的脚步依然没有停下。',

    "Script/scenario09_2.binu8@88648": '@vMirai_0895「因为如果不这样，哥哥就会讨厌我吧？」',
    "Script/scenario09_2.binu8@89040": '　究竟是因为妈妈教导得好，还是因为我拥有才能？无论愿不愿意，人终究都会改变。',
    "Script/scenario09_3.binu8@73028": '　那唯一一次，被●对待的那一天。@n　哥哥在我身上刻下●，而我眺望着耀眼光芒的彼岸。',
    # High-confidence full-game prose fixes, kept at the end so they win over
    # older duplicate entries above.
    "Script/scenario01_10.binu8@92606": '@vfutaba_0258「——那个，环。我之所以想演戏、想加入剧团，是因为想以戏剧为生。我不是为了暴露真实的自己才来到这里的。」',
    "Script/scenario05_13.binu8@75885": '　我不知道这场如暴走列车般疾驰的戏剧，最终会迎来怎样的结局。',
    "Script/scenario06_4.binu8@79743": '@vMirai_0475「不是。理世小姐不喜欢戏剧。所以我觉得，我应该能和理世小姐成为朋友。」',
    "Script/scenario06_4.binu8@80866": '@vMirai_0479「那是特殊的演出。因为那是一场让人得到满足的戏剧，所以才会那样。但下一次就不一样了。奇迹不会接连发生两次。」',
    "Script/scenario06_9.binu8@26885": '「……真是一场不可思议的戏剧啊。」',
    "Script/scenario06b_1.binu8@79745": '@vNanana_0421「妈、妈妈说，现在这种有活力、积极主动的孩子更好……」',
    "Script/scenario07_1.binu8@98199": '@vRize_1405「原来冰狐也讨厌戏剧啊。她已经厌倦了表演……所以才会对我产生兴趣。因为我们是相似的人……我还曾抱着这种微不足道的期待。」',
    "Script/scenario07_2.binu8@94483": '@vMirai_0536「果然我也想试着演戏啊。就算演得不好也没关系吧？谁都是从不擅长开始的嘛。」',
    "Script/scenario08_2.binu8@102162": '　我究竟是从什么时候开始，内心变得扭曲的？@n　我的妹妹又还能保持纯真到什么时候呢……',
    "Script/scenario09_2.binu8@88785": '　我始终没能喜欢上演戏。@n　我开始越来越讨厌戏剧了。',
    "Script/scenario09_5.binu8@97746": '　又要来了吗？@n　不过，这个“又”究竟是什么时候呢。',
    "Script/scenario08_5.binu8@97746": '　又要来了吗？@n　不过，这个“又”究竟是什么时候呢。',
    "Script/scenario04_7.binu8@50385": '@vRairai_0355「啧，别得意忘形。我们的演剧，从这里才要开始呢。」',
    "Script/scenario05_10.binu8@92648": '@vRairai_0531「……先不说这个，喂，老头！别打瞌睡了！下一场演剧演什么？差不多该定下来了吧！」',
    "Script/scenario05_11.binu8@97613": '@vKohaku_0605「啊，太好了，太好了。刚才差点因为巡酱，弄砸了我们的演出呢。」',
    "Script/scenario05_12.binu8@73916": '@vRairai_0580「……给我牢牢记在视网膜上。今天这场演出，会成为你一生的养分。无论好坏，全都刻进心里。」',
    "Script/scenario05_12.binu8@78083": '@vMirai_0364「我并不觉得人们嘈杂的声音令人厌烦。也许是这座回声剧场让我产生了这种感觉吧。这里真是个不可思议的地方。」',
    "Script/scenario06b_1.binu8@81784": '@vMeguri_0943「如果想要更进一步，就需要新的战力。幸好演出的评价相当不错，那么下一场公演才是真正的较量。」',
    "Script/scenario08_1.binu8@79737": '@vOmi_0109「蠢货！谁跟你说演戏的事了！？」',
    "Script/scenario08_4.binu8@60441": '　她那愈发骇人的疯狂演技，不知不觉间令周围的演员心生畏惧；说得难听些，常常演成了只顾自己发挥的独角戏。',
    "Script/scenario08_5.binu8@99640": '　白发赤眼的魔法师。@n　啊，原来如此……我……想再看一次她的演出了……',
    "Script/scenario08b_2.binu8@89105": '@vKohaku_0213「啊，那真是场既可怕又快乐的游戏。想出精妙诡计时的喜悦，大概足以与艺术家相提并论；而执行诡计时那种兴奋又紧张的感觉……」',
    "Script/scenario09_5.binu8@109838": '@vNanana_1040「是的！我正在把匂宫王海老师的遗作改编成适合演出的剧本！那个，嗯……标题应该是——」',
    "Script/scenario02_4.binu8@62534": '　如果不能彻底看清现实、自己、才能以及本性……就不可能成为什么样的人。',
    "Script/scenario02_4.binu8@68107": '「兰比利斯剧团，目标是成为怎样的剧团呢？」',
    "Script/scenario02_8.binu8@60117": '「——我正在寻找天使奈奈菜。」',
    "Script/scenario03_4.binu8@77788": '　“菲莉亚”。@n　这是一个被名为北欧神话的故事玩弄于股掌之间的王神的故事。',
    "Script/scenario05_13.binu8@62478": '　过着平凡的生活，被平凡地爱着。@n　作为一个平凡的家庭，平凡地——',
    "Script/scenario06b_2.binu8@81719": '　一个恰到好处地听话、能够顺着我心意行事的妹妹。',
    "Script/scenario06b_5.binu8@23981": '@vNanana_0714「我是说，《暴风雨》的故事……」',
    "Script/scenario07_3.binu8@85516": '　啊啊，多么丑陋的女人啊。',
    "Script/scenario07_4.binu8@73400": '　那具纤细的身体一动不动。@n　她的心，已经被眼前如地狱般的景象彻底击溃。',
    "Script/scenario07_6.binu8@62751": '　真是彻头彻尾的不合时宜。@n　他确实是个无可救药的祖父。',
    "Script/scenario07b_1.binu8@98909": '　从窗外传来的棒球部呐喊声，令人心头一阵紧缩。',
    "Script/scenario07b_4.binu8@62830": '「请、请冷静！我是认真的，真的！我是真心爱着巡的！」',
    "Script/scenario07b_4.binu8@67247": '@vRairai_0771「……你、你是在开玩笑吧？」',
    "Script/scenario07b_5.binu8@51924": '@vMeguri_1703「一种虚假的、永恒不变的爱情。」',
    "Script/scenario08_2.binu8@99923": '@vMinami_0024「……到此为止。今天是环赢了。这已经是连胜多少场了？未来怎么就一直进步不起来呢？」',
    "Script/scenario08_3.binu8@54817": '@n　——您那成熟得不像孩子的演技，给人留下了深刻印象。请您坦率谈谈对《红色房间》公演的感想。',
    "Script/scenario08_3.binu8@86785": '@vMirai_0695「其实你明明知道，也早就察觉到了。却不肯承认……难道是因为你自以为是个讲常识的人吗？」',
    "Script/scenario08b_5.binu8@40368": '「……不行，不行啊。」',
    "Script/scenario08b_5.binu8@40412": '　我啊。@n　和你不一样……无论是说谎，还是演戏……都很不擅长。',
    "Script/scenario01_9.binu8@68307": '　我是个再普通不过的女孩。@n　外貌并不出众，没有什么耀眼的特长，也没有为了梦想努力的意志。',
    "Script/scenario04_5.binu8@74285": '　而且，那还是我第一次失恋。',
    "Script/scenario05_6.binu8@82054": '@vMeguri_0665「不只是演戏。我作为一个人，也同样很优秀。现在你明白了吧。」',
    "Script/scenario05_9.binu8@78832": '@vRairai_0465「教架桥演戏的时候，我就会不由自主地想起：我究竟是个什么样的人。我啊……总是在犯错。」',
    "Script/scenario06_1.binu8@91069": '「……那可是能铭记一生的感动。好好品味吧。」',
    "Script/scenario06_1.binu8@100726": '@vRize_0732「……过去我从没演过这种仿佛会迷失自我的戏。这种感觉，这种前方等待着我的感受……一定就是真正的实感吧。」',
    "Script/scenario06_10.binu8@63499": '　因为我想要的不是只有我们两人的世界……而是一个所有人都在欢笑的世界。',
    "Script/scenario06b_3.binu8@91746": '　真是副怎么看都伤眼的模样。',
    "Script/scenario07b_1.binu8@91431": '@vRize_1458「我正在揭开伤疤。看，新长出来的痂正四处徘徊，渴求着呼吸。」',
    "Script/scenario08b_2.binu8@84677": '　嗯，对，是啊。@n　我是不知挫折为何物的前天才童星。',
    "Script/scenario09_1.binu8@61375": '「……唉，真是个怪女人。我也不用再装模作样了。」',
    "Script/scenario09_3.binu8@79636": '　我。@n　我、我、我——！！',
    "Script/scenario04_6.binu8@69048": '　可是，我做不到。@n　因为我是个非常软弱的人。',
    "Script/scenario05_12.binu8@93234": '@vNanana_0383「我是个卑鄙的女人。」',
    "Script/scenario06_10.binu8@52290": '　这是一个只有幸福、平凡得不能再平凡的恋人故事。',
    "Script/scenario07_1.binu8@108030": '　然而，我绝没有被她的演技打动。',
    "Script/scenario07_1.binu8@109086": '　即使看着她的演技，我也没有感到一丝感动。',
    "Script/scenario07_2.binu8@84774": '@vMirai_0529「因为这里是虚构的世界，是由你那丑陋的受害者意识创造出来的虚假世界。」',
    "Script/scenario07_4.binu8@55447": '@vYuuen_0271「这里是演员生涯走到尽头的人最终漂泊到的地方。我们心灰意冷、失去了骄傲……如果还能帮助到其他人，我觉得那就是一件很美好的事。」',
    "Script/scenario08_4.binu8@69567": '　动摇让我的言行变得语无伦次。@n　我不由得想照字面接受那份心意……却被她接下来的话，彻底击碎了内心。',
    "Script/scenario08b_1.binu8@75166": '「真是个让人难过的反击……」',
    "Script/scenario08b_1.binu8@81231": '　那是完全出乎意料的反应。',
})

OVERRIDES.update({
    "Script/scenario07_4.binu8@60064": '@vRairai_0666「老头……你也和我一样，有着同样的心情吧。」',
    "Script/scenario07_4.binu8@60157": '　你也因为无法理解而感到困惑，对吧？',
    "Script/scenario07_4.binu8@60222": '　可即便如此，你已经感受到此刻的舒适，所以接受了这样也无妨。',
    "Script/scenario09_4.binu8@82360": '@vMirai_1027「――我可是天才女演员折原冰狐哦？在舞台上，我就是最强的。」',
    "Script/scenario09_4.binu8@82473": '@vMirai_1028「啊哈。」',
    "Script/scenario09_4.binu8@82505": '@vMirai_1029「呵呵。」',
})

OVERRIDES.update({
    "Script/scenario09_4.binu8@69978": '　折原冰狐作为演员而生，作为演员而死。@n　那就是我找出的、能在这个世界获得幸福的方法。',
    "Script/scenario09_4.binu8@70362": '　不过，没关系。@n　这个世界本就充满不合理……反正总有一天，连这份感情也会褪色。',
    "Script/scenario09_4.binu8@70504": '　虽然没能作为普通少女活下去，@n　但即便如此……我想，我也算是获得了属于自己的幸福。',
    "Script/scenario09_4.binu8@72584": '@vMirai_0964「还是把最初的感情夺回来吧！回到那一天重新来过，这次选择兄妹之爱，而不是演剧！这里存在着无限的可能性！」',
    "Script/scenario09_4.binu8@73477": '@vMirai_0969「你看，在你死去的时候，重要的人们正在燃烧哦？这样真的好吗……？真的好吗？再这样下去，大家都会死的……」',
    "Script/scenario09_4.binu8@74764": '@vMirai_0978「……啊，你看。哥哥没有逃走。明明大家都在避难……啊啊，火焰，还有柱子，都倒下来了……」',
    "Script/scenario09_4.binu8@75609": '@vMirai_0983「演戏并不快乐，对吧。演剧总是让我感到孤独。但是，未来啊，不爱演剧的人，不可能演出打动人心的戏。我直到骨髓都是演员。所以，你也希望迎来那样的结局，对吧？」',
    "Script/scenario09_4.binu8@75947": '@vMirai_0984「可那却让我的一切都失去了理智。这是无可否认的事实。」',
    "Script/scenario09_4.binu8@77947": '@vMirai_0996「月亮是无法得到之物。不合理正是为了维持秩序而存在。所以，妹妹不能和哥哥结合。这就是这个世界的法则。」',
    "Script/scenario09_4.binu8@86272": '@vMirai_1045「做梦有什么错！你凭什么断言逃进虚构就是错误！别想用单一的尺子衡量幸福的模样。如果你无法理解……就不要否定我！」',
    "Script/scenario09_4.binu8@91375": '「寻求不变的，不只是你。必须接受改变的，也不只是你。」',
    "Script/scenario09_4.binu8@91521": '「什么叫最棒的演剧。要是你把年岁增长视为退化，那你还远远没有抵达最棒的境界。」',
    "Script/scenario09_4.binu8@95513": '@vMirai_1070「那真是一段不幸的人生。回首望去，几乎没有什么好事……只有痛苦不断向我袭来。」',
    "Script/scenario09_4.binu8@97574": '　就在刚才我发呆的位置上方，天花板掉了下来。@n　如果没有双叶的声音，我毫无疑问会被压在下面。',
    "Script/scenario09_5.binu8@80110": '　我曾满心期待复仇的时刻即将到来……却没有察觉到那根植于心底的一丝扭曲。',
    "Script/scenario09_5.binu8@80374": '　我曾希望她过上悲惨的人生。@n　即使有人正确指出少女并没有罪，我也一直选择视而不见。',
    "Script/scenario09_5.binu8@83903": '　如果受了伤，就再也当不了偶像了。@n　即使侥幸保住性命，只要留下烧伤痕迹，也就无可挽回。',
    "Script/scenario09_5.binu8@85247": '　即使悲惨，即使羞耻，即使必须拼命挣扎。@n　我也要抛开所谓可爱，一直挣扎到死。',
    "Script/scenario09_5.binu8@86628": '　理世小姐紧紧抱住我。@n　她用力地一遍又一遍鼓励我，说着“没事的”。',
    "Script/scenario09_5.binu8@87867": '　这是一个火灾从未发生的时间轴。@n　这样的假想故事，甜美得仿佛快要融化，又带着令人沉醉的美感。',
    "Script/scenario09_5.binu8@88968": '@vMeguri_1737「我每天都在哭。哇哇大哭。只要那个顽固老头拿着剧本走过来，我就会尖叫着反抗。」',
    "Script/scenario09_5.binu8@91793": '　因为这份幸福并不完整，所以我才会醒来。@n　我真正渴望的东西，再也不会出现在我面前。',
    "Script/scenario09_5.binu8@93187": '　再一点点……再一点点，我就能逃离包裹着我的痛苦，以及仿佛要将心撕裂的悲伤。',
    "Script/scenario09_5.binu8@97479": '「不要半途而废地抛下故事。既然是演员，就演到最后给我看。只有活下去，才称得上是演员吧？」',
    "Script/scenario09_5.binu8@98833": '　嘴唇正在说着某句台词。@n　那句本应充满悲伤的台词，不知为何却显得无比可爱。',
    "Script/scenario09_5.binu8@98981": '@vMeguri_1762「即便如此，我也不会憎恨你。那天你给予我的温柔……无论怎样的暴力，都无法将它摧毁。」',
    "Script/scenario09_5.binu8@99832": '　那场最恶劣的火灾曾引发轩然大波，但随着新学年的开始，日常生活仍拉开了帷幕。',
    "Script/scenario09_5.binu8@102941": '　即使是现在，我恐怕也只是自以为已经理解了。@n　就算在自己心中找到了答案，也没有任何方法去确认它。',
    "Script/scenario09_5.binu8@106627": '　之后，那名女性向我讲述了一段悲惨的身世。@n　那是发生在我懂事以前、十多年之前的故事。',
    "Script/scenario09_5.binu8@109146": '@vRize_1492「……让我们从这里重新开始吧。将王海小姐留下的一切重新连接起来，振翅飞向新的可能性。」',
    "Script/scenario09_5.binu8@112488": '@vMeguri_1792「我爱着大家。我爱着演剧。所以，没关系。我会说，没关系！在这个故事的前方，有大家在。只要我继续做演员……我们还会再次相遇！」',
})

OVERRIDES.update({
    "Script/scenario09_2.binu8@75146": '@vFutaba_0961「我不懂那些复杂的事。但我至少明白，折原同学也曾有过自己的愿望。可为什么站在你面前的是我！？你本来应该想和另一个人对峙才对！」',
    "Script/scenario09_2.binu8@76230": '@vFutaba_0964「可是！连一句话都没说就消失，我绝对不会原谅！事到如今，别想逃跑啊！！」',
    "Script/scenario09_2.binu8@76844": '@vcs_Mirai_0003「要是一个满怀留恋的哥哥，面对久违出现的妹妹而产生动摇，你打算怎么办？啊啊，真麻烦，真麻烦。这种事我可不接受。」',
    "Script/scenario09_2.binu8@77220": '@vFutaba_0966「啊——！！你这人脑子太死板了！这种地方还真像环呢！」',
    "Script/scenario09_2.binu8@79503": '@vMirai_0864「……我可以给你留下心理创伤吗？恐怕我会不停地说出恶毒的话，直到你再也无法振作。」',
    "Script/scenario09_2.binu8@81202": '@vMirai_0875「难道我没能成为你的恋爱对象吗？我一直很在意这一点呢。」',
    "Script/scenario09_2.binu8@83634": '@vMirai_0885「生物必须适应环境。纯白而透明的我，立刻为自己创造出了一副面具。」',
    "Script/scenario09_2.binu8@84978": '　喜欢上某人，被甩，再喜欢上另一个人，相互结合，又分开，然后再喜欢上另一个人。',
    "Script/scenario09_2.binu8@85878": '@vMinami_0052「为什么，为什么，为什么！你为什么到现在还演不好！？啊啊，未来，未来，未来！！你明明应该拥有和我相似的才能才对！」',
    "Script/scenario09_2.binu8@89345": '　如果我和哥哥之间的力量关系发生逆转，毫无疑问会有不好的事情发生。',
    "Script/scenario09_2.binu8@89594": '　我把自己习得的演技用来保护自身。@n　啊啊，这真是多么讽刺的人生啊……',
    "Script/scenario09_2.binu8@91647": '「如果你能随心所欲地发挥现在的演技，就能成为出色的演员。别把梦想寄托在‘普通’这种无聊的东西上。既然拥有那份才能，就像我一样认真演剧吧！！」',
    "Script/scenario09_2.binu8@94038": '　就在这一刻，我的人生发生了巨大的改变。@n　只要哥哥需要我，无论哪里我都愿意去。',
    "Script/scenario09_3.binu8@48101": '@vMinami_0038「你终于醒过来了！我这些日子拼命教导你，总算没有白费！」',
    "Script/scenario09_3.binu8@49595": '@vMinami_0041「别再找借口了！正因为你努力得不够，才会输给未来吧！？」',
    "Script/scenario09_3.binu8@49906": '　我只是反复咀嚼那句话，凝视着前方。@n　我曾幻想着，如果是哥哥，他一定会追逐着我的背影。',
    "Script/scenario09_3.binu8@51072": '「……每一天，每一天，只要看到你的演技，我的内心就会发出刺耳的刮擦声，一点点被磨损。我们至今积累的一切，都在归于虚无。」',
    "Script/scenario09_3.binu8@51278": '「那个狼狈的我一直在问：为什么当时要推未来一把？可不是那样的。无论你在不在……我迟早都会遭遇同样的结局。」',
    "Script/scenario09_3.binu8@54180": '「别像决定菜单一样轻易决定放弃！！这种事，我绝对不允许！」',
    "Script/scenario09_3.binu8@60518": '「就算你爱着我，就算我爱着你，这份感情也一定会在你的演员生涯中留下巨大的伤痕。我们是兄妹。要想作为演员出人头地……彼此之间绝不能存在家庭之爱以外的感情。」',
    "Script/scenario09_3.binu8@61109": '「所以，那是绝不该存在的感情。你必须斩断这份思念，成为最出色的演员。」',
    "Script/scenario09_3.binu8@63140": '@vaudienceA_0006「她是那个濑和环的妹妹？妹妹反而是真正的天才吗……！！」',
    "Script/scenario09_3.binu8@63263": '　无能的哥哥很快就被冷落。@n　对我这个作品来说，他越是悲惨，就越适合作为垫脚石。',
    "Script/scenario09_3.binu8@64289": '　不成功就没有意义。@n　束缚着我的无数锁链，缠住四肢，怎么也不肯松开。',
    "Script/scenario09_3.binu8@68701": '　我不是那种能在世上留下痕迹的人，也没有像卡利古拉那样与不合理抗争的意志和行动力。',
    "Script/scenario09_3.binu8@69649": '　有时手捧辞典研读原文，有时搜寻各种解读，有时还参考现场演剧。',
    "Script/scenario09_3.binu8@70299": '　无论身处哪个时刻，所有感情都是平等的。@n　随着时间流逝，一切都会褪色，变得面目全非。',
    "Script/scenario09_3.binu8@73185": '@vMirai_0932「每当看见光，就会想起那一天。也会意识到，那一点幸福，以及被强加在身上的锁链有多么沉重。」',
    "Script/scenario09_3.binu8@74380": '　啊啊，所谓演员这种生物，究竟是多么罪孽深重。@n　明明我是如此任性自私的人，如今却仍满怀着对终焉的期待。',
    "Script/scenario09_3.binu8@75061": '　脚下摇摇晃晃，站都站不稳。@n　这是药物的缘故，还是最近身体不适造成的？',
    "Script/scenario09_3.binu8@76223": '@vMirai_0947「在这个没有任何人无罪的世界里，明明连审判者都不存在，又有谁能宣判我有罪！」',
    "Script/scenario09_3.binu8@76510": '　手脚自行活动，迸发出一句句台词。@n　刻进身体的动作，如流水般自然地涌现。',
    "Script/scenario09_3.binu8@78786": '　所以至少，我想找出成为演员的意义。@n　找出我所追求、我想成为的那种真正的演剧。',
})

OVERRIDES.update({
    "Script/scenario08b_4.binu8@65001": '@vKohaku_1183「既然吵过架，那就和好不就好了吗？这种事，小学生每天都在重复吧。」',
    "Script/scenario08b_4.binu8@67973": '「对她来说，救赎或许就是明白：即使感到孤独，也不必因此死去。这个认识终有一天会拯救她的内心。」',
    "Script/scenario08b_4.binu8@68962": '　我已经无法再与她对视。@n　离开这家店后，我们恐怕就会把一切都忘掉吧。',
    "Script/scenario08b_5.binu8@38840": '「……我曾经很幸福，很快乐，也过得很充实。可人生不会总是如愿，所以我逃走了。仅此而已。」',
    "Script/scenario08b_5.binu8@39604": '「我喜欢你，我是真的喜欢你……！不，不对，这份感情……没有任何怀疑的余地！所以，我才会和你……」',
    "Script/scenario08b_5.binu8@39911": '「啊啊，我对你做了什么……！！不，不对……我明明知道，也明明理解，可还是做了……这一切都是清醒时做的，我其实……」',
    "Script/scenario08b_5.binu8@42392": '@vKohaku_1203「所以，环同学也请继续演戏吧？让我们的双人剧，永远延续下去。」',
    "Script/scenario08b_5.binu8@43951": '@vKohaku_1280「只是因为太耀眼，所以才看不见。无论时间如何流逝，月亮始终都在那里。」',
    "Script/scenario08b_5.binu8@44346": '　我们被盛夏的直射阳光炙烤，汗流浃背。@n　却连汗水也无暇擦拭，只是平静地接受了这个结局。',
    "Script/scenario09_1.binu8@40303": '　我并非始终使用同一副面具，而是像切换开关一样不断更换各种面具，宛如被追赶的罪人般隐藏着真心。',
    "Script/scenario09_1.binu8@40628": '　这并不只是长大成人后的问题。即使在小小的社群，也就是小学或中学里，它同样作为一种心照不宣的共识，牢牢扎根着。',
    "Script/scenario09_1.binu8@42890": '　如果她毫不客气地扑上来，我的意识就会被卷入混乱的漩涡，只能对柔软肌肤的触感不知所措。',
    "Script/scenario09_1.binu8@44663": '　从那以后，我开始找各种借口，一次又一次地前往那座公园，只为了见到那个少女。',
    "Script/scenario09_1.binu8@47129": '　她的问题并没有什么深意。@n　只是因为我没听明白，所以才又问了一遍。',
    "Script/scenario09_1.binu8@48095": '　那几乎已经等同于说出了答案……可我却像开关被打开一样，戴上了面具。',
    "Script/scenario09_1.binu8@49116": '　你凭什么用一副什么都知道的口气说话。@n　有谁会允许一个为同性恋而苦恼的孩子呢。',
    "Script/scenario09_1.binu8@49726": '@vMirai_0807「我很可爱，像天使一样，对吧？所以我才想知道。我还是第一次遇见喜欢女孩子的女孩子。」',
    "Script/scenario09_1.binu8@52571": '@vFutaba_0900「班上确实有些男孩子长得像女孩子！！可、可是总得有个限度吧！！？」',
    "Script/scenario09_1.binu8@53004": '　月光下闪耀的美少女……竟然伸手抓住自己的头发，无情地将它剥了下来。',
    "Script/scenario09_1.binu8@53565": '@vFutaba_0901「你、你真坏……！明明知道答案，居然还问这种问题！」',
    "Script/scenario09_1.binu8@55398": '@vFutaba_0907「就像仰望天空时偶尔飞过的麻雀，又或是匍匐在地上的蚂蚁那样，原本与自己毫无关系的东西。可要被要求去喜欢它，那究竟是多么痛苦的一件事。」',
    "Script/scenario09_2.binu8@68866": '@vMirai_0834「是吗？其他人我就不知道了……但如果是双叶酱，她一定能理解。」',
    "Script/scenario09_2.binu8@69000": '@vFutaba_0944「如果是我？为什么？其实，我并不算聪明哦？」',
    "Script/scenario09_2.binu8@69652": '@vMirai_0838「我和你们不一样。我无法理解那些渴望爱情的人。想和喜欢的人在一起？想牵手？想接吻？想结合？啊啊，我没有打算否定这些……可那种事，去他的吧。」',
    "Script/scenario09_2.binu8@71419": '@vMirai_0844「你看，果然如此。到头来，你也被关系束缚着。和我、和哥哥一样。」',
    "Script/scenario09_2.binu8@71607": '@vMirai_0845「如果我是女孩子，我就会一直爱着你……那不就等于在说我喜欢哥哥吗？我爱慕着哥哥的性格与存在。只除了我们性别不同这一点……」',
    "Script/scenario09_2.binu8@72579": '　我喜欢环，喜欢他……要牵手？接吻……不、等等，再往上就……啊啊啊啊啊啊啊啊啊！',
    "Script/scenario09_2.binu8@73852": '@vMirai_0849「嗯，我明白。明白，明白得不得了。双叶酱果然和我想的一样。你就是芬里尔啊，吞噬我的狼先生。」',
    "Script/scenario09_2.binu8@74082": '@vMirai_0850「有双叶酱在的话，我就放心了。那我先走了，剩下的交给你。」',
})

OVERRIDES.update({
    "Script/scenario07b_1.binu8@101786": '@vMeguri_1288「呵呵，我没有别的意思。只是想请你把它当作闲聊来回答。环，你想在几年之内尽情享用女性的身体？」',
    "Script/scenario07b_1.binu8@102741": '　我知道她是在取笑我。@n　可即便如此，我还是会下意识地做出那种反应。',
    "Script/scenario07b_2.binu8@65853": '@vNanana_0994「我在数从这里能看见的悲剧。一、二、三、四……咦，我刚才数到几个来着？」',
    "Script/scenario07b_2.binu8@66670": '@vNanana_0998「看得见或看不见都一样。那个方向存在不幸，这一点是不会错的！」',
    "Script/scenario07b_2.binu8@67446": '@vNanana_1002「不幸是由甜味构成的。所以女孩子才最喜欢甜食。咕嘟咕嘟，吧唧吧唧，甜甜的……由不幸制成的糖果女孩。」',
    "Script/scenario07b_2.binu8@77149": '@vMeguri_1335「如果拒绝变化……在这种有限的状况下，就没有必要推进彼此的关系。」',
    "Script/scenario07b_2.binu8@77293": '@vMeguri_1336「因为不是这样吗？反正时间已经被固定，也受到空洞支柱的守护。不必追求特殊关系，只要现在能够延续下去，就已经足够了。」',
    "Script/scenario07b_2.binu8@78289": '　无论贪心与否，那里面都没有任何意义。@n　既然如此，就去屈服于人类无底的欲望吧。',
    "Script/scenario07b_2.binu8@79025": '　阴影笼罩下来。@n　我的嘴因此被封住，再也无法继续编织接下来的话语。',
    "Script/scenario07b_2.binu8@79514": '@vMeguri_1344「真正重要的，是我爱着你，而你也爱着我。竟然想给这样的关系取个名字……你还真是个不解风情的人啊。」',
    "Script/scenario07b_2.binu8@80169": '@vMeguri_1346「还是说，如果不把我留在恋人的框架里，你就连继续爱我都做不到吗？」',
    "Script/scenario07b_2.binu8@82542": '@vMeguri_1355「饥饿本身才是重要的。肚子填饱了，就没法期待下一次了，对吧？」',
    "Script/scenario07b_2.binu8@83083": '　看过接吻后的表情，就显而易见了。@n　托你的福，我安心了许多。',
    "Script/scenario07b_2.binu8@84077": '@vHana_0283「王海小姐还有别的工作要做。她应该很快就会追上来。毕竟这里正走在通往天上的道路上，说不定迟早会再次相遇呢。」',
    "Script/scenario07b_2.binu8@85489": '@vRairai_0733「我梦见那个老头了。那个即使面对无可救药的混账小鬼的我们，也没有抛弃，反而把我们捡回去的老混账。我啊，没错……一直想再见他一面。」',
    "Script/scenario07b_2.binu8@86357": '@vMeguri_1361「不可能的。祖父就在这里。所以，我们一起去找他吧？」',
    "Script/scenario07b_3.binu8@24795": '@vMeguri_1376「如果真是这样，那我还没有醒来。这里也可能仍在梦的途中。」',
    "Script/scenario07b_3.binu8@25410": '@vMeguri_1380「某处的某个人曾写道，万事万物都有意义，所有行动也必然有答案。那么，你要如何理解我吻你这件事呢？那个吻究竟意味着什么？」',
    "Script/scenario07b_3.binu8@29452": '　将彼此的欲望交织在一起，化作无底的爱意。@n　这略显粗暴的触碰，作为我们的初次接触，成了幸福的养分。',
    "Script/scenario07b_4.binu8@65214": '@vMeguri_1513「我接到悠的联络赶过来，结果竟然是……婆媳游戏？你的兴趣还真是恶劣呢。」',
    "Script/scenario07b_4.binu8@72545": '@vHana_0288「呐，呐，巡酱。那两个人到底要到什么时候才会交往啊？」',
    "Script/scenario07b_4.binu8@76064": '@vHana_0298「那副模样简直就是恋爱中的少女呢！啊——既然喜欢得那么深，直接告白不就好了吗！」',
    "Script/scenario07b_5.binu8@42214": '@vYuuen_0320「她比以前爱笑多了。别看那孩子平时那样，她好像真的很喜欢濑和同学。只要和你在一起，就总是一个劲儿地聊你的事呢。」',
    "Script/scenario07b_5.binu8@42506": '@vYuuen_0321「呵呵，被可爱女友意外的一面打动了？今后也别忘了这份新鲜感哦。」',
    "Script/scenario07b_5.binu8@45640": '@vMeguri_1597「不过，今天的公演本来就是面向情侣的……到处都洋溢着暧昧的气氛吧？」',
    "Script/scenario07b_5.binu8@53055": '@vMeguri_1708「我发自内心地爱着你。无论今后还是过去，你都是我此生唯一的伴侣。」',
})

OVERRIDES.update({
    "Script/scenario07b_2.binu8@67867": '@vNanana_1003「纷纷扰扰，蠢蠢欲动，被甜味吸引而来。为了吞食甜味而来。那也会孕育新的不幸。所以我数着它们，把它们收集起来，试着去爱抚……在银河的一隅守望着它们。」',
    "Script/scenario07b_2.binu8@69882": '@vNanana_1010「我本来是为了寻找理想才来到这里……可最后，我只能数着不幸。」',
    "Script/scenario07b_4.binu8@65715": '@vRairai_0763「话说回来，悠那家伙……居然把这事告密给巡……！那家伙难道就不担心巡吗……？」',
    "Script/scenario07b_4.binu8@76064": '@vHana_0298「那副模样简直就是恋爱中的少女呢！啊——既然喜欢得那么深，直接告白不就好了吗！」',
    "Script/scenario07b_5.binu8@40402": '　团员们离开之后。@n　确认只剩下我们两人，我才慢慢开口。',
})

OVERRIDES.update({
    "Script/scenario07_3.binu8@68953": '　直到不久前，我还以演员的身份待在这里。@n　可那时的我忘记了笑容，给大家添了不少麻烦。',
    "Script/scenario07_3.binu8@72585": '　那天正好是来来小姐不在的时候。@n　现在回想起来，或许正是下手的好时机吧。',
    "Script/scenario07_3.binu8@73572": '@vDirectorB_0004「大概吧。像这样交谈，就能了解你的内在。」',
    "Script/scenario07_3.binu8@78097": '@vDirectorB_0016「没什么夸张的，也不是什么大不了的事。这不过是场游戏。只要把自己交给我，一切都会顺利。世间万物本来就是这样运转的。」',
    "Script/scenario07_3.binu8@80952": '　面对那粗暴的对待，我甚至没法发出一句不满。@n　只能拼命忍住眼泪。',
    "Script/scenario07_3.binu8@83062": '　幸好，来来小姐醉得相当厉害。@n　随便找个借口糊弄过去，应该很容易。',
    "Script/scenario07_3.binu8@84590": '@vRairai_0647「……啧，真麻烦。喂，悠苑，你总不至于醉倒吧？嫌麻烦，你就自己回去。」',
    "Script/scenario07_3.binu8@86079": '　明明差一点就能抓住机会，却眼睁睁看着所有希望被击得粉碎。',
    "Script/scenario07_4.binu8@49622": '　我被巡那精神十足的声音唤回意识。@n　虽然并没有睡着，却仿佛神游到了遥远的地方。',
    "Script/scenario07_4.binu8@49907": '@vRize_1453「请大家在总结上次公演经验的同时，为下一次公演继续日复一日地磨炼自己。」',
    "Script/scenario07_4.binu8@55447": '@vYuuen_0271「这里是已经结束演员生涯的人最终漂泊到的地方。若是心碎、失去骄傲的我们……还能帮助到其他人，那将是一件很美好的事。」',
    "Script/scenario07_4.binu8@60941": '@vYuuen_0280「不是……巡和理世小姐还在参加期末考试。她们实在脱不开身，说等考完之后再来……」',
    "Script/scenario07_4.binu8@65245": '　火焰仿佛要将剧场吞噬般熊熊燃烧。发现火灾十五分钟后消防队赶到时，现场已经惨不忍睹，根本无从下手。',
    "Script/scenario07_4.binu8@65513": '　据当时的受害者说，火灾发生时观众席陷入了恐慌；在火焰与烟雾逼近的危险中，大家仍拼命展开救援。',
    "Script/scenario07_4.binu8@65895": '　此外，起火地点被认定为存放设备的储藏室，但起火时周围并没有足以引燃的物品，原因至今仍不明。',
    "Script/scenario07_4.binu8@66748": '　有人喊出了我的名字。@n　我回头的同时，木制柱子被熊熊烈火包裹着倒塌下来。',
    "Script/scenario07_4.binu8@66887": '　一瞬间的迟疑，一瞬间的困惑，再一次将我的思绪拖进阴沉而空虚的世界。',
    "Script/scenario07_4.binu8@67418": '　痛苦、悲鸣，以及临终的惨叫。@n　所谓人生，就是突然被迫面对终结，然后被残酷地夺走一切。',
    "Script/scenario07_4.binu8@68409": '　无人使用的储藏小屋起火了。@n　我们全神贯注于舞台，发现得实在太晚。',
    "Script/scenario07_4.binu8@70665": '　啊啊，多么猝不及防的结局。@n　悲剧没有预兆，也没有前兆，就这样不讲道理地降临。',
    "Script/scenario07_5.binu8@60705": '　为了《菲莉亚》的公演，进行个人指导。@n　他为我准备的不是技术指导，而是一段往事。',
    "Script/scenario07_5.binu8@65356": '　那个为了洛基的名誉而舍弃一切的暴君。@n　直到生命的最后一刻，我都相信那是为了守护他的骄傲。',
    "Script/scenario07_5.binu8@65516": '@vYuuen_0290「那个人虽然这么说，但我还是认为，我们的愿望确实反映在这个世界里。」',
    "Script/scenario07_5.binu8@67165": '@vKohaku_0764「……我不这么认为。因为我很珍惜自己。换作是我站在相反的位置，恐怕也会希望一切不要改变。就这样和大家在一起……那样对我来说才是幸福。」',
    "Script/scenario07_5.binu8@67829": '@vYuuen_0296「没关系。去找出你心中认定的答案吧。因为我和来来小姐说出的，也都建立在不确定的虚构之上。」',
    "Script/scenario07_5.binu8@73534": '@vRairai_0723「我害怕把自己放在第一位。所以我才会说出强硬的话。不管是傲慢、任性，还是暴君……我只能相信这是为了大家好，然后一头走下去。」',
    "Script/scenario07_5.binu8@73855": '@vRairai_0724「没错。都已经到了高潮前，不能停下演技。既然是演员，就必须在舞台上战斗到最后。」',
    "Script/scenario07_5.binu8@74056": '　温柔渗入我的体内。@n　痛苦、悲伤、慈爱……啊，是如玻璃般纤细的东西。',
    "Script/scenario07_5.binu8@76518": '@vKohaku_0789「我知道聚光灯有多耀眼，也记得舞台的气味。明明只要待在这里……就应该能感受到大家才对。」',
})

OVERRIDES.update({
    "Script/scenario07_2.binu8@88945": '@vMeguri_1064「不是那个意思……而且，那个人选也不是我提的。」',
    "Script/scenario07_2.binu8@92026": '@vMeguri_1078「你是觉得，不认真做就没有意义吧。完全不知收敛的戏剧笨蛋。要是我当时真的坏掉了，你打算怎么办？」',
    "Script/scenario07_2.binu8@92476": '@vMeguri_1079「……呵呵。这也是因为生来就是天才，必须经历的试炼吗？」',
    "Script/scenario07_2.binu8@95061": '　这一定是我内心的软弱。@n　扶住快要倒下的身体，迈出坚定的一步。',
    "Script/scenario07_2.binu8@96804": '@vKohaku_0733「是的。直到现在，那时的感觉仍残留在我心里。演出结束后，自己体内仿佛还住着另一个人。真是不可思议。」',
    "Script/scenario07_2.binu8@98315": '@vKohaku_0738「你应该也已经察觉到了。这个世界非常空虚，正处于极不稳定的状态。眼睛所看到的，并不一定就是真实。」',
    "Script/scenario07_2.binu8@99982": '「……我早就察觉到有些不对劲。那感觉就像指尖的一点毒素，正一点一点地扩散。可我一直视而不见，因为我想相信一切都很正常……」',
    "Script/scenario07_2.binu8@101121": '　满口恶言，态度恶劣，毫无礼貌。@n　演技虽然还过得去，却远远不足以弥补这些缺点。',
    "Script/scenario07_2.binu8@103217": '@vRairai_0620「呸，老头子的说教我已经听腻了。事到如今，已经不可能再打动我的心了。」',
    "Script/scenario07_2.binu8@103663": '@vYuuen_0233「是的。因为我是个笨拙又愚蠢的女人，若不在那个人身边，我就无法作为演员活下去。」',
    "Script/scenario07_2.binu8@103925": '@vOmi_0053「这样啊。既然你是以演员的身份留在这里，那我就没什么好说的了。随你便吧。」',
    "Script/scenario07_3.binu8@57459": '@vRize_1429「这个剧团没有你期待的那么有价值哦？如果你想成名，还有更出色的剧团……我可以介绍给你。」',
    "Script/scenario07_3.binu8@58694": '@vMeguri_1096「名气什么的无所谓。我只演自己想演的东西。既不想成名，也不想把名字留在后世。」',
    "Script/scenario07_3.binu8@58904": '@vRize_1432「你之所以能说出这种话，是因为你拥有实力吧。可那些没有才能的人，明明渴望它渴望得不得了……」',
    "Script/scenario07_3.binu8@62357": '@vRize_1442「过头了就是过头了。现在没出问题，不代表以后不会出问题。」',
    "Script/scenario07_3.binu8@63712": '　之后，她通过不断在周围拉拢盟友，制造出让人无法反抗的局面，强行让剧团承认她入团。',
    "Script/scenario07_3.binu8@63959": '@vRairai_0622「既然本人想做，就让她随便做好了。结果会变成什么样，关我屁事。」',
    "Script/scenario07_3.binu8@64136": '　成员们各有鲜明个性。@n　他们不理会周围的声音，一心钻研自己想做的事。',
    "Script/scenario07_3.binu8@64787": '　右手边这位，是最近加入的匂宫巡小姐。@n　听说她是座长王海小姐的孙女，因此备受大家关注！',
})

OVERRIDES.update({
    "Script/scenario07_4.binu8@59763": '@vRairai_0665「……之前还那么激动，真是可笑啊。」',
    "Script/scenario07_4.binu8@59841": '　如今，这里已经以巡为中心，变成了一群戏剧笨蛋的聚集地。',
    "Script/scenario07_4.binu8@59930": '　虽然争执几乎每天都会发生，但大家心里想的都只有一件事：怎样才能让演剧变得更好。',
})

OVERRIDES.update({
    "Script/scenario06_2.binu8@82928": '　实在无法面对那种事。',
    "Script/scenario07_2.binu8@94834": '「……我不能永远这样消沉下去。」',
    "Script/scenario07_3.binu8@55837": '　无论作为剧团还是作为娱乐作品，都无法否认这是一次失败。',
    "Script/scenario07_4.binu8@57755": '@vRairai_0658「……杂鱼只能抱团取暖、合力抗敌。不过，就算是这样的杂鱼，也应该能创作出有趣的演剧。」',
    "Script/scenario07_4.binu8@59314": '　那不过是卖不出去时找的借口。@n　明明曾经的我，还把这种说法当成笑话。',
    "Script/scenario07_4.binu8@72379": '　即使狼狈挣扎，我也什么都实现不了。',
    "Script/scenario07_6.binu8@70081": '@vOmi_0101「现在的你对剧团兰比利斯来说已经没有必要了……所以，我只能解雇你。」',
    "Script/scenario07_6.binu8@82337": '　我觉得你已经不能继续留在这里了。@n　否则，我没脸去面对天乐座长。',
})

OVERRIDES.update({
    "Script/scenario07_2.binu8@91563": '　即使是天乐座长带给她的痛苦，匂宫巡也会一并接受。',
    "Script/scenario07_3.binu8@66578": '@vRairai_0625「――闭嘴，巡。喂，悠苑，这种事你就不能自己动脑子想想吗？」',
    "Script/scenario07_4.binu8@52596": '　自从匂宫巡加入后，她一边展现出作为演员的模范姿态，一边也为我们带来了笑容。',
    "Script/scenario07_5.binu8@72286": '　他太过相信匂宫巡了。@n　也太过相信自己消失之后的未来了。',
    "Script/scenario07_5.binu8@72580": '　就算我们不在了，匂宫巡也能一个人活下去吗？',
    "Script/scenario07b_2.binu8@70561": '　巡似乎想说些什么。@n　但我立刻将她拉到身边。',
    "Script/scenario07b_4.binu8@60507": '「你说巡？」',
    "Script/scenario07b_4.binu8@63744": '@vRairai_0755「我知道你也不是个坏家伙。你是巡信任的为数不多的男人之一。至少你没有轻率地和她交往，这点我认可。就这样继续保持纯洁的交往吧。」',
    "Script/scenario07b_4.binu8@71467": '　我转身背对天乐座长，牵起了她的手。',
})

OVERRIDES.update({
    "Script/scenario07b_2.binu8@73479": '「……说起来，天乐座长和龙木前辈在交往吗？」',
})

OVERRIDES.update({
    "Script/scenario01_8.binu8@72385": '@vrairai_0073「啊，是这样。不过我改变主意了。有问题吗？」',
    "Script/scenario01_10.binu8@98153": '@n　我用视线毫不留情地打断了双叶那声“请什么都别说”的请求。',
    "Script/scenario03_6.binu8@78357": '　王海小姐直截了当地说，单纯只是因为我的实力还不够。',
})

OVERRIDES.update({
    "Script/scenario05_14.binu8@81171": '@vMeguri_0917「你――无论到什么时候，都是对我来说最重要的@r义@か@@r兄@ぞ@@r弟@く@だ！」',
})

OVERRIDES.update({
    "Script/scenario05_14.binu8@81171": '@vMeguri_0917「你――无论到什么时候，都是对我来说最重要的@r义@か@@r兄@ぞ@@r弟@く@だ！」',
})

OVERRIDES.update({
    "Script/scenario01_7.binu8@85820": '「……所以，我们正在寻找愿意协助幕后工作的成员。」',
    "Script/scenario02_1.binu8@69290": '@vyuuen_0013「――就这样，今年我们迎来了三位新成员。大家打起精神，好好努力吧。」',
    "Script/scenario02_5.binu8@63705": '@vhana_0077「――情况就是这样。虽然现在举行试胆大会还早了些，不过怎么样！我们一起去寻找怪奇谈的真相吧！」',
    "Script/scenario04_4.binu8@92014": '@vHana_0157「――于是，天真烂漫的白坂花酱，就这样成为了一名迷人的幕后工作人员！」',
    "Script/scenario05_9.binu8@94200": '@vMeguri_0780「……事情的经过就是这样。真的很抱歉。」',
    "Script/scenario08_5.binu8@93007": '@vKohaku_0873「可是，世事就是如此。我们本来就是被人这样利用的存在。」',
})

OVERRIDES.update({
    "Script/scenario04_7.binu8@48636": '　座长提高了声音。',
    "Script/scenario05_1.binu8@99981": '　排练室里，座长的怒骂声此起彼伏。',
    "Script/scenario05_11.binu8@97784": '@vKohaku_0606「――这都是座长的功劳。你要好好向她道谢哦？」',
    "Script/scenario05_12.binu8@73641": '　接下来的统筹工作，将由身为舞台监督的座长和身为幕后负责人白坂小姐共同负责。',
    "Script/scenario05_4.binu8@76440": '　即便如此，座长仍说道。',
    "Script/scenario05_7.binu8@74022": '　胧笑眯眯地捅了捅灌木丛。',
    "Script/scenario05_7.binu8@92011": '「胧，你也这么认为吗？看起来他也在用自己的方式不断摸索。今后应该还会越来越成熟吧。」',
    "Script/scenario05_8.binu8@83279": '@vMirai_0346「……人心竟是如此不可思议。」',
    "Script/scenario05_9.binu8@95134": '　座长毫不留情的话语。',
    "Script/scenario06_1.binu8@84387": '　胧所指的方向上，琥珀正呆呆地愣在那里。',
    "Script/scenario06_2.binu8@92584": '@vOboro_0278「座长让我转告你。明天放学后，大家在佩特里科尔集合。」',
    "Script/scenario06_4.binu8@87385": '@vKohaku_0721「我想，我是为了大家而演的。正因如此，才能坚持到最后。座长一定也是一样。」',
    "Script/scenario06b_1.binu8@70973": '@vMeguri_0933「我绝不会因为成功了就说‘太好了’……所以，我无法原谅座长。」',
    "Script/scenario06b_1.binu8@71165": '　褪去了锋芒的座长，显得十分平静。',
    "Script/scenario06b_2.binu8@72132": '@vFutaba_0663「是天使酱带来的效果！演出刚结束那会儿，客人可多了！现在好像已经平稳下来……不过，客流量还是比以前增加了。」',
    "Script/scenario07_3.binu8@75285": '座长A',
    "Script/scenario07_5.binu8@66031": '@vKohaku_0761「……龙木小姐……你觉得座长说得对吗？」',
    "Script/scenario08_1.binu8@84115": '「……啊，是胧啊。」',
    "Script/scenario08_1.binu8@84280": '「哦，原来胧也会感到寂寞啊。」',
    "Script/scenario08_1.binu8@85482": '　胧温柔地说道。',
    "Script/scenario08_1.binu8@89662": '　胧露出苦笑。@n　正因为知晓那份辛劳，才会露出这样的笑容。',
    "Script/scenario08_2.binu8@77959": '「……胧到底在做什么……？」',
    "Script/scenario08_2.binu8@78693": '　胧先开口说道。',
    "Script/scenario08_2.binu8@82088": '　接着，胧坦白了一切。',
    "Script/scenario08_2.binu8@102363": '　我却没有意识到自己的丑陋。',
    "Script/scenario08_5.binu8@92909": '「……那也太令人难过了吧？胧只是被人利用了……」',
    "Script/scenario08b_1.binu8@81049": '@vKohaku_0901「太惊人了……！那就是演剧吗？那种气势？演剧……竟然如此不得了！」',
    "Script/scenario08b_1.binu8@81281": '@vFutaba_0841「……真的很厉害。」',
    "Script/scenario08b_2.binu8@86410": '「谁来担任座长？巡还要兼任其他工作，恐怕不太合适……难道是琥珀？」',
})

OVERRIDES.update({
    "Script/scenario01_10.binu8@95292": '　总之，事情就是这样。@n　最后，因为不成熟的我拖了后腿，《红色房间》只能以不尽如人意的评价收场。',
    "Script/scenario04_1.binu8@101174": '　某个与折原冰狐相似的存在，像是突然想到什么似的说道。',
    "Script/scenario04_5.binu8@78527": '　少女语气坚定地说道。',
    "Script/scenario04_6.binu8@55836": '　她的演技与表现力，甚至能让最刻薄的评论家为之惊叹。@n　据说，只要看过她的演剧，就会被那魔性的魅力俘获。',
    "Script/scenario05_11.binu8@80004": '@vMenberA_0006「真是太有气势了。那声音仿佛承载着世间的不合理，发出阵阵呐喊。可惜她竟然退团了。明明只要忍耐一阵子，关于人的流言就会消失……」',
    "Script/scenario05_11.binu8@101743": '　座长一脸无奈地说道。',
    "Script/scenario05_12.binu8@91422": '　要与那种存在平分秋色……究竟得失去多少东西才办得到呢？',
    "Script/scenario05_2.binu8@83355": '@vRairai_0382「那还用说。把这种外行人聚在一起，能成什么事？真是的，剧团的名字倒是起得够响亮，实际却完全名不副实。」',
    "Script/scenario05_2.binu8@94950": '@vRairai_0393「节哀顺变。」',
    "Script/scenario05_3.binu8@85618": '　少女毫不犹豫地宣告。@n　与她上次说出类似话语时的模样，截然不同。',
    "Script/scenario05_4.binu8@78559": '　座长神情认真地说道。',
    "Script/scenario07_1.binu8@107370": '　别人喜欢的东西，我喜欢不起来。@n　别人称赞厉害的东西，我也无法认同其厉害之处。',
    "Script/scenario07_2.binu8@89310": '「这次可真是找了个不得了的地方啊。」',
    "Script/scenario07_4.binu8@52929": '@vOmi_0073「下一出戏是《哈姆雷特》。巡……你能编织出那愚蠢而可悲的复仇剧吗？」',
    "Script/scenario07b_1.binu8@95460": '@vMeguri_1260「……我讨厌时钟的声音。那是束缚着我们的魔性音色。」',
    "Script/scenario08_1.binu8@88245": '@vOboro_0344「没错！关键就在这里。她最惊人的地方，正是她真的不爱你。她明明确实抱有好感，却没有发展成爱情。我认为，这才是真正的爱。」',
    "Script/scenario08_4.binu8@57719": '　折原冰狐在暮色中微笑。@n　她是能俘获万物的魔性演员。',
    "Script/scenario08_5.binu8@71170": '「不不，我只是个稍微优秀一点的普通人。真正的天才还要厉害得多。我很清楚自己的分量，所以才转行做了演出家。」',
    "Script/scenario09_1.binu8@44421": '　然而，我的视网膜却将那仿佛梦境般的景象，连同每一个细节都牢牢记住了。',
    "Script/scenario09_5.binu8@84971": '　即使可怜，即使空虚，即使不讨人喜欢。@n　我也一定不能放弃。',
})

OVERRIDES.update({
    "Script/scenario05_1.binu8@86391": '　舞台设在街头，角色是一名能干的打工者。@n　他是个沟通能力出色、精力充沛又可靠的年轻人。',
    "Script/scenario05_7.binu8@90391": '「胧饰演的角色是巴尔德。」',
    "Script/scenario08_4.binu8@56047": '　然后，我们彼此道别。@n　也向至今为止的种种感情道别。',
    "Script/scenario08_5.binu8@86430": '　可这一次，泪水却流个不停，连我自己都不明白为什么。',
    "Script/scenario08b_2.binu8@83856": '「剩下的就是肌肉训练和跑步。发声练习之类的也很重要。演剧没有对话框或字幕，吐字清晰真的非常重要。」',
    "Script/scenario09_4.binu8@81306": '　随后，我取出了一本书。',
})

OVERRIDES.update({
    "Script/scenario07_2.binu8@95695": '　我终于逃离了那家伙的魔爪，擦着冷汗来到了那个地方。',
    "Script/scenario07_2.binu8@103081": '　我知道，就算说了他也不会听。@n　可即便如此，我还是必须把话说出来。',
    "Script/scenario07_4.binu8@51415": '　我始终有意识地站在演出家和舞台监督的视角，努力从旁观者的角度汲取些什么。',
    "Script/scenario07_6.binu8@61610": '　起初，我一边流泪，一边不断忍受那种教育；但从某个时候开始，我渐渐学会了反抗。',
    "Script/scenario08_2.binu8@88780": '　热爱古典文学的未来，埋头翻阅着译成日文的剧本。',
    "Script/scenario08_5.binu8@76498": '　他斜着眼看了过去，若无其事地说道。',
    "Script/scenario09_1.binu8@43134": '　我总是容易被孤立，所以便和那些少女保持一步之遥，以自己的方式维持着平静。',
    "Script/scenario09_2.binu8@83919": '@vMirai_0886「就算禁止她恋爱，妹妹也不会因此死去。她并没有脆弱到必须得到哥哥的爱才能活下去。」',
    "Script/scenario09_3.binu8@68959": '　“我”这一存在，虽然暧昧得仿佛只会随波浪摇曳，但至少在狭小的空间里，我自信不会输给任何人。',
    "Script/scenario09_5.binu8@85562": '　为了不输给火焰的势头。@n　那个不体面地紧抓着生存不放、如此可怜的我。',
    "Script/scenario09_5.binu8@97342": '「――你是演员。你还没有把哈姆雷特演到最后。」',
})

OVERRIDES.update({
    "Script/scenario02_10.binu8@60468": '@vrize_0164「――她试图介入某人的人生，以另一个人的身份活下去。」',
    "Script/scenario02_10.binu8@60903": '@vrize_0166「不，我会原谅她。只要那就是她获得幸福的方式。所以，你看。」',
    "Script/scenario02_10.binu8@61781": '@vrize_0170「她为什么会如此了解天使奈奈菜的过去？那可是只有本人才能知道的往事，对吧？」',
    "Script/scenario02_10.binu8@72695": '　我并不是一个值得被爱的人。@n　而是一个必须去爱别人的人……所以才会这样。',
})

OVERRIDES.update({
    "Script/scenario01_1.binu8@70249": '「作为男人，就要负起责任来。」',
})

OVERRIDES.update({
    "Script/scenario02_4.binu8@79580": '　那是什么？@n　我可不知道啊？',
    "Script/scenario04_3.binu8@71467": '@vFutaba_0470「……这、这人是怎么回事？」',
    "Script/scenario05_9.binu8@95369": '@vRairai_0482「你确实闯了祸，也确实疏忽大意了。既然如此，我就得好好提醒你。要是在职业圈子里发生同样的事，可是会影响一辈子的。」',
    "Script/scenario07_3.binu8@82271": '@vRairai_0643「喂喂，这是什么状况？还真够厉害的啊？……嗯？嗯嗯？如果我没记错的话……你不是已经结婚了吗？」',
    "Script/scenario08_2.binu8@85453": '　声音和外貌都没有改变。@n　然而……某种致命的东西，却已经切换了。',
    "Script/scenario09_1.binu8@52191": '@vFutaba_0899「不、不是！可是！这、这到底怎么回事！？那是男的……！？骗人的吧！？」',
    "Script/scenario09_3.binu8@55886": '「……你在说什么啊。」',
})

OVERRIDES.update({
    "Script/scenario07_4.binu8@63181": '　本作将成为匂宫巡主演出道的作品。',
    "Script/scenario08_2.binu8@86922": '　濑和环与濑和未来的生母，曾是知名剧团的台柱女演员。',
    "Script/scenario08_4.binu8@70601": '@vKohaku_0839「――我是濑和未来。对，就是这样。」',
    "Script/scenario08_5.binu8@76780": '「不是不是，你在说什么啊？她是濑和未来，我的妹妹。架桥是谁？又是什么人？」',
})

OVERRIDES.update({
    # Whole-game pass: repair early-batch translation artifacts in Acts 8-9.
    "Script/scenario08_3.binu8@89680": '「想要登上顶峰，就把一切都抛开，拼上性命去面对！你可是濑和未来，这个家的台柱啊！」',
    "Script/scenario09_1.binu8@51464": '@vMirai_0815「妹妹和」',
    "Script/scenario09_1.binu8@51569": '@vFutaba_0895「………………咦」',
    "Script/scenario09_1.binu8@51647": '　阿尼？阿妮？@n　欧尼酱？嗯？',
    "Script/scenario09_1.binu8@51813": '@vMirai_0817「名字叫环。啊，环这个名字，女孩子也会用来取呢——」',
    "Script/scenario09_3.binu8@62364": '　我发誓，要把一切都当作垫脚石，活在演剧的世界里。',
    "Script/scenario09_3.binu8@62456": '　所谓演剧，就是融化、沉入自身的存在，并让它彼此缠绕的东西。',
    "Script/scenario09_3.binu8@62557": '　当我想要饰演某个角色时，就必须把名为“我”的存在拆得七零八落，再重新塑造。',
    "Script/scenario09_3.binu8@62703": '观众A',
    "Script/scenario09_3.binu8@62781": '　沉浸在某种身份之中时，反而很轻松。@n　忘却身为濑和未来时的留恋，只是一心一意地投入那个角色。',
    "Script/scenario09_3.binu8@62935": '　渐渐地，我开始越来越不明白所谓真正的自己究竟是什么。',
    "Script/scenario09_3.binu8@73614": '　让她听进去，让她亲眼见证，把我的呐喊刻进她的灵魂。',
    "Script/scenario09_3.binu8@73700": '　向这个可怜小姑娘扭曲的思念俯首称臣吧。',
    "Script/scenario09_3.binu8@73774": '@vMirai_0935「――我」',
    "Script/scenario09_5.binu8@94739": '@vRairai_0795「呸……明明都死透了，还活蹦乱跳的。」',
    "Script/scenario09_5.binu8@94915": '@vOmi_0115「你以为那家伙是谁？那可是匂宫王海的孙女……稀世的天才女演员啊！她可不是会被这种程度的即兴发挥击垮的演员。」',
    "Script/scenario09_5.binu8@95107": '@vRairai_0796「……死老头。」',
    "Script/scenario09_5.binu8@95146": '　他也终于明白了。@n　明白匂宫王海为何从未踏上前往虚构世界的旅途。',
    "Script/scenario09_5.binu8@95285": '　他知道幸福是什么。@n　也知道那些肉眼看不见、却无比珍贵的事物。',
    "Config/bgm.datu8@450": '怀抱大志',
})

OVERRIDES.update({
    "Script/scenario06b_5.binu8@19133": '　然后，一夜过去。',
    "Script/scenario06b_5.binu8@19860": '　我不经意间转过视线，看见奈奈菜红了脸。@n　不知不觉吸引了我目光的，是她那双湿润的嘴唇。',
    "Script/scenario06b_5.binu8@23792": '　这是个别人拜托了就无法拒绝的性格。',
    "Script/scenario06b_5.binu8@23839": '　那种情况下，我也说不出“不”吧。',
    "Script/scenario06b_5.binu8@24845": '　就连彼此那一点点迷糊的地方，也会让人觉得可爱。',
})

OVERRIDES.update({
    "Script/scenario06b_5.binu8@19398": '　交握的手被紧紧握住。@n　仅仅是彼此接触，心情就会高涨起来。',
    "Script/scenario06b_5.binu8@20144": '　——我想接吻。',
    "Script/scenario06b_5.binu8@21218": '　奈奈菜羞涩地继续说道。',
    "Script/scenario06b_5.binu8@22731": '　把那些无聊的妄想一笑置之吧。',
    "Script/scenario06b_5.binu8@22793": '「你是我的妹妹。所以，我们才会结合在一起。」',
    "Script/scenario06b_5.binu8@23482": '「说起来，那件事要怎么办？」',
    "Script/scenario06b_5.binu8@23946": '　稍微思考了一会儿。',
    "Script/scenario06b_5.binu8@24179": '　僵住的时间，只有短短一瞬。',
    "Script/scenario06b_4.binu8@73344": '「果然，最坏的害虫就是你啊。」',
    "Script/scenario06b_4.binu8@74851": '　羞涩让她选择了退缩的话语。',
})

OVERRIDES.update({
    "Script/scenario06b_4.binu8@65401": '　我把手伸过去，揉乱了她的头发。',
    "Script/scenario06b_4.binu8@65908": '　仿佛能让人头晕目眩的脑内物质，正要摧毁我的理性。',
    "Script/scenario06b_4.binu8@68512": '　遇到不开心的事，逃避也没关系。',
    "Script/scenario06b_4.binu8@68633": '@vNanana_0581「……好的。」',
    "Script/scenario06b_4.binu8@71515": '　她继续喃喃自语着，仿佛在念诅咒。',
    "Script/scenario06b_4.binu8@73344": '「果然，最坏的害虫就是你啊。」',
    "Script/scenario06b_4.binu8@74851": '　羞涩让她选择了退缩的话语。',
    "Script/scenario06b_4.binu8@76143": '　我用力握紧拳头。',
    "Script/scenario06b_4.binu8@76917": '　我从她坚定的意志中感受到了决心，于是顺从地对她点了点头。',
    "Script/scenario06b_4.binu8@77392": '　奈奈菜究竟是什么时候来到这里的？',
    "Script/scenario06b_4.binu8@77704": '　奈奈菜的身体微微颤抖着。',
    "Script/scenario06b_4.binu8@78822": '　现在，这一瞬间是属于奈奈菜的。',
    "Script/scenario06b_4.binu8@79249": '　这个世界不存在那些无聊的常识。',
    "Script/scenario06b_4.binu8@79676": '　从开始之前，答案就已经决定了。',
    "Script/scenario06b_4.binu8@79860": '　我产生了仿佛被雷击中的感觉。',
    "Script/scenario06b_4.binu8@80283": '　妹妹向哥哥告白。',
    "Script/scenario06b_4.binu8@80895": '　心意与心意彼此相通。',
    "Script/scenario06b_4.binu8@81465": '　我心中的某种东西逐渐融化，再也无法恢复原状。',
    "Script/scenario06b_4.binu8@81904": '　我们已经停不下来了。',
    "Script/scenario06b_5.binu8@19188": '@vNanana_0695「……余韵还残留着呢。」',
    "Script/scenario06b_5.binu8@19398": '　交握的手被紧紧握住。@n　仅仅是彼此接触，心情就会高涨起来。',
    "Script/scenario06b_5.binu8@20144": '　——我想接吻。',
    "Script/scenario06b_5.binu8@21218": '　奈奈菜羞涩地继续说道。',
    "Script/scenario06b_5.binu8@22731": '　把那些无聊的妄想一笑置之吧。',
    "Script/scenario06b_5.binu8@22793": '「你是我的妹妹。所以，我们才会结合在一起。」',
    "Script/scenario06b_5.binu8@23482": '「说起来，那件事要怎么办？」',
    "Script/scenario06b_5.binu8@23946": '　稍微思考了一会儿。',
    "Script/scenario06b_5.binu8@24179": '　僵住的时间，只有短短一瞬。',
})

OVERRIDES.update({
    "Script/scenario06b_4.binu8@64549": '@vNanana_0567「……可以抱我一下吗？」',
    "Script/scenario06b_4.binu8@64856": '「……不，我只是睡过头了吧？」',
    "Script/scenario06b_4.binu8@64965": '　虽然我们悠闲地走着，但肯定已经迟到了。',
    "Script/scenario06b_4.binu8@65143": '　我看到了可爱妹妹那令人愉快的一面。',
    "Script/scenario06b_4.binu8@65695": '　奈奈菜满脸喜色地碰了碰我的手。',
    "Script/scenario06b_4.binu8@65867": '　啊啊，真是危险啊。',
    "Script/scenario06b_4.binu8@66058": '　虽然我们不被允许发展出超越那一步的关系。',
    "Script/scenario06b_4.binu8@66159": '　可又有谁会因此责怪我们呢？',
    "Script/scenario06b_4.binu8@67661": '　听到这句话，奈奈菜的脸都快要沸腾了。',
    "Script/scenario06b_4.binu8@69419": '　你说的“各种各样”，究竟是什么？',
    "Script/scenario06b_4.binu8@69996": '「我哥到底哪里麻烦了？」',
    "Script/scenario06b_4.binu8@70189": '@vFutaba_0680a「有那么可爱的妹妹，哪个哥哥能不产生邪恶的想法？怎么可能嘛！」',
    "Script/scenario06b_4.binu8@71984": '　随后，双叶再次转过身面对我。',
    "Script/scenario06b_4.binu8@72327": '「……你到底是什么人啊？」',
    "Script/scenario06b_4.binu8@73999": '@vMeguri_0972「你有好好在家里练习过吗？」',
    "Script/scenario06b_4.binu8@78077": '　仅仅这一瞬间，我就充分感受到了那份心意。',
    "Script/scenario06b_4.binu8@78157": '「所以，你想说什么？」',
    "Script/scenario06b_4.binu8@78287": '@vNanana_0595「奈、奈奈菜……！！」',
    "Script/scenario06b_4.binu8@78477": '　都特意把人叫到这里来了……任谁都能猜到吧。',
    "Script/scenario06b_4.binu8@79036": '　因为是妹妹。',
    "Script/scenario06b_4.binu8@79059": '　“因为是妹妹”这句话，究竟包含着什么含义？',
    "Script/scenario06b_4.binu8@79139": '　从这句话延伸出去的后续，究竟会是什么？',
    "Script/scenario06b_4.binu8@79412": '　禁忌也好，理解也好，那些都无所谓了。',
    "Script/scenario06b_4.binu8@79492": '　只要连大脑都融化、沉溺其中，就能得到幸福。',
    "Script/scenario06b_4.binu8@79913": '　刹那间，思绪完全停止，喉咙深处迸发出热意。',
    "Script/scenario06b_4.binu8@81172": '　妹妹的声音，在脑海中回响。',
})

OVERRIDES.update({
    "Script/scenario06b_3.binu8@73781": '　那是一种难以理解的感情。',
    "Script/scenario06b_3.binu8@73837": '@vNanana_0496「就像手脚不知所措地乱动，显得十分可疑一样。」',
    "Script/scenario06b_3.binu8@75369": '　凝视镜中的自己，看到的只有一张可爱的脸。',
    "Script/scenario06b_3.binu8@76180": '　歌也好，舞也好，演戏也好……我什么都做不好。',
    "Script/scenario06b_3.binu8@76768": '　直到那时，我一直挂在嘴边的“喜欢”，转眼间便被彻底吹散。',
    "Script/scenario06b_3.binu8@77214": '@vNanana_0505「——真的吗？」',
    "Script/scenario06b_3.binu8@77256": '　我猛然醒悟，努力让自己冷静下来。',
    "Script/scenario06b_3.binu8@81827": '@vNanana_0523「——谁会把那种东西称作恋爱？」',
    "Script/scenario06b_3.binu8@84005": '　这样一个丑陋的女孩，真的正在恋爱吗？',
    "Script/scenario06b_3.binu8@86917": '　啊啊，我真是个愚蠢的女孩。',
    "Script/scenario06b_3.binu8@87078": '@vNanana_0542「——就算只是被利用，也没关系。」',
    "Script/scenario06b_3.binu8@87153": '　只要能让我看到甜蜜的梦，什么都无所谓。',
    "Script/scenario06b_3.binu8@88123": '　那个故事，究竟该叫什么名字？',
    "Script/scenario06b_3.binu8@89617": '　世界彻底崩溃，连一丝完整都不剩。',
    "Script/scenario06b_3.binu8@89841": '@vMirai_0392「这样一来，你们两个人就是双向奔赴了。」',
    "Script/scenario06b_3.binu8@89985": '　最初，被囚禁在那间白色房间里的时候，我就已经察觉到了。',
    "Script/scenario06b_3.binu8@90990": '　为了确认这不是梦，我必须保持冷静。',
    "Script/scenario06b_3.binu8@91355": '　甜美而纯白的房间。',
    "Script/scenario06b_3.binu8@93301": '「我觉得没时间聊天了吧？」',
})

OVERRIDES.update({
    "Script/scenario04_4.binu8@77999": '　她的状态明显不对。@n　脸红得厉害，身体也有些摇摇晃晃……实在太毫无防备了。',
    "Script/scenario04_4.binu8@78430": '@vcs_Oboro_0001「不，我也完全搞不清楚……」',
    "Script/scenario04_4.binu8@78654": '@vcs_Oboro_0002「……难道是因为这个？」',
    "Script/scenario04_4.binu8@78728": '　胧指向的是一块裸露出成熟气息的巧克力。@n　这是店主出于好意端出来的、在当地很受欢迎的甜点。',
    "Script/scenario04_4.binu8@79636": '@vcs_Oboro_0004「毕竟她又没喝酒，应该很快就会恢复吧。那照顾她的事就拜托你啦。」',
    "Script/scenario04_4.binu8@81850": '　要是放任这样的理世不管，肯定会酿成无法挽回的后果。',
    "Script/scenario04_4.binu8@83225": '　不过，比起就这样把理世带回她的房间，还是这里更方便。',
    "Script/scenario04_4.binu8@83565": '@n　——真是如花朵般可爱的笑容啊。',
    "Script/scenario04_4.binu8@83709": '　从掌心传来的温度，正位于记忆最根本的地方。',
    "Script/scenario04_4.binu8@85158": '　就在那时，我迎来了命运般的邂逅。@n　那是在艺术之城尼克斯的一间小剧场里，某个剧团举办的专场演出。',
    "Script/scenario04_4.binu8@90309": '　极致的自我满足。@n　这就是兰比里斯剧团的宗旨。',
    "Script/scenario05_13.binu8@70488": '　天兄为什么要毁掉悠小姐的转团？@n　还用“她曾经接受过枕营业”这种方式，深深伤害了她的心。',
    "Script/scenario05_14.binu8@67856": '@vMeguri_0906「……你不先杀了我吗？」',
    "Script/scenario05_14.binu8@89619": '@vMirai_0381「你究竟想要什么呢？」',
    "Script/scenario06_6.binu8@83093": '「……那个，要去哪里？」',
    "Script/scenario06_6.binu8@83146": '@vRize_0965「哪里都可以。」',
    "Script/scenario06_6.binu8@84162": '@vRize_0973「还想要更多……」',
    "Script/scenario06_6.binu8@84202": '　双唇仿佛在贪饮甘甜的蜜一般，被轻轻吮吸着。',
    "Script/scenario06_6.binu8@84719": '@vRize_0976「环君……想触摸我的身体吗？想摸我的胸部吗？」',
    "Script/scenario06_6.binu8@84980": '　这里可是学校的、没什么人的中庭啊！@n　为什么要毫无防备地暴露自己啊！',
    "Script/scenario06_6.binu8@85324": '　每次双唇交叠，吻便变得更加激烈。',
    "Script/scenario06b_2.binu8@86773": '　你在这座公园里，把那副腹黑的本性肆意散播了出去。',
    "Script/scenario06b_2.binu8@88935": '@vMika_0097「你现在已经不想当偶像了吗？」',
    "Script/scenario06b_2.binu8@89329": '　天使美嘉瞪圆了眼睛。',
    "Script/scenario06b_2.binu8@89373": '　奈奈菜涨红了脸，移开视线。',
    "Script/scenario06b_3.binu8@66577": '　亲生母亲去世后，我被天使家收养的时候。',
    "Script/scenario06b_3.binu8@68301": '　几年前。',
    "Script/scenario06b_3.binu8@69088": '　偶尔也有人邀请我出去玩，但我总是拒绝，因为妈妈说过不能擅自做这种事。',
    "Script/scenario06b_3.binu8@69876": '　我只是在为了达成目的，表现得像个正常人而已。',
    "Script/scenario06b_3.binu8@70754": '@vNanana_0486「可、可是……偶像不是不能喜欢上某一个人吗……」',
    "Script/scenario06b_3.binu8@72267": '　我立刻回到家，按照妈妈吩咐的那样做了。',
})

OVERRIDES.update({
    "Script/scenario05_2.binu8@87752": '@vOmi_0016「如果要谈才华，你才是更优秀的那个。比来来更优秀，比悠苑更优秀，也比理世更优秀。你……是被戏剧之神所眷顾的人。」',
    "Script/scenario05_14.binu8@70173": '页：1',
    "Script/scenario06b_3.binu8@83223": '页：1',
    "Script/scenario05_13.binu8@62910": '页：1',
})

OVERRIDES.update({
    "Script/scenario04_4.binu8@87853": '　世人给出的结论是：匂宫王海与一群愉快的外行人。',
    "Script/scenario04_7.binu8@40218": '　濑和未来说道。',
    "Script/scenario05_2.binu8@87208": '　天乐先生误以为我是一名优秀的演员，但如果真是这样，我现在就不会在这里当文员了。',
    "Script/scenario05_2.binu8@94986": '　她的脸抽搐了一下。@n　与此同时，天乐先生和龙木先生都露出了苦笑。',
    "Script/scenario05_9.binu8@80622": '　即便如此，天乐团长的眼中也没有丝毫迷惘。',
    "Script/scenario05_9.binu8@81987": '　天乐团长叫住了正要开口说些什么的琥珀。',
    "Script/scenario05_9.binu8@84078": '「天、天乐团长？」',
    "Script/scenario06_1.binu8@92767": '「……你是说天乐团长吗？」',
    "Script/scenario06b_3.binu8@78237": '「……奈奈菜？」',
    "Script/scenario06b_3.binu8@79075": '@vMika_0126「……奈奈菜？」',
    "Script/scenario06b_4.binu8@64439": '　看着奈奈菜的表情不断变化，连我也跟着开心起来。',
    "Script/scenario06b_4.binu8@78884": '　这是奈奈菜亲自争取到的、十分重要的一幕。',
    "Script/scenario06b_6.binu8@60405": '@vNanana_0731「……匂宫小姐尊重了我的心意。她真是个温柔的人呢。」',
})

OVERRIDES.update({
    "Script/scenario05_14.binu8@89814": '@vNanana_0408「——我……」',
    "Script/scenario05_12.binu8@75963": '　照这样下去，菲莉亚演出会失败。@n　以现在的状态，我不认为能够顺利进行。',
    "Script/scenario06b_6.binu8@58208": '@vNanana_0723「……作为故事，哪里都没有宣泄感。对渴望复仇的我来说，这样的发展就像被泼了冷水。」',
    "Script/scenario06b_4.binu8@80708": '　这个世界从什么时候起，变得如此美丽了？',
    "Script/scenario05_13.binu8@80674": '@n　——那时，我究竟能为她做些什么呢？',
})

OVERRIDES.update({
    "Script/scenario05_1.binu8@75226": '　从天乐来来到架桥琥珀。',
    "Script/scenario05_10.binu8@72926": '　我绝不会让任何人妨碍我们的演剧。',
    "Script/scenario05_10.binu8@74049": '　团长一脸无奈地说道。',
    "Script/scenario05_10.binu8@78563": '　他用那副背影，纵容着我的撒娇。',
    "Script/scenario05_10.binu8@82958": '　他若无其事地说道。',
    "Script/scenario05_11.binu8@78101": '　悠苑强忍泪水，瞪着我。',
    "Script/scenario05_11.binu8@78265": '　想要抢先一步的你，才是错的。',
    "Script/scenario05_13.binu8@80674": '@n　——那时，我究竟能为她做些什么呢？',
    "Script/scenario06b_6.binu8@67419": '　近来还有一种做法，就是在视频网站上直播，或在同人展销会上发布 cosplay 图片。',
    "Script/scenario06b_6.binu8@61503": '　咕咚一声咽下口水。',
})

OVERRIDES.update({
    "Script/scenario04_4.binu8@85742": '　最令人印象深刻的，是饰演配角的少女脸上的表情。',
    "Script/scenario04_4.binu8@86085": '　从那以后，我越来越常去剧场。@n　因为从那天起，我就彻底被戏剧的魅力俘虏了。',
    "Script/scenario04_4.binu8@86401": '　我看到圈内一则有些特别的招募启事，回过神来，已经投了申请。',
    "Script/scenario05_4.binu8@82874": '@vMeguri_0550a「——你是说，你的演技不只是能与我并驾齐驱，而是足以把我彻底盖过吗？」',
})

OVERRIDES.update({
    "Script/scenario06b_4.binu8@70148": '　双叶“砰”地一声拍了下桌子。',
    "Script/scenario06b_4.binu8@71154": '　双叶瞥了一眼旁边。',
    "Script/scenario06b_4.binu8@73394": '　邪恶的欲望毫不掩饰地泄露出来。',
    "Script/scenario06b_4.binu8@77751": '　肩膀、声音、嘴唇……全都在害怕着什么。',
    "Script/scenario06b_4.binu8@77825": '　她一定是在放学铃响后，便一溜烟地跑出了学校。',
    "Script/scenario06b_4.binu8@78388": '　今早奈奈菜的状态，以及她和匂宫偷偷密谈了很久这件事。',
    "Script/scenario06b_4.binu8@80708": '　这个世界从什么时候起，变得如此美丽了？',
    "Script/scenario06b_5.binu8@20507": '　趁太阳还在天空注视着一切，根本什么都做不了。',
    "Script/scenario06b_5.binu8@20766": '　脸颊转眼间便染上了红晕。',
    "Script/scenario06b_5.binu8@20998": '　奈奈菜关于性的知识，或许有些偏颇。',
    "Script/scenario06b_5.binu8@24226": '　视线的前方，一名相貌端正的青年正一边摆弄手机一边走着。',
    "Script/scenario06b_5.binu8@24632": '「咦，我们刚才在聊什么来着？」',
    "Script/scenario06b_5.binu8@24801": '　彼此凝视着，相视而笑。',
})

OVERRIDES.update({
    "Script/scenario04_4.binu8@77698": '「……理世？」',
    "Script/scenario04_4.binu8@77724": '　感觉她说话都有些含糊不清？',
    "Script/scenario04_4.binu8@87225": '　无论怎样学习、怎样努力，我都比同龄人差得多……甚至连小角色都不肯给我。',
    "Script/scenario04_4.binu8@87753": '@n　——把厉害的人赶走，却让杂鱼加入剧团，这算什么啊。',
    "Script/scenario04_4.binu8@89902": '　那是我完全没有预料到的话，竟然从王海先生口中说了出来。',
    "Script/scenario04_4.binu8@92183": '　白坂小姐得意洋洋地说着，不知为何显得很开心。',
    "Script/scenario04_4.binu8@94153": '「——！？」',
    "Script/scenario05_1.binu8@75658": '@vKohaku_0517「因为这是个很有名的故事嘛。」',
    "Script/scenario05_4.binu8@83207": '　团长会采取这种手段，说明他对琥珀的完成度很有信心吧。',
    "Script/scenario05_9.binu8@95283": '@vYuuen_0194「来、来来小姐……请不要说得这么严厉……！」',
    "Script/scenario06b_1.binu8@73995": '@vFutaba_0632「明明因为不想被奇怪地关注，一直隐瞒着名字……为什么偏偏到了现在，天使奈奈菜的名字反而传开了呢？」',
    "Script/scenario06b_7.binu8@42374": '@vFutaba_0750「……好吵。因为你的口气很臭，请安静一点。」',
    "Script/scenario05_12.binu8@83736": '@vRairai_0587「……漂亮，悠苑。干得真不错。」',
})

OVERRIDES.update({
    "Script/scenario05_13.binu8@63037": '@vMirai_0371「……已经不算演技或什么了。」',
    "Script/scenario05_13.binu8@67519": '@vMeguri_0880「……奥丁。」',
    "Script/scenario05_13.binu8@68981": '@vKohaku_0640「我不是说过，我就在这里吗？你也已经看不见了吗？」',
    "Script/scenario05_13.binu8@70452": '@vMeguri_0886「为什么……」',
    "Script/scenario05_13.binu8@70639": '@vMeguri_0887「为什么……」',
    "Script/scenario05_13.binu8@70862": '@vMeguri_0888「为什么……」',
    "Script/scenario05_13.binu8@71061": '@vMeguri_0889「为什么……」',
    "Script/scenario05_13.binu8@77542": '@vRize_0703「冰狐。」',
    "Script/scenario05_13.binu8@78629": '@vRize_0706「所以，胸口才会被勒得这么紧。」',
    "Script/scenario05_14.binu8@84849": '@vKohaku_0663「……这样就好。直到最后，你都是个高尚的人。接下来，慢慢休息吧。暴力的魔爪，不会再追到另一个世界去了。」',
    "Script/scenario05_14.binu8@87578": '@vMeguri_0927「结束了。你真的……做得很好。」',
    "Script/scenario05_14.binu8@89814": '@vNanana_0408「——我……」',
    "Script/scenario06b_3.binu8@70341": '@vMika_0115「——爱上他吧。把他当作异性，试着去爱他。」',
    "Script/scenario06b_3.binu8@72805": '@vNanana_0491「无论何时，无论何地。」',
    "Script/scenario06b_3.binu8@73715": '@vNanana_0495「那种让人忍不住想大喊出来的感觉。」',
    "Script/scenario06b_3.binu8@89225": '@vNanana_0546「所以……」',
    "Script/scenario06b_3.binu8@93372": '@vNanana_0560「呜呜～～～～！！！」',
    "Script/scenario06b_4.binu8@67424": '@vNanana_0578「……谢、谢谢您。」',
    "Script/scenario06b_4.binu8@70654": '@vFutaba_0682「……没想到天使竟然是艺名。因为是天使酱，我还以为她从出生起就是天使呢。」',
    "Script/scenario06b_4.binu8@75630": '@vMeguri_0978「……你和濑和君看起来非常般配。明明是兄妹，却不知为何，比我和琥珀还要更加、更加亲近。」',
    "Script/scenario06b_4.binu8@76101": '@vNanana_9002「……匂宫小姐。」',
    "Script/scenario06b_5.binu8@20031": '@vcs_Nanana_0003「呜！」',
    "Script/scenario05_1.binu8@90777": '@vNanana_0302「是约会，毫无疑问就是约会。」',
    "Script/scenario05_1.binu8@93109": '@vNanana_0308「……演出？」',
    "Script/scenario05_1.binu8@93605": '@vNanana_0309「以前一直都是巡小姐负责演出指导吗？」',
})

OVERRIDES.update({
    "Script/scenario06b_3.binu8@82882": '　其实，是因为洗脑还没有结束吧？',
    "Script/scenario06b_3.binu8@83512": '　把十几年来积攒的不满，一股脑倾泻出来。',
    "Script/scenario06b_3.binu8@83700": '　不是，不是，不是！我确确实实是在恋爱！',
    "Script/scenario06b_3.binu8@86855": '　白发与红瞳，侵入了我的心。',
    "Script/scenario06b_3.binu8@88023": '　白发红瞳将引导我前行。',
    "Script/scenario06b_3.binu8@88538": '　难道，她是要向我告白吗？',
    "Script/scenario06b_3.binu8@89929": '　映照出愿望的、甜美而唯美的故事。',
    "Script/scenario06b_3.binu8@90596": '　并不是在开玩笑。',
    "Script/scenario06b_3.binu8@90772": '　这种充盈胸口的感觉，究竟是什么？',
    "Script/scenario06b_3.binu8@90949": '　让时钟的指针倒转吧。',
    "Script/scenario06b_3.binu8@91909": '　就在那时，我终于从梦境世界中回来了。',
    "Script/scenario06b_3.binu8@92818": '「正值年纪的女孩子，哪能五分钟就准备好？你该不会想顶着一头乱蓬蓬的头发去上学吧？」',
    "Script/scenario06b_6.binu8@60866": '@vNanana_0732「就、就是那件事……！我、我有一件想试着挑战的事情，啊、啊、啊、啊……！」',
    "Script/scenario06b_6.binu8@61101": '@vNanana_0733「那个、呃，呃呃呃呃……！！」',
    "Script/scenario06b_6.binu8@61553": '@vNanana_0735「我向环君表明了心意……然后愿望实现了……！这是我出生以来第一次，觉得奈奈菜也能获得幸福……！所、所以……所以？所以，那个……」',
    "Script/scenario06b_6.binu8@61867": '@vNanana_0736「我、我重新审视了自己想做什么、想成为什么……那个……重新思考了这些……！」',
    "Script/scenario06b_6.binu8@62327": '@vNanana_0737「我、我想起来了……！小时候曾经憧憬过的东西……我想再一次、再一次试试看……！」',
})

OVERRIDES.update({
    "Script/scenario06b_6.binu8@64576": '@vNanana_0744「你会支持我吗……？」',
    "Script/scenario06b_6.binu8@64662": '@vNanana_0745「你会帮我吗……？」',
    "Script/scenario06b_6.binu8@66132": '@vNanana_0748「好的！」',
    "Script/scenario06b_6.binu8@70471": '　双叶毫不犹豫地说道。',
    "Script/scenario06b_6.binu8@74464": '　虽然看透了一切，语气中却带着几分怨念。',
    "Script/scenario06b_6.binu8@75923": '@vNanana_0750「现在没有人在看哦。所以……」',
    "Script/scenario06b_6.binu8@77446": '@vNanana_0755「……！」',
    "Script/scenario06b_6.binu8@77573": '@vNanana_0756「……啾……」',
    "Script/scenario06b_6.binu8@77677": '@vNanana_0757「嗯啾、嗯……！哈啊……啊……！」',
    "Script/scenario06b_6.binu8@77820": '@vNanana_0758「哈啊……嗯、啾……」',
    "Script/scenario06b_8.binu8@32589": '@vcs_Nanana_0010「呃、那个……」',
    "Script/scenario06b_8.binu8@33388": '　想到不失败的理由又增加了，紧张也是理所当然的吧。',
    "Script/scenario06b_8.binu8@33720": '　我用力咽下口水，集中精神。',
    "Script/scenario06b_8.binu8@33865": '　或许是因为意识到了这一点，现实反而变得更加糟糕。@n　然而，如何化解这份紧张，正是我存在的意义。',
    "Script/scenario06b_8.binu8@33820": '@vcs_Nanana_0015「哈、哈呜！」',
    "Script/scenario06b_8.binu8@35637": '@vcs_Nanana_0022「呀！？」',
    "Script/scenario06b_8.binu8@38592": '@vNanana_0914「今、今天要对大家说……！」',
    "Script/scenario06b_8.binu8@38810": '　奈奈菜，果然还是奈奈菜。',
    "Script/scenario06b_8.binu8@39112": '@vNanana_0917「……！」',
    "Script/scenario06b_8.binu8@39380": '　她展现出一副充满偶像气息、灿烂绽放的笑容。',
    "Script/scenario06b_8.binu8@39682": '　人气网络偶像被曝出热恋消息，成为街头巷尾的热门新闻。',
})

OVERRIDES.update({
    "Script/scenario06b_6.binu8@57415": '@vNanana_0719「如果我是普罗斯佩罗，我绝不会原谅他们。」',
    "Script/scenario06b_6.binu8@57603": '@vNanana_0720「复仇的空虚，究竟是什么？」',
    "Script/scenario06b_6.binu8@57788": '　既然创作了复仇与悲剧的故事，为什么偏偏在最后关头不将它贯彻到底？',
    "Script/scenario06b_6.binu8@58208": '@vNanana_0723「……作为故事，哪里都没有宣泄感。对渴望复仇的我来说，这样的发展就像被泼了冷水。」',
    "Script/scenario06b_6.binu8@58548": '　如果宽恕被称作美德，那我就这样肮脏下去也无妨。',
    "Script/scenario06b_6.binu8@58685": '　朝向那个消失在远方的世界。',
    "Script/scenario06b_6.binu8@58938": '@vMeguri_0982「……这样啊。我明白奈奈菜的心情了。」',
    "Script/scenario06b_6.binu8@59441": '@vNanana_0728「……好的。」',
    "Script/scenario06b_6.binu8@61503": '　咕咚一声咽下口水。',
    "Script/scenario06b_6.binu8@65177": '　仅凭纯真，是很难在这个世界走下去的。',
    "Script/scenario06b_6.binu8@65245": '　遇到不顺利的事情时，也一定会有许多心灰意冷的时刻。',
    "Script/scenario06b_6.binu8@66412": '　她曾在网络上拥有一定人气，可即使经历了相当长的休止期，也意外地没有被世人遗忘。',
    "Script/scenario06b_6.binu8@66609": '「……看来，天使美嘉确实很了不起啊。」',
    "Script/scenario06b_6.binu8@66793": '　似乎因为种种原因，她已经和天使美嘉断绝了关系——咦？为什么来着，我怎么想不起来了……',
    "Script/scenario06b_6.binu8@67060": '　嗯？嗯嗯？？我到底在说谁？',
    "Script/scenario06b_6.binu8@67419": '　近来还有一种做法，就是在视频网站上直播，或在同人展销会上发布 cosplay 图片。',
    "Script/scenario06b_6.binu8@68518": '　声音稍微放低了一些。',
    "Script/scenario06b_6.binu8@70471": '　双叶毫不犹豫地回答。',
    "Script/scenario06b_6.binu8@71951": '　双叶用快得惊人的语速滔滔不绝地讲述着具体到过头的规划。',
    "Script/scenario06b_6.binu8@72890": '　我咕咚一声咽下口水。',
    "Script/scenario06b_6.binu8@76374": '@vNanana_0752「确、确实……」',
    "Script/scenario06b_6.binu8@76625": '　奈奈菜一旦兴奋起来，就很难平静下来。',
    "Script/scenario06b_6.binu8@76821": '　我留下来可不是为了和奈奈菜卿卿我我。',
    "Script/scenario06b_6.binu8@77479": '　她踮起脚尖。',
    "Script/scenario06b_6.binu8@77621": '　从温柔得仿佛轻抚一般的吻开始。',
    "Script/scenario06b_6.binu8@77886": '　黄昏的教室里，品尝妹妹双唇时的背德感。',
    "Script/scenario06b_6.binu8@78081": '　双唇分离之后，奈奈菜仍沉浸在余韵之中。',
    "Script/scenario06b_6.binu8@78226": '@vNanana_0760「那、那个……」',
    "Script/scenario06b_6.binu8@78377": '　她说的“后续”，究竟是到什么程度？',
    "Script/scenario06b_8.binu8@33388": '　想到不失败的理由又增加了，紧张也是理所当然的吧。',
    "Script/scenario06b_8.binu8@33720": '　我用力咽下口水，集中精神。',
    "Script/scenario06b_8.binu8@33865": '　或许是因为意识到了这一点，现实反而变得更加糟糕。@n　然而，如何化解这份紧张，正是我存在的意义。',
    "Script/scenario06b_8.binu8@35637": '@vcs_Nanana_0022「呀！？」',
    "Script/scenario06b_8.binu8@35679": '　女主角像小动物一样蹦蹦跳跳，向我展现出毫不掩饰的表情。',
    "Script/scenario06b_8.binu8@38810": '　奈奈菜，果然还是奈奈菜。',
    "Script/scenario06b_8.binu8@39380": '　她展现出一副充满偶像气息、灿烂绽放的笑容。',
    "Script/scenario06b_8.binu8@39682": '　人气网络偶像被曝出热恋消息，成为街头巷尾的热门新闻。',
})

OVERRIDES.update({
    "Script/scenario06b_3.binu8@67194": '　被疼爱、被夸奖、被珍视。',
    "Script/scenario06b_3.binu8@67889": '　即使做不到很多事，只要努力展现可爱，妈妈就会夸奖我。',
    "Script/scenario06b_3.binu8@67993": '　简直就像真正的家人一样。@n　就像理想的家人一样。',
    "Script/scenario06b_3.binu8@68674": '　她命令我在学校不要交亲密的朋友，下课后直接回家，专心磨炼自己的可爱。',
    "Script/scenario06b_3.binu8@68945": '　一个人反而轻松自在。我由衷地认为，只要照妈妈说的去做就好。',
    "Script/scenario06b_3.binu8@69766": '　即使对别人露出亲切的笑容，心里也完全不在乎对方。',
    "Script/scenario06b_3.binu8@70051": '　我对他人的不擅长与抗拒，其本质或许就是自我厌恶。',
    "Script/scenario06b_3.binu8@74159": '　可是，我发自内心地松了一口气。',
    "Script/scenario06b_3.binu8@75200": '　就这样，日子一天天过去。',
    "Script/scenario06b_3.binu8@75579": '　开始什么的，已经无所谓了吧？',
    "Script/scenario06b_3.binu8@76703": '　那充满怒意的咆哮声，深深打动了我的心。',
    "Script/scenario06b_3.binu8@77047": '　“喜欢”这句话，满溢在我的胸口。',
    "Script/scenario06b_3.binu8@78093": '　什么是真实，什么又是错误？',
    "Script/scenario06b_3.binu8@78199": '　真正的心意，究竟在哪里？',
    "Script/scenario06b_3.binu8@78325": '　你为什么要用那种眼神看着我？',
    "Script/scenario06b_3.binu8@78771": '　从出生直到今天。',
    "Script/scenario06b_3.binu8@78969": '　熊熊燃烧的火焰，灼烧着身体。',
    "Script/scenario06b_3.binu8@80011": '　故事始于一片如低吟般的寂静。',
    "Script/scenario06b_3.binu8@80917": '　那时被强迫的事实，始终沉重地压在我的心头。',
    "Script/scenario06b_3.binu8@81021": '@n　——爱上他吧。把他当作异性，试着去爱他。',
    "Script/scenario06b_3.binu8@81628": '　每当我这样质问自己，眼前就会彻底陷入一片黑暗。',
    "Script/scenario06b_3.binu8@86032": '@vMirai_0385「你曾经是被他爱过的稀有之人。来，想起那间纯白的房间了吗？」',
    "Script/scenario06b_3.binu8@88460": '@vNanana_0544「我有些话想对你说。你愿意听吗？」',
    "Script/scenario06b_4.binu8@63961": '@vNanana_0564「嗯……洗澡、刷牙、卷头发、化简单的妆、换衣服……还有其他各种各样的事情……！」',
    "Script/scenario06b_4.binu8@66218": '　这个世上，怎么会有那么没礼貌的家伙？',
    "Script/scenario06b_4.binu8@66488": '　我用身体遮住她那张涨得通红、可爱得不得了的脸。',
    "Script/scenario06b_4.binu8@72591": '@vFutaba_0689「不就是因为你们两个都喜欢怪东西，所以才一拍即合吗？」',
    "Script/scenario06b_4.binu8@72965": '「最喜欢的天使酱被人欺负了，你居然还能无动于衷吗？」',
    "Script/scenario06b_4.binu8@73888": '　让我慢慢品味拥有最爱的妹妹这份幸福吧。',
})

OVERRIDES.update({
    "Script/scenario05_10.binu8@75069": '@vFutaba_0624「呜哇——！！现在说那些根本不重要！！」',
    "Script/scenario05_10.binu8@88318": '　然后。',
    "Script/scenario05_10.binu8@93459": '@vYuuen_0196「来、来来小姐，请冷静！一定只是开玩笑而已！」',
    "Script/scenario05_13.binu8@62922": '@vaudienceA_0002「——！」',
    "Script/scenario05_13.binu8@64526": '@vKohaku_0629「是吗？那又怎么样？」',
    "Script/scenario05_13.binu8@65996": '@vMeguri_0876「喂，奥丁。你无论过去还是现在，都没有改变过吧？」',
    "Script/scenario05_13.binu8@68259": '落雷',
    "Script/scenario05_13.binu8@69104": '@vMeguri_0883「……不是。看不见的不是我！！」',
    "Script/scenario05_13.binu8@77650": '　面对压倒性的演技，以及那种逼真到极点的压迫感，想必有不少人都被震住了。',
    "Script/scenario05_13.binu8@80386": '　受伤、被囚禁的洛基身影，与冰狐重叠在了一起。',
    "Script/scenario05_13.binu8@80674": '@n　——那时，我究竟能为她做些什么呢？',
    "Script/scenario05_14.binu8@76795": '@vMeguri_0913「——！」',
    "Script/scenario05_14.binu8@77105": '@n　——我知道？',
    "Script/scenario05_14.binu8@77154": '　我知道什么？@n　又在假装不知道什么？',
    "Script/scenario05_14.binu8@83492": '　无论何时，都温柔以待。',
    "Script/scenario05_14.binu8@86649": '@vKohaku_0666「这样就好。一定要做到。只要由你完成那件事——我的战斗就会以胜利告终。北欧神话将会毁灭。」',
    "Script/scenario05_14.binu8@87787": '　每个人都有自己的看法。',
    "Script/scenario05_14.binu8@88700": '　声音在颤抖。',
    "Script/scenario05_14.binu8@88735": '「你已经……做得很好了。」',
    "Script/scenario06b_2.binu8@82361": '　这颗被邪念玷污的心脏，在耀眼的情感面前无法保持理智。',
    "Script/scenario06b_2.binu8@83017": '　那个被希望背叛的少女，泪水啪嗒啪嗒地落下。',
    "Script/scenario06b_2.binu8@83514": '「……兰比里斯的大家，不会抛弃奈奈菜的。」',
    "Script/scenario06b_2.binu8@83965": '　……真的吗？',
    "Script/scenario06b_2.binu8@84251": '　我缓缓讲述着。',
    "Script/scenario06b_2.binu8@84483": '　我究竟该怎么做才好？',
    "Script/scenario06b_2.binu8@84542": '　难道正因为从一开始就放弃了一切，所以才什么都想不出来吗？',
    "Script/scenario06b_2.binu8@85787": '　速成的煽情故事。',
    "Script/scenario06b_2.binu8@85822": '　毫无感动可言、仿佛和解仪式般的过场？',
})

OVERRIDES.update({
    "Script/scenario05_10.binu8@79621": '　动摇的匂宫，依然故作坚强地发问。',
    "Script/scenario05_10.binu8@71656": '　演员要是失去了诚实，还能做什么？@n　带着多余的东西，我真的能和那个女孩一较高下吗？',
    "Script/scenario05_10.binu8@72009": '　别忘了，牢牢记住。@n　因为匂宫巡这个人，在成为女人之前，首先是一名演员。',
    "Script/scenario05_10.binu8@75477": '　不行，振作起来……你以为自己究竟是为了什么，才重新找回这份距离感的？',
    "Script/scenario05_10.binu8@75804": '@vFutaba_0625「你才是！要是以为自己能永远做那只山头上的大王，可就大错特错了！迟早会被所有人嫌弃的！」',
    "Script/scenario05_10.binu8@77376": '@vRairai_0497「啊？你那是什么眼神？把我当成圣人之类的了吗？我可是个为了演剧什么手段都用得出来的混蛋啊？」',
    "Script/scenario05_11.binu8@92326": '　天乐团长僵住了。',
    "Script/scenario06b_1.binu8@70514": '　菲利亚演出结束后，天乐团长低下了头。',
    "Script/scenario05_11.binu8@81023": '　匂宫王海那种用过度激烈的手段逼迫演员精神崩溃，甚至发展成社会问题的方法论。',
    "Script/scenario05_11.binu8@96868": '　正因为把匂宫逼入这种境地，洛基陷入不幸的演技才增添了真实感。',
    "Script/scenario06b_1.binu8@80974": '演出家A',
    "Script/scenario05_11.binu8@84223": '演出家A',
    "Script/scenario06b_3.binu8@75848": '　即便如此，心意确实存在于此。',
    "Script/scenario06b_3.binu8@75786": '　即便如此，这份心意确实存在于此。',
    "Script/scenario06b_2.binu8@86023": '　可是，我心中仅存的那一点自尊，正在呼喊着让我战斗。',
    "Script/scenario06b_4.binu8@75138": '@vMeguri_0976「即便如此，我也不建议你拖太久。一直等下去不会有任何好事。相反，有时正因为迟迟不行动，才会失去某些东西。人生就是这样不尽如人意，不是吗？」',
    "Script/scenario06b_8.binu8@39059": '　即便如此，骨气倒是十足。',
})

OVERRIDES.update({
    "Script/scenario05_11.binu8@81023": '　匂宫王海那种用过度激烈的手段逼迫演员精神崩溃，甚至发展成社会问题的方法论。',
    "Script/scenario05_11.binu8@96868": '　正因为把匂宫逼入这种境地，洛基陷入不幸的演技才增添了真实感。',
    "Script/scenario05_14.binu8@78249": '　我不确定那究竟是哪段记忆。@n　祖父讲述这些时的侧脸，充满了仿佛即将被压垮般的悲哀。',
    "Script/scenario05_14.binu8@85545": '　与展现了美丽死亡的洛基不同——他的死，承受的是丑陋而残酷的命运。',
    "Script/scenario06b_1.binu8@90486": '　我忽然想起了真正的妹妹，濑和未来。',
    "Script/scenario06b_2.binu8@81861": '　一个方便、什么都顺着自己心意的妹妹……难道不就是只把她当作宠物吗？',
    "Script/scenario06b_3.binu8@74524": '@vNanana_0499「谢、谢谢您……」',
    "Script/scenario06b_3.binu8@87908": '　哪怕只是在掌心上也无妨。',
    "Script/scenario06b_4.binu8@71885": '@vFutaba_0686「我是在感叹，这个世界竟然如此险恶。」',
    "Script/scenario06b_4.binu8@79629": '　答案早已决定。',
    "Script/scenario06b_4.binu8@80149": '「——我很开心，奈奈菜。啊，这种感情究竟该用怎样的语言来表达，我也不知道。」',
    "Script/scenario06b_6.binu8@63052": '　是奈奈菜本人的意志在渴求着它。',
    "Script/scenario06b_6.binu8@65340": '@n　——但是。',
    "Script/scenario06b_6.binu8@74693": '　你还真是个感觉敏锐的家伙。',
    "Script/scenario06b_7.binu8@33517": '　她一边说着，一边开始从包里取出大量设备。',
    "Script/scenario06b_8.binu8@35679": '　女主角像小动物一样蹦蹦跳跳，向我展现出毫不掩饰的表情。',
    "Script/scenario06b_8.binu8@37177": '　啊啊，幸福的兄妹时光。@n　没有人来打扰我们，所有人都拍着手向我们献上祝福。',
    "Script/scenario06b_8.binu8@41842": '　兄妹之间的恋情，究竟要在怎样的世界里才能得到祝福呢？',
})

OVERRIDES.update({
    "Script/scenario05_4.binu8@86048": '　匂宫有些不满地说道。',
    "Script/scenario05_5.binu8@73091": '　我想，她心里一定有自己的想法。@n　像匂宫这样的人，不会在黑暗中迷失方向。',
    "Script/scenario05_5.binu8@78550": '　虽然我还没有察觉，但匂宫的演技已经开始一点一点地发生变化。',
    "Script/scenario05_9.binu8@95955": '　这也是有道理的。@n　这不只是匂宫一个人的责任。',
    "Script/scenario05_9.binu8@101273": '@n　——匂宫能否保持内心的震惊？',
    "Script/scenario06b_1.binu8@84405": '　听到匂宫先生的决心后，我意识到自己并没有这样的决心。',
    "Script/scenario05_10.binu8@75238": '　理世话音一落，大家便各自散去。@n　双叶和团长互相吼叫，已经成了熟悉的景象。',
    "Script/scenario05_10.binu8@79185": '　团长承认，那篇诽谤井上惠的文章就是他写的。',
    "Script/scenario05_10.binu8@79917": '「团长——！！」',
    "Script/scenario05_10.binu8@81540": '@vMeguri_0804「…………这不值一提。团长就是因为这个，才贬低我的吗？」',
    "Script/scenario05_11.binu8@94301": '「没关系，都是梦而已。天乐团长逼迫巡…………」',
    "Script/scenario05_11.binu8@95984": '　唯一轻轻一笑的人，就是天乐团长。',
    "Script/scenario05_11.binu8@103475": '　巡的表情明显不对。@n『天乐团长歪歪扭扭地笑着，似乎对此很是开心。',
    "Script/scenario05_12.binu8@74117": '「团长…………」',
    "Script/scenario05_12.binu8@75493": '　是因为天乐团长很可怕吗？',
    "Script/scenario05_13.binu8@65162": '@vMeguri_0873「那就没有任何问题了。」',
    "Script/scenario06_1.binu8@105061": '　我想请你代替我，去见证那个我没能实现的未来。',
    "Script/scenario06_1.binu8@97153": '「——如果你允许我说出个人感想的话。」',
    "Script/scenario06_2.binu8@97449": '　馥郁的咖啡香气，让我的意识稍微清醒了一些。',
    "Script/scenario06_7.binu8@96613": '　你可以朝着目标努力，之后再决定它是否适合自己。',
})

OVERRIDES.update({
    "Script/scenario04_5.binu8@69601": '@vKohaku_0509「仅仅做自己，就能吸引那么多人……真是不可思议。」',
    "Script/scenario04_5.binu8@72894": '@vFutaba_0517「可是，那样的我也曾经只是个普通女孩。」',
    "Script/scenario04_5.binu8@74476": '　即使渴望被爱，也不会有好结果。@n　即使对某件事抱有期待，最终也只会遭到背叛。',
    "Script/scenario05_1.binu8@80714": '　我紧紧攥住传单，手上不由得加大了力道。',
    "Script/scenario05_1.binu8@89267": '@vNanana_0296「…………」',
    "Script/scenario05_1.binu8@93970": '@vMeguri_0420「哎呀，你知道得真详细。不过，兰比里斯剧团时期的祖父，和现在有些不同。他那时圆滑得多……是个温柔的人。」',
    "Script/scenario05_2.binu8@79702": '@vRize_0569「即便如此，我还是很高兴。你们愿意喜欢当时的我，我真的很开心。下一场演出，是要给花小姐看的、现在的我的演技。无论如何，我都得打起精神来。」',
    "Script/scenario05_3.binu8@75375": '　没想到，你还挺信任我的。',
    "Script/scenario05_4.binu8@70609": '@vMeguri_0511「……天兄」',
    "Script/scenario05_5.binu8@78050": '　匂宫亲手做的便当，看起来朴素至极，却有着沁入心底的美味。',
    "Script/scenario05_5.binu8@86586": '@vMeguri_0623「不过，我好像有点做过头了。谁让濑和君的反应太可爱了……反省，反省。」',
    "Script/scenario05_6.binu8@94486": '　这究竟是何等荒谬？@n　悲剧？不幸？',
    "Script/scenario05_8.binu8@73453": '@vMeguri_0740「因为我喜欢他。不是朋友之间的喜欢，而是把他当作异性、当作男人来喜欢。」',
    "Script/scenario05_8.binu8@78095": '@vFutaba_0611「都说恋爱会让人盲目。过不了多久，匂宫小姐也会清醒过来的。」',
    "Script/scenario05_9.binu8@95175": '@vRairai_0481「你可真行啊，巡。虽说现在也没办法了。」',
    "Script/scenario06_1.binu8@105061": '　我想请你代替我，去见证那个我没能实现的未来。',
    "Script/scenario06_1.binu8@95527": '「下次见到天乐前团长时，就让他看看吧。看看由匂宫团长率领的新生兰比里斯剧团，究竟有多厉害！」',
    "Script/scenario06_2.binu8@86912": '　未来几乎与我交替着崭露头角。他展现出足以媲美成年人的演技，让我明白了什么才是真正的天才。',
    "Script/scenario06_2.binu8@97449": '　馥郁的咖啡香气，让我的意识稍微清醒了一些。',
    "Script/scenario06_4.binu8@73415": '@vRize_0832「憧憬并没有消失。只是，我已经没有时间去想那些了。」',
    "Script/scenario06_5.binu8@63689": '　耀眼的聚光灯照在身上，灼烧着肌肤。',
    "Script/scenario06b_1.binu8@86117": '@vNanana_0431「你真的喜欢过濑和环吗？」',
    "Script/scenario06b_1.binu8@92861": '　即便如此，双叶仍然一直思念着他。@n　和那份纯洁相比，我确实还称不上恋爱了吧。',
    "Script/scenario06b_2.binu8@81364": '　正因为拥有血缘关系，两人才被牢固的羁绊连接在一起，彼此心意相通。',
    "Script/scenario06b_2.binu8@90567": '　我这一生差点对她出手，也就只有在那间白色房间里的时候。',
    "Script/scenario06b_3.binu8@77628": '　唯独不想让你知道啊。',
    "Script/scenario06b_3.binu8@79266": '@vNanana_0511「你为什么会如此丑陋？」',
    "Script/scenario06b_4.binu8@65463": '　虽然是冲动之下的举动，却把好不容易整理好的头发弄得一团糟。',
    "Script/scenario06b_5.binu8@21713": '　这种偏差似乎还没有严重到那种程度。',
    "Script/scenario06b_5.binu8@22920": '「我们两个人一起获得幸福吧。我们已经共度了那么美好的夜晚……幸福早已注定。」',
    "Script/scenario06b_6.binu8@72523": '　你该不会不只是个普通的偶像迷吧？',
    "Script/scenario06b_7.binu8@37364": '　偶像可以被塑造，可爱也能被进一步衬托出来吧。',
    "Script/scenario06b_8.binu8@38732": '@vNanana_0915「哇、哇哇哇……！那、那个……！」',
})

OVERRIDES.update({
    "Script/scenario05_10.binu8@86341": '　声音发不出来。@n　却连让对话停下来都做不到。',
    "Script/scenario05_12.binu8@89210": '@vOboro_0266「并不是那样，我的王。」',
    "Script/scenario05_2.binu8@69472": '「……你没事吧，琥珀？」',
    "Script/scenario05_2.binu8@69722": '　啊，我明白了。@n　琥珀现在怀抱的感情是……',
    "Script/scenario05_7.binu8@75566": '@vHana_0188「唔唔唔，那真遗憾。本来还想举办一年一度的成人书籍搜寻活动呢！」',
    "Script/scenario06_1.binu8@100038": '@vRize_0729「不、不是那样……」',
    "Script/scenario06_1.binu8@103941": '「——不是那样。」',
    "Script/scenario06_6.binu8@73285": '　不，不是那样，不是那样啊！',
    "Script/scenario06b_4.binu8@81551": '「我再也不会放开这只手了……！！」',
    "Script/scenario06b_6.binu8@60124": '　除此之外，我已经不再奢求。',
    "Script/scenario06b_7.binu8@43095": '　奈奈菜已经不再总是低着头了。',
    "Script/scenario07_3.binu8@80673": '　可是，我却视而不见，反复告诉自己这才是正确的。',
    "Script/scenario07_6.binu8@83373": '　知道过去、得到琥珀的鼓励之后，我仍然只是在遵循某种意志，一边告诉自己那才是正确的。',
    "Script/scenario07b_2.binu8@83678": '@vYuuen_0298「是的，正是如此。这里就是我们的天国。看吧，这里什么可怕的东西都没有。我们一定是被神所爱着的吧。」',
    "Script/scenario07b_5.binu8@42869": '「啊哈哈……是啊。」',
    "Script/scenario07b_5.binu8@44868": '「别这么说嘛。我其实挺喜欢的，尤其是主演女演员的演技，实在太精彩了。」',
    "Script/scenario07b_5.binu8@46447": '「是这样没错！就是这样！！」',
    "Script/scenario07b_5.binu8@49479": '　巡开心地指了指。',
    "Script/scenario08_3.binu8@58904": '　明明只是因为获得了超出自身水平的评价，就得意忘形起来。',
    "Script/scenario08_5.binu8@71376": '@vKohaku_0841「不是那样。哥哥毫无疑问就是天才。」',
    "Script/scenario08_5.binu8@71748": '@vKohaku_0842「才不是那样！我现在就会超越哥哥给你看。」',
    "Script/scenario08_5.binu8@83979": '　如果那才是正确的。',
    "Script/scenario09_1.binu8@40149": '　因为那些戴着面具的家伙都说，那才是正确的。',
    "Script/scenario09_1.binu8@56411": '@vFutaba_0911「一定是这样，毫无疑问。我是个会从外在形式开始判断的人。因为是男人、因为是女人，从这里开始区分，然后坠入爱河。但这并不只是我一个人的问题。」',
    "Script/scenario09_5.binu8@84229": '@vNanana_1022「是啊，是啊，请你……可怜我吧——」',
    "Script/scenario09_5.binu8@86491": '@vRize_1476「我已经不会再逃了。」',
    "Script/scenario09_5.binu8@106001": '「——我再也不会弄丢重要的东西了。」',
})

OVERRIDES.update({
    "Script/scenario05_14.binu8@74493": '　怀抱着傲慢的理想，让身边的人们沉入不幸。',
    "Script/scenario05_14.binu8@77031": '　如今的你……看起来就像昔日的你。',
    "Script/scenario05_14.binu8@81874": '　因为，你啊。@n　因为，天兄啊。',
    "Script/scenario06_6.binu8@83189": '　理世带着吐息、令人心跳加速的话语。',
    "Script/scenario06_6.binu8@83444": '　理世开心地笑了。',
    "Script/scenario06_6.binu8@83575": '　她轻轻地靠近身体。',
    "Script/scenario06_6.binu8@87209": '　那双渴求更多的眼睛。',
    "Script/scenario06_10.binu8@58427": '　我不由得退了一步。',
    "Script/scenario06_10.binu8@59819": '　我现在，真的非常幸福。',
    "Script/scenario06_10.binu8@62624": '　我不断告诉自己，这样就好。',
    "Script/scenario06_2.binu8@103901": '　轻而易举地推翻了原本的前提。',
})

OVERRIDES.update({
    "Script/scenario04_4.binu8@78271": '　理世咕咚咕咚地灌下橙汁。',
    "Script/scenario04_4.binu8@79823": '　胧离开座位，站了起来。',
    "Script/scenario04_4.binu8@80734": '　她一点点贴近身体。',
    "Script/scenario04_4.binu8@81806": '「那就更糟了！！」',
    "Script/scenario04_4.binu8@84092": '　所以，我学会了。',
    "Script/scenario04_4.binu8@93497": '　要是现在已经醉得不省人事，至少也该让我稍微袒露一点真心吧。',
    "Script/scenario04_4.binu8@93925": '　我猛然一惊，回过头去。',
    "Script/scenario04_4.binu8@94018": '　心底的黑暗，隐约露出了一角。',
    "Script/scenario05_13.binu8@57838": '　刀刃抵在喉咙前。',
    "Script/scenario05_13.binu8@59280": '　这样一来，我的戏份就结束了。',
    "Script/scenario05_13.binu8@59589": '　啊啊，这还真像我啊。',
    "Script/scenario05_13.binu8@59755": '　坐在观众席上的人们，茫然地凝视着我。',
    "Script/scenario05_13.binu8@60058": '　看见了，光。@n　我深爱的你，正在看着我。',
    "Script/scenario05_13.binu8@60842": '　所谓怜悯某个人，并不是那样的东西。',
    "Script/scenario05_13.binu8@61901": '　那句小得几乎听不见的话，像低吟般被吐了出来。',
    "Script/scenario05_13.binu8@63105": '　京子陶醉地说道。',
    "Script/scenario05_13.binu8@67404": '　她抬头望向天空，稍微思考了一会儿。',
    "Script/scenario05_13.binu8@74615": '　那种任性妄为的举止……不正是天乐来来本人吗？',
    "Script/scenario05_13.binu8@75814": '　请你不留一粒尘埃地毁灭吧。',
    "Script/scenario05_13.binu8@77295": '　我之所以无法理解她，真的只是因为她吗？',
    "Script/scenario05_13.binu8@78708": '　光是看着巡的演技，我的心就仿佛要被撕裂了。',
    "Script/scenario05_13.binu8@80750": '　回应这份祈愿的答案，始终没有传来。',
    "Script/scenario05_14.binu8@65372": '　不明白？@n　真的不明白吗？',
    "Script/scenario05_14.binu8@65595": '　本来就不是这样。@n　我的真心也不是这样。',
    "Script/scenario05_14.binu8@65780": '　所以，一定就是在那时……',
    "Script/scenario05_14.binu8@69687": '　他在我身旁，开心地笑着。',
    "Script/scenario05_14.binu8@69743": '「还是老样子……真是直率的演技啊。」',
    "Script/scenario05_14.binu8@74615": '　那种任性妄为的举止……不正是天乐来来本人吗？',
    "Script/scenario05_14.binu8@77764": '　站在她身旁的，是天兄。',
    "Script/scenario05_14.binu8@81800": '　那些点缀其中的回忆，永远不会褪色。',
    "Script/scenario05_14.binu8@81874": '　因为，你啊。@n　因为，天兄啊。',
    "Script/scenario05_14.binu8@87504": '　琥珀茫然地凝视着这一切，依旧沉浸在梦境般的感觉中。',
    "Script/scenario05_14.binu8@88011": '　倾尽一切的演员们，已经遍体鳞伤。',
    "Script/scenario05_14.binu8@89669": '　面对那恶魔般的质问。',
    "Script/scenario05_14.binu8@89974": '　　　再见了，这个世界。　　　',
})

OVERRIDES.update({
    "Script/scenario04_6.binu8@56277": '　折原冰狐这个存在，实在太过强大。@n　没有任何人能够与她并肩。',
    "Script/scenario04_6.binu8@56902": '　为了不让折原冰狐孤独，我决定继续当演员。',
    "Script/scenario04_6.binu8@74744": '@vOboro_0209「——你其实一直都讨厌折原冰狐吧？」',
    "Script/scenario04_7.binu8@38394": '　远处传来濑和同学开心的声音。@n　不知为何，让我觉得有些怀念。@n　那段幸福的时光，为什么会如此令人怀念。',
    "Script/scenario04_7.binu8@41996": '@vRize_0517「……濑和同学。」',
    "Script/scenario04_7.binu8@42169": '@vRize_0518「呐，濑和同学。你退出演艺圈之后……没有后悔吗？没有什么留恋吗？」',
    "Script/scenario05_12.binu8@78779": '　盘踞在心中的，是与折原冰狐的回忆。@n　曾经珍藏起来的重要之物，再次从心底涌现。',
    "Script/scenario06_2.binu8@99320": '「不是这样。不是这样吧。因为折原冰狐已经——！」',
    "Script/scenario06_2.binu8@101670": '「和她共演过的演员都异口同声地拒绝了下一次合作。因为他们的一切，都被折原冰狐压倒性的存在感吞噬了。演技、存在感、内在、自信……所有的感情都被击碎了。」',
    "Script/scenario06_2.binu8@103761": '@vMirai_0416「我不会演戏哦？所以，就算你们期待折原冰狐的演技，也恐怕要失望了。」',
    "Script/scenario06b_7.binu8@41077": '　虽然一路都是挑战与摸索……奈奈菜真的一直在拼命努力。',
    "Script/scenario06b_8.binu8@40056": '　和其他人气偶像一样，她也无法避免卷入舆论风波。',
    "Script/scenario07_1.binu8@104913": '@vMirai_0509「所以啊，我想让你来欺负我。那才是最适合折原冰狐的拜访方式，不是吗？」',
    "Script/scenario07b_2.binu8@87860": '@vRairai_0736「……我也该走了。」',
    "Script/scenario08_1.binu8@73930": '　折原冰狐这个异形从世上消失，已经过去了一段时间。',
    "Script/scenario08_1.binu8@74420": '　难道我的本能，也随着折原冰狐一起坠入地狱了吗？',
    "Script/scenario08_2.binu8@78725": '@vOboro_0388「——因为你才是真正的折原冰狐？」',
    "Script/scenario08_2.binu8@78964": '@vOboro_0389「那么，折原冰狐和折原京子究竟有什么不同？我们一项一项确认吧。」',
    "Script/scenario08_2.binu8@100536": '「对不起，未来……」',
    "Script/scenario08_3.binu8@81780": '　未来轻轻地点了点头。@n　那一瞬间，连我自己都不曾知晓的残酷一面，悄然露出了真容。',
    "Script/scenario08_4.binu8@60799": '　由折原冰狐主演的舞台，最终变成了只为折原冰狐而存在的作品。',
    "Script/scenario08_4.binu8@61325": '　可是，折原冰狐却丝毫不在意。',
    "Script/scenario08_5.binu8@91235": '「生活在这个世界上的每个人，都带着某种愿望来到这里。折原冰狐也是一样。」',
    "Script/scenario08_5.binu8@98925": '　我想更接近那个美丽的哈姆雷特。@n　我确信，成为折原冰狐的一部分，正是理解她的第一步。',
})

OVERRIDES.update({
    "Script/scenario02_1.binu8@80750": '@vMeguri_0100「……」',
    "Script/scenario02_1.binu8@84898": '@vMeguri_0107「～～～！！」',
    "Script/scenario01_1.binu8@79136": '@vfutaba_0031「环……」',
    "Script/scenario01_1.binu8@79739": '@vfutaba_0032「呜。」',
})

OVERRIDES.update({
    "Script/scenario09_3.binu8@53821": '「别开玩笑了！别开玩笑了！！别开玩笑了！！拥有所有人都渴望的东西，你怎么能这么轻易地说放弃就放弃！！你知道这个世上有多少人憧憬着你的才能，却只能默默埋没吗？够了……！」',
    "Script/scenario09_4.binu8@84465": '@vMirai_1038「作为演员的我，在那一天已经完成了。我已经演出了一场值得献上一切的戏。所以……我很幸福。」',
})

OVERRIDES.update({
    "Script/scenario08b_5.binu8@35354": '@vKohaku_0556「无法遏制的感情，如洪水般不断涌出。原本平静的地平线，为什么会变得如此狂乱？」',
    "Script/scenario08b_5.binu8@35924": '@vKohaku_1185「……夜晚的街道上，声音回荡着。真奇怪，为什么夜晚总能让人如此心跳加速呢。」',
    "Script/scenario08b_5.binu8@40805": '「让你陪我演了这么无聊的戏，还把令人不适的剧情强加给你，真的很抱歉。……琥珀，我……你……是这样啊。你并不是我的妹妹……」',
})

OVERRIDES.update({
    "Script/scenario04_4.binu8@91413": '　我确信，这里就是我的容身之处。@n　今后，我也要和兰比里斯的大家一起，朝着终极的自我满足努力！',
    "Script/scenario04_4.binu8@94179": '　看来，理世背负的东西，比我想象中沉重得多。',
    "Script/scenario04_5.binu8@88493": '　我不会否定这股热情。@n　在此基础上，我要继续着眼于未来。',
    "Script/scenario05_13.binu8@69527": '@vKohaku_0642「没错。我什么都没有改变。真正改变的，是除我之外的一切。」',
    "Script/scenario06b_3.binu8@72856": '　我不擅长处理这种事，所以肯定不会进展得很顺利。',
    "Script/scenario06b_5.binu8@21645": '「……嗯，倒也不能说错了吧。」',
    "Script/scenario06b_6.binu8@61253": '　看来，这内容实在很难说出口。',
    "Script/scenario06b_6.binu8@64075": '　你该不会打算把这件事公开说出去吧。',
    "Script/scenario06b_6.binu8@75280": '@vFutaba_0721「……别说傻话了。你要是这么做，天使酱会伤心的。看到喜欢的人受伤……我会很难受。」',
    "Script/scenario06b_8.binu8@42581": '　请允许我说出自己的真心。',
})

OVERRIDES.update({
    "Script/scenario03_1.binu8@54394": '咚咚。',
    "Script/scenario07_3.binu8@55968": '　却。',
    "Script/scenario07_4.binu8@71658": '咚咚。',
    "Script/scenario07_5.binu8@57125": '备忘录',
    "Script/scenario07_5.binu8@58001": '　用力。',
    "Script/scenario07b_2.binu8@74052": '　巡略显无奈。',
    "Script/scenario07b_4.binu8@65051": '　就在这时。',
    "Script/scenario09_5.binu8@85443": '　用力。',
})

OVERRIDES.update({
    "Script/scenario07_2.binu8@93221": '　倾注真心。',
    "Script/scenario07_3.binu8@81094": '@vDirectorB_0022「那么。」',
    "Script/scenario07_4.binu8@64511": '@vMeguri_1127「来吧！！」',
    "Script/scenario07_4.binu8@69503": '@vYuuen_0285「危险！！」',
})

OVERRIDES.update({
    "Script/scenario09_1.binu8@43054": '　这样的我，当然不可能交到女孩子朋友。',
    "Script/scenario09_1.binu8@62081": '「喂，双叶。」',
    "Script/scenario09_1.binu8@62196": '@vFutaba_0931「呀、呀啊～～～！！」',
    "Script/scenario09_1.binu8@62724": '　即使如此，环在我面前仍然继续戴着面具。',
    "Script/scenario09_2.binu8@72749": '@vFutaba_0955「呜、呜呜呜……呕、呕呕呕呕……」',
})

OVERRIDES.update({
    "Script/scenario09_5.binu8@101608": '　看似相似，却又并不相似。@n　那份真正的心情究竟存在于何处，我大概永远也无法明白。',
    "Script/scenario09_5.binu8@105756": '「当然。」',
    "Script/scenario09_5.binu8@107125": '@vMeguri_1774「那个嘴笨、顽固，却充满爱意的爷爷。」',
    "Script/scenario09_5.binu8@109631": '@vNanana_1039「剧、剧本现在正在修改……！对、对不起，不过再过一会儿就能完成了……！！」',
})

OVERRIDES.update({
    "Script/scenario09_1.binu8@43054": '　这样的我，当然不可能交到女孩子朋友。',
    "Script/scenario09_1.binu8@62196": '@vFutaba_0931「呀、呀啊～～～！！」',
    "Script/scenario09_1.binu8@62724": '　即便如此，环在我面前仍然继续戴着面具。',
    "Script/scenario09_2.binu8@67464": '@vFutaba_0938「原来你喜欢环啊。」',
    "Script/scenario09_2.binu8@67589": '　她立刻给出了回答。@n　因为回答得太过理所当然，反而让我吃了一惊。',
    "Script/scenario09_2.binu8@73493": '@vFutaba_0957「正因为这样……我才能继续和环做朋友。环一定……也是一样的。」',
    "Script/scenario09_2.binu8@86186": '@vMinami_0053「看环！那孩子的演技多么出色！未来，你也应该能做到那种程度！必须增加练习量才行……！！」',
    "Script/scenario09_2.binu8@87440": '@vMinami_0024「到此为止。今天是环赢了。这样算来，这是连胜多少场了？未来为什么到现在都没有进步呢？」',
    "Script/scenario09_2.binu8@88900": '　然而，与这份心情相反……我的演技却变得越来越精湛，甚至连我自己都能清楚地察觉。',
    "Script/scenario09_3.binu8@48386": '　即使被倾注了满满的不求回报的爱，我也得不到任何满足；但为了达到目的，我只需要利用这份爱。',
    "Script/scenario09_3.binu8@57780": '@vMirai_0703「……哥哥？」',
    "Script/scenario09_3.binu8@71310": '@vMirai_0925「‘一切都显得极其复杂。然而，所有事情其实都无比简单。’」',
    "Script/scenario09_3.binu8@75280": '@vMirai_0941「所以，我注定必须死在戏剧里。」',
    "Script/scenario09_3.binu8@75366": '@vMirai_0942「……是啊……哥哥……」',
    "Script/scenario09_3.binu8@75948": '@vMirai_0946「卡里古拉！你也是，你果然也有罪！」',
    "Script/scenario09_3.binu8@76661": '@vMirai_0948「一切都显得极其复杂。然而，所有事情其实都无比简单。」',
    "Script/scenario09_3.binu8@76963": '@vMirai_0949「如果当初我得到了月亮，如果只满足于爱，一切或许都会改变。可是，这颗干渴的心，又该在哪里得到治愈？」',
    "Script/scenario09_3.binu8@77512": '　我想要的是不可能之物。@n　不是戏剧，不是演戏，而是更加更加不同的东西。',
    "Script/scenario09_3.binu8@77787": '@vMirai_0951「只要世上存在不可能之物就够了。不可能之物！我曾追寻它直到世界尽头，直到自己内心的每个角落。」',
    "Script/scenario09_3.binu8@78177": '@vMirai_0952「我曾伸出双手，如今仍在伸出双手。可我遇见的始终是你，是永远站在我正前方的你。」',
    "Script/scenario09_3.binu8@78533": '@vMirai_0953「如今，我正燃烧在对你的憎恨之中。我没有走上本该前进的道路，最终却什么都没得到。我的自由也无从挽回。什么都没有！果然什么都没有！」',
    "Script/scenario09_3.binu8@79694": '@vMirai_0955「这是历史，卡里古拉。回到历史中去吧。」',
    "Script/scenario09_4.binu8@73857": '@vMirai_0971「哥哥无法接受妹妹的死。他原以为一切都是为了妹妹，却后悔自己逼得妹妹走投无路，最终害死了她。未来，都是因为你选择了那样自杀——！！」',
    "Script/scenario09_4.binu8@74502": '@vMirai_0976「不，并不是这样。如果你再坚强一点，就不会发生这种事。其实你应该早就明白了吧？明白自己的愿望，自己的心愿，以及真正的爱！」',
    "Script/scenario09_4.binu8@78530": '@vMirai_0999「那么，未来，你所祈愿的那个‘如果’世界会是什么样？你所期望的剧本，究竟会是什么样子？」',
    "Script/scenario09_4.binu8@79055": '@vMirai_1003「真是个残酷的妹妹。那不是最差劲的愿望吗？作为妹妹，不是应该永远以妹妹的身份爱着哥哥吗？」',
    "Script/scenario09_4.binu8@81092": '@vMirai_1016「如果是一个方便的世界，或许就能让哥哥幸福吧。」',
    "Script/scenario09_4.binu8@81540": '@vMirai_1020「……是啊。未来就是这样的女孩嘛。」',
    "Script/scenario09_4.binu8@81629": '@vMirai_1021「真是意味深长啊。」',
    "Script/scenario09_4.binu8@82590": '@vMirai_1030「……哥哥。」',
    "Script/scenario09_4.binu8@85222": '@vMirai_1041「那一天，那一夜，我舍弃了一切感情，下定了决心。可是，为什么会变成这样的结果？」',
})

OVERRIDES.update({
    "Script/scenario08b_1.binu8@72680": '「哦，是琥珀啊。有什么事吗？」',
    "Script/scenario08b_1.binu8@76702": '@vFutaba_0840「哇——，你那副得意的表情真让人火大。琥珀酱，我们还是两个人一起去吧！」',
    "Script/scenario08b_1.binu8@81400": '@vfutaba_0047「完全没听懂！环的说明又烂，周围的观众又吵！根本不可能集中精神看戏嘛！」',
    "Script/scenario08b_1.binu8@83122": '　琥珀双眼闪闪发亮地说道。',
    "Script/scenario08b_1.binu8@84817": '　琥珀一脸认真地说道。',
    "Script/scenario08b_1.binu8@85111": '　琥珀鼓起脸颊，可爱地闹起了别扭。',
    "Script/scenario08b_1.binu8@86071": '@vKohaku_0919「嗯，啾……」',
    "Script/scenario08b_1.binu8@87850": '@vKohaku_0926「哥哥……我就在这里哦。」',
    "Script/scenario08b_1.binu8@89274": '「喂、喂，双叶！！啊——真是的！对不起，打扰了——！！」',
    "Script/scenario08b_1.binu8@89712": '　对方的态度确实有问题，但我也没资格说别人。',
    "Script/scenario08b_2.binu8@75555": '@vMeguri_1710「嗯，没错。你就是濑和君的妹妹吧。我是匂宫巡，请多关照。」',
    "Script/scenario08b_2.binu8@80063": '　琥珀歪着头说道。',
    "Script/scenario08b_2.binu8@80924": '　琥珀满脸喜悦地宣布道。',
    "Script/scenario08b_2.binu8@94178": '「很遗憾，琥珀。」',
    "Script/scenario08b_3.binu8@15837": '@vMika_0153「……如果能再次见到那个孩子，我该说什么呢？对不起？你没有错？啊啊……我犯下的最大罪过，或许就是没能活成一个能够对她说出‘我爱你’的人吧。」',
    "Script/scenario09_1.binu8@47031": '@vMirai_0797「这是什么意思？」',
    "Script/scenario09_1.binu8@54579": '@vFutaba_0904「……那是不可能的。」',
    "Script/scenario09_1.binu8@62949": '　所以，至少……',
    "Script/scenario09_2.binu8@70961": '@vFutaba_0950「什、什么！？不、不是……！……你不是应该明白我的心情吗？」',
    "Script/scenario09_2.binu8@74901": '@vFutaba_0960「消、消失！？你开什么玩笑！把我们搅得天翻地覆之后，居然想一声不响地消失，谁会允许这种事啊！」',
    "Script/scenario09_2.binu8@88354": '「对不起，未来……」',
    "Script/scenario09_3.binu8@55600": '　我无法打破名为自我的外壳，只能一再刺激哥哥的情绪。',
    "Script/scenario09_3.binu8@58656": '　那里究竟存在着怎样的幸福，又有什么意义呢？',
    "Script/scenario09_3.binu8@74084": '　我一边渴望有人能够理解我，@n　一边又觉得反正不会有人理解我。',
    "Script/scenario09_4.binu8@95490": '　这一次，一定要……',
    "Script/scenario09_5.binu8@95685": '@vOmi_0118「——你要活下去。活着，继续演戏。演到死为止。」',
    "Script/scenario09_5.binu8@110387": '@vMeguri_1785「你们真是一点都不留情。把一个正在伤心的少女硬拉出来……啊啊，真是残酷的人啊……！」',
    "Script/scenario09_5.binu8@110992": '@vMeguri_1786「……要是一直低着头，天兄会笑话我的。唯独这一点，我可不想承受。」',
    "Script/scenario09_5.binu8@111465": '@vMeguri_1788「我……现在的话，或许能演出最棒的戏。」',
})

OVERRIDES.update({
    "Script/scenario08_4.binu8@54922": '　我甚至已经无法再直视未来的脸。',
    "Script/scenario08_4.binu8@62801": '　她已经到达极限。@n　可是，我并没有近到能够向她伸出援手的距离。',
    "Script/scenario08_4.binu8@64518": '「……如果不这么想，我就无法承受失去你的痛苦，对吗。」',
    "Script/scenario08_4.binu8@68410": '「梦见了失去你。啊啊，太好了……原来这一切，全都是幻觉。」',
    "Script/scenario08_5.binu8@73332": '「我觉得，我从来没能把任何话传达给你。就连那天晚上……我也没能把心意告诉你。」',
    "Script/scenario08_5.binu8@74760": '　那个称呼我为妹妹的你。@n　以及即便如此，依然感到喜悦的我。',
    "Script/scenario08_5.binu8@75123": '　我无法决定究竟是哪一边。@n　因为一旦做出决定，我就不再是我自己了。',
    "Script/scenario08_5.binu8@77097": '「等、等一下，双叶。别再让我更加混乱了。头、头开始痛了……这到底是怎么回事？」',
    "Script/scenario08_5.binu8@80860": '　我以为那是出于好意，于是选择相信，结果却得到了完全相反的答案。',
    "Script/scenario08_5.binu8@82048": '　我再也无法离开镇静剂，只能一边尖叫一边疯狂挣扎。',
    "Script/scenario08_5.binu8@83351": '　我明明知道不能再这样下去，身体却不听使唤。',
    "Script/scenario08_5.binu8@85145": '　日复一日地自我厌恶与悔恨，外界的声音根本传不到我的脑海。',
    "Script/scenario08_5.binu8@88640": '　然而，无论火焰烧得多么猛烈，我都无法从观众席上移动一步。',
    "Script/scenario08_5.binu8@89671": '「我想，我只是无法接受那家伙的死。」',
    "Script/scenario08_5.binu8@91019": '　——只要找回这份感情，你就再也无法维持这个世界了，对吧？',
})

OVERRIDES.update({
    "Script/scenario08_1.binu8@82593": '@vMirai_0566「所以你逃不掉。就算你的朋友回到了家，你也会继续被囚禁在这个世界里。你把永不改变的美德，刻进了他们的灵魂之中。」',
    "Script/scenario08_1.binu8@89519": '@vOboro_0346「……喜欢一个人的心情，是无法控制的呢。要是能停留在友情上，也就不用这么辛苦了吧。」',
    "Script/scenario08_1.binu8@95150": '@vKohaku_0805「嗯。我没能演好洛基。无论模仿谁的演技，都不可能胜过巡小姐的表演。所以……能演奥丁，真的太好了。」',
    "Script/scenario08_1.binu8@96631": '「空空如也又怎么样？那并不能成为损害你魅力的理由。如果里面是空的，那就由我来填满。从今以后一起经历各种各样的戏剧……一起在这个世界里活下去吧。」',
    "Script/scenario08_1.binu8@98198": '「……我知道。我知道。但是，现实就是我还在这里……我已经没有什么留恋了……！！」',
    "Script/scenario08_2.binu8@71084": '　以天乐座长为首的剧团成员们。@n　他们无法把巡一个人留下，于是创造并渴望了这个世界。',
    "Script/scenario08_2.binu8@78100": '@vOboro_0385「——把折原冰狐召回来。她绝不会原谅这个世界。」',
    "Script/scenario08_2.binu8@80500": '「即便如此，这家伙也不是未来，不可能成为折原冰狐。仅凭这些，还不足以表现出那家伙的异常。」',
    "Script/scenario08_2.binu8@85870": '@vMirai_0607「我以为已经舍弃的东西回来了。所以，我已经不能再继续当折原京子了。我……嗯，我是未来。」',
    "Script/scenario08_2.binu8@94029": '　她深爱的丈夫，竟然抛弃了身为失败者的自己，转而投向那个成功的出轨对象……这让她从心底无法原谅。',
    "Script/scenario08_2.binu8@98364": '@vMinami_0022「未来，你为什么连吩咐的事都做不到！！一字不差地背下剧本，这种事连幼儿园小孩都做得到吧！！不仅要记住自己的台词，别人的台词也当然要记住啊！！」',
    "Script/scenario08_3.binu8@70231": '　那个无法注入感情的玩偶，究竟去了哪里？@n　那个充满虚幻与悲哀、宛如天使般的妹妹，为什么会消失？',
    "Script/scenario08_3.binu8@75619": '@vMinami_0040「你为什么不能演出像未来那样的演技？只是因为一点微不足道的成功就得意忘形，根本没好好练习吧！？」',
    "Script/scenario08_3.binu8@86187": '@vMirai_0693「哥哥越是作为演员成功，就会越讨厌我。他会憎恨我、嫉妒我、厌恶我……这种结果，正是我求之不得的。」',
    "Script/scenario08_3.binu8@89862": '　啊啊，好恨，好恨。@n　我为什么不是站在那个位置的人，这件事真的无法原谅。',
    "Script/scenario08_4.binu8@53836": '「……啊，是啊。我最讨厌的是作为演员的你。那份超越我一切的才能，我嫉妒得恨不得发疯。」',
    "Script/scenario08_4.binu8@59219": '@vMirai_0775「初次见面，我是折原冰狐。大家，请多关照。」',
    "Script/scenario08_4.binu8@59999": '　作为哥哥，温柔地守望妹妹的成功……这种事，我当然做不到。',
    "Script/scenario08_4.binu8@65395": '　眼泪止不住地流。@n　只要能从这种痛苦中得到解脱，无论怎样都好。',
    "Script/scenario08_5.binu8@72467": '　可是，他看起来很幸福。@n　他把我当成妹妹，兴奋得滔滔不绝。',
    "Script/scenario08_5.binu8@83461": '「……我活下来又能怎么样？明明应该代替未来去死的人，是我才对。」',
    "Script/scenario08_5.binu8@92672": '@vKohaku_0872「为了让折原京子变回濑和未来。只要找回对哥哥的感情，她就无法保持冷静。结果，虚构世界出现了裂缝，她也就想起了一切。」',
    "Script/scenario08_5.binu8@94533": '　她想舍弃的，是爱与才能。@n　她明白，只拥有其中一方是无法获得幸福的。',
})

OVERRIDES.update({
    "Script/scenario07b_3.binu8@24239": '@vMeguri_1373「早上好，环。」',
    "Script/scenario07b_3.binu8@24319": '@vMeguri_1374「嗯，睡得可香了。我看着你可爱的睡脸，都看入迷了。」',
    "Script/scenario07b_3.binu8@24518": '「已经这个时间了吗。」',
    "Script/scenario07b_3.binu8@24562": '@vMeguri_1375「没睡多久哦？大概五到十分钟吧。」',
    "Script/scenario07b_3.binu8@24664": '「……感觉像是睡了很久。简直像是打了好几天的瞌睡。」',
    "Script/scenario07b_3.binu8@24974": '@vMeguri_1377「要不要确认一下？」',
    "Script/scenario07b_3.binu8@25799": '「……为了让我明白这里就是现实。早安吻？」',
    "Script/scenario07b_3.binu8@26057": '@vMeguri_1384「这是希望你爱我的信号哦。」',
    "Script/scenario07b_3.binu8@26297": '「……巡害羞了。脸颊微微泛红呢。」',
    "Script/scenario07b_3.binu8@26386": '@vMeguri_1385「只是夕阳的恶作剧罢了。才不是害羞……」',
    "Script/scenario07b_3.binu8@26794": '@vMeguri_1387「干什么，一直盯着我看。」',
    "Script/scenario07b_3.binu8@26848": '「只是看入迷了而已。」',
    "Script/scenario07b_3.binu8@26886": '@vMeguri_1388「……我明白了。原来害羞的是你啊。」',
    "Script/scenario07b_3.binu8@27123": '「我也想让巡尝尝害羞的感觉。」',
    "Script/scenario07b_3.binu8@27582": '@vMeguri_1391「才没有害羞！」',
    "Script/scenario07b_3.binu8@27624": '「不，你害羞了。你就是在害羞。」',
    "Script/scenario07b_3.binu8@27816": '「我想再吻一次。」',
    "Script/scenario07b_3.binu8@27860": '@vMeguri_1393「你想怎么样就怎么样啊。」',
    "Script/scenario07b_3.binu8@27926": '「我想让你主动来。」',
    "Script/scenario07b_3.binu8@28115": '「那就由我来吧。」',
    "Script/scenario07b_3.binu8@28207": '　我强硬地压在巡身上。@n　就这样单方面夺走了她的嘴唇。',
    "Script/scenario07b_3.binu8@28444": '@vMeguri_1397「呜、啊……！你、你这家伙……！！」',
    "Script/scenario07b_3.binu8@28593": '@vMeguri_1398「真是太强硬了……！！」',
    "Script/scenario07b_3.binu8@28745": '「呐，再让我触碰你一会儿，可以吗？」',
    "Script/scenario07b_4.binu8@58350": '@vMeguri_1508「我害怕睡觉。总觉得一睁开眼，就会发现自己躺在那座山丘的草丛里。」',
    "Script/scenario07b_4.binu8@58538": '@vMeguri_1509「我想永远、永远地在这个没有尽头的多维世界尽头徘徊。随着细碎的震动摇晃肩膀，做着美梦般的梦。」',
    "Script/scenario07b_4.binu8@58966": '@vMeguri_1510「好开心。」',
    "Script/scenario07b_4.binu8@59073": '@vMeguri_1511「啊啊，这就是真正的幸福啊。」',
    "Script/scenario07b_4.binu8@59291": '@vRairai_0739「……哟，濑和。来得正好。」',
    "Script/scenario07b_4.binu8@59354": '「您、您好……」',
    "Script/scenario07b_4.binu8@59963": '「话是这么说没错……」',
    "Script/scenario07b_4.binu8@61442": '@vRairai_0748「我、我才没担心她！她怎么样都无所谓！……不过，要是她被什么奇怪的男人骗了，我可不知道该怎么向老头子交代。就这个意义上说，我多少算是她的哥哥吧……」',
    "Script/scenario07b_4.binu8@62970": '@vRairai_0752「爱、爱什么……！？你、你别说这种让人害臊的话……这种话，给我只在本人面前说……」',
    "Script/scenario07b_4.binu8@63206": '@vRairai_0753「吵、吵死了！！……不过，这么说来，你们还没有正式交往啊……」',
    "Script/scenario07b_4.binu8@63427": '@vRairai_0754「啊？那不是当然的吗。她还太早接触恋爱了。就凭你这种小不点，我可不觉得你能让她幸福。更可靠的对象，才配做巡的结婚对象。」',
    "Script/scenario07b_4.binu8@63712": '「……结、结婚？」',
    "Script/scenario07b_4.binu8@64049": '　看来，天乐座长的恋爱观，和一般人相去甚远。',
    "Script/scenario07b_4.binu8@64392": '「就、就是关系比较亲密……」',
    "Script/scenario07b_4.binu8@64448": '@vRairai_0757「那算什么？我说的是更具体的关系。」',
    "Script/scenario07b_4.binu8@64768": '@vRairai_0758「……喂，濑和。难道你……」',
    "Script/scenario07b_4.binu8@65013": '「天、天乐座长……！」',
    "Script/scenario07b_4.binu8@65364": '@vRairai_0761「我、我没那个意思……！！」',
    "Script/scenario07b_4.binu8@65628": '@vRairai_0762「呜、呜……！我、我无话可说……！！」',
    "Script/scenario07b_4.binu8@66851": '@vRairai_0770「什么？明明没交往？那你们到底是什么关系啊？」',
    "Script/scenario07b_4.binu8@66992": '@vMeguri_1519「嗯……这个嘛。」',
    "Script/scenario07b_4.binu8@67099": '@vMeguri_1520「我是他的性伴侣哦。」',
    "Script/scenario07b_4.binu8@67304": '@vMeguri_1521「因为我已经是大人了嘛。」',
    "Script/scenario07b_4.binu8@67589": '@vRairai_0773「……濑和，你把我惹火了。」',
    "Script/scenario07b_4.binu8@67887": '@vRairai_0774a「你、你这家伙！！至少也该像个学生一样，矜持一点……呜……」',
    "Script/scenario07b_4.binu8@68005": '@vRairai_0774b「你这混蛋！！果然还是不能原谅你！」',
    "Script/scenario07b_4.binu8@68151": '@vYuuen_0305「好啦，到此为止。来来小姐，请冷静一点。别把巡的玩笑当真。」',
    "Script/scenario07b_4.binu8@68312": '@vRairai_0775「悠……！！可是这家伙，把巡当成……性、性……」',
    "Script/scenario07b_4.binu8@69218": '@vRairai_0777「一演戏就没那种闲工夫了！而且女人的心思我也搞不懂……」',
    "Script/scenario07b_4.binu8@69448": '@vRairai_0778「啊？你当然是特别的。你以为我们认识多少年了？」',
})

OVERRIDES.update({
    "Script/scenario07b_1.binu8@81633": '@vMeguri_1220「——出发！」',
    "Script/scenario07b_1.binu8@96691": '@vMeguri_1265「在阴沉的北海天空下」',
    "Script/scenario07b_1.binu8@96842": '@vMeguri_1267「不知何时才会结束的诅咒」',
    "Script/scenario07b_1.binu8@99711": '「因为乘客不只是我们。」',
    "Script/scenario07b_1.binu8@100117": '@vMeguri_1281「顺便一提，我还是处女哦。这个世上没有任何人知道我身体的甜美。」',
    "Script/scenario07b_1.binu8@100320": '@vMeguri_1282「听说战国时代的武士，在交剑之前会先报上名号。所以我也试着遵循那个作法。」',
    "Script/scenario07b_1.binu8@100778": '「别用这种像是被人硬逼着说出来的说法！」',
    "Script/scenario07b_1.binu8@101334": '「……你为什么要问这种事？有什么意义吗？」',
    "Script/scenario07b_1.binu8@101435": '@vMeguri_1286「真是拐弯抹角的问题呢。你的期待和不安，我都能清楚地感受到。」',
    "Script/scenario07b_1.binu8@102238": '「时机什么的无所谓啦！如果遇到了想和她做那种事的人，当然越早越好……如果没有，那就等很久以后也行吧……？」',
    "Script/scenario07b_1.binu8@102880": '「有、有喜欢的人……如果已经有恋人的话，那当然……！！」',
    "Script/scenario07b_1.binu8@102981": '@vMeguri_1292「如果有恋人呢？」',
    "Script/scenario07b_1.binu8@103124": '「……你、你这混蛋……！！」',
    "Script/scenario07b_1.binu8@103174": '@vMeguri_1294「呵呵呵，希望你能早点遇到一个漂亮又出色的女朋友呢。」',
    "Script/scenario07b_1.binu8@103500": '「真是多管闲事！！」',
    "Script/scenario07b_1.binu8@103727": '@vMeguri_1296「……啊——真开心。」',
    "Script/scenario07b_1.binu8@103840": '「你其实什么都明白吧。」',
    "Script/scenario07b_2.binu8@65534": '@vMeguri_1299「无论去到哪里。」',
    "Script/scenario07b_2.binu8@66420": '@vNanana_0997「很简单哦！看，看到那边了吗？」',
    "Script/scenario07b_2.binu8@66987": '@vNanana_1000「是不幸哦。来，吃吧？」',
    "Script/scenario07b_2.binu8@67169": '@vMeguri_1304「……好甜。」',
    "Script/scenario07b_2.binu8@67351": '@vNanana_1001「不是哦，是不幸。」',
    "Script/scenario07b_2.binu8@68773": '@vNanana_1006「请用一个？」',
    "Script/scenario07b_2.binu8@68824": '「……不用了，我……」',
    "Script/scenario07b_2.binu8@68915": '「我已经吃得够多，肚子很饱了。所以还是算了吧。」',
    "Script/scenario07b_2.binu8@69004": '@vNanana_1007「……这样啊。」',
    "Script/scenario07b_2.binu8@69224": '@vNanana_1008「环君你们可以去任何地方呢。甚至能自由前往我无法去的地方。」',
    "Script/scenario07b_2.binu8@69359": '@vMeguri_1308「不是那样。我们虽然哪里都能去，却又哪里都去不了。我们只能存在于这里。」',
    "Script/scenario07b_2.binu8@69533": '@vNanana_1009「已经足够了！在这里，你们会让我看到各种各样的景色，也会带我去喜欢的地方。啊，说实话……我或许有一点羡慕你们。」',
    "Script/scenario07b_2.binu8@70256": '@vNanana_1012「明明根本不需要！啊哈哈……巡小姐真温柔啊。」',
    "Script/scenario07b_2.binu8@70501": '@vMeguri_1310「……我、我只是……！」',
    "Script/scenario07b_2.binu8@70501": '@vMeguri_1310「……我、我只是……！」',
    "Script/scenario07b_2.binu8@71389": '「……要不要告白呢。」',
    "Script/scenario07b_2.binu8@73354": '「天乐座长真是乱来啊。」',
    "Script/scenario07b_2.binu8@73410": '@vMeguri_1321「呵呵呵，悠小姐似乎也很辛苦呢。」',
    "Script/scenario07b_2.binu8@74087": '@vMeguri_1324「悠小姐当然最喜欢天兄了。这是全体团员的共识。」',
    "Script/scenario07b_2.binu8@74796": '「……可是，那样的话……」',
    "Script/scenario07b_2.binu8@74887": '@vMeguri_1327「是啊。这样下去，两个人大概会在无法结合的情况下各奔前程吧。毕竟，他们能在一起的只有学生时代。」',
    "Script/scenario07b_2.binu8@75409": '@vMeguri_1329「正因为尊重彼此珍视的东西，才选择了最合适的距离。她不是被恋爱的热情冲昏头脑，只顾眼前。悠小姐已经是个大人了，真的很帅气。」',
    "Script/scenario07b_2.binu8@75735": '@vMeguri_1330「是啊。那是一段宛如微小祈祷般的恋情……真美好。」',
    "Script/scenario07b_2.binu8@76391": '@vMeguri_1332「是啊。他们不是看起来很幸福吗？成为恋人并不是幸福的必要条件。」',
    "Script/scenario07b_2.binu8@78074": '@vMeguri_1339「环……我现在真的非常幸福。要是还不知足地继续贪求……一定会遭报应的。」',
    "Script/scenario07b_2.binu8@79748": '「我、我……！」',
    "Script/scenario07b_2.binu8@80481": '「因为幸福仿佛就要从掌心溜走了。」',
    "Script/scenario07b_2.binu8@81159": '「我是不是只要努力到明天，让巡对我说喜欢就好了？」',
    "Script/scenario07b_2.binu8@81921": '「巡……我想再吻你一次。」',
    "Script/scenario07b_2.binu8@81986": '@vMeguri_1351「真不解风情。明明这种话不该直接说出口的。」',
    "Script/scenario07b_2.binu8@82435": '@vMeguri_1354「……好啦，到此为止。下次再继续。」',
    "Script/scenario07b_2.binu8@82504": '「故意吊我胃口……」',
    "Script/scenario07b_2.binu8@83222": '@vMeguri_1358「有所欠缺，才会幸福。我们可别忘了这一点。」',
    "Script/scenario07b_2.binu8@84011": '@vRairai_0731「那老头子跑哪儿去了？」',
})

OVERRIDES.update({
    "Script/scenario07_6.binu8@60984": '@vOmi_0081「你这个笨蛋！！我说多少遍你才能明白！！！ 」',
    "Script/scenario07_6.binu8@61228": '@vOmi_0082「去学习，去观察，去仔细体会。你有义务作为演员活下去。」',
    "Script/scenario07_6.binu8@62436": '@vMeguri_1140「你、你这家伙……竟敢打可爱女孩的脸……！！！」',
    "Script/scenario07_6.binu8@62544": '@vOmi_0086「吵死了！嘴上说不明白，就只能让你用疼痛明白！！」',
    "Script/scenario07_6.binu8@62664": '@vMeguri_1141「哼，那我也要揍你——！！」',
    "Script/scenario07_6.binu8@63437": '@vMeguri_1143「……真是个可悲的人。」',
    "Script/scenario07_6.binu8@64541": '@vMeguri_1144「这不是当然的吗？回想起过去那些日子，我怎么可能喜欢得起来。真的……一件美好的回忆都没有。」',
    "Script/scenario07_6.binu8@64748": '　怒吼与辱骂，宛如地狱般的练习日子。@n　交不到朋友，也与家人分离，只能和顽固的老头子两个人艰难地生活。',
    "Script/scenario07_6.binu8@65290": '@vMeguri_1146「看着落魄的爷爷，也不是件坏事呢。」',
    "Script/scenario07_6.binu8@65576": '@vMeguri_1147「……事到如今才后悔，已经太迟了。」',
    "Script/scenario07_6.binu8@65698": '@vMeguri_1148「——别开玩笑了！！」',
    "Script/scenario07_6.binu8@66109": '@vOmi_0089「……等这场演出结束，你就被解雇了。想去哪家剧团，就随你喜欢转过去吧。」',
    "Script/scenario07_6.binu8@66235": '@vMeguri_1149「我说了我不明白这是什么意思！既然让我当主演，为什么偏偏现在才说这种话！」',
    "Script/scenario07_6.binu8@67688": '@vOmi_0095「每当你在那些人面前演戏，他们的心就会一点点崩溃。被一个乳臭未干的臭小鬼打击得彻底失去信心。你别以为演技好，戏就一定会变好！因为你，其他人的干劲都被削弱了！」',
    "Script/scenario07_6.binu8@68012": '@vMeguri_1152「……怎、怎么会……！！」',
    "Script/scenario07_6.binu8@68075": '@vOmi_0096「啊，对你来说，或许确实与你无关。普通剧团大概会迁就你的标准吧。」',
    "Script/scenario07_6.binu8@68270": '@vOmi_0097「很遗憾，这里是失败者的聚集地。按照民主的规矩，该离开的是你。而且这可不只是我个人的意见。」',
    "Script/scenario07_6.binu8@68572": '@vMeguri_1154「我、我只是想和大家一起，演一场快乐的戏而已……！！」',
    "Script/scenario07_6.binu8@69144": '@vMeguri_1156「谁说要把我变成天才了！！要不是你多管闲事，我本来会是个普通女孩的！演戏什么的……要是当初没遇见就好了……！！」',
    "Script/scenario07_6.binu8@69833": '@vMeguri_1158「才没有那种东西！别自作主张地胡说……！！」',
    "Script/scenario07_6.binu8@69950": '@vOmi_0100「即便如此，我还是……」',
    "Script/scenario07_6.binu8@70369": '@vMeguri_1160「……真差劲。」',
    "Script/scenario07_6.binu8@71097": '「圣埃克苏佩里的故事在全世界都非常受欢迎。我也很喜欢。」',
    "Script/scenario07_6.binu8@71345": '@vMeguri_1165「太悲哀了。因为我只能觉得，一切都已经无可挽回。」',
    "Script/scenario07_6.binu8@71566": '@vMeguri_1166「你对我来说，和其他十万个男孩没有任何不同。所以，就算你消失了也没关系；对你来说，就算我消失了也没关系。对你而言，我也和其他十万只狐狸没有任何不同。」',
    "Script/scenario07_6.binu8@71999": '@vMeguri_1167「但是，如果你驯服了我，我们就会彼此成为不可或缺的存在。对你来说，我会成为全世界唯一的人；对我来说，你也会成为全世界唯一的狐狸……」',
    "Script/scenario07_6.binu8@72295": '「……嗯，就是这个。狐狸的话语，确实能传达到心里。」',
    "Script/scenario07_6.binu8@72378": '「只有驯服过它、与它建立羁绊的人，才能真正理解它。」',
    "Script/scenario07_6.binu8@73072": '　巡用温柔的语调继续说道。',
    "Script/scenario07_6.binu8@75599": '@vMeguri_1177「从一开始，我就觉得很烦人。」',
    "Script/scenario07_6.binu8@75816": '「每次登上舞台，你都会眯起眼睛，憎恨那道光吗？」',
    "Script/scenario07_6.binu8@75902": '@vMeguri_1180「……不是。」',
    "Script/scenario07_6.binu8@76234": '@vMeguri_1181「冰冷的灯光，或者说……天花板。」',
    "Script/scenario07_6.binu8@76558": '@vMeguri_1182「……从舞台上看出去的观众席，比我想象中更加宽广。但是其中的一切，都只有冰冷的质感。」',
    "Script/scenario07_6.binu8@76738": '　“最重要的东西，肉眼是看不见的……”',
    "Script/scenario07_6.binu8@78122": '「……大家已经死了。也差不多该是面对现实的时候了。」',
    "Script/scenario07_6.binu8@78377": '「你应该还记得火焰燃烧时的灼热，也应该听见过人们的喊声。那地狱般的景象，你不可能忘记。最后的演剧，《哈姆雷特》的公演……」',
    "Script/scenario07_6.binu8@78800": '@vMeguri_1188「《哈姆雷特》的公演早就结束了……现在应该为了下一场戏……」',
    "Script/scenario07_6.binu8@79325": '@vMeguri_1191「大家明明都好好地在这里！只是暂时离得有点远……别说他们已经死了这种残酷的话！！」',
    "Script/scenario07_6.binu8@79766": '「……你是大家的希望。所以，必须继续向前走。」',
    "Script/scenario07_6.binu8@80021": '「战斗吧，巡。战斗，战斗，再战斗……就算只有你一个人，也要活在未来。」',
    "Script/scenario07_6.binu8@80998": '@vMeguri_1196「……真是一群傻瓜。你们太沉溺于故事里的梦想了。」',
    "Script/scenario07_6.binu8@81091": '@vMeguri_1197「你们太高估我了。你们真的觉得，这样我就能得到幸福吗？」',
    "Script/scenario07_6.binu8@81861": '@vMeguri_1201「但是，如果那就是你的愿望，我会老老实实听从。因为……这里已经没有大家了吧？既然如此，也就没有继续留恋的理由了。」',
    "Script/scenario07_6.binu8@82985": '@vMeguri_1204「你得负起责任。」',
    "Script/scenario07_6.binu8@83939": '@vMeguri_1208「再见了，环。如果你要求我面对正确的道路……那你自己也好好面对现实吧。」',
    "Script/scenario07_6.binu8@84086": '「……巡……！」',
    "Script/scenario07_6.binu8@85009": '@vMeguri_1210「……好热。」',
    "Script/scenario07_6.binu8@85248": '@vMeguri_1211「大家，都被烧掉了。」',
    "Script/scenario07_6.binu8@85869": '@vMeguri_1214「……或许这样也不错呢。」',
    "Script/scenario07_6.binu8@86098": '@vMeguri_1215「大家，请等着我。」',
})

OVERRIDES.update({
    "Script/scenario07_5.binu8@57288": '@vYuuen_0286「……来来小姐。」',
    "Script/scenario07_5.binu8@58039": '@vRairai_0701「接下来要开始的，是我们最后一场演剧。你可千万别抱什么奇怪的希望。」',
    "Script/scenario07_5.binu8@58247": '@vHana_0271「当然，我明白。」',
    "Script/scenario07_5.binu8@58355": '@vRairai_0702「戏剧真正的乐趣，恰恰是在落幕之后才会到来。」',
    "Script/scenario07_5.binu8@58569": '@vHana_0272「……我不能就这样把巡小姐一个人留下。」',
    "Script/scenario07_5.binu8@59066": '@vRairai_0704「算了，没关系。」',
    "Script/scenario07_5.binu8@59262": '@vRairai_0705「故事若不结束，就不会美丽。」',
    "Script/scenario07_5.binu8@59715": '@vMirai_0546「可是，他们其实在那时就已经死了。无法推翻的现实，马上就等在眼前。就这样落幕，真的好吗？就这样结束故事，真的好吗？」',
    "Script/scenario07_5.binu8@59975": '@vMirai_0547「——匂宫巡无法承受。因为对她来说，兰比里斯剧团就是她的一切。」',
    "Script/scenario07_5.binu8@60847": '@vKohaku_0748「那么，现在的你们……？」',
    "Script/scenario07_5.binu8@61035": '@vRairai_0708「……算了，那些事无所谓。对我们来说重要的是，你究竟能不能彻底成为奥丁。为此，你必须知道未来。」',
    "Script/scenario07_5.binu8@61290": '@vKohaku_0749「未来？」',
    "Script/scenario07_5.binu8@61323": '@vRairai_0709「没错。就像失去一只眼睛、观测到灭亡未来的奥丁一样……你必须知道即将到来的毁灭。那就是故事的终焉，也是兰比里斯剧团的崩溃。」',
    "Script/scenario07_5.binu8@61942": '@vRairai_0711「正因如此，你必须彻底成为完美的奥丁。作为巡的对手、同伴，成为能与她并肩而立的人。」',
    "Script/scenario07_5.binu8@62155": '@vKohaku_0750「现在不是演戏的时候……！我得马上去找巡小姐……！」',
    "Script/scenario07_5.binu8@62562": '@vKohaku_0751「可是……巡小姐她……！！」',
    "Script/scenario07_5.binu8@62981": '@vKohaku_0753「……我明白了。」',
    "Script/scenario07_5.binu8@63073": '@vKohaku_0754「告诉我，奥丁究竟怀抱着怎样的感情。」',
    "Script/scenario07_5.binu8@64148": '@vRairai_0716「因为这场演剧，是兰比里斯剧团的毕业公演。我们已经死了，完成自己的使命后就该退场。因此，我们不能再出演主角级别的角色。」',
    "Script/scenario07_5.binu8@64697": '@vKohaku_0758「既然如此，就更应该……」',
    "Script/scenario07_5.binu8@64918": '@vRairai_0718「不用了，什么告别致辞都不需要。那只会让人更加难受，不是吗。」',
    "Script/scenario07_5.binu8@65780": '@vYuuen_0291「至少在我面临死亡的危机时……我曾经许下愿望。啊啊，我还想演更多戏。还想和巡一起，在聚光灯下绽放光芒。」',
    "Script/scenario07_5.binu8@66384": '@vKohaku_0762「……我不明白。如果你真的担心巡小姐，明明一直陪在她身边就好了。」',
    "Script/scenario07_5.binu8@68658": '@vKohaku_0767「一点也不值得惋惜。」',
    "Script/scenario07_5.binu8@74568": '@vRairai_0726「结局已经决定好了，谁也无法改变。你就贯彻自我，直到最后吧。因为这是只有你才能演好的角色。」',
    "Script/scenario07_5.binu8@75120": '@vKohaku_0786「而我，也终于真正成为了奥丁。」',
    "Script/scenario07_5.binu8@76898": '「我们……必须长大成人吗？」',
    "Script/scenario07_5.binu8@76975": '@vKohaku_0790「不，不是那样。就算长大，事情也不会因此改变。甚至连自己也不需要改变。」',
    "Script/scenario07_5.binu8@77184": '@vKohaku_0791「只是所有人都迷失了方向。只要稍微改变一下视线，就已经足够了。」',
    "Script/scenario07_5.binu8@77879": '@vKohaku_0794「因为如果不是环君，就没有意义。」',
})

OVERRIDES.update({
    "Script/scenario08_1.binu8@95534": "@vKohaku_0806「……做出那种事的孩子，真的能演绎出充满爱意的表演吗？如果只能通过失去来想象痛苦……那我也只不过是一台复读机罢了。」",
    "Script/scenario06b_4.binu8@78580": "　反复进行着自问自答。",
    "Script/scenario06b_5.binu8@25189": "　我记得好像叫……什么来着，雷吉？",
    "Script/scenario06b_6.binu8@58426": "　他正喊着让人把拳头挥下去。",
    "Script/scenario06b_6.binu8@70059": "　我们就别再遮遮掩掩了，说出真心话吧。",
    "Script/scenario09_4.binu8@70833": '本来应该在这里结束的故事。',
    "Script/scenario09_4.binu8@71719": '诅咒着荒谬世界的演员小姐。@n　既然如此，从今天起，你就成为月亮吧。',
    "Script/scenario09_4.binu8@72040": '@vMirai_0961「祈愿就能实现，诅咒就能杀人，呼喊就能得到回应——一个如此方便的世界！」',
    "Script/scenario09_4.binu8@72209": '@vMirai_0962「来写吧！来画吧！来创造吧！来歌唱吧！来呐喊吧！」',
    "Script/scenario09_4.binu8@72351": '@vMirai_0963「向割舍了心意的哥哥复仇！向强迫我演戏的母亲定罪！向安然活着的凡人降下天罚！然后，向一直忍受悲剧的自己——给予救赎！」',
    "Script/scenario09_4.binu8@72955": '@vMirai_0966「月亮，本来就是无法得到的东西。」',
    "Script/scenario09_4.binu8@74129": '@vMirai_0972「我只是完成了最棒的演出。没有理由被任何人指责。」',
    "Script/scenario09_4.binu8@74260": '@vMirai_0973「你根本什么都不明白。」',
    "Script/scenario09_4.binu8@74940": '@vMirai_0979「……怎么会这样。」',
    "Script/scenario09_4.binu8@75031": '@vMirai_0980「为什么？为什么会变成这样？我、我不是这个意思……！」',
    "Script/scenario09_4.binu8@77670": '@vMirai_0993「其实啊……」',
    "Script/scenario09_4.binu8@77755": '@vMirai_0994「我想超越兄妹的界限，成为哥哥的恋人。」',
    "Script/scenario09_4.binu8@78224": '@vMirai_0998「——只是希望哥哥能够幸福。真的，就只是这样而已。」',
    "Script/scenario09_4.binu8@78900": '@vMirai_1002「我不需要戏剧才能，也不需要兄妹之爱。我……想出生在一个与哥哥毫无关系的世界。」',
    "Script/scenario09_4.binu8@79222": '@vMirai_1004「不是的。无论我是妹妹还是不是妹妹，我都喜欢哥哥。我不是因为自己是妹妹、你是哥哥，才喜欢上你的。」',
    "Script/scenario09_4.binu8@80045": '@vMirai_1011「所以，如果要祈求一个方便的世界……我想放弃戏剧才能，忘掉对哥哥的感情，成为濑和未来以外的某个人。」',
    "Script/scenario09_4.binu8@80512": '@vMirai_1014「……那么，角色就决定了。梗概也差不多完成了。来吧，得把演员们从火焰中带出来才行。幸运的是，世上有很多因不幸而绝望的人。」',
    "Script/scenario09_4.binu8@82132": '@vMirai_1025「故事不是一个人就能编织出来的。正因为有大家的愿望，才能构筑出虚构。」',
    "Script/scenario09_4.binu8@83305": '无法用道理解释的怒火，在全身血管中奔涌。',
    "Script/scenario09_4.binu8@83670": '@vMirai_1035「啊啊，多么蛮不讲理的世界。难道我走错了该走的路吗？不，不是。说到底，我根本就没有未来！」',
    "Script/scenario09_4.binu8@84957": '@vMirai_1040「……说到底，最坏的人是你。明明要求我走上演戏这条路……却没有发自内心地支持我，也没有爱过我的演出！」',
    "Script/scenario09_4.binu8@85527": '@vMirai_1042「所以我才想要重生！想成为一个没有戏剧才能、没有兄妹之爱的普通少女！我的幸福终点，就是折原京子。」',
    "Script/scenario09_4.binu8@85991": '@vMirai_1044「没有被自卑折磨，也没有为兄妹之爱挣扎，只是享受着平静的日常。那才是让所有人幸福的唯一方法。可是……被你彻底毁掉了。」',
    "Script/scenario09_4.binu8@86550": '我的心在颤抖。@n　未来的呐喊，啊啊，真的好痛苦。',
    "Script/scenario09_4.binu8@86650": '「你所做的一切把周围的人也卷了进来。所以大家才回到了现实。」',
    "Script/scenario09_4.binu8@86763": '@vMirai_1046「嗯，是啊。有现实可以回去的人，才能随意进出这里。可是我没有可以回去的地方，只能消失。」',
    "Script/scenario09_4.binu8@86969": '「……那不对。」',
    "Script/scenario09_4.binu8@87227": '@vMirai_1047「……是啊。说到底就是这样。不可能的事，仍然是不可能的。活着时做不到的事，死后也不可能做到。我输了，世界什么都没有改变。」',
    "Script/scenario09_4.binu8@87487": '@vMirai_1048「我本来就不需要月亮。我也不是想要毁灭神明。」',
    "Script/scenario09_4.binu8@87609": '未来用满怀爱意的语气说道。',
    "Script/scenario09_4.binu8@87847": '「……未来。」',
    "Script/scenario09_4.binu8@88056": '「……你很坚强。啊，是啊……你太坚强了。」',
    "Script/scenario09_4.binu8@88720": '@vMirai_1050「哥哥似乎无法忍受没有我的世界。在那座熊熊燃烧的剧场里……他没有逃走，而是准备接受死亡。」',
    "Script/scenario09_4.binu8@88929": '「那不是理所当然的吗……！哪有哥哥能接受妹妹的死！我以为自己已经失去了活下去的意义。所以我才……！！」',
    "Script/scenario09_4.binu8@89296": '「我不需要那种保证。我……想永远为你的死而悲伤！！」',
    "Script/scenario09_4.binu8@89578": '@vMirai_1052「所以你就觉得死掉也没关系？觉得死了就不会再悲伤？啊哈哈，哥哥真是个笨蛋。即便如此，万物仍然会不断变化。」',
    "Script/scenario09_4.binu8@89790": '@vMirai_1053「我终于明白了。嗯……因为不久以前，我也和哥哥抱着同样的想法，所以我很清楚。但是……请不要害怕感情会改变。我认为，变化正是人类的美德。」',
    "Script/scenario09_4.binu8@90662": '「未来，你……」',
    "Script/scenario09_4.binu8@91021": '@vMirai_1056「我不是想死。只是觉得那是必要的。因为我认为那就是我作为演员所能抵达的终点。在年老、失去魅力之前……我想完成最棒的演出。」',
    "Script/scenario09_4.binu8@92352": '@vMirai_1058「别开玩笑了——！那样不就好像是我做错了一样吗！」',
    "Script/scenario09_4.binu8@92483": '「你做错了。」',
    "Script/scenario09_4.binu8@93324": '@vMirai_1061「……闭幕的时间快到了。为了不让一切永远不变……我也会逐渐消失……」',
    "Script/scenario09_4.binu8@93470": '「未来！！」',
    "Script/scenario09_4.binu8@93845": '「那是因为，未来。」',
    "Script/scenario09_4.binu8@93971": '「因为是我们决定要那样的。所谓规则，永远都是从认知中诞生的。」',
    "Script/scenario09_4.binu8@94360": '所以世界才添上了这样的规则。@n　因为它知道，那是一件美好的事。',
    "Script/scenario09_4.binu8@94505": '@vMirai_1064「……那么，哥哥，为什么兄妹之爱会如此珍贵呢？」',
    "Script/scenario09_4.binu8@94632": '我犹豫着该如何回答，未来却马上替我答了出来。',
    "Script/scenario09_4.binu8@94709": '@vMirai_1065「——因为兄妹不能相爱。」',
    "Script/scenario09_4.binu8@94848": '@vMirai_1066「遍体鳞伤、奄奄一息的哥哥。」',
    "Script/scenario09_4.binu8@94946": '@vMirai_1067「没关系，没关系，没关系的。悲伤会慢慢淡去的——」',
    "Script/scenario09_4.binu8@95165": '@vMirai_1068「即使是虚构的人生，也有它真正的意义。因为那是一场不断寻找重要之物的旅程。」',
    "Script/scenario09_4.binu8@95311": '「……是啊。我也这么认为。」',
    "Script/scenario09_4.binu8@95367": '光芒如此耀眼。@n　未来，啊啊，正在渐渐远去。',
    "Script/scenario09_4.binu8@95689": '这一次，未来终于……彻底摘下了所有面具。',
    "Script/scenario09_4.binu8@95763": '@vMirai_1071「我并不讨厌戏剧。恰恰相反，那曾是我活下去的唯一理由。可是，仅仅这样还不够。只有戏剧，无法让我幸福。」',
    "Script/scenario09_4.binu8@95978": '濑和未来说道。',
    "Script/scenario09_4.binu8@96080": '@vMirai_1073「只因为生来是你的妹妹，我就已经比任何人都幸福了。」',
    "Script/scenario09_4.binu8@96202": '那句话，便是她最后的话语。',
    "Script/scenario09_4.binu8@96269": '「能够成为你的哥哥……我从心底感到幸福。」',
    "Script/scenario09_4.binu8@96644": '@vMirai_1074「请不要忘记。即使无法把不可能变成可能，也仍然能够把不幸变成幸福。」',
    "Script/scenario09_4.binu8@96799": '那是一个曾向世界的荒谬发起挑战的少女，竭尽全力送出的声援。',
    "Script/scenario09_4.binu8@97442": '@vFutaba_0988「你还愣着干什么！？着火了，着火了！！快点避难——！！」',
    "Script/scenario09_4.binu8@97743": '「未来……」',
    "Script/scenario09_4.binu8@98603": '@vFutaba_0990「那当然了！除了环以外，还有人没来得及逃出去呢！」',
    "Script/scenario03_4.binu8@68436": '杂乱不堪的房间中央。@n　这里是一片与整洁毫无关系、任意堆放物品的区域。',
})

