OVERRIDES.update({
    "Script/scenario01_9.binu8@78110": '@n　——那是一个异常者说出的一句话。',
    "Script/scenario01_5.binu8@81763": '那是一个格外耀眼、与众不同的回答。',
    "Script/scenario01_4.binu8@94424": '「真让人吃惊。这是一人独演吗？」',
})

OVERRIDES.update({
    "Script/scenario06b_3.binu8@77309": '@vNanana_0506「环君根本没有把我放在心上。」',
    "Script/scenario06b_3.binu8@78266": '环君正用悲痛的表情看着我。',
    "Script/scenario06b_3.binu8@83246": '@vNanana_0528「我也是！」',
    "Script/scenario06b_3.binu8@90533": '@vNanana_0549「我最喜欢环君了。」',
    "Script/scenario06b_4.binu8@64358": '@vNanana_0566「我、我还没废柴到那种程度啦！」',
    "Script/scenario06b_6.binu8@71051": '「双、双叶同学？」',
    "Script/scenario06b_7.binu8@33864": '说着，双叶把智能手机递给了我。',
    "Script/scenario06b_7.binu8@41933": '双叶真的为奈奈菜付出了很多努力。',
    "Script/scenario07_2.binu8@90393": '@vMeguri_1072「我不记得了。因为当时正在想事情。」',
    "Script/scenario07_2.binu8@92263": '「我当时是相信你的。」',
    "Script/scenario07_2.binu8@99832": '「……琥珀，我……」',
    "Script/scenario07_3.binu8@77450": '@vDirectorB_0014「我想和你谈谈我们今后的事。这是一件重要的事，我想确认你的觉悟。」',
    "Script/scenario07_3.binu8@86796": '@vYuuen_0265「即便如此，我还是想相信。」',
    "Script/scenario07_4.binu8@50058": '副座长理世小姐似乎已经完全适应我们剧团了。',
    "Script/scenario07_4.binu8@53680": '@vMeguri_1123「我也还没有对自己的演技感到满意。即使某一种演法很出色，变化仍然太少。这些我都明白。」',
    "Script/scenario07_4.binu8@64158": '@vHana_0269「咳咳！那位姗姗来迟的主角，请专心演戏！」',
    "Script/scenario07_4.binu8@64700": '关于十二月十九日发生在某地的苏尔特座剧场火灾事件。',
    "Script/scenario07_4.binu8@64798": '当天，苏尔特座原定上演剧团兰比里斯的《哈姆雷特》。',
    "Script/scenario07_4.binu8@65689": '后来的调查表明，苏尔特座的建筑严重违反防灾规定，因此造成了大量伤亡。',
    "Script/scenario07_5.binu8@70873": '随后，她向环君告白了。',
    "Script/scenario07_5.binu8@76816": '「……琥珀，我……」',
    "Script/scenario07_6.binu8@60749": '@n　——不愧是匂宫王海的孙女。',
    "Script/scenario07_6.binu8@62052": '打击1',
    "Script/scenario07b_2.binu8@78818": '「我最喜欢你了。所以，和我……」',
    "Script/scenario07b_2.binu8@89129": '@vRairai_0738「不是这样的。全都是谎言。神明是骗子，你也是骗子。」',
    "Script/scenario07b_4.binu8@74587": '@vHana_0293「唉……真让人着急啊。」',
    "Script/scenario08_2.binu8@86721": '啪的一声。@n　视野骤然变暗，我放开了意识的缰绳。',
    "Script/scenario08b_4.binu8@57368": '@vKohaku_1160「——因为我喜欢环君。」',
    "Script/scenario08b_4.binu8@57791": '@vKohaku_1161「环君就像混合咖啡，对吧？」',
    "Script/scenario08b_4.binu8@57904": '@vKohaku_1162「关于环君，我什么都知道哦。你不加糖，也不要牛奶，对吧？」',
    "Script/scenario08b_4.binu8@58785": '@vKohaku_1165「唔唔唔，说这里可不行！这里装满了我们的回忆。在这里和环君一起走过，是有意义的。而且……」',
    "Script/scenario08b_4.binu8@66226": '@vHana_0312「当然带她去了。无论那是真实还是幻想，我都觉得这是必要的。可是……医生只说她的精神出了问题，便不再管她了。」',
    "Script/scenario08b_5.binu8@45124": '@vKohaku_1285「只要和环君在一起，我什么都不怕。」',
    "Script/scenario08b_5.binu8@46758": '由我和你来演绎。',
    "Script/scenario09_1.binu8@41588": '@vF_ChildA_0001「哎呀，双叶真是的！我也喜欢呀，但不是在说这个啦！」',
    "Script/scenario09_3.binu8@48276": '只要展现出令人满意的演技，她立刻就会像对待公主一样恭敬地对待你。',
    "Script/scenario09_3.binu8@57361": '打击1',
    "Script/scenario09_3.binu8@78411": '我就是我……我是妹妹。是一个没人愿意●爱、可悲又孤独的小女孩。',
    "Script/scenario09_3.binu8@79026": '@vMirai_0954「埃利孔没有回来。我们将永远背负着罪活下去！今夜沉重得仿佛人类的苦难。」',
    "Script/scenario09_4.binu8@77076": '@vMirai_0989「没有人能够成为卡里古拉。所以，卡里古拉才是卡里古拉。」',
    "Script/scenario09_5.binu8@100412": '苏尔特座火灾事件之后。',
    "Script/scenario09_5.binu8@112102": '@vMeguri_1791「这光芒，这热度，啊啊，没错！我知道……！！这是大家共同创造的故事！是剧团兰比里斯的温暖！」',
    "Script/scenario09_5.binu8@113312": '@vMeguri_1794「——琥珀。」',
})

OVERRIDES.update({
    "Script/scenario09_5.binu8@79709": '@vMika_0154「那孩子……求求你，救救那孩子……啊啊，怎么会这样……！！不要啊啊啊啊啊——！！」',
    "Script/scenario09_5.binu8@79946": '@vMika_0155「女儿还在里面……！我重要的女儿，还被留在那里……！！」',
    "Script/scenario09_5.binu8@80273": '@vReiji_0073「妈、妈妈，危险……！不能再继续了……！！」',
    "Script/scenario09_5.binu8@80649": '@vMika_0156「不是的，不是那样，我……！！我确实祈求过不幸！可是，我……！！」',
    "Script/scenario09_5.binu8@80942": '@vMika_0157「啊啊，好奇怪，好奇怪啊，我……！！为什么会这样失控？为什么不能把这也当成复仇的一部分！！？」',
    "Script/scenario09_5.binu8@81138": '@vMika_0158「我一直咀嚼着憎恨，把那孩子养到今天……明明那里不可能存在爱啊！！」',
    "Script/scenario09_5.binu8@81304": '啊啊……竟然要失去之后才察觉，我真是个多么愚蠢的人。',
    "Script/scenario09_5.binu8@81491": '@vMika_0159「谁来……」',
    "Script/scenario09_5.binu8@82212": '刚才看到的幸福梦境余韵，仍然没有完全消散。',
    "Script/scenario09_5.binu8@82776": '@vNanana_1016「……啊，我……没来得及逃出去……」',
    "Script/scenario09_5.binu8@83190": '哥哥和妈妈在一起吗？@n　如果是这样，嗯……那也是没有办法的事。',
    "Script/scenario09_5.binu8@83335": '@vNanana_1018「……妈妈。」',
    "Script/scenario09_5.binu8@83647": '@vNanana_1019「……真漂亮啊。」',
    "Script/scenario09_5.binu8@83855": '@vNanana_1020「我累了啊……」',
    "Script/scenario09_5.binu8@84178": '@vNanana_1021「啊啊，我真可怜。」',
    "Script/scenario09_5.binu8@84726": '@vNanana_1026「我只是想要幸福而已。」',
    "Script/scenario09_5.binu8@85160": '@vNanana_1029「谁来救救我……！谁来，谁来——！！」',
    "Script/scenario09_5.binu8@85865": '@vRize_1473「原来你在这里，奈奈。来，把手给我。快点，我们一起从这里逃出去。」',
    "Script/scenario09_5.binu8@86156": '@vRize_1474「啊，太好了。真的太好了。我也终于能够救到谁了。」',
    "Script/scenario09_5.binu8@86594": '@vRize_1477「没事的。」',
    "Script/scenario09_5.binu8@87043": '@vMeguri_1730「可是现在想想，天兄、悠先生和花都陪在我身边……为什么只有祖父被留在了现实里呢？」',
    "Script/scenario09_5.binu8@87259": '剧团兰比里斯的核心人物。@n　若不提起主角，根本无从谈起。',
    "Script/scenario09_5.binu8@87368": '@vMeguri_1731「……我知道。我知道原因。因为我打从心底讨厌那个人。如果想要一个方便的世界，就没有必要把讨厌的人招来。」',
    "Script/scenario09_5.binu8@87789": '@vMeguri_1732「我很幸福。真的，很幸福。」',
    "Script/scenario09_5.binu8@88024": '@vMeguri_1733「那个严厉斥责我的祖父已经不在了。那个坏心眼的祖父也不在任何地方。我自由了。想怎么做都能被原谅。没有祖父的世界，啊啊！是多么幸福啊！」',
    "Script/scenario09_5.binu8@88323": '@vMeguri_1734「……不对劲。」',
    "Script/scenario09_5.binu8@88439": '@vMeguri_1735「我的心感到了干渴。要说这就是幸福，好像又缺少了什么。啊啊，我知道了，我知道的。我把那件事忘记了。」',
    "Script/scenario09_5.binu8@88797": '@vMeguri_1736「祖父确实是个坏心眼、严厉又守旧的人。被他打、被他吼，我不知多少次对他产生过杀意。」',
    "Script/scenario09_5.binu8@89263": '@vMeguri_1738「……原来我哭，是因为……」',
    "Script/scenario09_5.binu8@89340": '@vMeguri_1739「一定……从一开始就是这样。」',
    "Script/scenario09_5.binu8@89613": '@vMeguri_1740「我这个性格别扭的孩子，一直被周围人讨厌。不可爱的孩子、让人喜欢不起来的小鬼。作为麻烦人物的处境，和祖父其实没有什么不同。」',
    "Script/scenario09_5.binu8@90157": '那场残酷的英才教育也是。@n　那种无可救药、彻底的斯巴达式训练也是。',
    "Script/scenario09_5.binu8@91364": '@vMeguri_1746「——我必须把爱还给他！祖父把我养到今天，我却还没有对他说过一句话……！！」',
    "Script/scenario09_5.binu8@92432": '@vMeguri_1210「……好热。」',
    "Script/scenario09_5.binu8@92568": '@vMeguri_1211「大家，都烧起来了。」',
    "Script/scenario09_5.binu8@92824": '@vMeguri_1215「大家，等着我哦。」',
    "Script/scenario09_5.binu8@93672": '@vRairai_0792「喂，老头。你为什么没陪在巡身边？」',
    "Script/scenario09_5.binu8@93845": '@vRairai_0793「别装傻。你本来也可以做到。否定自己的死亡，活在假想的世界里。」',
    "Script/scenario09_5.binu8@94019": '@vOmi_0111「少说蠢话，小鬼。我已经活得够久了。这里就是我的天命。能死在舞台前，对演出家来说不是最棒的结局吗？和你不同，我对自己的人生已经无怨无悔了。真是的，年纪轻轻就死了……」',
    "Script/scenario09_5.binu8@94319": '@vRairai_0794「啊？我没在说老头你。我在意的是巡。」',
    "Script/scenario09_5.binu8@94484": '@vOmi_0113「事到如今，已经没什么要对她说的了。不用说也能传达。我已经把很多东西留在了这个世界上，所以没必要着急。你不也是这样吗？」',
    "Script/scenario09_5.binu8@94832": '@vOmi_0114「巡没事。」',
    "Script/scenario09_5.binu8@95421": '@vOmi_0116「走吧，来来。」',
    "Script/scenario09_5.binu8@96384": '@vMeguri_1753「……啊，我明白了……」',
    "Script/scenario09_5.binu8@96476": '@vMeguri_1754「演出……还没有结束，对吧……」',
    "Script/scenario09_5.binu8@96975": '「我追到地狱的最底层来了。来吧，我们一起逃走。」',
    "Script/scenario09_5.binu8@97625": '「这里不是终点。从这里开始，故事还会继续。所以……巡。」',
    "Script/scenario09_5.binu8@98424": '各种各样的感情不断闪回。@n　我只能被那无法阻挡的思念洪流反复冲刷。',
    "Script/scenario09_5.binu8@98584": '@vMeguri_1761「……所爱之物全都消失了。相信之物也无法得到救赎。这个世界上只剩下无法反抗的绝望。无尽的痛苦，正将我的灵魂烧尽。」',
    "Script/scenario09_5.binu8@99308": '@vMeguri_1763「——必须活下去。」',
    "Script/scenario09_5.binu8@100145": '我紧紧握住拳头。',
    "Script/scenario09_5.binu8@100192": '「从今以后，也要继续活下去。」',
    "Script/scenario09_5.binu8@100354": '@vMika_0161「我曾经恨过你。」',
    "Script/scenario09_5.binu8@101874": '@vNanana_1036「我肚子饿了……想吃妈妈亲手做的饭。」',
    "Script/scenario09_5.binu8@102176": '@vNanana_1037「可是，我……」',
    "Script/scenario09_5.binu8@102400": '@vNanana_1038「嗯，这样就够了。因为奈奈最喜欢妈妈了。」',
    "Script/scenario09_5.binu8@102733": '@vRize_1479「……冰狐。」',
    "Script/scenario09_5.binu8@102832": '@vRize_1480「……我终究还是无法理解冰狐，无法真正明白她。」',
    "Script/scenario09_5.binu8@103113": '@vRize_1481「不过，这样也好。无法理解才是正常的。什么都能互相理解的朋友，只存在于童话里。」',
    "Script/scenario09_5.binu8@103544": '「未来交到了一个很好的朋友啊。」',
    "Script/scenario09_5.binu8@103720": '@vRize_1484「……是啊。」',
    "Script/scenario09_5.binu8@103976": '@vRize_1485「怎么了？」',
    "Script/scenario09_5.binu8@104010": '「连同未来那一份，也要幸福地活下去。」',
    "Script/scenario09_5.binu8@104119": '@vRize_1486「要这么说的话，濑和君才是。即便如此，你也是哥哥，所以要守护好妹妹的骄傲。」',
    "Script/scenario09_5.binu8@104750": '「你还……」',
    "Script/scenario09_5.binu8@104832": '@vMeguri_1768「伤口太深了，不可能那么容易愈合。」',
    "Script/scenario09_5.binu8@104972": '@vMeguri_1769「不过没关系……你以为我是谁？我是能让哭泣的孩子闭嘴的天才女演员，匂宫巡哦……？」',
    "Script/scenario09_5.binu8@107709": '@vRize_1488「今天是约定的日子。来，跟我走。」',
    "Script/scenario09_5.binu8@108118": '@vMeguri_1778「嗯……不过，我想再过一会儿，就能继续前进了……」',
    "Script/scenario09_5.binu8@108576": '@vMeguri_1780「为、为什么……会在这里……？」',
    "Script/scenario09_5.binu8@109631": '@vNanana_1039「剧、剧本现在还在修改中……！对、对不起，不过马上就能完成了……！！」',
    "Script/scenario09_5.binu8@109838": '@vNanana_1040「是的！我正在把匂宫王海先生的遗作改编成适合舞台的剧本！那个，标题应该是——」',
    "Script/scenario09_5.binu8@110085": '@vNanana_1041「没错，是《菲莉亚》公演！虽然是个有点悲惨的故事，但我觉得这是匂宫小姐会喜欢的剧本！」',
    "Script/scenario09_5.binu8@110658": '「——不是这样吧，巡。」',
    "Script/scenario09_5.binu8@111430": '「怎么了，巡？」',
    "Script/scenario09_5.binu8@113083": '@vKohaku_1295「大家，抱歉来晚了！啊，巡！你已经到了！」',
    "Script/scenario09_5.binu8@113631": '@vMeguri_1795「真巧啊，琥珀。我也正好有件事想和你商量。」',
    "Script/scenario09_5.binu8@114126": '@vMeguri_1797「哼，那就好！」',
    "Script/scenario09_5.binu8@114446": '@vMirai_1076「让我们在一张洁白的画布上作画吧。燃烧心灵，用生命的墨水，将一切记录下来。」',
    "Script/scenario09_5.binu8@114577": '@vMirai_1077「不一定要在纸上。就算是在手掌上，也没有关系。」',
    "Script/scenario09_5.binu8@114672": '@vMirai_1078「因为故事所需要的，只有悲剧和眼泪。」',
    "Script/scenario09_5.binu8@114755": '@vMirai_1079「白发红瞳会为我们指引方向。」',
    "Script/scenario09_5.binu8@114811": '@vMirai_1080「为每个人那充满艰难险阻的现实。」',
})

OVERRIDES.update({
    "Script/scenario07_2.binu8@94817": '不过。',
    "Script/scenario07_2.binu8@98702": '那是《银河铁道之夜》中康帕内拉说过的台词。',
    "Script/scenario07_2.binu8@101689": '@vOmi_0046「你还真是个老实过头的家伙。」',
    "Script/scenario07_3.binu8@59877": '@vRize_1435「这里的基本理念，似乎就是将终极的自我满足贯彻到底。真让人惊讶，竟然和你如此相似。」',
    "Script/scenario07_3.binu8@81396": '然而。',
    "Script/scenario07_4.binu8@57214": '但是。',
    "Script/scenario07_4.binu8@62173": '他抓耳挠腮。@n　因为刚刚萌生的感情实在太过稚嫩，他拼命忍住笑意。',
    "Script/scenario07_4.binu8@74831": '然而。',
    "Script/scenario07_5.binu8@57329": '回过神来，悠正站在我身边。@n　她握着我的手，露出虚幻的笑容。',
    "Script/scenario07_5.binu8@70197": '然而。',
    "Script/scenario07_5.binu8@77832": '她脸上浮现出淡淡的笑容。',
    "Script/scenario07_6.binu8@65951": '@vOmi_0088「我可没在开玩笑。你没听见的话，我就再说一遍。」',
    "Script/scenario07_6.binu8@78601": '@vMeguri_1187「……我不知道。我一点都不明白你在说什么……」',
    "Script/scenario07b_1.binu8@99536": '铛的一声。@n　金属与白球相撞的声音响起。',
    "Script/scenario07b_1.binu8@100933": '他笑得轻佻而又开心。',
    "Script/scenario07b_2.binu8@72046": '「啊、啊……是啊。你今天也会来我家吧？」',
    "Script/scenario07b_4.binu8@59718": '「不……我不知道。是剧团的事，有什么要和我商量的吗？」',
    "Script/scenario07b_4.binu8@59825": '@vRairai_0741「才不是呢，笨蛋。是兰比里斯的事，我干嘛要找你商量。切！」',
    "Script/scenario07b_4.binu8@66285": '@vRairai_0767「濑和，你和她……在交往吗？」',
    "Script/scenario07b_4.binu8@72253": '「那么，我先失陪了。谢谢你的咖啡！」',
    "Script/scenario09_1.binu8@59019": '然而。',
    "Script/scenario09_2.binu8@70861": '砰的一声。@n　我感觉自己的脑袋像是被锤子狠狠砸了一下。',
    "Script/scenario09_2.binu8@89786": '可是。',
    "Script/scenario09_3.binu8@66535": '没关系。@n　因为我甚至已经不再感到寂寞了。',
    "Script/scenario09_3.binu8@67979": '卡里古拉因失去所爱之人而知晓世间的残酷，渴求将不可能化为可能，试图反抗这个世界的法则。',
    "Script/scenario09_3.binu8@72137": '不是属于某个人的。@n　而是属于我的卡里古拉王。',
    "Script/scenario09_3.binu8@73564": '@vMirai_0934「我是卡里古拉王。」',
    "Script/scenario09_4.binu8@70796": '那么。@n　那么，那么。',
    "Script/scenario09_4.binu8@76347": '@vcs_Mirai_0005「可是哥哥说那样不行。我知道，我知道啊，我自己也知道！所以，求你乖乖听话！……所以，我……！」',
    "Script/scenario09_4.binu8@77201": '@vMirai_0990「我是镜子哦。镜中的我，应该一直都明白自己真正渴望的东西。白发红瞳之人，被允许拥有实现它的力量。」',
    "Script/scenario09_4.binu8@77626": '@vMirai_0992「嗯。那是因为……」',
    "Script/scenario09_4.binu8@78159": '@vMirai_0997「我啊，哥哥。只是……」',
    "Script/scenario09_4.binu8@80328": '@vMirai_1013「嗯。因为我觉得那对哥哥来说是碍事的东西。」',
    "Script/scenario09_4.binu8@92140": '「你憎恨戏剧，也同样深爱着戏剧。否则，怎么可能演出那样的表演？这一点，你哥哥我可以保证！」',
    "Script/scenario09_5.binu8@84662": '是啊。@n　不能弄错。',
})

OVERRIDES.update({
    "Script/scenario07_4.binu8@49564": '@vHana_0266「好——！马上就来！」',
    "Script/scenario07_4.binu8@49784": '@vRize_1452「好了，各位，练习时间到了。」',
    "Script/scenario07_4.binu8@50290": '@vOmi_0070「吵死了，你这个混账孙子。所谓主角，可不是只看演技就能决定的。」',
    "Script/scenario07_4.binu8@50533": '@vOmi_0071「喂，来来。让这个笨孙子闭嘴。」',
    "Script/scenario07_4.binu8@51784": '@vMeguri_1118「看吧，悠小姐站在我这边！她明明就理解我！」',
    "Script/scenario07_4.binu8@51904": '@vYuuen_0268「呵呵呵，真可爱呢。」',
    "Script/scenario07_4.binu8@52390": '@vOmi_0072「随你喜欢。」',
    "Script/scenario07_4.binu8@52438": '@vMeguri_1120「喂——！你怎么能对招牌女演员大人说这种话！！」',
    "Script/scenario07_4.binu8@53166": '@vOmi_0074「你还只是个臭小鬼。你的演技确实不错，但还没能表现出深层情感的细微变化。所以，你还远远算不上一流。」',
    "Script/scenario07_4.binu8@53441": '@vOmi_0075「去掌握戏剧的深度和广度。以你现在的实力，还不可能演好哈姆雷特王子。」',
    "Script/scenario07_4.binu8@54438": '@vRairai_0652「别摆出那副老气横秋的表情。你现在还是我们了不起的招牌女演员吧。」',
    "Script/scenario07_4.binu8@54573": '@vYuuen_0269「……呵呵，是啊。不过现在，我真的很期待那孩子的成长。」',
    "Script/scenario07_4.binu8@54784": '@vRairai_0653「你最好别陷得太深。那家伙迟早会离开这个剧团的。她不该待在这种寒酸的剧团里，而是得去更了不起的地方。」',
    "Script/scenario07_4.binu8@55872": '@vYuuen_0272「……来来小姐。」',
    "Script/scenario07_4.binu8@56876": '@vYuuen_0275「……总有一天，必须把这件事告诉她呢。」',
    "Script/scenario07_4.binu8@57122": '@vRairai_0656「别摆出那种表情，悠苑。」',
    "Script/scenario07_4.binu8@57384": '@vYuuen_0277「……来来小姐。」',
    "Script/scenario07_4.binu8@58193": '@vRairai_0659「你问的是什么问题？」',
    "Script/scenario07_4.binu8@58508": '@vRairai_0661「也就是说，这就叫家人吧。」',
    "Script/scenario07_4.binu8@59260": '@vRairai_0663「终极的自我满足吗……」',
    "Script/scenario07_4.binu8@60513": '@vHana_0267「好——，进场时间到了！时间有限，大家利落一点哦！」',
    "Script/scenario07_4.binu8@60791": '@vOmi_0077「喂，理世！！巡那个笨蛋跑哪儿去了！那家伙身为主角，难道还迟到了吗？」',
    "Script/scenario07_4.binu8@61099": '@vOmi_0078「……哦，对了。老头子我给忘了。」',
    "Script/scenario07_4.binu8@61177": '@vYuuen_0281「真是的，王海先生。」',
    "Script/scenario07_4.binu8@62354": '@vRairai_0671「……还是道个歉吧。」',
    "Script/scenario07_4.binu8@62833": '@vHana_0268「终于到明天了呢！由巡小姐主演的《哈姆雷特》！」',
    "Script/scenario07_4.binu8@63055": '@vRairai_0673「笨蛋，别小看那个早熟丫头的厚脸皮。她和普通人可不是一个级别的。」',
    "Script/scenario07_4.binu8@63392": '@vRairai_0674「——至少，给它留下点值得铭记的痕迹吧。」',
    "Script/scenario07_4.binu8@63552": '@vMeguri_1125「快点，理世！再不快点就要结束了！」',
    "Script/scenario07_4.binu8@63875": '@vMeguri_1126「来晚了……！！来，我们也来帮忙！」',
    "Script/scenario07_4.binu8@67204": '@vMeguri_1130「……在燃烧。」',
    "Script/scenario07_4.binu8@67762": '@vMeguri_1131「……好美。」',
    "Script/scenario07_4.binu8@69317": '@vYuuen_0284「不行，必须逃走！！」',
    "Script/scenario07_4.binu8@70614": '@vRairai_0683「……开什么玩笑。」',
    "Script/scenario07_4.binu8@70976": '@vRairai_0684「……巡、巡……？」',
    "Script/scenario07_4.binu8@71523": '@vMeguri_1135「大家，大家都被烧死了。爷爷、天兄、悠小姐、花……」',
    "Script/scenario07_4.binu8@72643": '@vRairai_0688「……好美。」',
    "Script/scenario07_4.binu8@74404": '　自从组建兰比里斯剧团以来，我究竟是怎么才能度过如此充实的每一天？',
})

OVERRIDES.update({
    "Script/scenario07b_5.binu8@40832": '「嗯……我……确实已经告诉她，我希望她成为我的恋人。」',
    "Script/scenario07b_5.binu8@41623": '「嗯，当然。我自己并没有对此感到多么不安……我现在过得很幸福。」',
    "Script/scenario07b_5.binu8@41926": '@vYuuen_0319a「……一向只顾演戏的巡，第一次谈起了恋爱……那孩子有时候太莽撞了，我当时真的非常担心。」',
    "Script/scenario07b_5.binu8@42103": '@vYuuen_0319b「不过，看样子她似乎已经顺利平静下来了，我也终于放心了。」',
    "Script/scenario07b_5.binu8@42735": '@vYuuen_0322「你只是故意这么说而已吧？真是的，性格太别扭了。」',
    "Script/scenario07b_5.binu8@42910": '@vYuuen_0323「……真羡慕你们。我也曾想像这样谈一次恋爱。」',
    "Script/scenario07b_5.binu8@43008": '「现在开始也不算晚。」',
    "Script/scenario07b_5.binu8@43064": '@vYuuen_0324「谁知道呢。也许我只是在逃避那个已经无可挽回的事实。」',
    "Script/scenario07b_5.binu8@43330": '@vYuuen_0325「他是一位很棒的座长，仅此而已。」',
    "Script/scenario07b_5.binu8@43431": '@vYuuen_0326「……我害怕改变。靠近一个人、希望被爱，却遭到拒绝怎么办？被讨厌怎么办？即使心意相通，后来产生误会、彼此厌恶，又该怎么办？分别的痛苦，会凌驾于一切疼痛之上。」',
    "Script/scenario07b_5.binu8@43762": '@vYuuen_0327「……那么，成为值得信赖的同伴不就好了吗？贪得无厌的女人只会显得丑陋。只要能和那个人长久地一起微笑……我就已经很幸福了。」',
    "Script/scenario07b_5.binu8@43971": '「……这……」',
    "Script/scenario07b_5.binu8@44281": '@vYuuen_0328「幸福以各种各样的形式存在。不能只用单纯的大小来衡量它的价值。」',
    "Script/scenario07b_5.binu8@44439": '「是啊……」',
    "Script/scenario07b_5.binu8@44706": '@vMeguri_1594「……今天的戏，和之前的好评相比，感觉有些普通。我本来期待的是更让人心潮澎湃的东西。」',
    "Script/scenario07b_5.binu8@44993": '　和巡看完戏约会回家的路上。@n　我们一边随意交换着感想，一边并肩走着。',
    "Script/scenario07b_5.binu8@45222": '「……虽然确实挺色情的，但也不能只说色情……」',
    "Script/scenario07b_5.binu8@45787": '「才不是这个问题！」',
    "Script/scenario07b_5.binu8@46019": '「我们引以为傲的戏剧，怎么能和那种东西相提并论！？」',
    "Script/scenario07b_5.binu8@46114": '@vMeguri_1599「顺便一提，这是我凭感觉得出的统计。」',
    "Script/scenario07b_5.binu8@46183": '「全都是骗人的吧！」',
    "Script/scenario07b_5.binu8@46292": '@vcs_Meguri_0007_b「哎呀，我就是想和你卿卿我我，所以才约你出来约会的呀？难道你不是吗？」',
    "Script/scenario07b_5.binu8@46801": '@vMeguri_1602「呵呵呵，遗憾。我可等不到那时候——」',
    "Script/scenario07b_5.binu8@46926": '@vMeguri_1603「……顺便问一下，你知道吗？今天排练的时候，大家的时间都对不上……看来只有我们两个有空呢。」',
    "Script/scenario07b_5.binu8@47514": '「是排练。下一场你要演公主吧？要是演成一个太过任性的公主，不就显得格格不入了吗？」',
    "Script/scenario07b_5.binu8@47922": '「……你、你这家伙！」',
    "Script/scenario07b_5.binu8@47960": '「行了，走吧！！」',
    "Script/scenario07b_5.binu8@48665": '「说的是天乐座长和龙木前辈。」',
    "Script/scenario07b_5.binu8@48721": '@vMeguri_1695「那两个人就放着不管吧。要是光凭别人说几句就能改变，他们早就有进展了。」',
    "Script/scenario07b_5.binu8@49045": '@vMeguri_1696「我们只要培育好属于我们的感情就够了。能做的也只有这些。所以你也别去管他们了。」',
    "Script/scenario07b_5.binu8@49332": '@vMeguri_1697「而且也不能说他们永远不会改变。看到幸福的我，说不定他们也会改变想法。」',
    "Script/scenario07b_5.binu8@49772": '@vYuuen_0329「好的，有什么事吗？」',
    "Script/scenario07b_5.binu8@49946": '@vRairai_0786「这次我要去视察新剧场，你也陪我一起去。」',
    "Script/scenario07b_5.binu8@50341": '@vYuuen_0331「……呵呵，明白了。那我们一起去吧。」',
    "Script/scenario07b_5.binu8@50529": '@vYuuen_0332「无聊？怎么会。只要和来来小姐一起，肯定就不会无聊。」',
    "Script/scenario07b_5.binu8@51685": '@vMeguri_1702「只要能慢慢走到极限，终点就仿佛不存在。所以，你就和我一起在这里，细细品味这份迟缓的幸福吧。」',
    "Script/scenario07b_5.binu8@51892": '「迟缓的幸福？」',
    "Script/scenario07b_5.binu8@52452": '「巡真是贪心啊。真是个贪心鬼。」',
    "Script/scenario07b_5.binu8@52922": '@vMeguri_1707「不过，我会好好告诉你的。」',
    "Script/scenario07b_5.binu8@53498": '「让我们一起，不论走到哪里都继续前进吧。」',
})

OVERRIDES.update({
    "Script/scenario06b_3.binu8@85447": '@vMirai_0383「试着相爱之后，你就能明白这种感情的本质。所以，先试着成为恋人不就好了吗？」',
    "Script/scenario05_7.binu8@88156": '@vNanana_0366「看来是被夏天的炎热击垮了！！对不起，环君！奈奈先走一步啦——！！」',
    "Script/scenario06b_2.binu8@71690": '@vNanana_0451「失、失、失、失礼了！我、我得走了！」',
    "Script/scenario05_2.binu8@72894": '@vNanana_0315「对、对不起……我还要去咖啡店打工……」',
    "Script/scenario06_6.binu8@81481": '@vRize_0958「对、对啊……对不起，我只是有点吃惊，脑子还没转过来……」',
    "Script/scenario06_9.binu8@30053": '　这是两个恋人尽情品味幸福的甜蜜故事。',
    "Script/scenario04_4.binu8@88901": '　所以。',
    "Script/scenario05_14.binu8@89599": '　所以。',
    "Script/scenario07_3.binu8@72038": '@n　所以。',
    "Script/scenario07_5.binu8@66136": '@vYuuen_0292「谁知道呢？故事已经不是该判断对错的阶段了。重要的是，他自己想要什么、相信什么。他相信巡的未来。」',
    "Script/scenario07b_1.binu8@104537": '　距离正式成为恋人之前的这一刻。@n　啊啊，真是幸福啊。',
    "Script/scenario07b_5.binu8@52224": '@vMeguri_1705「我们慢慢来就好。先从朋友变成伙伴，再从伙伴变成恋人。成为恋人之后……还要继续往前走吗？越是向前，终点就越近。」',
    "Script/scenario07b_5.binu8@52786": '　我期待着终有一天，能称呼彼此为恋人。@n　此刻，我们正为即将到来的变化而雀跃。',
})

OVERRIDES.update({
    "Script/scenario07b_4.binu8@69556": '@vYuuen_0310「……呵呵，是啊。不过，他完全没有察觉呢。」',
    "Script/scenario07b_4.binu8@69808": '@vMeguri_1524「怎么了？」',
    "Script/scenario07b_4.binu8@69844": '「天乐座长该不会……」',
    "Script/scenario07b_4.binu8@70058": '@vMeguri_1526「他究竟要到什么时候才会察觉呢？再这样磨磨蹭蹭下去，可是会错过机会的。」',
    "Script/scenario07b_4.binu8@70309": '@vMeguri_1527「不，不是那样。」',
    "Script/scenario07b_4.binu8@70560": '「……不可能。巡一直都很擅长周旋于人际关系吧。」',
    "Script/scenario07b_4.binu8@70646": '@vMeguri_1529「只是看起来像那样而已。所以，你看。」',
    "Script/scenario07b_4.binu8@71074": '@vRairai_0780「……你、你们在这种地方干什么啊！！怎么看都像是在交往吧！！！」',
    "Script/scenario07b_4.binu8@71320": '@vRairai_0781「别在那儿炫耀啊！！」',
    "Script/scenario07b_4.binu8@71675": '@vRairai_0782「巡——！！你什么时候变成这么下流的女人了！！」',
    "Script/scenario07b_4.binu8@72737": '@vMeguri_1537「你是说悠小姐和天兄？那两个人已经没救了。」',
    "Script/scenario07b_4.binu8@73312": '@vMeguri_1538「那件事……确实挺惨的。想想悠小姐当时的心情……」',
    "Script/scenario07b_4.binu8@73458": '@vMeguri_1539「……不过，停滞不前的原因也许在悠小姐那边。说不定，她正为现在的距离感感到幸福……」',
    "Script/scenario07b_4.binu8@73804": '@vHana_0290「……龙木先生就是太认真了。他大概觉得恋爱会妨碍对方，所以才选择了退让。」',
    "Script/scenario07b_4.binu8@74069": '@vHana_0291「嗯，偶尔会试探一下。不过大多时候都会被他含糊带过。」',
    "Script/scenario07b_4.binu8@74166": '@vHana_0292「我甚至提醒过他，再这样下去两个人会在还没交往之前就各奔东西，可他还是只会温和地笑。换作是我，绝对承受不了！」',
    "Script/scenario07b_4.binu8@74386": '@vMeguri_1541「要是能拉近距离，我们早就交往了。之所以一直拖到现在……大概都是因为戏剧吧。」',
    "Script/scenario07b_4.binu8@74675": '@vMeguri_1542「干脆让悠小姐喜欢上别人吧。要是她被别的男人抢走，天兄说不定就会察觉。悠小姐既漂亮又有女人味……真想找的话，找上一两个男人根本不成问题。」',
    "Script/scenario07b_4.binu8@74963": '@vHana_0294「……谁知道呢。她看起来经验丰富，其实意外地像个少女。」',
    "Script/scenario07b_4.binu8@75128": '@vHana_0295「对了，你知道天乐小姐的发圈吗？就是她总是戴着的那个……」',
    "Script/scenario07b_4.binu8@75580": '@vHana_0297「讨厌花里胡哨装饰的天乐小姐，唯一戴在身上的东西就是龙木先生的发圈！她还一脸幸福地说，因为对方一直不肯还给她，所以自己很困扰。真是让人浑身发痒，受不了了！！」',
    "Script/scenario07b_5.binu8@41473": '@vYuuen_0317b「可是……那孩子应该也在用自己的方式认真思考。所以，请你相信她。」',
    "Script/scenario07_5.binu8@70131": '@vRairai_0719「……这种感情，或许能派上用场。」',
    "Script/scenario07_5.binu8@70217": '@vHana_0280「座、座长……！」',
    "Script/scenario07_5.binu8@71609": '@vKohaku_0776「……原来如此。」',
    "Script/scenario07_5.binu8@74195": '@vRairai_0725「……你说过，只要由我来演奥丁就行。没错……要是真能做到，我也不用这么辛苦。正因为做不到……才要把它托付给别人。」',
    "Script/scenario07_5.binu8@77616": '「我明白了，琥珀。」',
    "Script/scenario07_6.binu8@72695": '@vMeguri_1168「人类因为忙于追赶时间，已经什么都无法真正理解了。他们只会在商店里买来一切已经完成的东西。可是，世上没有出售朋友的商店，所以人类已经没有朋友了。如果你也想要朋友，就来驯服我吧！」',
    "Script/scenario07_6.binu8@75780": '@vMeguri_1179「……现在呢？」',
    "Script/scenario07_6.binu8@77159": '「这个世界充满了温柔。」',
    "Script/scenario07_6.binu8@80615": '　聪明的巡，不可能对此一无所知。',
    "Script/scenario07_6.binu8@60807": '　每当我提出一个看似正确的答案，心里就会像被枕头里的歌词搅动一样不安。@n　每当听到这样的消息，我都会感到不舒服。',
    "Script/scenario07_6.binu8@61080": '　那段记忆里，只剩下刺耳的尖叫。@n　在加入兰比里斯剧团之前，我曾接受过彻底的天才教育。',
    "Script/scenario07_6.binu8@61401": '　祖父当时像个斯巴达教官一样指导我，考察我的才能，并不断强化那种恶魔般的教育。',
    "Script/scenario07_6.binu8@61610": '　起初，我不得不承受那种撕裂般的教育，但我也试图用时间来抵消它。',
    "Script/scenario07_6.binu8@61851": '@vOmi_0083「哦，巡。你今天怎么来练习了？」',
    "Script/scenario07_6.binu8@62098": '　我明明还是个孩子，却不得不继续扮演一个孩子。',
    "Script/scenario07_6.binu8@62226": '@vOmi_0085「我很高兴你还保有一颗健康的心！只要稍微尝到一点甜头，我就觉得自己能够继续活在这个世界上了！」',
    "Script/scenario07_6.binu8@63047": '　当然，公众眼中的我只是祖父失去行业地位后留下的继承人。',
    "Script/scenario07_6.binu8@63849": '　作为亲人，我遭到祖父的厌恶；他从来没有寻求过任何血缘上的联系。',
    "Script/scenario07_6.binu8@64004": '　然而，对祖父而言，只要我作为一个存在回应他，就已经足够了。',
    "Script/scenario07_6.binu8@64114": '@vOmi_0087「这是什么意思？」',
    "Script/scenario07_6.binu8@64162": '　随着祖父的心脏逐渐衰弱，那种斯巴达式的平静教育也变成了一场折磨。',
    "Script/scenario07_6.binu8@64466": '@vRairai_0727「哦，我可不喜欢这样。」',
    "Script/scenario07_6.binu8@64914": '@vMeguri_1145「我并不是想成为演员，也不是因为喜欢这部戏才不得不演。」',
    "Script/scenario07_6.binu8@65094": '　因为爷爷这个经纪人管得太松，我反而无法停下来。',
    "Script/scenario07_6.binu8@65484": '　从剧团的第一线退下来之后，我们就不再接受那种斯巴达式的教育了。',
    "Script/scenario07_6.binu8@65752": '「什么时候的事？」',
    "Script/scenario07_6.binu8@65808": '「哦，是啊。我加入兰比里斯剧团以后……」',
    "Script/scenario07_6.binu8@66777": '@vMeguri_1150「太棒了！就算是明天的乡村公演，也一定能成功！」',
    "Script/scenario07_6.binu8@67133": '@vOmi_0093「我记得，周围没有任何反对者，都和我站在一起。只要把它用在正确的地方，你已经是演员了。」',
    "Script/scenario07_6.binu8@67481": '@vOmi_0094「说清楚一点吧？兰比里斯是一群失败者组成的剧团。你需要真正的天才，可问题并不只是这个。」',
    "Script/scenario07_6.binu8@69417": '「你什么时候来的？」',
    "Script/scenario07_6.binu8@69476": '@vMeguri_1157「为了方便就说我爱你？你把自己藏起来，享受着快乐，却不用承担任何后果吗？」',
    "Script/scenario07_6.binu8@70258": '@vOmi_0102「这是座长的责任。」',
    "Script/scenario07_6.binu8@70660": '@vMeguri_1162「你要为爷爷而死吗？」',
    "Script/scenario07_6.binu8@70874": '@vMeguri_1163「这样一来，明星公主就成了一个圆满的故事。」',
    "Script/scenario07_6.binu8@70991": '　据说，在冰咖啡上加糖的时候，曾经是令人怀念的时光。',
    "Script/scenario07_6.binu8@71468": '「我喜欢小猫的故事。你认识巡吗？」',
    "Script/scenario07_6.binu8@74068": '@vMeguri_1171「王子？有个小故事……」',
    "Script/scenario07_6.binu8@74205": '@vMeguri_1172「我不喜欢玫瑰。它只是带刺的花，会为了美丽带来疼痛。就像一场戏。」',
    "Script/scenario07_6.binu8@74397": '「你喜欢演戏吗？」',
    "Script/scenario07_6.binu8@74563": '@vMeguri_1174「我没有露出那样的表情。至少，因为我们是世界上彼此唯一的人。」',
    "Script/scenario07_6.binu8@74713": '「我不是玫瑰吗？」',
    "Script/scenario07_6.binu8@74969": '@vMeguri_1176「这是什么意思？」',
    "Script/scenario07_6.binu8@75017": '　我笑了起来。@n　因为害怕失去，所以我没有依靠它。',
    "Script/scenario07_6.binu8@75141": '　第一次站上舞台时，我才知道聚光灯是炽热的。我觉得那双眼睛很美。',
    "Script/scenario07_6.binu8@75469": '「什么变了？」@n「你不是说过，什么都不应该改变吗？」',
    "Script/scenario07_6.binu8@75683": '「这是真的吗？」',
    "Script/scenario07_6.binu8@75938": '「和我一样。我本以为自己什么都不必改变，可还是有些东西变了。」',
    "Script/scenario07_6.binu8@76133": '「我觉得，在聚光灯的热量另一边，存在着某种完整的东西。」',
    "Script/scenario07_6.binu8@76297": '「那绝对不是一个好的立场。也许你还必须卸下最后的伪装，慢慢确认周围的一切。」',
    "Script/scenario07_6.binu8@86967": '@vKohaku_0795a「到了夜里，请看星星。我的星星太小了，没法告诉你它在哪里。不过，这样反而更好。我的星星会成为夜空中无数星星里的某一颗。」',
    "Script/scenario07_6.binu8@87240": '@vKohaku_0795b「这样一来，你就会喜欢上仰望整个夜空吧……夜空里的每一颗星星，都会成为你的朋友。现在，我要送给你一件礼物……」',
    "Script/scenario07_6.binu8@87471": '「于是，王子笑了。」',
    "Script/scenario05_13.binu8@74550": '　这个故事的元凶，不是另有其人吗？',
    "Script/scenario05_14.binu8@87224": '　对神话的彻底否定。@n　守护洛基的名誉，才是对他而言的“善意”。',
    "Script/scenario05_9.binu8@86856": '　毕竟，“现在”的我曾经很幸福。@n　“现在”还会在“之后”再次到来。',
    "Script/scenario06b_6.binu8@65759": '　所以我觉得，自己应该推他一把。',
})

OVERRIDES.update({
    "Script/scenario04_4.binu8@80089": '「这是醉了吗？明明没有酒精才对吧？」',
    "Script/scenario04_4.binu8@82178": '@vHana_0140「我是个坏孩子……我不能眼睁睁看着那种事发生。」',
    "Script/scenario04_4.binu8@84274": '　我点头确认，和她反复调整着语气，却忘记了母亲曾经对我说过的话。',
    "Script/scenario04_4.binu8@90024": '@vOmi_0008「我不需要别人来决定我喜欢什么。我只召集了自己喜欢的人，才创办了这个剧团。你没听见外面的声音吗？想清楚自己想要什么，再做决定。」',
    "Script/scenario04_4.binu8@90602": '@vOmi_0009「我拥有剧团的才能，也有支撑它的天赋。你想把这些都扔掉吗？」',
    "Script/scenario05_13.binu8@68572": '@vMeguri_0882「我不知道！你为什么不看着我？为什么不和我联系？奥丁，你究竟在哪里？你知道真相吗？」',
    "Script/scenario05_13.binu8@71495": '　究竟是什么在我的腹中翻涌？我不知道自己正在虚构的现实里起舞。',
    "Script/scenario05_13.binu8@74933": '@vMeguri_0898「你是怎么死的？你知道吗？」',
    "Script/scenario05_14.binu8@66335": '　我的力量是——@n　我无法成为其他演员。我只想做一个好人。',
    "Script/scenario05_14.binu8@76648": '@vKohaku_0657「你知道吗？我们已经走到这里了。现在的我，已经不再后悔。」',
    "Script/scenario05_14.binu8@80077": '@vYuuen_0226「我不喜欢这样。所以，我们来创造一个舞台，让那些如此出色的孩子们一起演出吧。」',
    "Script/scenario05_14.binu8@84449": '@vMeguri_0926「不过我保证，在那一天，你的慈悲不会被任何人破坏。」',
    "Script/scenario06b_2.binu8@83735": '「如果你能独立思考，就能真正意义上做出自己的决定。所以，我们只能依靠周围的环境。」',
    "Script/scenario06b_3.binu8@69231": '　所以，当我突然来到一个挤满陌生人的地方时，就会感到无比焦虑和恐惧，甚至一整天都无法平静下来。',
    "Script/scenario06b_3.binu8@70492": '@vMika_0116「我从来没有爱上过谁，所以才无法成为偶像。我的孩子很可爱，而发自内心的爱会吸引别人。」',
    "Script/scenario06b_4.binu8@75867": '@vMeguri_0979「以朋友的身份为他做饭就够好了。在和别人发生交集之前，先把自己的爱藏起来。如果是奈奈菜，就不能这样做。」',
    "Script/scenario06b_6.binu8@65966": '　即使意识到自己的极限，也是在为过程划定边界。',
})

OVERRIDES.update({
    "Script/scenario07_6.binu8@70613": '　怨恨之火正在燃烧。',
    "Script/scenario07_6.binu8@77615": '「所以，让我告诉你吧。@n　这个世界背后的真相。」',
    "Script/scenario07_6.binu8@77818": '　我没有犹豫。@n　有一句话，我想告诉你，也想告诉所有人。',
    "Script/scenario07_6.binu8@79867": '「我不知道这个世界是如何诞生的。」',
    "Script/scenario07_6.binu8@79932": '　然而，如果必须这样做，我的头脑就会发出尖叫。',
    "Script/scenario07_6.binu8@80223": '@vMeguri_1194「为什么一定要面对现实？沉浸在梦里，不是更幸福吗？」',
    "Script/scenario07_6.binu8@81261": '@vMeguri_1198「让人面对现实这种话，只有强者才说得出口。努力、战斗、面对现实……他们从来没有考虑过弱者的处境。」',
    "Script/scenario07_6.binu8@81641": '@vMeguri_1200「你说寻找现实？你看看那火焰就知道了。」',
    "Script/scenario07_6.binu8@82476": '@vMeguri_1203「逃跑真的不好吗？如果你努力活过，就能明白什么才是真正重要的东西吗？」',
    "Script/scenario07_6.binu8@83725": '　对他而言，那是燃烧的生命之光；而那光也随之消失了。',
    "Script/scenario07_6.binu8@83802": '@vMeguri_1207「我想要完成这个梦想。」',
    "Script/scenario07_6.binu8@83939": '@vMeguri_1208「再见了，环。如果你要求我面对正确的道路……那你自己也好好面对现实吧。」',
    "Script/scenario07_6.binu8@84421": '「为此，我必须面对现实。」',
    "Script/scenario07_6.binu8@85148": '「哦，这就是现实吗。@n　真相……我想把自己的双眼献给它，却难以置信。」',
    "Script/scenario07_6.binu8@85356": '　我跪倒在地。@n　即使能够运用自己的力量，也依然无法做到完美。',
    "Script/scenario07_6.binu8@85501": '@vMeguri_1213「面对现实，究竟意味着什么？」',
    "Script/scenario07_6.binu8@85742": '　你已经来迟了，她们都已经死了。@n　让我们回到大家身边吧。',
    "Script/scenario07_6.binu8@85929": '　如果你死去，说不定就能再次见到大家。',
    "Script/scenario07_6.binu8@86802": '　火焰翻腾，发出咆哮。@n　这个世界高耸如天国，燃烧着，无法逾越。',
})

OVERRIDES.update({
    "Script/scenario07_6.binu8@65213": '　那是因为，这里只有一种游戏规则。',
    "Script/scenario07_6.binu8@67065": '　爷爷说过，只要注视自己的内心深处，就能找到答案。',
    "Script/scenario07_6.binu8@68477": '@vMeguri_1153「……什么？」',
    "Script/scenario07_6.binu8@70081": '@vOmi_0101「我无法放弃过去留下的模式。」',
    "Script/scenario07_6.binu8@70408": '　欲望发自内心。@n　难道正因为是亲人，才会和孙女产生血缘上的联系吗？',
    "Script/scenario07_6.binu8@72573": '　这是明星王子的故事。',
    "Script/scenario07_6.binu8@73245": '「让我们低下头，说声再见吧。」',
    "Script/scenario07_6.binu8@73916": '「我肯定你去过那里。那朵无可替代、全世界唯一的玫瑰。」',
    "Script/scenario07_6.binu8@74760": '@vMeguri_1175「你哪里像玫瑰了？它是带刺的花，而你更像是……最接近它的东西。」',
    "Script/scenario07_6.binu8@76808": '@vMeguri_1183「让我们停下来吧。更何况，我已经不想再考虑接下来的演出。」',
    "Script/scenario07_6.binu8@76934": '「我没有下文。我们看看吧。」',
    "Script/scenario07_6.binu8@77253": '「我不是告诉过你吗？你是个好人。」',
    "Script/scenario07_6.binu8@77526": '@vMeguri_1184「这是什么？」',
    "Script/scenario07_6.binu8@77748": '「你害怕耳朵吗？」',
    "Script/scenario07_6.binu8@77933": '@n我们联系起来吧。',
    "Script/scenario07_6.binu8@79181": '@vMeguri_1190「为什么这么说？说出这种话很过分吗？」',
    "Script/scenario07_6.binu8@79647": '　因为我们知道，有多少人深爱着这个剧团。',
    "Script/scenario07_6.binu8@80385": '　这是一个即使手握剪刀、承受痛苦，也仍然能够活下去的地方。',
    "Script/scenario07_6.binu8@80686": '　突然之间，所有人都消失了。@n　每个人都想离开这里。',
    "Script/scenario07_6.binu8@80798": '@vMeguri_1195「……………………难道就没有别的办法了吗？你能告诉我吗？」',
    "Script/scenario07_6.binu8@81603": '「这是什么意思？」',
    "Script/scenario07_6.binu8@81799": '　一瞬间，火焰的碎片散落在眼前。',
    "Script/scenario07_6.binu8@82293": '「我还是…………」',
    "Script/scenario07_6.binu8@82337": '　我觉得你不应该留在这里。@n　我无法面对那个答案。',
    "Script/scenario07_6.binu8@82772": '　换句话说，生活在这个世界上的，是一个个真实的人类。',
    "Script/scenario07_6.binu8@82867": '　我站在自己的立场上。@n　以上这些话，不过都是借他人之口说出的思念。',
    "Script/scenario07_6.binu8@83193": '「对。@n　这才是正确的。」',
    "Script/scenario07_6.binu8@83275": '　说实话，我并不是想把她送走。',
    "Script/scenario07_6.binu8@83543": '@vMeguri_1206「哦，你不该再次面对那片火焰。」',
    "Script/scenario07_6.binu8@83645": '　它被光包裹着，现实与虚构之间的空间也随之震动。',
    "Script/scenario07_6.binu8@83898": '　最后，他说道。',
    "Script/scenario07_6.binu8@84212": '　一个女孩消失在自己的不幸之中。@n　我想拥抱她瘦小的背影。',
    "Script/scenario07_6.binu8@84501": '　这就是我们已经走到这里的意义。@n　我决定了自己的目的地。',
    "Script/scenario07_6.binu8@85045": '　我来过这里。@n　我们是来见你的。',
    "Script/scenario07_6.binu8@86039": '　如果有来世，',
    "Script/scenario07_6.binu8@86246": '　在不断膨胀的觉悟中，我想起了那片被烧焦的火焰，也想起了那个没有救赎的结局。',
    "Script/scenario07_6.binu8@86514": '　再过一会儿，我就能摆脱身体的痛苦，以及仿佛即将崩裂的悲伤。',
    "Script/scenario07_6.binu8@86645": '　我太幸福了。@n　我想，我的泪水会流成河。',
})

OVERRIDES.update({
    "Script/scenario07_6.binu8@70613": '　怨恨之火正在燃烧。',
    "Script/scenario07_6.binu8@77615": '「所以，让我告诉你吧。@n　这个世界背后的真相。」',
    "Script/scenario07_6.binu8@77818": '　我没有犹豫。@n　有一句话，我想告诉你，也想告诉所有人。',
    "Script/scenario07_6.binu8@79867": '「我不知道这个世界是如何诞生的。」',
    "Script/scenario07_6.binu8@79932": '　然而，如果必须这样做，我的头脑就会发出尖叫。',
    "Script/scenario07_6.binu8@80223": '@vMeguri_1194「为什么一定要面对现实？沉浸在梦里，不是更幸福吗？」',
    "Script/scenario07_6.binu8@81261": '@vMeguri_1198「让人面对现实这种话，只有强者才说得出口。努力、战斗、面对现实……他们从来没有考虑过弱者的处境。」',
    "Script/scenario07_6.binu8@81641": '@vMeguri_1200「你说寻找现实？你看看那火焰就知道了。」',
    "Script/scenario07_6.binu8@82476": '@vMeguri_1203「逃跑真的不好吗？如果你努力活过，就能明白什么才是真正重要的东西吗？」',
    "Script/scenario07_6.binu8@83725": '　对他而言，那是燃烧的生命之光；而那光也随之消失了。',
})

OVERRIDES.update({
    "Script/scenario07_5.binu8@63142": '　我可以学会新的演戏方式。@n　如果理解了这份感情，说不定就能抵达过去无法触及的境界。',
    "Script/scenario07_5.binu8@64382": '@vKohaku_0757「可是，这就是最后一场演剧了。座长既然也是演员，应该也很想亲自饰演奥丁吧。」',
    "Script/scenario07_5.binu8@67435": '@vKohaku_0765「死亡并不像银河那样美丽。它阴郁而晦暗，难以名状的恐惧匍匐其中。面对那暴力般的呐喊，所有人都会捂住耳朵转身逃开。所以……」',
    "Script/scenario07_5.binu8@68498": '@vHana_0274「嗯——很接近了！答案是：对各位而言，真正的幸福正是青春时代。」',
    "Script/scenario07_5.binu8@68709": '@vHana_0275「……长大成人、逐渐成长之后，就再也无法保持学生时代的心情了。座长和龙木前辈，都经历了太多太多痛苦。」',
    "Script/scenario07_5.binu8@69006": '@vHana_0276「所以，你才会格外担心巡小姐吧。这个世界，确实残酷得让人难以应付。」',
    "Script/scenario07_5.binu8@69465": '@vHana_0278「看起来像是空无一物，只是因为感情正在沉睡。琥珀小姐只是个迟钝的人而已。」',
    "Script/scenario07_5.binu8@69682": '@vHana_0279「嗯，就是这样。如果你真的一片空白……就连恋爱，也不可能谈得下去才对。」',
    "Script/scenario07_5.binu8@70260": '@vRairai_0720「如果不知道失去的恐惧，就不会意识到某样东西究竟有多重要。你现在最需要的，是足以让人发疯的饥渴感。」',
    "Script/scenario07b_2.binu8@70791": '@vMeguri_1312「……是啊。」',
    "Script/scenario07b_2.binu8@76056": '@vMeguri_1331「而且，他们两个人都很害怕。就算表达心意、彼此相通，也可能因为一点小事产生错位……最后再也无法喜欢对方。既然如此，倒不如……」',
    "Script/scenario07b_2.binu8@84318": '@vYuuen_0299「没有什么值得悲伤的事。虽然曾有许多艰辛痛苦的回忆……但多亏了兰比里斯剧团，我也尽情享受过无与伦比的美好。让我们欢笑着，把这一切歌唱出来吧？」',
    "Script/scenario07b_2.binu8@85941": '@vMeguri_1360「天兄，差不多该醒了。已经没有时间做奇怪的梦了。」',
    "Script/scenario07b_2.binu8@87979": '@vHana_0287「我们马上就要出发了。不过，我们必须在这里下车。」',
    "Script/scenario07b_2.binu8@90254": '@vMeguri_1371「周而复始，来回奔波。不停下，也不急着赶路。就这样一直重复下去。」',
})

OVERRIDES.update({
    "Script/scenario07_4.binu8@49403": '@vMeguri_1115「——花！爷爷在叫你，能过来一下吗？好像要和你商量服装的事。」',
    "Script/scenario07_4.binu8@50153": '@vMeguri_1116「爷爷！下一场由我当主角，对吧？我明明是演得最好的那个，肯定没错吧？」',
    "Script/scenario07_4.binu8@50661": '　如果是在普通剧团，像巡这样过度自信的女孩，恐怕早就被人讨厌了。',
    "Script/scenario07_4.binu8@52075": '@vMeguri_1119「天兄是导演吧？那就好好驾驭我这个演员吧！既然手里有最强的武器，肯定很轻松吧？」',
    "Script/scenario07_4.binu8@55258": '@vRairai_0654「虽、虽然那家伙还一副小鬼样，应该还是很久以后的事。不过在那个老头手下，还有很多东西要学。」',
    "Script/scenario07_4.binu8@56340": '　我无法面对愚蠢的自己。@n　即使是现在，只要试图回想起来，我还是会移开视线。',
    "Script/scenario07_4.binu8@58745": '　那个本应燃烧着野心的我，究竟从什么时候开始变得圆滑了呢？',
    "Script/scenario07_4.binu8@59632": '　这些人被人际关系折磨、经历失败、感到厌倦，却只是单纯地想演戏而已。',
    "Script/scenario07_4.binu8@61390": '@vRairai_0667「……原来如此。」',
    "Script/scenario07_4.binu8@64379": '@vOmi_0080「马上开始排练。巡……让我看看你的哈姆雷特。」',
    "Script/scenario07_4.binu8@70166": '　不用确认也知道，它恐怕已经被弄得面目全非，连原本的样子都不剩了。',
    "Script/scenario07_4.binu8@72284": '　到头来，我什么也没能做到，只是虚度了自己的人生。',
    "Script/scenario07_4.binu8@74167": '　即使万一能够九死一生地活下来，也会让那家伙高贵的心蒙上阴影。',
    "Script/scenario07_4.binu8@75169": '@vMirai_0543「既然死也无法彻底死去，那就否定这场悲剧吧。在一个什么都没有发生过的虚构世界里，和大家幸福地生活下去就好。」',
})

OVERRIDES.update({
    "Script/scenario07_5.binu8@69223": '　对我来说，没有什么是真正重要的。@n　因为那是空洞、虚无、不断模仿他人的人生。',
    "Script/scenario07_5.binu8@72805": '@vKohaku_0781「你其实是害怕面对内心吧？你的傲慢之中，正渗出了怯懦的声音。」',
    "Script/scenario07_5.binu8@75626": '　我不得不绷紧眼皮，否则就会一边发出尖叫，一边移开视线。',
})

OVERRIDES.update({
    "Script/scenario07b_2.binu8@75212": '「明明彼此喜欢，却不能交往。那不是只会让人感到悲伤吗……」',
    "Script/scenario07b_2.binu8@78024": '　巡悲痛地反复念叨着。',
    "Script/scenario07b_2.binu8@82683": '「那么，巡她……」',
    "Script/scenario07b_2.binu8@83514": '@vHana_0282「哇，好美的剧场！这里就是下一座舞台吗？」',
    "Script/scenario07b_2.binu8@83955": '　天乐座长露出一副不悦的表情。',
    "Script/scenario07b_2.binu8@86661": '@vYuuen_0303「……为什么会这么悲伤呢？啊，果然，不幸对人的内心没有好处。即使是甜食，吃得太多也会变成毒药。」',
    "Script/scenario07b_2.binu8@89012": '@vMeguri_1368「既然如此，我就要把这里变成比天堂更美好的地方。」',
    "Script/scenario07b_2.binu8@90162": '@vMeguri_1370「不，哪里都不去。」',
})

OVERRIDES.update({
    "Script/scenario07b_3.binu8@24025": '　让我们沉浸在不朽不变的故事中，将自己交给那永远不会完结的剧本吧。',
    "Script/scenario07b_3.binu8@28849": '　扑通、扑通、扑通扑通。@n　这究竟是哪一颗心脏在剧烈跳动呢？',
    "Script/scenario07b_4.binu8@58744": '「没事的。」',
    "Script/scenario07b_4.binu8@59386": '　被叫到的是佩特里科尔咖啡馆。@n　我环顾四周，却没有看到其他客人。',
    "Script/scenario07b_4.binu8@59548": '　我隐约察觉到，这不会是什么轻松的话题。',
    "Script/scenario07b_4.binu8@60627": '@vRairai_0745「没什么。嗯，没错，我也没有那个义务。完全没有，一点都没有。不过，你看……偶尔汇报一下情况，也没什么不好吧？」',
    "Script/scenario07b_4.binu8@67412": '　她狠狠瞪了我一眼。@n　那眼神，仿佛是在看杀父仇人。',
    "Script/scenario07b_4.binu8@70008": '　巡露出怜爱般的笑容。',
})

OVERRIDES.update({
    "Script/scenario07_5.binu8@57156": '　我仿佛做了一个非常讨厌的梦。@n　梦里，我珍视的一切都化为了灰烬。',
    "Script/scenario07_5.binu8@57511": '　别解释了。@n　究竟发生了什么，你应该已经凭本能理解了吧。',
    "Script/scenario07_5.binu8@57828": '　从身体深处涌上的滑稽感让我无言以对。',
    "Script/scenario07_5.binu8@60396": '　平日里粗暴的座长说出了令人难以置信的故事。@n　座长眼中盛满深沉的悲伤，告诉我那就是真相。',
    "Script/scenario07_5.binu8@61601": '@vRairai_0710「——这个故事，是我们最后的希望。巡……会找到除我们之外的同伴，和他们携手创作出一部戏。为她准备一个新的归宿，就是这场戏的目的。」',
    "Script/scenario07_5.binu8@62799": '　我本来想把一切都告诉她。@n　放下演剧，好好和她谈一谈。',
    "Script/scenario07_5.binu8@62923": '@n　我本来应该是这么想的——。',
    "Script/scenario07_5.binu8@64024": '　理解天乐座长。@n　他说，这是理解奥丁王内心的第一步。',
    "Script/scenario07_5.binu8@64780": '@vKohaku_0759「……至少，也该向她传达一声再见。巡小姐现在也还在想着座长他们……」',
    "Script/scenario07_5.binu8@65266": '@vKohaku_0760「……奥丁当时也是这样的心情吗？」',
    "Script/scenario07_5.binu8@67693": '　……所以，我才无法理解。@n　无法理解超越“死亡”这一概念之后，等待着我们的真正幸福。',
    "Script/scenario07_5.binu8@69362": '@vHana_0277「没有人是真正空洞的。」',
    "Script/scenario07_5.binu8@69964": '@vKohaku_0772「因为有环君在，所以我并不是空洞的。」',
    "Script/scenario07_5.binu8@71136": '@vKohaku_0775「……这就是，失去的感觉吗。」',
    "Script/scenario07_5.binu8@71980": '　为了演戏，甚至利用自己的恋心。@n　这种莫名其妙的暴行，才是世上最令人怜爱的东西。',
    "Script/scenario07_5.binu8@73216": '@vRairai_0722「……就算面对它，也没有意义。不仅没有意义，还会让人产生迷惘。我根本不是什么强者。正因为如此，我才只能用这种方式传达。」',
    "Script/scenario07_5.binu8@74941": '@vKohaku_0785「——奥丁若不傲慢，就无法反抗。」',
    "Script/scenario07_5.binu8@75046": '　这就是她从天乐来来身上学到的、奥丁的本质。',
    "Script/scenario07_5.binu8@76219": '@vKohaku_0788「巡小姐知道真正重要的东西。那看不见的东西，她也确实理解着。可是，好奇怪啊……巡小姐为什么现在还在这里呢？」',
    "Script/scenario07_5.binu8@76480": '「为什么这么说……？」',
    "Script/scenario07_5.binu8@76719": '　空气在颤抖。@n　仿佛连琥珀的一字一句都让它感到畏惧。',
    "Script/scenario07_5.binu8@77301": '　琥珀轻轻露出了笑容。',
})

OVERRIDES.update({
    "Script/scenario07_3.binu8@54013": '　那时的我还背着书包，得以加入他们的戏剧部。',
    "Script/scenario07_3.binu8@58265": '@vRize_1431「……你应该也知道这个剧团的恶评吧。王海先生拒绝你，是因为加入这个剧团会损害你的演艺事业……」',
    "Script/scenario07_3.binu8@60711": '@vRize_1437「我也是听说的……有个演员表演溺水的戏……结果天乐小姐冲着她大喊‘演得烂透了！’。那个孩子气得满脸通红，离开了排练场……」',
    "Script/scenario07_3.binu8@63296": '　与曾经背弃戏剧的我不同，她的眼中充满了希望。',
    "Script/scenario07_3.binu8@69930": '@vOmi_0067「在下一场公演之前，你照看一下巡。那家伙没戏可演，闲得发慌，老是插嘴。她说得倒是准确，但不能让演员连思考的时间都没有。把后台的工作全丢给她，让她闭嘴。」',
    "Script/scenario07_3.binu8@82818": '　他的笑容中浮现出烦躁。@n　如果在这里惹恼了他，一切肯定都会毁于一旦。',
    "Script/scenario07_3.binu8@83539": '@vDirectorB_0030「悠苑小姐似乎已经醒酒了。这样的话，应该可以用出租车送她回去。你是她的朋友吧？那就拜托你……送她回家吧。」',
})

OVERRIDES.update({
    "Script/scenario07_2.binu8@89074": '「哦？」',
    "Script/scenario07_2.binu8@93053": '@vMeguri_1082「只要有家人在身边，就算漫长的黑夜降临，也不会感到害怕。一定能够继续寻找真正的幸福。所以，环……」',
    "Script/scenario07_2.binu8@94305": '@vMirai_0535「因为现在正是这样的时间啊。我想抬头仰望那片闪耀的金刚石之海，尽情欣赏它的美。」',
    "Script/scenario07_2.binu8@94923": '@vMirai_0537「嗯？」',
    "Script/scenario07_2.binu8@102889": '@vOmi_0050「别迷失自我。别把你认为正确的东西弄错了。如果不想变得和我一样，就继续思考，不断向自己发问。」',
    "Script/scenario07_2.binu8@103827": '　对周围的人来说，这大概是一个令人不禁歪头的展开吧。',
    "Script/scenario07_2.binu8@105663": '@vOmi_0059「——你们这些沉迷戏剧的蠢货。既然有无法放弃的东西，就到死都后悔去吧。」',
})

OVERRIDES.update({
    "Script/scenario06b_2.binu8@84691": '　撒娇般的声音响彻四周。',
    "Script/scenario06b_2.binu8@91430": '@vMika_0109「……奈奈菜，你已经不必再自以为喜欢濑和君了。那时的排练，也该结束了吧？」',
    "Script/scenario06b_3.binu8@67806": '　只要磨炼可爱之处，妈妈就会开心地笑起来。',
    "Script/scenario06b_3.binu8@81386": '@vNanana_0522「我不要，不想承认……！！可是，我对自己没有信心。因为这一切的开始……实在太卑劣了。」',
    "Script/scenario06b_3.binu8@83285": '　发出狂吠。',
    "Script/scenario06b_3.binu8@89355": '　她曾给予我的爱——是超越真伪、超越一切定义的某种非同寻常之物。',
    "Script/scenario06b_4.binu8@66639": '@vKohaku_0689「是啊！一想起之前的《菲利亚》公演，我晚上都睡不着！我想快点再演一次……！」',
    "Script/scenario06b_4.binu8@68098": '　那股从未停滞的旺盛热情，大概正支撑着她演技的根基。',
    "Script/scenario06b_4.binu8@69457": '@vFutaba_0677「嗯？不过，偶像把家人当成事业伙伴，麻烦肯定是少不了的吧！话虽如此，你们也太理所当然了吧？居然光明正大地住在一起……！！」',
    "Script/scenario06b_4.binu8@74689": '@vNanana_0584「……可、可是，我觉得不一定非要今天。等我再熟练一点之后……或许更好……」',
    "Script/scenario06b_4.binu8@76855": '　难得一见，奈奈菜的眼中燃起了坚定的光芒。',
})

OVERRIDES.update({
    "Script/scenario07b_1.binu8@83856": '「……说起来，琥珀她们去哪儿了？」',
    "Script/scenario07b_1.binu8@85265": '@vMeguri_1226「最让人生气的是，内容根本就是凭空捏造的。要是真的，那可就另当别论了。」',
    "Script/scenario07b_1.binu8@85630": '「我也无法判断，究竟该不该接受这样的结果。」',
    "Script/scenario07b_1.binu8@86761": '「我、我没有别的意思，知道吗？从语境来看，会自然地认为我指的是和你的关系……这不是很正常吗！」',
    "Script/scenario07b_1.binu8@87958": '　我完全看不出巡的话究竟有几分认真。',
    "Script/scenario07b_1.binu8@92137": '@vRize_1460「束缚我们感受和思考的，正是现在这样的框架。如果我们生活在流动的空间里，或许应该从学会爱上不完美的幻想开始。」',
    "Script/scenario07b_1.binu8@92437": '@vRize_1461「逝去的记忆聚集在这个地方。那些看似随意的事物，并不是毫无意义地堆积在那里。对我而言的“现在”，正被过去的你们，或未来的你们观测着。我想确认这一点。」',
    "Script/scenario07b_1.binu8@92989": '@vRize_1463「即使有人告诉我们，那些星星的光芒属于过去，我们也没有办法亲自确认。」',
    "Script/scenario07b_1.binu8@93365": '@vRize_1465「……不过，也许这样就够了。我们所认识的世界，全都只能是过去。因为那个无法理解的“现在”，是无法被观测的。」',
    "Script/scenario07b_1.binu8@94775": '@vMeguri_1258「大人们总把‘为了将来、为了将来’挂在嘴边，说着千篇一律的话，却不明白真正重要的东西。」',
    "Script/scenario07b_1.binu8@98464": '　我仿佛感觉整个世界都被寂静包围。@n　面对本应一成不变的现实，我却隐约感到一丝违和。',
    "Script/scenario07b_1.binu8@100619": '@vMeguri_1283「那种事怎样都无所谓。然后呢？难道你让我说完之后，自己打算一直沉默吗？」',
    "Script/scenario07b_1.binu8@103338": '@vMeguri_1295「那么，今天该给你做什么菜呢？既然是男孩子，就做些能让你精力充沛的东西吧？」',
    "Script/scenario07b_1.binu8@104166": '　啊啊，那是多么幸福的日子。@n　我们的日常生活缓慢而慵懒地继续着。',
})

OVERRIDES.update({
    "Script/scenario07b_4.binu8@58538": '@vMeguri_1509「我想永远、永远地在这个没有尽头的多维世界尽头徘徊。随着细碎的震动摇晃肩膀，沉浸在梦境般的心情里。」',
    "Script/scenario07b_4.binu8@60137": '@vRairai_0743「那、那个……你明白吧？你有义务好好汇报吧。到底怎么样？喂！！」',
    "Script/scenario07b_4.binu8@60296": '「那个……我不明白你在说什么。」',
    "Script/scenario07b_4.binu8@60539": '　不，等等，嗯？@n　我果然还是不明白他在说什么。',
    "Script/scenario07b_4.binu8@60864": '@vRairai_0746「那家伙最近心情好得离谱……而且和你关系变得相当不错了吧？啊，我知道，我知道。你们有自己的节奏嘛。可是，我们毕竟认识这么久了，偶尔多管一次闲事，也该原谅我吧？」',
    "Script/scenario07b_4.binu8@62108": '「没有，我们没有交往。」',
    "Script/scenario07b_4.binu8@64165": '@vRairai_0756「所以，濑和，你和巡进展到哪一步了？既然还没交往，最多也就是牵手吧？该不会……已经接吻了吧？」',
    "Script/scenario07b_4.binu8@64632": '　我要撒谎吗？要说实话吗？@n　可无论怎么回答，之后被发现的话，似乎都很可怕……！',
    "Script/scenario07b_4.binu8@65445": '@vMeguri_1514「如果你在意我和环的关系，直接问我不就好了？把处于弱势的环叫来审问，你还真是差劲。」',
    "Script/scenario07b_4.binu8@66363": '@vMeguri_1517「我们没有交往，也不是男女朋友。这样你满意了吗？」',
    "Script/scenario07b_4.binu8@66731": '@vMeguri_1518「哎呀，不用担心。即便如此，我们也正在培养一段美好的关系。」',
    "Script/scenario07b_4.binu8@67043": '　巡露出带着恶意的笑容。',
    "Script/scenario07b_4.binu8@68423": '@vYuuen_0306「呵呵，怎么会呢？你觉得这孩子像是会被人玩弄的类型吗？我们可是认真地交往着，并不是抱着玩玩的心态在一起。」',
    "Script/scenario07b_4.binu8@68689": '@vYuuen_0307「巡也别捉弄得太过分了。这位先生看起来如此，其实可是个纯情的人。」',
    "Script/scenario07b_4.binu8@68910": '@vRairai_0776「吵、吵死了……！这和我有什么关系啊！」',
    "Script/scenario07b_4.binu8@69356": '@vYuuen_0309「可是，你不是也能理解我的心情吗？」',
    "Script/scenario07b_4.binu8@70401": '@vMeguri_1528「只是因为喜欢你的心情已经无法抑制了而已。那里面根本不存在什么周旋试探。」',
    "Script/scenario07b_4.binu8@71529": '@vMeguri_1534「我们得从这个爱多管闲事的大叔身边逃走才行。不然连好好相爱都做不到。」',
    "Script/scenario07b_4.binu8@71851": '@vMeguri_1536「我才不想被一个不擅长恋爱的天兄说教呢——！不服气的话，就试着找一两个女朋友啊——！」',
    "Script/scenario07b_4.binu8@72839": '　和花一起走在回家的路上。@n　难得地，我们聊起了恋爱话题。',
    "Script/scenario07b_4.binu8@75321": '@vHana_0296「没错没错！其实那原本好像是龙木先生的东西……她借来之后，就一直擅自用到现在。」',
    "Script/scenario07b_4.binu8@75914": '@vMeguri_1545「……哇，那算什么，炫耀恋爱吗？悠小姐是那种会给没用男人花钱的类型呢……」',
    "Script/scenario07b_4.binu8@76233": '@vMeguri_1546「没有契机的话，应该不可能吧。」',
    "Script/scenario07b_4.binu8@76305": '　两个人得出了相同的结论。@n　说到底，我们也不能对别人的恋爱指手画脚。',
})

OVERRIDES.update({
    "Script/scenario07b_4.binu8@60007": '　那究竟是什么？',
    "Script/scenario07b_4.binu8@62155": '　我明确地回答。@n　我和巡还没有发展成明确的关系。',
    "Script/scenario07b_4.binu8@64448": '@vRairai_0757「那算什么？我说的是更具体的事！」',
    "Script/scenario07b_4.binu8@66086": '@vRairai_0765「局外人给我闭嘴！」',
    "Script/scenario07b_4.binu8@66570": '　天乐座长皱起眉头说道。',
    "Script/scenario07b_4.binu8@66851": '@vRairai_0770「那算什么？明明没有交往？那你们到底是什么关系啊！」',
    "Script/scenario07b_4.binu8@75526": '@vMeguri_1544「哎呀，原来是这样啊？」',
    "Script/scenario07b_4.binu8@76429": '@vMeguri_1547「嗯，在关心别人之前，还是先找到自己的对象吧。」',
})

OVERRIDES.update({
    "Script/scenario06b_6.binu8@58476": '@vNanana_0724「我无法理解普罗斯佩罗。」',
    "Script/scenario06b_6.binu8@58735": '@vNanana_0726「我……无法理解莎士比亚。」',
    "Script/scenario06b_6.binu8@59019": '　无法理解。@n　无法产生共鸣。',
    "Script/scenario06b_6.binu8@60866": '@vNanana_0732「就、就是那件事……！我、我想挑战一件事，啊、啊、啊、啊……！」',
    "Script/scenario06b_6.binu8@61025": '「咦？」',
    "Script/scenario06b_6.binu8@62667": '　她涨红了脸，却还是清清楚楚地说了出来。',
    "Script/scenario06b_6.binu8@67758": '「嗯？」',
    "Script/scenario06b_6.binu8@68741": '@vFutaba_0700「咦！？」',
    "Script/scenario06b_6.binu8@72523": '「你该不会不只是喜欢偶像吧？」',
    "Script/scenario06b_6.binu8@74520": '@vFutaba_0717「……偶像也是女孩子。果然，女孩子谈恋爱之后，就会变得更有魅力啊……」',
    "Script/scenario06b_6.binu8@76098": '　挽起手臂，贴近身体，索求双唇。',
    "Script/scenario06b_6.binu8@76163": '「……不、不行！要是被人看见了怎么办啊！」',
})

OVERRIDES.update({
    "Script/scenario06b_7.binu8@32957": '　双叶一边给我看某位写真偶像的视频，一边说道。',
    "Script/scenario06b_7.binu8@37677": '@vFutaba_0742「……啊，是角色扮演啊。这样的话，反而很适合让大家看看吧。」',
    "Script/scenario06b_7.binu8@39846": '「不行吗？」',
    "Script/scenario06b_8.binu8@32747": '@vcs_Nanana_0011「比、比个耶？」',
    "Script/scenario06b_8.binu8@33212": '@vcs_Nanana_0013「要是拍出来不可爱，岂不是会适得其反吗！所、所以……那个……！」',
    "Script/scenario06b_8.binu8@34914": '@vcs_Nanana_0019「你这么一说……反而让我有点不好意思了。啊哈哈……原来如此，确实是这样呢。」',
    "Script/scenario06b_8.binu8@38382": '　天使奈奈菜，第一本写真集。',
    "Script/scenario06b_8.binu8@43634": '　我绝不允许自己追问一句“真的吗？”。@n　至少，不能问出口。',
})

OVERRIDES.update({
    "Script/scenario05_13.binu8@68572": '@vMeguri_0882「我不知道！你为什么不看我？为什么听不见我的声音？奥丁，真正的你究竟去了哪里！」',
    "Script/scenario05_13.binu8@71495": '　最让我生气的是……一无所知的自己，竟然被虚构的现实牵着鼻子走。',
    "Script/scenario05_13.binu8@74933": '@vMeguri_0898「你问巴德尔为什么会死？这种事你们都不明白吗？」',
    "Script/scenario05_13.binu8@76243": '　那是任性而孤独、夺走所有存在感的魔性演技。',
    "Script/scenario05_14.binu8@66335": '　我的优势究竟是什么？@n　有什么是其他演员做不到，只有我才能做到的长处？',
    "Script/scenario05_14.binu8@76648": '@vKohaku_0657「你应该明白。现在，我们彼此都在这里。对于此刻，我没有一丝后悔。」',
    "Script/scenario05_14.binu8@80077": '@vYuuen_0226「不是那样的。因为现在……我已经和这些能展现如此精彩演技的孩子们，一起完成了一座舞台。」',
    "Script/scenario05_14.binu8@84449": '@vMeguri_0926「即便如此，我也不会憎恨你。那一天，你给予我的温柔——是任何暴力都无法摧毁的。」',
    "Script/scenario05_14.binu8@85655": '@vKohaku_0665「——！？」',
})

OVERRIDES.update({
    "Script/scenario05_2.binu8@69510": '@vKohaku_0525「我才不好呢。这是第一次，我如此清楚地意识到自己什么都做不到。」',
    "Script/scenario05_2.binu8@71451": '@vHana_0161「还没有到那么危急的地步，所以没关系啦！」',
    "Script/scenario05_2.binu8@78529": '@vRize_0565「我一直想着应该向你道谢。可是，不知为什么总觉得害羞。所以……是花小姐特意帮了我吧？要不是这样，我根本没法坦率起来。」',
    "Script/scenario05_2.binu8@81663": '「反正是在衣服外面，就算安全通过了吧。」',
    "Script/scenario05_2.binu8@82030": '@vRize_0579「我会把自己能做到的一切都倾注进去。所以……你要好好看着我。」',
    "Script/scenario05_2.binu8@82423": '　这是我心灰意冷、放弃演员之路之后，一路走来的历程。',
    "Script/scenario05_2.binu8@85468": '　性格一本正经的我，没法用陪笑把这件事敷衍过去。',
    "Script/scenario05_2.binu8@86870": '　我只顾着专心演戏，其他方面全都一塌糊涂。',
})

OVERRIDES.update({
    "Script/scenario05_4.binu8@61164": '　有一天，一个眼神凶恶的男人来到了我家。',
    "Script/scenario05_4.binu8@61336": '@vRairai_0405「哈，看起来没什么了不起嘛。你真的很擅长演戏吗？」',
    "Script/scenario05_4.binu8@63100": '@vMeguri_0486「你这身高，也好意思说别人吗？你自己作为男人，不也有很多不足之处？啊，说你是男人，会不会对你来说太早了？真是抱歉呢。」',
    "Script/scenario05_4.binu8@66257": '　我一时无法理解，原来他们甚至还不是一个剧团。',
    "Script/scenario05_4.binu8@66415": '@vRairai_0419「啊？你是不是误会了什么？那个老头又不是我们的顾问，也不是老师。」',
})

OVERRIDES.update({
    "Script/scenario05_8.binu8@63047": '　而我，却连别人教给我的事情都做不到。',
    "Script/scenario05_8.binu8@66098": '　我之所以无法理解那份心情……是因为我总抱着“反正不可能”的消极想法吗？',
    "Script/scenario05_8.binu8@68829": '@vFutaba_0598「我有件事一直觉得奇怪。环把家人的私人物品都收在各自的房间里……生活区域里，应该只有环的东西才对。」',
    "Script/scenario05_8.binu8@69459": '@vMeguri_0726「我、我不知道！我才不知道呢！多半是琥珀带来的东西吧？」',
    "Script/scenario05_8.binu8@70258": '@vMeguri_0728「总之我不知道。以环的性格，说不定是把别的女孩子带回来了。」',
    "Script/scenario05_8.binu8@70622": '@vHana_0211「所以，我们现在就打电话确认吧。我和巡小姐的父母关系很好，他们应该马上就会告诉我们的。」',
    "Script/scenario05_8.binu8@71217": '@vHana_0213「那么，开始打电话吧！啊，您好，请问是匂宫家吗？我是巡小姐的朋友……」',
    "Script/scenario05_8.binu8@73746": '@vMeguri_0741「……你有什么好惊讶的？我还没愚蠢到会住进不喜欢的男人家里。正因为这件事也很丢脸，我才一直藏着不说。」',
    "Script/scenario05_8.binu8@74442": '@vMeguri_0743「那就是他会喜欢上我的未来。」',
    "Script/scenario05_8.binu8@74815": '@vMeguri_0744「哎呀，谁知道呢。至少现在，还是我单方面的暗恋吧？」',
    "Script/scenario05_8.binu8@76199": '@vFutaba_0608「……我不知道，也不想知道。」',
})

OVERRIDES.update({
    "Script/scenario05_11.binu8@78166": '@vRairai_0556「我不知道。我只是单纯看你不顺眼而已。」',
    "Script/scenario05_11.binu8@79126": '　后来。@n　她再也无法忍受同行投来的怀疑目光，最终离开了剧团。',
    "Script/scenario05_11.binu8@80423": '　这种荒唐的事，怎么可能允许它发生！',
    "Script/scenario05_11.binu8@81301": '　匂宫王海迅速落魄的理由。',
    "Script/scenario05_11.binu8@84063": '　摇曳在夹缝中的、毫无印象的记忆。',
    "Script/scenario05_11.binu8@84540": '　这个世界，究竟已经缺演员到必须对这样的小姑娘寄予厚望了吗？',
    "Script/scenario05_11.binu8@88950": '　意识一片混沌。@n　过去、现在与未来彼此纠缠，故事也在继续，却失去了应有的连贯性。',
    "Script/scenario05_11.binu8@89092": '　人们把沉入泥沼的未来称为绝望。@n　等待着我的东西，似乎也有着一个相近的名字。',
})

OVERRIDES.update({
    "Script/scenario05_5.binu8@70643": '「无论洛基遭受了多么残酷的对待，他都无法忘记奥丁往日的温柔。那份感情，甚至胜过了失去家人的憎恨。」',
    "Script/scenario05_5.binu8@71271": '「啊，是的。那一刻，我知道奥丁心中还残留着爱。所以，爱战胜了仇恨。就在那一瞬间，洛基的反叛之心彻底崩溃了。」',
    "Script/scenario05_5.binu8@73295": '@vMeguri_0575「……不过真让人吃惊。没想到你竟然看得这么透彻。你什么时候调查过我过去演过的角色？」',
    "Script/scenario05_5.binu8@75335": '@vMeguri_0583「我也没特意认真准备，别抱太大期待。时间也不够，只是用手头现成的食材做了些东西而已。」',
    "Script/scenario05_5.binu8@76377": '@vMeguri_0587「哎呀，真失礼。即便如此，这些也全都是我亲手做的。这边是糖醋肉丸，那边是菠菜拌菜，这是毛豆天妇罗。还有……」',
    "Script/scenario05_5.binu8@77177": '「我以前总是吃便利店的饭，所以不太习惯这样的饭菜。不过，真的很感谢你。该怎么说呢……很有家的味道。」',
    "Script/scenario05_5.binu8@83707": '　我必须移开视线。@n　这是匂宫的恶作剧。',
    "Script/scenario05_5.binu8@84148": '「只要把裙子放下来不就好了吗。」',
})

with MASTER.open(encoding="utf-8-sig", newline="") as handle:
    rows = list(csv.DictReader(handle, delimiter="\t"))
changed = 0
# Expanded manual pass for Acts 4-6: remove literal phrasing that changes
# characterization or meaning while preserving the original control tags.
OVERRIDES.update({
    "Script/scenario04_1.binu8@82488": '@vMirai_0157「红色房间时期的哥哥，在现实里也经历了很多事，整个人都变得荒凉颓废。所以，他才能把 T 氏的疯狂演得那么好。……不，或许不是这样。」',
    "Script/scenario04_1.binu8@85974": '　所以，我只能从远处守望着她。@n　她自由得就像演剧之神一样。',
    "Script/scenario04_1.binu8@87265": '　真正的天才，真是让人头疼。@n　所谓生活在不同的世界，大概就是这么回事吧。',
    "Script/scenario04_5.binu8@70822": '　还有架桥先生。他披着角色的外皮，肆无忌惮地侵犯天使。',
    "Script/scenario04_6.binu8@64659": '　当然是要强行决定。',
    "Script/scenario05_5.binu8@82620": '　明明知道自己是在被捉弄，却还是不得不在意，这就是男人。',
    "Script/scenario05_5.binu8@89647": '@vMeguri_0636「…………男孩子还真是可怕。」',
    "Script/scenario05_10.binu8@74733": '@vFutaba_0623「……阴沉会长，请闭嘴。女孩子可是很柔弱的。所以你才会是个阴沉男。」',
    "Script/scenario05_10.binu8@91237": '　即使在这个宏大的世界里渺小得如同微生物，至少在这座破败狭小的舞台上，还能沉浸于自身的特别之中。',
    "Script/scenario05_11.binu8@91797": '　没有任何人能发出声音。@n　我、奈奈菜，还有天乐座长，都只能服从那来自天上的声音。',
    "Script/scenario05_7.binu8@83579": '「即便如此，奈奈菜描绘的仍是不讲理与荒谬。这不正是她想要表达的东西吗？」',
    "Script/scenario06b_8.binu8@41523": '@vNanana_0924「哥哥这种生物，就是会爱妹妹的哦。」',
    "Script/scenario06_7.binu8@97450": '@vRize_1047「……如果环君愿意认真走上和我相同的道路……我们就能一直@n一起走下去了吧。」',
    "Script/scenario04_4.binu8@83819": '　然而，即使是如此可爱的少女，也会在了解现实后，一点一点学会如何露出虚假的笑容。',
    "Script/scenario04_4.binu8@84764": '　我并不是对时尚毫无兴趣，但对所谓的流行，无论如何都提不起兴致。',
    "Script/scenario04_4.binu8@85507": '　那场演出铺陈出的世界，压倒了我除惊叹之外的一切情感。',
    "Script/scenario04_4.binu8@88782": '　光是知道了这件事，我就觉得加入这个剧团是值得的。',
    "Script/scenario04_4.binu8@89540": '　然而，得到的却是意料之外的回答。',
    "Script/scenario04_4.binu8@91123": '　既然已经不再迷惘，我便没有什么好害怕的了。',
    "Script/scenario04_4.binu8@93361": '　所以，我只能听下去。',
    "Script/scenario04_5.binu8@71340": '　那是不可能的事。@n　那是荒谬的东西。',
    "Script/scenario04_5.binu8@75873": '　夜晚无人的公园，是只属于我的空间。@n　可即便如此，还是有东西从意识之外来妨碍我。',
    "Script/scenario04_5.binu8@78051": '@vMirai_0267 「人终有一死。所以，人不可能获得幸福。」',
    "Script/scenario05_10.binu8@91410": '@vRairai_0528 「可怜、可怜的凡人君。正因为你无法接受这一点，才永远无法蜕变。」',
    "Script/scenario06b_3.binu8@85350": '　直到最后，我都无法承认那样的话。',
    "Script/scenario06b_3.binu8@89154": '　正因为如此，我明明必须拒绝才对——',
    "Script/scenario05_10.binu8@73953": '@vRairai_0486 「我只是没法集中精神。除此之外还能有什么原因？」',
    "Script/scenario05_10.binu8@80013": '　这是故意煽动我的话。@n　我明知道不能上他的激将法，可是！',
    "Script/scenario05_10.binu8@98871": '　与其让那些沉溺于欲望的人上演群像剧，倒不如原原本本地把他们展现出来，说不定更能逗人发笑。',
    "Script/scenario05_13.binu8@59333": '　我什么特别的事都没做，只是随波逐流，结果一切就这样结束了。',
    "Script/scenario05_3.binu8@80964": '@vKohaku_0542 「说什么只凭才能演戏、什么横冲直撞的蠢女人，真是差劲透顶。环君，你可不能变成那种男孩子啊。」',
    "Script/scenario06_2.binu8@86546": '「渐渐有人发现我的演技很差……也看出我的表演太过单调……于是妈妈的态度突然变得严厉起来，不断指导我。她还说：‘怎么会变成这样！你明明本来可以做得更好！’」',
    "Script/scenario06_4.binu8@87689": '@vKohaku_0722 「正因为如此，我才觉得不能把它白白浪费掉。我们不能逃避接下来的故事。」',
    "Script/scenario06b_2.binu8@89631": '　她那扭曲的笑容，意味着什么。',
    "Script/scenario06b_3.binu8@88887": '　她越是认真，我就越不能对她手下留情。',
    "Script/scenario06b_6.binu8@59074": '　这样的我，当然不可能理解原作真正的意图。',
    "Script/scenario06b_6.binu8@75227": '　如果是你的话，就算你这样对我，我也愿意。',
    "Script/scenario06b_8.binu8@34489": '　明明应该明白，却始终无法明白的事。',
    "Script/scenario06b_8.binu8@35249": '　她的笑容“啪”地绽开。@n　终于，奈奈菜露出了属于她的、含蓄的笑容。',
    "Script/scenario05_13.binu8@58467": '　对观看这场故事的人来说，只要能让他们觉得我很可怜，就够了——@n　',
    "Script/scenario05_13.binu8@58612": '　那个人，是统治这个国家的奥丁王。@n　就连部下的妻女，也都是他的所有物。',
    "Script/scenario05_13.binu8@58727": '　没错，我只是他的所有物。',
    "Script/scenario05_13.binu8@58765": '　那一次也是，那一次也是，还有那一次。@n　所谓自由……我从来都不曾拥有过。',
    "Script/scenario05_13.binu8@59003": '　纯洁被夺走，身心一点点堕落。',
    "Script/scenario05_13.binu8@59085": '　我只是供人享用的贡品。@n　我只需要从口中发出喘息声就够了吧。',
    "Script/scenario05_13.binu8@59881": '@vNanana_0396「……咦？」',
    "Script/scenario05_13.binu8@60019": '@vNanana_0397「……环君。」',
    "Script/scenario05_13.binu8@60143": '　你是在为我感到可怜、对我心生怜悯吗？@n　大家，我……',
    "Script/scenario05_13.binu8@60261": '　那双望着我的眼睛里，绝没有怜悯。@n　他们只是在注视着事情最后会如何发展。',
    "Script/scenario05_13.binu8@60741": '　对于任由自己随波逐流、沉溺于不幸的人，没人会产生那样的感情。',
    "Script/scenario05_13.binu8@60919": '　真正的同情与悲伤——只会献给那些拼命活着的人。',
    "Script/scenario05_13.binu8@61397": '蹒跚',
    "Script/scenario05_13.binu8@61411": '　我的身体正要消失在舞台侧幕。',
    "Script/scenario05_13.binu8@61613": '　或许，从观众席能看到的……只有那双丑陋挣扎着的小手。',
    "Script/scenario05_13.binu8@61708": '　那只手用力伸出，试图抓住什么。',
    "Script/scenario05_13.binu8@61779": '　我有生以来第一次——用尽全力，发出了发自内心的声音。',
    "Script/scenario05_13.binu8@62165": '　某个人的手臂、身体、脚，将我的心搅得一团糟。',
    "Script/scenario05_13.binu8@62360": '　不要，不要，不要。',
    "Script/scenario05_13.binu8@62478": '　平凡地活着，平凡地被爱着。@n　作为一个普通的家庭，普通地——',
    "Script/scenario05_13.binu8@62741": '　就在即将消失在舞台侧幕的刹那，灵魂的声音不经意间溢了出来。',
    "Script/scenario05_13.binu8@62818": '　声音很轻，难以听清——可那声 SOS 确实传达到了。',
    "Script/scenario05_13.binu8@63444": '@vMeguri_0865「……哦。」',
    "Script/scenario05_13.binu8@64688": '　原本用来束缚洛基自由的楔子，反而一步步将他引向了叛逆。',
    "Script/scenario05_13.binu8@64945": '　以女儿之死为开端，两人之间出现了决定性的裂痕。@n　这对本应是义兄弟的两人，如今的关系已经惨不忍睹。',
    "Script/scenario05_13.binu8@65705": '@vMeguri_0875「没错，是自由。那双不受任何事物束缚的翅膀，曾是我们的憧憬。直到现在也没有改变。对吧，奥丁？」',
    "Script/scenario05_13.binu8@67912": '　匂宫巡一直压抑着的、最后一道枷锁，就这样断开了。',
    "Script/scenario05_13.binu8@68161": '　这一刻，他化身为被憎恨之火囚禁的邪神洛基。',
    "Script/scenario05_13.binu8@68770": '　原本应该演出那种恳切的情感，最后却变成了单纯宣泄怨恨的表演。',
    "Script/scenario05_13.binu8@69698": '　那就是天乐来来种下的憎恨之种。@n　面对以愤怒表情嘶吼的洛基——就连观众也不由得心生恐惧。',
    "Script/scenario05_13.binu8@69849": '「……巡。」',
    "Script/scenario05_13.binu8@69946": '「巡……！」',
    "Script/scenario05_13.binu8@69978": '　因为我痛切地明白，她那无处安放的感情究竟有多么难受。',
    "Script/scenario05_13.binu8@70105": '　可演出仍在继续。@n　如果一直被愤怒吞噬——一切都会毁掉。',
    "Script/scenario05_14.binu8@64354": '　那么，我呢？@n　我为什么会存在于那个孩子身边？',
    "Script/scenario05_14.binu8@65024": '　濑和未来说道。',
    "Script/scenario05_14.binu8@65139": '　一瞬间敞开的、发自内心的真话。@n　她希望我做的，仅仅就是这件事。',
    "Script/scenario05_14.binu8@65827": '　王子的职责，是向公主伸出援手。',
    "Script/scenario05_14.binu8@65957": '　因为再也听不到她的声音……我才逃离了演员这条道路。',
    "Script/scenario05_14.binu8@66073": '　动乱的脚步声传来。怒吼与悲鸣，枪声与燃烧的声音。',
    "Script/scenario05_14.binu8@66176": '@vMeguri_0905「……听，终结的声音已经传来了。叛乱开始了。那是奥丁所期望的世界末日。」',
    "Script/scenario05_14.binu8@66517": '　因为箱鸟理世是个直率、笨拙又无可救药的女孩。',
    "Script/scenario05_14.binu8@66929": '　我既不肯定，也不否定。@n　我能做的，只有陪在你身边，直到你的心平静下来。',
    "Script/scenario05_14.binu8@67260": '　我会担心那个遍体鳞伤、迷失自我的你，拼命追上你的背影。',
    "Script/scenario05_14.binu8@67373": '　即使你被愤怒吞噬，即使你将疯狂藏于自身。@n　只有我，会允许这一切，并接受这样的你。',
    "Script/scenario05_14.binu8@68235": '　我无法以托尔的身份拯救洛基。@n　但我可以以箱鸟理世的身份，支持匂宫巡。',
    "Script/scenario05_14.binu8@69004": '　演剧，就像是在漆黑的大海上航行。',
    "Script/scenario05_14.binu8@69390": '　宣告终结的那一幕，为什么会变成如此震撼人心的表演？',
    "Script/scenario05_14.binu8@69811": '　演技力只能算中上。@n　完成度明明比匂宫巡和架桥琥珀低了好几个层次……为什么却如此扣人心弦？',
    "Script/scenario05_14.binu8@70078": '　直到刚才还弥漫着的恐惧，已经荡然无存。',
    "Script/scenario05_14.binu8@70438": '@vMirai_0379「……嗯。」',
    "Script/scenario05_14.binu8@70476": '　不明来由的烦躁，让人坐立不安。@n　原本像隔岸观火般置身事外的事情，突然开始有了真实感。',
    "Script/scenario05_14.binu8@70648": '@vMirai_0380「不过，仇恨并没有因此消散。再次面对奥丁时，洛基还能把愤怒咽回去吗？」',
    "Script/scenario05_14.binu8@70924": '　叛乱正式开始，起义的革命军向奥丁的王座进发。',
    "Script/scenario05_14.binu8@71222": '　即便如此，仰慕奥丁的人仍试图保护他，可就连这份保护也被他拒绝了。',
    "Script/scenario05_14.binu8@71936": '　胜负早已注定。@n　奥丁王的暴政，很快就要迎来终结。',
    "Script/scenario05_14.binu8@73021": '　孤独黑暗中的奥丁，即使濒临死亡，也仍试图贯彻自己的信念。',
    "Script/scenario05_14.binu8@74582": '　他不断说着毫无意义的理由，只是一味地把自己的想法强加给别人。',
    "Script/scenario05_14.binu8@74816": '　你仿佛看透了一切，正在笑着。@n　把我逼到这种地步，你一定觉得很开心吧。',
    "Script/scenario05_14.binu8@75840": '　可是，我……',
    "Script/scenario05_14.binu8@78497": '　悠小姐为什么要这么说呢？@n　明明她才应该比任何人都憎恨天兄。',
    "Script/scenario05_14.binu8@75510": '　我绝对不会原谅你。',
    "Script/scenario05_14.binu8@79285": '@vRairai_0594「……啊？」',
    "Script/scenario05_14.binu8@80295": '@vRairai_0597「……哈。」',
    "Script/scenario05_14.binu8@81171": '@vMeguri_0917「你——无论到什么时候，都是对我来说最重要的@r义@か@@r兄@ぞ@@r弟@く@人！」',
    "Script/scenario05_14.binu8@88773": '　谢谢你带给我的安心与兴奋。@n　剧场中回荡的掌声，久久没有停歇。',
    "Script/scenario05_13.binu8@59645": '　只要观看这场故事的人愿意觉得我很可怜，那就够了——',
    "Script/scenario05_13.binu8@63480": '　听说要把角色让给天使奈奈菜时，我简直不敢相信自己的耳朵。',
    "Script/scenario05_13.binu8@63635": '　我没有对天使奈奈菜进行严格指导，是因为我知道，即使放任不管，她也会变成这样吗？',
    "Script/scenario05_13.binu8@63820": '　那么，也就是说，如果放任我不管，就不行吗？',
    "Script/scenario05_13.binu8@71097": '　学生时代的天兄，可靠、开朗，又风趣。@n　我曾经相信，和这样的人一起创作戏剧，一定能发自内心地享受其中。',
    "Script/scenario05_13.binu8@71384": '@vMeguri_0890「啊啊，令人不快的声音传来了。肮脏的诸神之声传来了。」',
    "Script/scenario05_13.binu8@71811": '　难道要说，愚直地相信就是美德吗？@n　明明那只不过是愚蠢而已，人为什么就是察觉不到！',
    "Script/scenario05_13.binu8@72132": '　我究竟在害怕什么？@n　我最害怕的，正是你们。',
    "Script/scenario05_13.binu8@74266": '　我放声怒吼，放声叫喊，@n　将所有情感一股脑地倾泻出去。',
    "Script/scenario05_13.binu8@74369": '　可是，为什么会这样呢？',
    "Script/scenario05_13.binu8@77760": '　可是，渐渐地，我发现两者之间存在许多不同之处。',
    "Script/scenario05_13.binu8@79593": '@vMeguri_0903「我没有怨恨。我所怨恨的，是这个世界的命运。我想，我大概会就这样死去吧。可是，我的死毫无意义。就连是谁杀死巴德尔，也没有意义。」',
    "Script/scenario05_13.binu8@80294": '　随着最后一幕逐渐逼近，那种奇妙的感觉再次袭来。',
    "Script/scenario05_14.binu8@72817": '@vKohaku_0649「正因如此，仅凭半吊子的觉悟根本不可能战胜神话。若没有足以抵达神明境界的奇迹，就无法否定北欧神话。」',
    "Script/scenario05_14.binu8@78917": '　我本来应该知道的。@n　我本来应该知道的。',
    "Script/scenario05_14.binu8@79008": '　真正的你。@n　真正的奥丁。',
    "Script/scenario05_14.binu8@79781": '@vYuuen_0225「直到现在，我都没能对那个不惜沾上污泥也要阻止这一切的你说声谢谢。」',
    "Script/scenario05_14.binu8@80331": '　他垂下眼帘，说道。',
    "Script/scenario05_14.binu8@81303": '　无论心中涌起多少愤怒，那份愤怒都无法将回忆焚烧殆尽。',
    "Script/scenario05_14.binu8@81416": '　即使想把回忆投入火焰，也总会有什么东西零零落落地掉出来。',
    "Script/scenario05_14.binu8@82028": '　所以，我要为这份感情殉身。@n　即使他真的充满恶意，我也已经无可奈何。',
    "Script/scenario05_14.binu8@82245": '　你笑得十分开心。@n　那笑容一如幸福的日子。',
    "Script/scenario05_14.binu8@85314": '　奥丁达成了自己的目的。@n　然而，到了最后，仍有一块缺失的拼图。',
    "Script/scenario05_14.binu8@87116": '@vKohaku_0668「永远传颂下去吧——我的家人绝不是什么邪神！」',
    "Script/scenario05_14.binu8@88186": '　许多话语涌到了喉咙深处。@n　然而到了此刻，再把它们说出口，反倒显得有些多余。',
    "Script/scenario05_14.binu8@88562": '　关于我们抵达这个地方的意义。@n　现在，就让我们细细体会，然后稍作休息吧。',
    "Script/scenario05_14.binu8@89486": '　我想，只要是在这个充满温暖的地方……我一定就能获得幸福。',
    "Script/scenario05_14.binu8@67491": '横扫',
    "Script/scenario05_14.binu8@67519": '@vRize_0718「——@r生@丶@き下去，洛基。你要按照自己的意志行动。」',
    "Script/scenario05_14.binu8@71718": '斩击',
    "Script/scenario05_14.binu8@75282": '蹒跚',
    "Script/scenario06b_2.binu8@80986": '　至少，濑和家的兄妹关系并不正常。',
    "Script/scenario06b_3.binu8@72113": '@vMika_0122「嗯。光是这样就够了。不需要再做其他事，也没有必要进行毫无意义的接触。」',
    "Script/scenario06b_3.binu8@90412": '哗啦哗啦',
    "Script/scenario06b_4.binu8@79837": '哗啦哗啦',
    "Script/scenario06b_6.binu8@64645": '「啊。」',
    "Script/scenario06b_6.binu8@78265": '「嗯。」',
})

OVERRIDES.update({
    "Script/scenario05_13.binu8@59191": '　她被奥丁王带着，就这样消失在舞台侧幕。',
    "Script/scenario05_13.binu8@63954": '　她的成功令我碍眼。@n　即使亲眼看到她的光芒，我心中的烦躁仍在加剧。',
    "Script/scenario05_13.binu8@64111": '　既然如你所愿，那就让我们在你的掌心起舞吧。@n　如果让我的怒火燃烧到这种程度，正是你的愿望。',
    "Script/scenario05_13.binu8@67596": '斩击',
    "Script/scenario05_13.binu8@68315": '横扫',
    "Script/scenario05_13.binu8@70675": '　你用充满恶意的报道，扰乱了我和濑和君的关系吗？@n　如果你讨厌我，从一开始就把我赶走不就好了吗。',
    "Script/scenario05_13.binu8@71278": '　真正的你，究竟去了哪里？@n　还是说，这就是你的本性？',
    "Script/scenario05_13.binu8@75509": '　既然这是你所祈求的结果。@n　那就如你所愿——我会让一切结束，将一切烧尽。',
    "Script/scenario05_13.binu8@76007": '　虽然勉强还在按照剧本推进，但巡那充满愤怒的演技，只是在不断加深观众对洛基的恐惧。',
    "Script/scenario05_13.binu8@77570": '　起初，我觉得架桥小姐的演技很像冰狐。',
    "Script/scenario05_13.binu8@77846": '@vRize_0704「架桥小姐的演技里，没有丝毫属于自己的感情。借用她本人的说法，那是空洞的演技。」',
    "Script/scenario05_13.binu8@77988": '　换句话说，那是映照他人的镜子般的演技。@n　那种演技里，不包含演员本人的任何感情。',
    "Script/scenario05_13.binu8@78130": '　所以，即使那份气势和演技力相近，本质上也是完全不同的方向。',
    "Script/scenario06b_2.binu8@84457": '「……奈奈菜。」',
    "Script/scenario06b_2.binu8@89295": '@vMika_0098「……咦？」',
    "Script/scenario06b_2.binu8@90541": '「那个……」',
    "Script/scenario06b_2.binu8@91652": '「……咦？」',
    "Script/scenario06b_3.binu8@70456": '@vNanana_0485「……咦？」',
    "Script/scenario06b_3.binu8@72466": '@vNanana_0489「……是。」',
    "Script/scenario06b_3.binu8@84986": '　……我明白。',
    "Script/scenario06b_3.binu8@86187": '@vNanana_0540「……咦？」',
})

OVERRIDES.update({
    "Script/scenario04_4.binu8@78401": '「……喂，胧。」',
    "Script/scenario04_4.binu8@80347": '「不行，我已经应付不了了。谁来……」',
    "Script/scenario04_4.binu8@90602": '@vOmi_0009「……你有演剧的才能。不是表演的才能，而是支撑演剧的才能。就这样舍弃它，你不觉得可惜吗——？」',
    "Script/scenario04_4.binu8@92742": '「……真是的。」',
    "Script/scenario04_4.binu8@93905": '「……咦？」',
    "Script/scenario05_4.binu8@82596": '「……为、为什么要做这种事……」',
    "Script/scenario05_4.binu8@84708": '「好，先回家去。然后把演剧需要的一切都带上，来我家。正好从明天开始放长假。我要对你进行特训。」',
    "Script/scenario06_6.binu8@85083": '@vRize_0978「啾。」',
    "Script/scenario06b_3.binu8@91870": '@vNanana_0552「……呜诶？」',
    "Script/scenario06b_3.binu8@92272": '@vNanana_0554「……咦？」',
    "Script/scenario06b_4.binu8@65365": '@vNanana_0571「……呜。」',
    "Script/scenario06b_4.binu8@65847": '「……！」',
    "Script/scenario06b_4.binu8@65997": '「奈奈菜……」',
    "Script/scenario06b_4.binu8@66396": '@vNanana_0575「……呜呜……！？」',
    "Script/scenario06b_4.binu8@67208": '@vNanana_0577「……咦？」',
    "Script/scenario06b_4.binu8@69070": '「……怎么了？」',
    "Script/scenario06b_4.binu8@78192": '@vNanana_0594「……呜。」',
    "Script/scenario06b_4.binu8@79201": '@vNanana_0598「那、那个……！」',
    "Script/scenario06b_4.binu8@81742": '@vNanana_0606「嗯……」',
})

