for row in rows:
    if row["id"] in OVERRIDES:
        row["translation"] = OVERRIDES[row["id"]]
        changed += 1
    # A legacy batch accidentally appended speaker record IDs to translations.
    # Remove only that unmistakable artifact; do not alter ordinary name text.
    cleaned = re.sub(r"理世_\d{4}|理世", "理世", row["translation"])
    # Remove a legacy duplicate speaker label inserted after Rize voice tags.
    cleaned = re.sub(r"(@vRize_\d{4})理世\s*", r"\1", cleaned)
    # A legacy converter emitted spaced ASCII dots for Japanese ellipses.
    # Normalize the other common ASCII ellipsis form from the PC patch too.
    cleaned = cleaned.replace("......", "……")
    cleaned = cleaned.replace("...", "……")
    cleaned = cleaned.replace(". . . . . . . . .", "……")
    cleaned = cleaned.replace(". . . . . . . .", "……")
    cleaned = cleaned.replace(". . . . . . .", "……")
    cleaned = cleaned.replace(". . . . . .", "……")
    cleaned = cleaned.replace(". . . . .", "……")
    cleaned = cleaned.replace(". . . .", "……")
    cleaned = cleaned.replace(". . .", "……")
    cleaned = cleaned.replace("多昆", "咚咚")
    # Normalize unreviewed romanized or machine-translated proper names.
    for old, new in (
        ("Sewa", "濑和"),
        ("Future", "未来"),
        ("Nioumiya", "匂宫"),
        ("Lambiris", "兰比里斯"),
        ("柏桥", "架桥"),
        ("㭴桥", "架桥"),
        ("王宫", "匂宫"),
        ("里约", "来来"),
        ("三轮未来", "濑和未来"),
        ("Yokonagi 2", "横扫2"),
        ("Yokonagi3", "横扫3"),
        ("瑟瓦", "濑和"),
        ("小白", "琥珀"),
        ("纳安赛", "奈奈菜"),
        ("折原日月", "折原冰狐"),
        ("折原日津", "折原冰狐"),
        ("折原日光", "折原冰狐"),
        ("新王惠美", "匂宫巡"),
        ("米莱", "未来"),
        ("迷途", "兰比里斯"),
        ("小巡游", "巡"),
        ("巡游", "巡"),
        ("小花", "花"),
        ("小双叶", "双叶"),
        ("小天使", "天使"),
        ("上茶", "喝茶"),
        ("圆辰和", "龙木悠苑"),
        ("巡酱", "巡"),
        ("巡ちゃん", "巡"),
        ("环君", "环"),
        ("濑和兄", "环"),
        ("匂宮", "匂宫"),
        ("天使酱", "天使"),
    ):
        cleaned = cleaned.replace(old, new)
    if cleaned != row["translation"]:
        row["translation"] = cleaned
        changed += 1
with MASTER.open("w", encoding="utf-8-sig", newline="") as handle:
    writer = csv.DictWriter(handle, fieldnames=list(rows[0]), delimiter="\t", lineterminator="\n")
    writer.writeheader()
    writer.writerows(rows)
print(f"manual_polished={changed}")
